Object.assign(window.TEM8_DICTIONARY, {"such":{"media":{"uk":"media/uk/such__gb_1.mp3","us":"media/us/such__us_1.mp3"},"oxford":{"phon":"sʌtʃ","pos":"determiner, pronoun","senses":[{"en":"used to emphasize the great degree of something","cn":"（强调程度）这样，非常，如此","lab":"formal","ex":{"en":"This issue was of such importance that we could not afford to ignore it.","cn":"这个问题十分重要，我们疏忽不得。"}},{"en":"of the type already mentioned","cn":"（指上文）这样的，那样的，类似的","ex":{"en":"They had been invited to a Hindu wedding and were not sure what happened on such occasions.","cn":"有人邀请他们去参加一个印度教徒的婚礼，但他们不清楚这样的庆典会是怎样一种场面。"}},{"en":"of the type that you are just going to mention","cn":"（指后文）这样的，那样的，下述一类的","ex":{"en":"There is no such thing as a free lunch.","cn":"世上没有免费午餐之类的好事儿。"}}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"这样的;那样的;上述的;诸如此类的","en":"You use such to refer back to the thing or person that you have just mentioned, or a thing or person like the one that you have just mentioned. You use such as and such...as to introduce a reference to the person or thing that has just been mentioned.","ex":{"en":"There have been previous attempts at coups. We regard such methods as entirely unacceptable","cn":"以前也有人试图发动政变。我们绝对不能接受这种做法。"}},{"pos":"DET 限定词","cn":"(后接从句)…那种的，…那样的","en":"You use such...as to link something or someone with a clause in which you give a description of the kind of thing or person that you mean.","ex":{"en":"Each member of the alliance agrees to take such action as it deems necessary, including the use of armed force","cn":"该联盟的每一位成员国都同意采取其认为必要的行动，包括动用武力。"}},{"pos":"DET 限定词","cn":"(用于举例)例如，像，诸如","en":"You use such...as to introduce one or more examples of the kind of thing or person that you have just mentioned.","ex":{"en":"He was said to have written such books as The Day of Locusts and Miss Lonely Hearts.","cn":"据说他曾经写过《蝗虫之日》和《寂寞芳心小姐》之类的小说。"}},{"pos":"DET 限定词","cn":"(用于名词词组前强调某事的程度或某事了不起)如此，这样，非常","en":"You use such before noun groups to emphasize the extent of something or to emphasize that something is remarkable.","ex":{"en":"I think most of us don't want to read what's in the newspaper anyway in such detail","cn":"我想我们大多数人无论如何都不想如此仔细地去读报纸。"}},{"pos":"PREDET 前置限定词","cn":"(用于强调程度)如此…，非常…(以至于…)","en":"You use such...that in order to emphasize the degree of something by mentioning the result or consequence of it.","ex":{"en":"The weather has brought such a demand for beer that one brewery will operate over the weekend","cn":"天气状况使得对啤酒的需求大增，一家啤酒厂周末要加班了。"}},{"pos":"DET 限定词","cn":"(用于表示结果)如此…使得…","en":"You use such...that or such...as in order to say what the result or consequence of something that you have just mentioned is.","ex":{"en":"The operation has uncovered such backstreet dealing in stolen property that police might now press for changes in the law.","cn":"这次行动破获了这样的地下销赃活动，现在警方可能会因此敦促修改法律。"}},{"pos":"PHRASE 短语","cn":"(用于不想明确指出时)某，某个","en":"You use such and such to refer to a thing or person when you do not want to be exact or precise.","ex":{"en":"I said, 'Well what time'll I get to Leeds?' and he said such and such a time but I missed my connection","cn":"我说：“那么我什么时候才能到利兹?”他说了一个时间，但是我没赶上联运车。"}},{"pos":"PHRASE 短语","cn":"就是这样;就是如此;就是这么回事儿","en":"You use such as it is or such as they are to suggest that the thing you have just mentioned is not very good, important, or useful.","ex":{"en":"Well my toilet's all blocked up and I've got it all coming into my flat and it'll ruin my home, such as it is","cn":"我的马桶堵死了，脏水全都涌到屋子里，家里脏得一塌糊涂，情况就是这样。"}},{"pos":"PHRASE 短语","cn":"(与否定词连用)严格来说，真正意义上","en":"You use as such with a negative to indicate that a word or expression is not a very accurate description of the actual situation.","ex":{"en":"I am not a learner as such —I used to ride a bike years ago","cn":"严格说来，我并不完全是一个初学者——几年前我经常骑自行车。"}},{"pos":"PHRASE 短语","cn":"(用于名词后)本身","en":"You use as such after a noun to indicate that you are considering that thing on its own, separately from other things or factors.","ex":{"en":"House prices are easily upset by factors which have nothing to do with property as such. The fall in prices in the South-East results largely from the high rate of interest on mortgages","cn":"房价很容易受与地产本身无关的因素所影响。东南部房价的下跌很大程度上是由于抵押贷款利率的上涨所引起的。"}},{"pos":"","cn":"","en":"no such thing→see: ;"}]},"examples":[{"en":"They had been invited to a Hindu wedding and were not sure what happened on such occasions.","cn":"有人邀请他们去参加一个印度教徒的婚礼，但他们不清楚这样的庆典会是怎样一种场面。"},{"en":"‘Well, did they offer it to you?’ ‘No, not as such, but they said I had a good chance.’ “","cn":"那么，他们把它给你了？” “不，不完全是那样，可是他们说我很有希望。”"}]},"summit":{"media":{"uk":"media/uk/summit__gb_1.mp3","us":"media/us/summit__us_1.mp3"},"oxford":{"phon":"ˈsʌmɪt","pos":"noun","senses":[{"en":"the highest point of something, especially the top of a mountain","cn":"最高点；顶点；山顶","lab":"figurative","ex":{"en":"We reached the summit at noon.","cn":"中午时分我们抵达峰顶。"}},{"en":"an official meeting or series of meetings between the leaders of two or more governments at which they discuss important matters","cn":"（政府间的）首脑会议；峰会","lab":"US English","ex":{"en":"a summit in Moscow","cn":"在莫斯科举行的首脑会议"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政府间的)峰会，首脑会议","en":"A summit is a meeting at which the leaders of two or more countries discuss important matters.","ex":{"en":"...next week's Washington summit.","cn":"下周的华盛顿峰会"}},{"pos":"N-COUNT 可数名词","cn":"山顶;顶峰","en":"The summit of a mountain is the top of it.","ex":{"en":"Snow gleamed on the summit of Mount Simon.","cn":"西蒙山山顶白雪皑皑。"}}]},"examples":[{"en":"We reached the summit at noon.","cn":"中午时分我们抵达峰顶。"},{"en":"This path leads to the summit.","cn":"这条路通往山顶。"}]},"superficially":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a person, place, or situation is pleasant, normal, calm etc on the surface , they seem that way until you know them better","cn":""},{"en":"if someone is outwardly calm, happy etc, that is how they seem to be, but in fact they are probably nervous, unhappy etc","cn":""}]},"examples":[{"en":"Even a superficial inspection revealed serious flaws.","cn":"","src":"ld"},{"en":"Naturally, such visits can allow only the most superficial understanding of prison life.","cn":"","src":"ld"}],"media":{"uk":"media/uk/superficially__gb_1.mp3","us":"media/us/superficially__us_1.mp3"},"oxford":{"phon":"ˌsuːpəˈfɪʃəli","pos":"adverb","senses":[{"en":"in a way that appears to be true, real or important until you look at it more carefully","cn":"表面的；外面的；外表的","ex":{"en":"The fruit superficially resembles a blackberry.","cn":"这种水果表面上类似于黑莓。"}},{"en":"not carefully or completely; in a way that only considers what is obvious","cn":"表面上：没有仔细或完全 只考虑明显的方式","lab":"often disapproving","ex":{"en":"A document of this length can only superficially address the topic.","cn":"如此长度的文档只能粗略地讨论该主题。"}},{"en":"not seriously or to a great degree; in a way that only affects the surface","cn":"表面上：不认真或在很大程度上 以仅影响表面的方式","ex":{"en":"The indigenous culture was only superficially affected by the Roman invasion.","cn":"土著文化仅受到罗马入侵的表面影响。"}},{"en":"in a way that is not serious or important and lacks any depth of understanding or feeling","cn":"浅薄的；肤浅的","lab":"often disapproving","ex":{"en":"He interacted only superficially with his co-workers.","cn":"他与同事之间的互动只是表面上的。"}}]}},"surrounded":{"lemma":"surround"},"sudden":{"media":{"uk":"media/uk/sudden__gb_1.mp3","us":"media/us/sudden__us_1.mp3"},"oxford":{"phon":"ˈsʌdn","pos":"adjective","senses":[{"en":"happening or done quickly and unexpectedly","cn":"突然的；忽然的；骤然的","ex":{"en":"News of his sudden and unexpected death came as a great shock.","cn":"他突然意外死亡的消息令人极为震惊。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"突然的;骤然的;忽然的","en":"Sudden means happening quickly and unexpectedly.","ex":{"en":"He had been deeply affected by the sudden death of his father-in-law","cn":"岳父的猝死使他十分伤心。"}},{"pos":"PHRASE 短语","cn":"突然地;出乎意料地","en":"If something happens all of a sudden, it happens quickly and unexpectedly.","ex":{"en":"All of a sudden she didn't look sleepy any more.","cn":"她突然看起来一点都不困了。"}}]},"examples":[{"en":"It was only decided yesterday. It's all been very sudden.","cn":"这是昨天才决定的，一切都非常突然。"},{"en":"All of a sudden someone grabbed me around the neck.","cn":"猛不防有人抓住了我的脖子。"}]},"sugary":{"media":{"uk":"media/uk/sugary__gb_1.mp3","us":"media/us/sugary__us_1.mp3"},"oxford":{"phon":"ˈʃʊɡəri","pos":"adjective","senses":[{"en":"containing sugar; tasting of sugar","cn":"含糖的；甜的","ex":{"en":"sugary snacks","cn":"甜点心"}},{"en":"seeming too full of emotion in a way that is not sincere","cn":"（态度等）甜腻腻的，媚人的；甜言蜜语的","lab":"disapproving","ex":{"en":"a sugary smile","cn":"媚笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"含糖量高的;甜的","en":"Sugary food or drink contains a lot of sugar.","ex":{"en":"Sugary canned drinks rot your teeth.","cn":"喝含糖的罐装饮料会滋生蛀牙。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(电影或音乐)煽情的，甜腻腻的，矫情的","en":"If you describe a film or piece of music as sugary, you mean that it is sentimental and insincere.","ex":{"en":"The programme seemed false and sugary, and the characters smug.","cn":"这个节目看起来矫揉造作，而其中的人物还自我感觉良好。"}}]},"examples":[{"en":"sugary pop songs","cn":"甜腻腻的流行歌曲"},{"en":"sugary snacks","cn":"甜点心"}]},"surprise":{"media":{"uk":"media/uk/surprise__gb_1.mp3","us":"media/us/surprise__us_1.mp3"},"oxford":{"phon":"səˈpraɪz","pos":"noun","senses":[{"en":"an event, a piece of news, etc. that is unexpected or that happens suddenly","cn":"意想不到（或突然）的事；令人惊奇的事（或消息等）","g":"[countable]","ex":{"en":"What a nice surprise!","cn":"真是让人惊喜！"}},{"en":"a feeling caused by something happening suddenly or unexpectedly","cn":"惊奇；惊讶；意外","g":"[uncountable, countable]","ex":{"en":"a look of surprise","cn":"惊讶的表情"}},{"en":"the use of methods that cause feelings of surprise","cn":"出人意表的做事方式；出奇制胜的策略","g":"[uncountable]","ex":{"en":"A successful campaign should have an element of surprise.","cn":"成功的宣传活动需有出奇制胜之处。"}},{"en":"to make somebody feel surprised","cn":"使惊奇；使诧异；使感到意外","ex":{"en":"It wouldn't surprise me if they got married soon.","cn":"即使他们很快就结婚，我也不会感到意外。"},"pos":"verb"},{"en":"to attack, discover, etc., somebody suddenly and unexpectedly","cn":"出其不意地攻击；使措手不及；无意中发现","ex":{"en":"The army attacked at night to surprise the rebels.","cn":"军队在夜间发起攻击，把叛乱者打了个措手不及。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"意想不到的事;突如其来的事;令人惊奇的事(或消息等)","en":"A surprise is an unexpected event, fact, or piece of news.","ex":{"en":"I have a surprise for you: We are moving to Switzerland!","cn":"我有一个惊喜的消息要告诉你：我们要搬去瑞士了！"}},{"pos":"N-UNCOUNT 不可数名词","cn":"惊奇;惊讶;诧异","en":"Surprise is the feeling that you have when something unexpected happens.","ex":{"en":"The Foreign Office in London has expressed surprise at these allegations","cn":"位于伦敦的英国外交部对这些说法表示惊讶。"}},{"pos":"VERB 动词","cn":"使惊奇;使诧异;使感到意外","en":"If something surprises you, it gives you a feeling of surprise.","ex":{"en":"We'll solve the case ourselves and surprise everyone","cn":"我们要自己解决这件事，然后让所有人感到吃惊。"}},{"pos":"VERB 动词","cn":"给…惊喜;使喜出望外","en":"If you surprise someone, you give them, tell them, or do something pleasant that they are not expecting.","ex":{"en":"Surprise a new neighbour with one of your favourite home-made dishes.","cn":"做一道拿手的家常小菜，给你的新邻居一个惊喜。"}},{"pos":"N-COUNT 可数名词","cn":"使人惊异(或意想不到)的事物;让人大吃一惊的人","en":"If you describe someone or something as a surprise, you mean that they are very good or pleasant although you were not expecting this.","ex":{"en":"...Senga MacFie, one of the surprises of the World Championships three months ago","cn":"森加·麦克菲，三个月前世界锦标赛上的一匹黑马"}},{"pos":"VERB 动词","cn":"突袭;使措手不及;使毫无防备","en":"If you surprise someone, you attack, capture, or find them when they are not expecting it.","ex":{"en":"Marlborough led his armies across the Rhine and surprised the French and Bavarian armies near the village of Blenheim.","cn":"马尔伯勒带领他的部队穿过莱茵河，在离布莱尼姆村不远的地方向法国和巴伐利亚联军发动了突袭。"}},{"pos":"PHRASE 短语","cn":"一点儿都不稀奇;可想而知","en":"You can say 'surprise, surprise' if you disapprove of something because it is not surprising or original, or could easily have been predicted.","ex":{"en":"There is a shortage of carrots. So everybody starts growing carrots. Next season, surprise, surprise, there is a glut of carrots.","cn":"胡萝卜紧缺，于是大家都去种胡萝卜。等到来年这个时候，可想而知，胡萝卜就会过剩。"}},{"pos":"PHRASE 短语","cn":"(用于遇见熟人或给别人一些意想不到的东西时)想不到吧","en":"You can say 'surprise, surprise' if you meet someone you know or give them something when they are not expecting it.","ex":{"en":"He came back in as I was heading up to the shower. 'Surprise, surprise,' he said.","cn":"我正要去淋浴时他回来了。“想不到吧，”他说。"}},{"pos":"PHRASE 短语","cn":"使大吃一惊;出乎…意料","en":"If something takes you by surprise, it happens when you are not expecting it or when you are not prepared for it.","ex":{"en":"His question took his two companions by surprise","cn":"他提的问题让他的两个伙伴都愣住了。"}}]},"examples":[{"en":"One of the candidates was the manager's niece, and surprise, surprise, she got the job.","cn":"求职者中有一个是经理的侄女，结果她被录用了。这有什么奇怪的呢。"},{"en":"The army attacked at night to surprise the rebels.","cn":"军队在夜间发起攻击，把叛乱者打了个措手不及。"}]},"suffering":{"media":{"uk":"media/uk/suffering__gb_1.mp3","us":"media/us/suffering__us_1.mp3"},"oxford":{"phon":"ˈsʌfərɪŋ","pos":"noun","senses":[{"en":"physical or mental pain","cn":"疼痛；痛苦；折磨；苦难","g":"[uncountable]","ex":{"en":"Death finally brought an end to her suffering.","cn":"死亡终于结束了她的痛苦。"}},{"en":"feelings of pain and unhappiness","cn":"痛苦；苦恼","g":"[plural]","ex":{"en":"The hospice aims to ease the sufferings of the dying.","cn":"临终关怀医院旨在减轻临终者的痛苦。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(肉体或内心的)痛苦，苦难，折磨","en":"Suffering is serious pain which someone feels in their body or their mind.","ex":{"en":"They began to recover slowly from their nightmare of pain and suffering","cn":"他们开始从痛苦的梦魇中慢慢恢复过来。"}}]},"examples":[{"en":"This war has caused widespread human suffering.","cn":"这场战争给许许多多的人带来了苦难。"},{"en":"The hospice aims to ease the sufferings of the dying.","cn":"善终关怀医院旨在减轻临终者的痛苦。"}],"base":"suffer"},"supporting":{"media":{"uk":"media/uk/supporting__gb_1.mp3","us":"media/us/supporting__us_1.mp3"},"oxford":{"phon":"səˈpɔːtɪŋ","pos":"adjective","senses":[{"en":"a supporting actor in a play or film has an important part but not the leading one","cn":"（演员、角色）次要的；配角的","ex":{"en":"The movie featured Robert Lindsay in a supporting role.","cn":"罗伯特·林赛在这部影片中担任配角。"}},{"en":"helping to show that something is true","cn":"能确证的","lab":"formal","ex":{"en":"There was a wealth of supporting evidence.","cn":"有大量证据。"}},{"en":"carrying the weight of something","cn":"支承的；支撑的；承重的","ex":{"en":"a supporting wall","cn":"承重墙"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(演员)次要的，配角的","en":"In a film or play, a supporting actor or actress is one who has an important part, but not the most important part.","ex":{"en":"...the winner of the best supporting actress award.","cn":"最佳女配角奖获得者"}}]},"examples":[{"en":"The movie featured Robert Lindsay in a supporting role.","cn":"罗伯特 · 林赛在这部影片中担任配角。"},{"en":"There was a wealth of supporting evidence.","cn":"有大量证据。"}],"base":"support"},"sufficient":{"media":{"uk":"media/uk/sufficient__gb_1.mp3","us":"media/us/sufficient__us_1.mp3"},"oxford":{"phon":"səˈfɪʃnt","pos":"adjective","senses":[{"en":"enough for a particular purpose; as much as you need","cn":"足够的；充足的","ex":{"en":"Allow sufficient time to get there.","cn":"留出充足的时间好赶过去。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"足够的;充足的","en":"If something is sufficient for a particular purpose, there is enough of it for the purpose.","ex":{"en":"One metre of fabric is sufficient to cover the exterior of an 18-in-diameter hatbox","cn":"一米布足以包裹住直径为 18 英寸的帽盒。"}},{"pos":"ADJ 形容词","cn":"(理由、条件)充足的，充分的","en":"If something is a sufficient cause or condition for something to happen, it can happen.","ex":{"en":"Discipline is a necessary, but certainly not a sufficient condition for learning to take place.","cn":"纪律是有必要的，但绝对不是保证学习成效的充分条件。"}}]},"examples":[{"en":"The following day she felt sufficiently well to go to work.","cn":"第二天，她感觉好转，完全可以去上班了。"},{"en":"These reasons are not sufficient to justify the ban.","cn":"这些理由不足以证明实施禁令有理。"}]},"summary":{"oxford":{"phon":"ˈsʌməri","pos":"noun","senses":[{"en":"a short statement that gives only the main points of something, not the details","cn":"总结；概括；概要","ex":{"en":"a news summary","cn":"新闻综述"}},{"en":"giving only the main points of something, not the details","cn":"总结性的；概括的；概要的","lab":"formal","ex":{"en":"a summary financial statement","cn":"财务汇总报表"},"pos":"adjective"},{"en":"done immediately, without paying attention to the normal process that should be followed","cn":"从速从简的；即决的；草草的","lab":"sometimes disapproving","ex":{"en":"summary justice/execution","cn":"即决裁判；草草处决"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"总结;摘要;概括","en":"A summary of something is a short account of it, which gives the main points but not the details.","ex":{"en":"What follows is a brief summary of the process","cn":"接下来是对此流程的一个简短概括。"}},{"pos":"ADJ 形容词","cn":"从速的;即决的;草草的","en":"Summary actions are done without delay, often when something else should have been done first or done instead.","ex":{"en":"It says torture and summary execution are common","cn":"那上面称酷刑和草草处决很常见。"}}]},"media":{"uk":"media/uk/summary__gb_1.mp3","us":"media/us/summary__us_1.mp3"},"examples":[{"en":"The following is a summary of our conclusions.","cn":"现将我们的几点结论综述如下。"},{"en":"In summary, this was a disappointing performance.","cn":"总的来说，这场演出令人失望。"}]},"suddenness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening suddenly","cn":""},{"en":"happening suddenly, and making a situation either much better or much worse","cn":""}]},"examples":[{"en":"a sudden change in the weather","cn":"","src":"ld"},{"en":"Life is cruel, she thought, with a sudden rush of anger.","cn":"","src":"ld"}],"media":{"uk":"media/uk/suddenness__gb_1.mp3","us":"media/us/suddenness__us_1.mp3"},"oxford":{"phon":"ˈsʌdnnəs","pos":"noun","senses":[{"en":"the fact that something happens or is done quickly and unexpectedly","cn":"突然；猛地","ex":{"en":"The suddenness of the attack left no time to launch lifeboats.","cn":"袭击的突然性使得救生艇来不及下水。"}}]}},"subtlety":{"oxford":{"phon":"ˈsʌtlti","pos":"noun","senses":[{"en":"the quality of being subtle","cn":"细微；微妙；巧妙；敏锐","g":"[uncountable]","ex":{"en":"It's a thrilling movie even though it lacks subtlety.","cn":"这部电影虽说不算精巧，但还是扣人心弦的。"}},{"en":"the small but important details or aspects of something","cn":"细小但重要的地方；微妙之处","g":"[countable, usually plural]","ex":{"en":"the subtleties of language","cn":"语言的微妙之处"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"细微差别;微妙之处","en":"Subtleties are very small details or differences which are not obvious.","ex":{"en":"His fascination with the subtleties of human behaviour makes him a good storyteller","cn":"他对人们行为上的细微差别极感兴趣，这使他成了一个很会讲故事的人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"精妙;精细;细微;微妙","en":"Subtlety is the quality of being not immediately obvious or noticeable, and therefore difficult to describe.","ex":{"en":"African dance is vigorous, but full of subtlety, requiring great strength and control","cn":"非洲舞蹈充满活力，但不乏精妙之处，需要舞者有很强的力量和控制能力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"细致;敏锐","en":"Subtlety is the ability to notice and recognize things which are not obvious, especially small differences between things.","ex":{"en":"She analyses herself with great subtlety.","cn":"她非常敏锐地分析自己。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"诡秘;狡猾;巧妙","en":"Subtlety is the ability to use indirect methods to achieve something, rather than doing something that is obvious.","ex":{"en":"They had obviously been hoping to approach the topic with more subtlety.","cn":"他们显然一直希望能更巧妙地切入这一话题。"}}]},"media":{"uk":"media/uk/subtlety__gb_1.mp3","us":"media/us/subtlety__us_1.mp3"},"examples":[{"en":"It's a thrilling movie even though it lacks subtlety.","cn":"这部电影虽说不算精巧，但还是扣人心弦的。"},{"en":"the subtleties of language","cn":"语言的微妙之处"}]},"suspicion":{"media":{"uk":"media/uk/suspicion__gb_1.mp3","us":"media/us/suspicion__us_1.mp3"},"oxford":{"phon":"səˈspɪʃn","pos":"noun","senses":[{"en":"a feeling that somebody has done something wrong, illegal or dishonest, even though you have no proof","cn":"怀疑；嫌疑","g":"[uncountable, countable]","ex":{"en":"They drove away slowly to avoid arousing suspicion.","cn":"他们缓缓驾车离去，以免引起怀疑。"}},{"en":"a feeling or belief that something is true, even though you have no proof","cn":"感觉；看法","g":"[countable]","ex":{"en":"I have a horrible suspicion that we've come to the wrong station.","cn":"我感觉不妙，我们可能来错车站了。"}},{"en":"the feeling that you cannot trust somebody/something","cn":"猜疑；怀疑；不放心","g":"[uncountable, countable]","ex":{"en":"Their offer was greeted with some suspicion.","cn":"他们的主动热情遭到一些猜疑。"}},{"en":"a small amount of something","cn":"少许；一点儿","g":"[singular]","lab":"formal","ex":{"en":"His mouth quivered in the suspicion of a smile.","cn":"他嘴唇微微一颤，露出一丝笑意。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"怀疑;疑心","en":"Suspicion or a suspicion is a belief or feeling that someone has committed a crime or done something wrong.","ex":{"en":"There was a suspicion that this runner attempted to avoid the procedures for dope testing","cn":"这名赛跑选手涉嫌有意逃避兴奋剂检验。"}},{"pos":"N-VAR 可变名词","cn":"疑心;疑忌;猜疑","en":"If there is suspicion of someone or something, people do not trust them or consider them to be reliable.","ex":{"en":"...the traditional British suspicion of psychotherapy","cn":"英国人传统上对心理疗法的猜忌"}},{"pos":"N-COUNT 可数名词","cn":"感觉;预感","en":"A suspicion is a feeling that something is probably true or is likely to happen.","ex":{"en":"I have a sneaking suspicion that they are going to succeed","cn":"我隐约觉得他们将要成功了。"}},{"pos":"N-SING 单数名词","cn":"些许;少量;一点","en":"A suspicion of something is a very small amount of it.","ex":{"en":"...large blooms of white with a suspicion of pale pink.","cn":"一朵朵略带淡粉色的大白花"}},{"pos":"","cn":"","en":"to point the finger of suspicion→see: ;"}]},"examples":[{"en":"Nobody who was near the scene of the crime is above suspicion.","cn":"犯罪现场附近的任何人都不能排除嫌疑。"},{"en":"They drove away slowly to avoid arousing suspicion.","cn":"他们缓缓驾车离去，以免引起怀疑。"}]},"supreme":{"oxford":{"phon":"suˈpriːm","pos":"adjective","senses":[{"en":"highest in rank or position","cn":"（级别或地位）最高的，至高无上的","ex":{"en":"the Supreme Commander of the armed forces","cn":"武装部队的最高统帅"}},{"en":"very great or the greatest in degree","cn":"（程度）很大的，最大的","ex":{"en":"to make the supreme sacrifice (= die for what you believe in)","cn":"作出最大牺牲（为信仰牺牲生命）"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最高的;至高无上的","en":"Supreme is used in the title of a person or an official group to indicate that they are at the highest level in a particular organization or system.","ex":{"en":"MacArthur was Supreme Commander for the allied powers in the Pacific.","cn":"麦克阿瑟将军曾是太平洋战区盟军的最高统帅。"}},{"pos":"ADJ 形容词","cn":"最大的;最多的","en":"You use supreme to emphasize that a quality or thing is very great.","ex":{"en":"Her approval was of supreme importance","cn":"她的认可是至关重要的。"}}]},"media":{"uk":"media/uk/supreme__gb_1.mp3","us":"media/us/supreme__us_1.mp3"},"examples":[{"en":"to make the supreme sacrifice (= die for what you believe in)","cn":"作出最大牺牲（为信仰牺牲生命）"},{"en":"It is an event in which she reigns supreme.","cn":"这个比赛项目她所向无敌。"}]},"sufficiency":{"oxford":{"phon":"səˈfɪʃnsi","pos":"noun","senses":[{"en":"an amount of something that is enough for a particular purpose","cn":"足量；充足","ex":{"en":"a sufficiency of well-trained teachers","cn":"足够的训练有素的教师"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"足量;充足","en":"Sufficiency of something is enough of that thing to achieve a purpose or to fulfil a need.","ex":{"en":"When foods from different plant sources are eaten together, deficiency in one is compensated for by sufficiency in another","cn":"多种蔬果类食物一起吃的话，一种食物所缺乏的营养会由另一种富含该营养的食物予以补足。"}}]},"media":{"uk":"media/uk/sufficiency__gb_1.mp3","us":"media/us/sufficiency__us_1.mp3"},"examples":[{"en":"The war has affected the country’s economic sufficiency.","cn":"战争已经影响到了这个国家的经济富足。"},{"en":"a sufficiency of raw materials","cn":"充足的原材料"}]},"sunbeam":{"media":{"uk":"media/uk/sunbeam__gb_1.mp3","us":"media/us/sunbeam__us_1.mp3"},"oxford":{"phon":"ˈsʌnbiːm","pos":"noun","senses":[{"en":"a stream of light from the sun","cn":"（一束）阳光"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阳光光束;一道日光","en":"A sunbeam is a ray of sunlight.","ex":{"en":"A sunbeam slants through the west window.","cn":"一束阳光从西边的窗户斜射进来。"}}]}},"sum":{"media":{"uk":"media/uk/sum__gb_1.mp3","us":"media/us/sum__us_1.mp3"},"oxford":{"phon":"sʌm","pos":"noun","senses":[{"en":"an amount of money","cn":"金额；款项","g":"[countable]","ex":{"en":"You will be fined the sum of £200.","cn":"你将被罚款 200 英镑。"}},{"en":"the number you get when you add two or more numbers together","cn":"和；总和；总数","g":"[countable, usually singular]","ex":{"en":"The sum of 7 and 12 is 19.","cn":"7 加 12 的和是 19。"}},{"en":"all of something, especially when you think that it is not very much","cn":"全部，一切（尤指自认为数量不大）","g":"[singular]","ex":{"en":"This is the sum of my achievements so far.","cn":"这就是我目前的全部成就。"}},{"en":"a simple problem that involves calculating numbers","cn":"算术；（数字的）简单计算","g":"[countable]","ex":{"en":"to do a sum in your head","cn":"做心算"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"款项;金额","en":"A sum of money is an amount of money.","ex":{"en":"Large sums of money were lost","cn":"损失了大笔钱财。"}},{"pos":"N-COUNT 可数名词","cn":"算术;简单计算","en":"A sum is a simple calculation in arithmetic.","ex":{"en":"I can't do my sums.","cn":"我算不出来。"}},{"pos":"N-SING 单数名词","cn":"和;总和;总数","en":"In mathematics, the sum of two numbers is the number that is obtained when they are added together.","ex":{"en":"The sum of all the angles of a triangle is 180 degrees.","cn":"三角形内角总和为 180 度。"}},{"pos":"N-SING 单数名词","cn":"全部;所有","en":"The sum of something is all of it.","ex":{"en":"'Public opinion' is only the sum of the views of thousands of people like yourself","cn":"“舆论”只是所有像你一样的成千上万人的意见的总和。"}},{"pos":"PHRASE 短语","cn":"总之;总而言之","en":"You use in sum to introduce a statement that briefly describes a situation.","ex":{"en":"In sum, the two countries are now true economic partners","cn":"总而言之，两国目前是真正的经济合作伙伴。"}},{"pos":"PHRASE 短语","cn":"个体相加不如集体的力量大;总体大于个体之和","en":"If you say that something is more than the sum of its parts or greater than the sum of its parts, you mean that it is better than you would expect from the individual parts, because the way they combine adds a different quality.","ex":{"en":"As individual members' solo careers have proved, each band was greater than the sum of its parts.","cn":"成员单飞后的发展证明，每个乐队的成员只有组合在一起才能创造出更大的成功。"}},{"pos":"","cn":"","en":"相关词组：sum up"}]},"examples":[{"en":"If I've got my sums right, I should be able to afford the rent.","cn":"要是我算对了的话，我应该负担得起这笔租金。"},{"en":"To sum up, there are three main ways of tackling the problem …","cn":"概括起来说，这一问题主要有三种解决办法 …"}]},"supervise":{"oxford":{"phon":"ˈsuːpəvaɪz","pos":"verb","senses":[{"en":"to be in charge of somebody/something and make sure that everything is done correctly, safely, etc.","cn":"监督；管理；指导；主管","ex":{"en":"to supervise building work","cn":"监理建筑工程"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"指导;监督","en":"If you supervise an activity or a person, you make sure that the activity is done correctly or that the person is doing a task or behaving correctly.","ex":{"en":"University teachers have refused to supervise students' examinations","cn":"大学教师拒绝监考。"}},{"pos":"VERB 动词","cn":"管理;主管","en":"If you supervise a place where work is done, you ensure that the work there is done properly.","ex":{"en":"He makes the wines and supervises the vineyards","cn":"他酿酒并管理葡萄园。"}}]},"media":{"uk":"media/uk/supervise__gb_1.mp3","us":"media/us/supervise__us_1.mp3"},"examples":[{"en":"Very young children should not be left to play without supervision.","cn":"不能让幼儿在没人照看的情况下独自玩耍。"},{"en":"She supervised the children playing near the pool.","cn":"她照料着在水池附近玩的几个孩子。"}]},"sustains":{"lemma":"sustain"},"subjectivity":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a statement, report, attitude etc that is subjective is influenced by personal opinion and can therefore be unfair","cn":""},{"en":"existing only in your mind or imagination","cn":""}]},"examples":[{"en":"As a critic, he is far too subjective.","cn":"","src":"ld"},{"en":"a highly subjective point of view","cn":"","src":"ld"}],"media":{"uk":"media/uk/subjectivity__gb_1.mp3","us":"media/us/subjectivity__us_1.mp3"},"oxford":{"phon":"ˌsʌbdʒekˈtɪvəti","pos":"noun","senses":[{"en":"the fact of being influenced by personal ideas, opinions or feelings, rather than facts","cn":"主观性：受个人想法，观点或感受影响的事实，而不是事实","ex":{"en":"There is an element of subjectivity in her criticism.","cn":"她的批评带有一点主观性。"}},{"en":"the fact of existing in somebody's mind rather than the outside world","cn":"主观的（非现实世界的）","ex":{"en":"How do we overcome the subjectivity inherent in our being?","cn":"我们如何克服我们存在中固有的主观性？"}}]}},"subgroup":{"media":{"uk":"media/uk/subgroup__gb_1.mp3","us":"media/us/subgroup__us_1.mp3"},"oxford":{"phon":"ˈsʌbɡruːp","pos":"noun","senses":[{"en":"a smaller group made up of members of a larger group","cn":"小组；（团体中的）部分","ex":{"en":"population subgroups","cn":"人口亚群"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小分组;小分队;小团体;小集团","en":"A subgroup is a group that is part of a larger group.","ex":{"en":"The Action Group worked by dividing its tasks among a large number of subgroups.","cn":"行动小组通过将其任务分配给多个下属小组来完成工作。"}}]}},"superiority":{"media":{"uk":"media/uk/superiority__gb_1.mp3","us":"media/us/superiority__us_1.mp3"},"oxford":{"phon":"suːˌpɪəriˈɒrəti","pos":"noun","senses":[{"en":"the state or quality of being better, more powerful, greater, etc. than others","cn":"优越（性）；优势","ex":{"en":"the superiority of this operating system","cn":"这种操作系统的优越性"}},{"en":"behaviour that shows that you think you are better than other people","cn":"优越感；神气活现的样子；盛气凌人的行为","ex":{"en":"He spoke with an air of superiority.","cn":"他说话时摆出一副高人一等的样子。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(战争或冲突中具有的)优势;优越(性)","en":"If one side in a war or conflict has superiority, it has an advantage over its enemy, for example because it has more soldiers or better equipment.","ex":{"en":"The US will need a three-to-one superiority in forces to be sure of a successful attack","cn":"美国需要在军力上具有3比1的优势才能确保进攻胜利。"}}]},"examples":[{"en":"the superiority of this operating system","cn":"这款操作系统的优越性"},{"en":"to have naval/air superiority (= more ships/planes than the enemy)","cn":"有海上/空中优势"}]},"sun":{"media":{"uk":"media/uk/sun__gb_1.mp3","us":"media/us/sun__us_1.mp3"},"oxford":{"phon":"sʌn","pos":"noun","senses":[{"en":"the star that shines in the sky during the day and gives the earth heat and light","cn":"太阳；日","g":"[singular]","lab":"North American English","ex":{"en":"The sun was shining and birds were singing.","cn":"阳光照耀，鸟儿啼啭。"}},{"en":"the light and heat from the sun","cn":"太阳的光和热；阳光；日光","g":"[singular, uncountable]","ex":{"en":"the warmth of the afternoon sun","cn":"下午温暖的阳光"}},{"en":"any star around which planets move","cn":"恒星","g":"[countable]","lab":"specialist"},{"en":"Sunday","cn":"星期日；星期天","pos":"abbreviation"},{"en":"to sit or lie in a place where the sun is shining on you","cn":"晒太阳","ex":{"en":"We lay sunning ourselves on the deck.","cn":"我们躺在甲板上晒太阳。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"太阳;日","en":"The sun is the ball of fire in the sky that the Earth goes round, and that gives us heat and light.","ex":{"en":"The sun was now high in the southern sky","cn":"太阳正高挂在南边的天空上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"太阳的光和热;日光;阳光","en":"You refer to the light and heat that reach us from the sun as the sun .","ex":{"en":"Dena took them into the courtyard to sit in the sun","cn":"德娜带他们到院子里晒太阳。"}},{"pos":"VERB 动词","cn":"晒太阳","en":"If you are sunning yourself, you are sitting or lying in a place where the sun is shining on you.","ex":{"en":"She was last seen sunning herself in a riverside park.","cn":"最后一次有人看见她时，她正在河边公园晒太阳。"}},{"pos":"N-COUNT 可数名词","cn":"恒星","en":"A sun is any star which has planets going around it."},{"pos":"PHRASE 短语","cn":"天下万物;世上一切;全世界","en":"Everything under the sun means a very great number of things. Anything under the sun means anything at all.","ex":{"en":"We sat there for hours talking about everything under the sun","cn":"我们在那儿坐了几个小时，谈天说地。"}},{"pos":"","cn":"","en":"a place in the sun→see: ;"}]},"examples":[{"en":"They've booked a holiday in the sun (= in a place where it is warm and the sun shines a lot).","cn":"他们已经预订好了去阳光充足的地方度假。"},{"en":"I was driving westwards and I had the sun in my eyes (= the sun was shining in my eyes).","cn":"我驱车向西行驶，阳光直晃眼。"}]},"supposed":{"media":{"uk":"media/uk/supposed__gb_1.mp3","us":"media/us/supposed__us_1.mp3"},"oxford":{"phon":"səˈpəʊzd","pos":"adjective","senses":[{"en":"used to show that you think that a claim, statement or way of describing somebody/something is not true or correct, although it is generally believed to be","cn":"误以为的；误信的；所谓的","ex":{"en":"This is the opinion of the supposed experts.","cn":"这是所谓专家的看法。"}}]},"collins":{"senses":[{"pos":"PHR-MODAL 情态动词短语","cn":"(按计划或期望)应当，应该，须","en":"If you say that something is supposed to happen, you mean that it is planned or expected. Sometimes this use suggests that the thing does not really happen in this way.","ex":{"en":"He produced a handwritten list of nine men he was supposed to kill","cn":"他拿出了一份手写的名单，上面列有 9 个他应该要杀死的人。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"本应该(发生而没有发生)","en":"If something was supposed to happen, it was planned or intended to happen, but did not in fact happen.","ex":{"en":"He was supposed to go back to Bergen on the last bus, but of course the accident prevented him","cn":"他本来要乘最后一班汽车回卑尔根，但当然，这起事故使他没能回去。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"认为;觉得;相信","en":"If you say that something is supposed to be true, you mean that people say it is true but you do not know for certain that it is true.","ex":{"en":"'The Whipping Block' has never been published, but it's supposed to be a really good poem","cn":"《鞭笞刑具》还从未发表过，但大家认为它是一首真正的好诗。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"(表示恼怒)还是，竟","en":"You can use 'be supposed to' to express annoyance at someone's ideas, or because something is not happening in the proper way.","ex":{"en":"You're supposed to be my friend!","cn":"你还是我朋友呢！"}},{"pos":"ADJ 形容词","cn":"误以为的;误信的;所谓的","en":"You can use supposed to suggest that something that people talk about or believe in may not in fact exist, happen, or be as it is described.","ex":{"en":"Not all indigenous regimes were willing to accept the supposed benefits of British trade.","cn":"并非所有当地的政权都愿意接受与英国贸易的所谓好处。"}}]},"examples":[{"en":"When did this supposed accident happen?","cn":"这场所谓的事故发生在什么时候？"},{"en":"This is the opinion of the supposed experts.","cn":"这是所谓专家的看法。"}],"base":"suppose"},"suitable":{"media":{"uk":"media/uk/suitable__gb_1.mp3","us":"media/us/suitable__us_1.mp3"},"oxford":{"phon":"ˈsuːtəbl","pos":"adjective","senses":[{"en":"right or appropriate for a particular purpose or occasion","cn":"合适的；适宜的；适当的；适用的","ex":{"en":"a suitable candidate","cn":"合适的人选"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合适的;适宜的;适当的","en":"Someone or something that is suitable for a particular purpose or occasion is right or acceptable for it.","ex":{"en":"Employers usually decide within five minutes whether someone is suitable for the job","cn":"雇主通常在 5 分钟内就能决定一个人是否适合这份工作。"}}]},"examples":[{"en":"I don't have anything suitable to wear for the party.","cn":"我没有适合在聚会上穿的衣服。"},{"en":"Would now be a suitable moment to discuss my report?","cn":"现在讨论我的报告合适不合适？"}]},"surgery":{"oxford":{"phon":"ˈsɜːdʒəri","pos":"noun","senses":[{"en":"medical treatment of injuries or diseases that involves cutting open a person’s body and often removing or replacing some parts; the branch of medicine connected with this treatment","cn":"外科手术；外科学","g":"[uncountable]","lab":"British English","ex":{"en":"major/minor surgery","cn":"大手术；小手术"}},{"en":"a place where a doctor, dentist or vet sees patients","cn":"诊室；门诊处","g":"[countable]","lab":"British English","ex":{"en":"a doctor’s/dentist’s/vet's surgery","cn":"医生的／牙医的／兽医的诊室"}},{"en":"the time during which a doctor, dentist or vet is available to see patients","cn":"应诊时间","g":"[uncountable, countable]","lab":"British English","ex":{"en":"morning/afternoon/evening surgery","cn":"上午／下午／晚间应诊时间"}},{"en":"a time when people can meet their Member of Parliament to ask questions and get help","cn":"（议员的）接待时间","g":"[countable]","lab":"British English","ex":{"en":"a constituency surgery","cn":"接待选区选民时间"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"外科手术","en":"Surgery is medical treatment in which someone's body is cut open so that a doctor can repair, remove, or replace a diseased or damaged part.","ex":{"en":"His father has just recovered from heart surgery","cn":"他父亲刚刚从心脏外科手术中康复过来。"}},{"pos":"N-COUNT 可数名词","cn":"诊疗室;诊所","en":"A surgery is the room or house where a doctor or dentist works.","ex":{"en":"Bill was in the doctor's surgery demanding to know what was wrong with him.","cn":"比尔在医生的诊疗室里想要知道自己到底得了什么病。"}},{"pos":"N-COUNT 可数名词","cn":"应诊时间","en":"A doctor's surgery is the period of time each day when a doctor sees patients at his or her surgery.","ex":{"en":"His surgery always ends at eleven.","cn":"他的出诊时间总是到11点结束。"}},{"pos":"N-COUNT 可数名词","cn":"(议员对公众的)接待时间","en":"In Britain, when someone such as an MP or a local councillor holds a surgery, they go to an office where members of the public can come and talk to them about problems or issues that concern them."},{"pos":"N-COUNT 可数名词","cn":"手术室","en":"A surgery is the room in a hospital where surgeons operate on their patients."}]},"media":{"uk":"media/uk/surgery__gb_1.mp3","us":"media/us/surgery__us_1.mp3"},"examples":[{"en":"He will require surgery on his left knee.","cn":"他的左膝需要做手术。"},{"en":"Is there a surgery this evening?","cn":"今晚有没有医生应诊？"}]},"subjective":{"oxford":{"phon":"səbˈdʒektɪv","pos":"adjective","senses":[{"en":"based on your own ideas or opinions rather than facts and therefore sometimes unfair","cn":"主观的（非客观的）","ex":{"en":"a highly subjective point of view","cn":"非常主观的看法"}},{"en":"existing in somebody’s mind rather than in the outside world","cn":"主观的（非现实世界的）"},{"en":"the subjective case is the one which is used for the subject of a sentence","cn":"主语的；主格的","g":"[only before noun]","lab":"grammar"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"主观的;非客观的","en":"Something that is subjective is based on personal opinions and feelings rather than on facts.","ex":{"en":"We know that taste in art is a subjective matter","cn":"我们知道艺术品位因人而异。"}}]},"media":{"uk":"media/uk/subjective__gb_1.mp3","us":"media/us/subjective__us_1.mp3"},"examples":[{"en":"People who are less subjectively involved are better judges.","cn":"主观因素介入愈少，愈能作出恰当的判断。"},{"en":"Everyone's opinion is bound to be subjective.","cn":"每个人的意见都必定是主观的。"}]},"suffered":{"lemma":"suffer"},"survive":{"oxford":{"phon":"səˈvaɪv","pos":"verb","senses":[{"en":"to continue to live or exist","cn":"生存；存活；继续存在","g":"[intransitive]","lab":"humorous","ex":{"en":"She was the last surviving member of the family.","cn":"她是这家人中仅存的一员。"}},{"en":"to continue to live or exist despite a dangerous event or time","cn":"幸存；幸免于难；艰难度过","g":"[transitive]","ex":{"en":"Her 5-year-old son miraculously survived the crash.","cn":"车祸中她 5 岁的儿子奇迹般生还。"}},{"en":"to live or exist longer than somebody/something","cn":"比…活（或存在）的时间长","g":"[transitive]","ex":{"en":"She survived her husband by ten years.","cn":"丈夫死后她又活了十年。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"生存;存活;幸存","en":"If a person or living thing survives in a dangerous situation such as an accident or an illness, they do not die.","ex":{"en":"...the sequence of events that left the eight pupils battling to survive in icy seas for over four hours","cn":"致使这 8 个小学生在冰冷的海水里挣扎求生四个多小时的一连串事件"}},{"pos":"VERB 动词","cn":"挺过;艰难度过","en":"If you survive in difficult circumstances, you manage to live or continue in spite of them and do not let them affect you very much.","ex":{"en":"On my first day here I thought, 'Ooh, how will I survive?'","cn":"我第一天到这儿时就想，“天哪，我怎么能挺过去呢?”"}},{"pos":"VERB 动词","cn":"幸存;幸免于难;留存","en":"If something survives, it continues to exist even after being in a dangerous situation or existing for a long time.","ex":{"en":"When the market economy is introduced, many factories will not survive","cn":"引入市场经济后，许多工厂将面临倒闭。"}},{"pos":"VERB 动词","cn":"比…活得久;比…长寿","en":"If you survive someone, you continue to live after they have died.","ex":{"en":"Most women will survive their spouses","cn":"大多数女性都比配偶长寿。"}}]},"media":{"uk":"media/uk/survive__gb_1.mp3","us":"media/us/survive__us_1.mp3"},"examples":[{"en":"Of the six people injured in the crash, only two survived.","cn":"因这次撞车事故受伤的六人中，只有两人活了下来。"},{"en":"He survived as party leader until his second election defeat.","cn":"直至第二次参选失败他才不再担任党的领导人。"}]},"suggesting":{"lemma":"suggest","media":{"uk":"media/uk/suggest__gb_1.mp3","us":"media/us/suggest__us_1.mp3"}},"successfully":{"oxford":{"phon":"səkˈsesfəli","pos":"adverb","senses":[{"en":"in a way that achieves your aims or what was intended","cn":"达到目的地；有成效地","ex":{"en":"She had already successfully completed these courses.","cn":"她已经顺利修完这些课程。"}}]},"media":{"uk":"media/uk/successfully__gb_1.mp3","us":"media/us/successfully__us_1.mp3"},"examples":[{"en":"The operation was successful.","cn":""},{"en":"a highly successful (= very successful ) meeting","cn":""}]},"suppression":{"media":{"uk":"media/uk/suppression__gb_1.mp3","us":"media/us/suppression__us_1.mp3"},"oxford":{"phon":"səˈpreʃn","pos":"noun","senses":[{"en":"the act of suppressing something","cn":"镇压；压制；抑制","ex":{"en":"the suppression of a rebellion","cn":"对叛乱的镇压"}}]},"examples":[{"en":"the suppression of a rebellion","cn":"对叛乱的镇压"},{"en":"the suppression of emotion","cn":"对感情的抑制"}]},"sustained":{"oxford":{"phon":"səˈsteɪnd","pos":"adjective","senses":[{"en":"continuing for a period of time without becoming less","cn":"持续的；维持不变的","ex":{"en":"a period of sustained economic growth","cn":"经济持续增长的时期"}}]},"media":{"uk":"media/ldoce/hwd/bre/9/brelasdesustained.mp3","us":"media/ldoce/hwd/ame/a/amelasdesustained.mp3"},"examples":[{"en":"a period of sustained economic development","cn":"经济持续发展的时期"},{"en":"a sustained attack on the government","cn":"对政府的不断攻击"}],"base":"sustain"},"substantive":{"media":{"uk":"media/uk/substantive__gb_1.mp3","us":"media/us/substantive__us_1.mp3"},"oxford":{"phon":"səbˈstæntɪv","pos":"adjective","senses":[{"en":"dealing with real, important or serious matters","cn":"实质性的；本质上的；重大的；严肃认真的","ex":{"en":"substantive issues","cn":"实质性问题"}},{"en":"a noun","cn":"名词","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"本质上的;重大的;实质性的","en":"Substantive negotiations or issues deal with the most important and central aspects of a subject.","ex":{"en":"They plan to meet again in Rome very soon to begin substantive negotiations.","cn":"他们计划不久在罗马再次会晤以开始实质性的谈判。"}}]},"examples":[{"en":"The report concluded that no substantive changes were necessary.","cn":"报告的结论是，无须作任何重大变更。"},{"en":"substantive issues","cn":"实质性问题"}]},"succeeding":{"lemma":"succeed","media":{"uk":"media/uk/succeed__gb_1.mp3","us":"media/us/succeed__us_1.mp3"}},"substantial":{"media":{"uk":"media/uk/substantial__gb_1.mp3","us":"media/us/substantial__us_1.mp3"},"oxford":{"phon":"səbˈstænʃl","pos":"adjective","senses":[{"en":"large in amount, value or importance","cn":"大量的；价值巨大的；重大的","ex":{"en":"substantial sums of money","cn":"大笔大笔的钱"}},{"en":"large and solid; strongly built","cn":"大而坚固的；结实的；牢固的","g":"[usually before noun]","lab":"formal","ex":{"en":"a substantial house","cn":"结实的房子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"大量的;相当程度的;重大的","en":"Substantial means large in amount or degree. →see usage note at:","ex":{"en":"The party has just lost office and with it a substantial number of seats","cn":"该党刚刚竞选失利，同时还失去了许多席位。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(建筑物)大而坚固的，结实的，牢固的","en":"A substantial building is large and strongly built.","ex":{"en":"...those fortunate enough to have a fairly substantial property to sell.","cn":"那些有相当多的固定资产可出售的幸运儿"}}]},"examples":[{"en":"Substantial numbers of people support the reforms.","cn":"相当多的人支持这些改革措施。"},{"en":"He ate a substantial breakfast.","cn":"他吃了一顿丰盛的早餐。"}]},"surroundings":{"media":{"uk":"media/uk/surroundings__gb_1.mp3","us":"media/us/surroundings__us_1.mp3"},"oxford":{"phon":"səˈraʊndɪŋz","pos":"noun","senses":[{"en":"everything that is around or near somebody/something","cn":"环境","ex":{"en":"to work in pleasant surroundings","cn":"在愉快的环境中工作"}}]},"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"环境","en":"When you are describing the place where you are at the moment, or the place where you live, you can refer to it as your surroundings .","ex":{"en":"Schumacher adapted effortlessly to his new surroundings.","cn":"舒马赫非常轻松地适应了新环境。"}}]},"examples":[{"en":"The buildings have been designed to blend in with their surroundings.","cn":"这些建筑物设计巧妙，与周围环境浑然一体。"},{"en":"to work in pleasant surroundings","cn":"在愉快的环境中工作"}]},"supper":{"media":{"uk":"media/uk/supper__gb_1.mp3","us":"media/us/supper__us_1.mp3"},"oxford":{"phon":"ˈsʌpə(r)","pos":"noun","senses":[{"en":"the last meal of the day, either a main meal, usually smaller and less formal than dinner, or a snack eaten before you go to bed","cn":"晚饭；晚餐；夜宵","lab":"British English","ex":{"en":"I'll do my homework after supper.","cn":"晚饭后我要做家庭作业。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"晚餐;晚饭","en":"Some people refer to the main meal eaten in the early part of the evening as supper .","ex":{"en":"Some guests like to dress for supper.","cn":"一些客人喜欢穿礼服去赴晚宴。Y See Usage Note at meal. 见 meal 的用法说明"}},{"pos":"N-VAR 可变名词","cn":"夜宵;宵夜","en":"Supper is a simple meal eaten just before you go to bed at night.","ex":{"en":"She gives the children their supper, then puts them to bed.","cn":"她让孩子们吃了点夜宵，然后让他们上床睡觉。"}},{"pos":"PHRASE 短语","cn":"打点;疏通","en":"If someone has to sing for their supper, they have to do a job before they are allowed to do something they want to do.","ex":{"en":"They would have to 'sing for their supper' during the exhausting official round of duties.","cn":"他们不得不在那些耗人精力的官方手续的办理过程中进行疏通。"}}]},"examples":[{"en":"I'll do my homework after supper.","cn":"晚饭后我要做家庭作业。"},{"en":"We'll have an early supper tonight.","cn":"今天我们要早点吃晚饭。"}]},"suppose":{"media":{"uk":"media/uk/suppose__gb_1.mp3","us":"media/us/suppose__us_1.mp3"},"oxford":{"phon":"səˈpəʊz","pos":"verb","senses":[{"en":"to think or believe that something is true or possible (based on the knowledge that you have)","cn":"（根据所知）认为，推断，料想","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"Getting a visa isn't as simple as you might suppose.","cn":"办签证不像你想的那么容易。"}},{"en":"used to make a statement, request or suggestion less direct or less strong","cn":"（婉转表达）我看，要我说，要不","g":"[intransitive, transitive]","ex":{"en":"I could take you in the car, I suppose (= but I don't really want to).","cn":"要不你坐我的车。"}},{"en":"to pretend that something is true; to imagine what would happen if something were true","cn":"假定；假设；设想","g":"[transitive]","lab":"formal","ex":{"en":"Suppose flights are fully booked on that day—which other day could we go?","cn":"假定那天的航班都订满了，我们还可以在哪天走呢？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"假定;假设;设想","en":"You can use suppose or supposing before mentioning a possible situation or action. You usually then go on to consider the effects that this situation or action might have.","ex":{"en":"Suppose someone gave you an egg and asked you to describe exactly what was inside","cn":"假设有人给了你一枚鸡蛋并要你准确描述鸡蛋里面有什么。"}},{"pos":"VERB 动词","cn":"(根据所知)认为，推断，料想","en":"If you suppose that something is true, you believe that it is probably true, because of other things that you know.","ex":{"en":"The policy is perfectly clear and I see no reason to suppose that it isn't working","cn":"这项政策非常清楚明了，我没有理由认为它不会奏效。"}},{"pos":"PHRASE 短语","cn":"我看;要我说;我想","en":"You can say 'I suppose' when you want to express slight uncertainty.","ex":{"en":"I get a bit uptight these days. Hormones, I suppose","cn":"这些天我有点焦躁。我看是荷尔蒙在作怪。"}},{"pos":"PHRASE 短语","cn":"(表示不耐烦或有些生气)我想，我看","en":"You can say 'I suppose' or 'I don't suppose' before describing someone's probable thoughts or attitude, when you are impatient or slightly angry with them.","ex":{"en":"I suppose you think you're funny","cn":"我想你认为自己很好笑。"}},{"pos":"PHRASE 短语","cn":"(用于婉转地提出请求)","en":"You can say 'I don't suppose' as a way of introducing a polite request.","ex":{"en":"I don't suppose you could tell me where James Street is could you?","cn":"你能否告诉我詹姆斯街在哪儿？"}},{"pos":"PHRASE 短语","cn":"(用于询问意见)你认为，你觉得","en":"You can use 'do you suppose' to introduce a question when you want someone to give their opinion about something, although you know that they are unlikely to have any more knowledge or information about it than you.","ex":{"en":"Do you suppose he was telling the truth?","cn":"你认为他说的是实话吗？"}},{"pos":"PHRASE 短语","cn":"(用于礼貌地建议或请求)","en":"You can use 'do you suppose' as a polite way of suggesting or requesting that someone does something.","ex":{"en":"Do you suppose we could get together for a little chat sometime soon?","cn":"我们最近能抽空聚在一起聊上几句吗？"}}]},"examples":[{"en":"Suppose flights are fully booked on that day — which other day could we go?","cn":"假定那天的航班都订满了，我们还可以在哪天走呢？"},{"en":"I haven't seen it myself, but it's supposed to be a great movie.","cn":"这部电影我没看过，不过人们普遍认为很不错。"}]},"supplying":{"lemma":"supply","media":{"uk":"media/uk/supply__gb_1.mp3","us":"media/us/supply__us_1.mp3"}},"suit":{"media":{"img":["media/pic/clothes_suit_comp.jpg","media/thumb/suit.jpg"],"uk":"media/uk/suit__gb_1.mp3","us":"media/us/suit__us_1.mp3"},"oxford":{"phon":"suːt","pos":"noun","senses":[{"en":"a set of clothes made of the same cloth, including a jacket and trousers or a skirt","cn":"西服；西装；套装","ex":{"en":"She was wearing a grey business suit.","cn":"她穿着一套灰色西装。"}},{"en":"a set of clothing worn for a particular activity","cn":"（从事特定活动时穿的）成套服装","ex":{"en":"a diving suit","cn":"潜水服"}},{"en":"any of the four sets that form a pack of cards","cn":"（扑克牌中）所有同花色的牌","ex":{"en":"The suits are called hearts, clubs, diamonds and spades.","cn":"扑克牌的四种花色分别叫红桃、梅花、方块和黑桃。"}},{"en":"a claim or complaint against somebody that a person or an organization can make in court","cn":"诉讼；起诉","ex":{"en":"to file/bring a suit against somebody","cn":"控告某人"}},{"en":"a person with an important job as a manager in a company or organization, especially one who is thought to work mainly with financial matters or to have a lot of influence","cn":"（具影响力的）高级管理人员（尤指财务方面的）","g":"[usually plural]","lab":"informal","ex":{"en":"We can leave the detailed negotiations to the suits.","cn":"我们可以把细节的谈判交给公司经理。"}},{"en":"to be convenient or useful for somebody","cn":"对（某人）方便；满足（某人）需要；合（某人）心意","ex":{"en":"If we met at two, would that suit you?","cn":"我们两点钟见面，你方便吗？"},"pos":"verb"},{"en":"to make you look attractive","cn":"相配；合身","ex":{"en":"Blue suits you. You should wear it more often.","cn":"你适合穿蓝色，你该多穿蓝色衣服。"},"pos":"verb"},{"en":"to be right or good for somebody/something","cn":"适合；适宜；有利于","lab":"especially British English","ex":{"en":"This hot weather doesn't suit me.","cn":"天这么热，我真受不了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(男士的)一套外衣，套装，西装","en":"A man's suit consists of a jacket, trousers, and sometimes a waistcoat, all made from the same fabric.","ex":{"en":"...a dark pinstriped business suit.","cn":"黑色的细条纹正装"}},{"pos":"N-COUNT 可数名词","cn":"(女士的)一套外衣，套装，套裙","en":"A woman's suit consists of a jacket and skirt, or sometimes trousers, made from the same fabric.","ex":{"en":"I was wearing my tweed suit.","cn":"我穿着我的花呢套装。"}},{"pos":"N-COUNT 可数名词","cn":"(从事特定活动时穿的)成套服装","en":"A particular type of suit is a piece of clothing that you wear for a particular activity.","ex":{"en":"...a completely revolutionary atmospheric diving suit.","cn":"令人耳目一新的大气压潜水服"}},{"pos":"VERB 动词","cn":"对…方便;满足…需要;合…心意","en":"If something suits you, it is convenient for you or is the best thing for you in the circumstances.","ex":{"en":"They will only release information if it suits them","cn":"他们只会发布对他们有利的信息。"}},{"pos":"VERB 动词","cn":"讨…喜欢;中…的意","en":"If something suits you, you like it.","ex":{"en":"I don't think a sedentary life would altogether suit me.","cn":"我认为长期伏案的生活一点也不适合我。"}},{"pos":"VERB 动词","cn":"(服装、风格、颜色)使显得漂亮，与…相配;适合","en":"If a piece of clothing or a particular style or colour suits you, it makes you look attractive.","ex":{"en":"Green suits you.","cn":"绿色很配你。"}},{"pos":"VERB 动词","cn":"随自己的意愿;随性子;自便","en":"If you suit yourself, you do something just because you want to do it, without bothering to consider other people.","ex":{"en":"These large institutions make — and change—the rules to suit themselves","cn":"这些大机构总是随意制定规定，而且说变就变。"}},{"pos":"N-COUNT 可数名词","cn":"诉讼;讼案","en":"In a court of law, a suit is a case in which someone tries to get a legal decision against a person or company, often so that the person or company will have to pay them money for having done something wrong to them.","ex":{"en":"Up to 2,000 former employees have filed personal injury suits against the company","cn":"多达 2,000 名旧职员以个人伤害为由向该公司提起诉讼。"}},{"pos":"N-COUNT 可数名词","cn":"(扑克牌中的)同花色牌，花色","en":"A suit is one of the four types of card in a set of playing cards. These are hearts, diamonds, clubs, and spades."},{"pos":"PHRASE 短语","cn":"跟着做;照着做;仿效","en":"If people follow suit, they do the same thing that someone else has just done.","ex":{"en":"Efforts to persuade the remainder to follow suit have continued.","cn":"说服其余人跟着效仿的努力仍在继续。"}},{"pos":"PHRASE 短语","cn":"对…非常方便;很合…心意","en":"If something suits you down to the ground, you like it a great deal or find it very convenient.","ex":{"en":"Their London house suits them down to the ground.","cn":"他们在伦敦的房子很合他们心意。"}},{"pos":"","cn":"","en":"相关词组：suit up"}]},"examples":[{"en":"The suits are called hearts, clubs, diamonds and spades.","cn":"扑克牌的四种花色分别叫红桃、梅花、方块和黑桃。"},{"en":"He can be very helpful, but only when it suits him.","cn":"有时候他非常肯帮忙，不过那得合他心意。"}]},"sugar":{"media":{"uk":"media/uk/sugar__gb_1.mp3","us":"media/us/sugar__us_1.mp3"},"oxford":{"phon":"ˈʃʊɡə(r)","pos":"noun","senses":[{"en":"a sweet substance, often in the form of white or brown crystals, made from the juices of various plants, used in cooking or to make tea, coffee, etc. sweeter","cn":"食糖","g":"[uncountable]","ex":{"en":"Do you take sugar (= have it in your tea, coffee, etc.)?","cn":"您放糖吗？"}},{"en":"the amount of sugar that a small spoon can hold or that is contained in a small cube, added to tea, coffee, etc.","cn":"一匙糖；一块方糖","g":"[countable]","ex":{"en":"How many sugars do you take in coffee?","cn":"您在咖啡里放几块方糖？"}},{"en":"any of various sweet substances that are found naturally in plants, fruit, etc.","cn":"（植物、水果等所含的）糖","g":"[countable, usually plural]","lab":"specialist","ex":{"en":"fruit sugars","cn":"果糖"}},{"en":"a way of addressing somebody that you like or love","cn":"（爱称）亲爱的，宝贝儿","g":"[uncountable]","lab":"informal, especially North American English，，","ex":{"en":"See you later, sugar.","cn":"回头见，亲爱的。"}},{"en":"to add sugar to something; to cover something in sugar","cn":"在…中加糖；在…上撒糖；给…裹上糖衣","pos":"verb"},{"en":"used to show that you are annoyed when you do something stupid or when something goes wrong (to avoid saying ‘shit’)","cn":"（做了蠢事或出现差错时表示懊恼，用作 shit 的委婉语）哎呀，真是的","ex":{"en":"Oh sugar! I've forgotten my book!","cn":"哎呀！我忘记带书了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"食糖","en":"Sugar is a sweet substance that is used to make food and drinks sweet. It is usually in the form of small white or brown crystals.","ex":{"en":"...bags of sugar","cn":"几袋食糖"}},{"pos":"N-COUNT 可数名词","cn":"一匙糖;一块方糖","en":"If someone has one sugar in their tea or coffee, they have one small spoon of sugar or one sugar lump in it.","ex":{"en":"How many sugars do you take?","cn":"你加几勺糖？"}},{"pos":"VERB 动词","cn":"给…加糖;在…中加糖","en":"If you sugar food or drink, you add sugar to it.","ex":{"en":"He sat down and sugared and stirred his coffee.","cn":"他坐下来，在咖啡中加糖并搅拌。"}},{"pos":"N-COUNT 可数名词","cn":"(食物中所含的)糖，糖分","en":"Sugars are substances that occur naturally in food. When you eat them, the body converts them into energy.","ex":{"en":"Plants produce sugars and starch to provide themselves with energy.","cn":"植物产生糖和淀粉来为自身提供能量。"}},{"pos":"N-VOC 称呼名词","cn":"宝贝;亲爱的;心肝儿","en":"If one person knows another person very well and likes them a lot, they sometimes call them sugar .","ex":{"en":"I know how to make you feel better, sugar. I'll tell you a story.","cn":"宝贝，我知道怎么能让你感觉好些，我给你讲个故事。"}},{"pos":"","cn":"","en":"to sugar the pill→see: ;"}]},"examples":[{"en":"How many sugars do you take in coffee?","cn":"您在咖啡里放几块方糖？"},{"en":"Oh sugar! I've forgotten my book!","cn":"哎呀！我忘记带书了！"}]},"supporters":{"lemma":"supporter"},"sung":{"lemma":"sing","media":{"uk":"media/uk/sung__gb_1.mp3","us":"media/us/sung__us_1.mp3"}},"surely":{"media":{"uk":"media/uk/surely__gb_1.mp3","us":"media/us/surely__us_1.mp3"},"oxford":{"phon":"ˈʃʊəli","pos":"adverb","senses":[{"en":"used to show that you are almost certain of what you are saying and want other people to agree with you","cn":"（对自己的话很有把握，并希望他人同意）想必","ex":{"en":"Surely we should do something about it?","cn":"我们总得为此想个办法吧？"}},{"en":"used with a negative to show that something surprises you and you do not want to believe it","cn":"（用于否定句，表示难以置信）","ex":{"en":"Surely you don't think I was responsible for this?","cn":"你一定不会以为这是我的责任吧？"}},{"en":"without doubt; certainly","cn":"无疑；必定","lab":"formal","ex":{"en":"He knew that if help did not arrive soon they would surely die.","cn":"他知道，如果救援不能很快到，他们必死无疑。"}},{"en":"used to say ‘yes’ to somebody or to agree to something","cn":"（表示肯定或同意）当然","lab":"old-fashioned, North American English, informal，，，，"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"想必;当然","en":"You use surely to emphasize that you think something should be true, and you would be surprised if it was not true.","ex":{"en":"You're an intelligent woman, surely you realize by now that I'm helping you","cn":"你是个聪明的女人，想必你现在明白了我是在帮你。"}},{"pos":"ADV 副词","cn":"无疑;必定","en":"If something will surely happen or is surely the case, it will definitely happen or is definitely the case.","ex":{"en":"He knew that under the surgeon's knife he would surely die","cn":"他知道他必定会死在外科医生刀下。"}},{"pos":"PHRASE 短语","cn":"缓慢但确定地;稳扎稳打地","en":"If you say that something is happening slowly but surely, you mean that it is happening gradually but it is definitely happening.","ex":{"en":"Slowly but surely she started to fall in love with him","cn":"虽然过程缓慢，但她无疑开始爱上他了。"}}]},"examples":[{"en":"The meal was surely too expensive? (= that is my opinion. Don’t you agree?)","cn":"这顿饭不是太贵了吗？（我这样认为，你不同意吗？）"},{"en":"He knew that if help did not arrive soon they would surely die.","cn":"他知道，如果救援没能及早来到，他们必死无疑。"}]},"suggestions":{"lemma":"suggestion"},"substance":{"oxford":{"phon":"ˈsʌbstəns","pos":"noun","senses":[{"en":"a type of solid, liquid or gas that has particular qualities","cn":"物质；物品；东西","g":"[countable]","ex":{"en":"a sticky substance","cn":"一种黏乎乎的东西"}},{"en":"a drug, especially an illegal one","cn":"药物；（尤指）违禁药，毒品","g":"[countable]","ex":{"en":"illegal/controlled substances","cn":"非法/管制物质"}},{"en":"the quality of being based on facts or the truth","cn":"事实基础；根据","g":"[uncountable]","ex":{"en":"The commission's report gives substance to these allegations.","cn":"委员会的报告为这些说法提供了事实根据。"}},{"en":"the most important or main part of something","cn":"主旨；要点；实质；基本内容","g":"[uncountable]","ex":{"en":"Love and guilt form the substance of his new book.","cn":"他的新书主要讲爱情与罪孽。"}},{"en":"importance","cn":"重要性","g":"[uncountable]","lab":"formal","ex":{"en":"matters of substance","cn":"重大问题"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"物质;物品;东西","en":"A substance is a solid, powder, liquid, or gas with particular properties.","ex":{"en":"There's absolutely no regulation of cigarettes to make sure that they don't include poisonous substances","cn":"根本没有法规来确保香烟不含有毒物质。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"重要性;重大意义","en":"Substance is the quality of being important or significant.","ex":{"en":"It's questionable whether anything of substance has been achieved","cn":"是否已经取得了任何实质性进展还是个问题。"}},{"pos":"N-SING 单数名词","cn":"主旨;要点;实质;基本内容","en":"The substance of what someone says or writes is the main thing that they are trying to say.","ex":{"en":"The substance of his discussions doesn't really matter.","cn":"他讨论的要点实际上根本不重要。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"事实基础;根据","en":"If you say that something has no substance, you mean that it is not true.","ex":{"en":"There is no substance in any of these allegations.","cn":"这些指控都毫无根据。"}},{"pos":"PHRASE 短语","cn":"财力雄厚的;有权有势的；有影响力的","en":"A person of substance has a lot of money, power, or influence.","ex":{"en":"...mature men of substance.","cn":"有钱有势的成熟男人"}}]},"media":{"uk":"media/uk/substance__gb_1.mp3","us":"media/us/substance__us_1.mp3"},"examples":[{"en":"I agreed with what she said in substance , though not with every detail.","cn":"对于她所说的，虽然不是每个细节我都同意，但基本内容却是赞同的。"},{"en":"The commission's report gives substance to these allegations.","cn":"委员会的报告为这些说法提供了事实根据。"}]},"suited":{"media":{"uk":"media/uk/suited__gb_1.mp3","us":"media/us/suited__us_1.mp3"},"oxford":{"phon":"ˈsuːtɪd","pos":"adjective","senses":[{"en":"right or appropriate for somebody/something","cn":"合适；适宜；适当","ex":{"en":"She was ideally suited to the part of Eva Perón.","cn":"她演爱娃·庇隆这个角色再合适不过了。"}},{"en":"if two people are suited or well suited, they are likely to make a good couple","cn":"般配","ex":{"en":"Jo and I are very well suited.","cn":"我跟乔非常合得来。"}},{"en":"wearing a suit, or a suit of the type mentioned","cn":"穿西装的；穿…套装的","ex":{"en":"sober-suited city businessmen","cn":"城市里那些穿着素净的西装的生意人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"合适的;适宜的;适当的","en":"If something is well suited to a particular purpose, it is right or appropriate for that purpose. If someone is well suited to a particular job, they are right or appropriate for that job.","ex":{"en":"The area is well suited to road cycling as well as off-road riding","cn":"这个地方很适合举行自行车公路赛和越野赛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指情侣)般配的，志同道合的","en":"If two people, especially a man and a woman, are well suited, they are likely to have a successful relationship because they have similar personalities or interests.","ex":{"en":"They were well suited to each other.","cn":"他们俩是天造地设的一对。"}}]},"examples":[{"en":"She was ideally suited to the part of Eva Peron.","cn":"她演爱娃 · 庇隆这个角色再合适不过了。"},{"en":"This diet is suited to anyone who wants to lose weight fast.","cn":"这食谱适合每一个希望迅速减肥的人。"}],"base":"suit"},"sublime":{"media":{"uk":"media/uk/sublime__gb_1.mp3","us":"media/us/sublime__us_1.mp3"},"oxford":{"phon":"səˈblaɪm","pos":"adjective","senses":[{"en":"of very high quality or great beauty","cn":"极佳的；绝美的","ex":{"en":"sublime beauty","cn":"令人赞叹的美"}},{"en":"extreme, especially in a way that shows they are not aware of what they are doing or are not concerned about what happens because of it","cn":"极端的；极端而盲目的；一味的","lab":"formal, often disapproving，，","ex":{"en":"the sublime confidence of youth","cn":"年轻人目空一切的自信"}},{"en":"something that is sublime","cn":"崇高的事物；壮丽的景象；绝妙的东西","ex":{"en":"He transforms the most ordinary subject into the sublime.","cn":"经他一点化，极普通的题材也能变得令人叫绝。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"崇高的;壮丽的;宏伟的;令人赞叹的","en":"If you describe something as sublime, you mean that it has a wonderful quality that affects you deeply.","ex":{"en":"Sublime music floats on a scented summer breeze to the spot where you lie.","cn":"优美的音乐随着充满香气的夏日微风飘到了你躺着的地方。"}},{"pos":"ADJ 形容词","cn":"极端的;过分的;令人无比反感的","en":"You can use sublime to emphasize a quality that someone or something has, usually a quality that is undesirable or negative.","ex":{"en":"The administration's sublime incompetence is probably temporary","cn":"政府的极端软弱无能或许只是暂时的。"}}]},"examples":[{"en":"He transforms the most ordinary subject into the sublime.","cn":"经他一点化，极普通的题材也能变得令人叫绝。"},{"en":"She was sublimely unaware of the trouble she had caused.","cn":"她压根儿没察觉自己闹出了乱子。"}]},"sunday":{"media":{"uk":"media/uk/sunday__gb_1.mp3","us":"media/us/sunday__us_1.mp3"},"oxford":{"phon":"ˈsʌndeɪ","pos":"noun","senses":[{"en":"the day of the week after Saturday and before Monday, thought of as either the first or the last day of the week","cn":"星期日；星期天","g":"[countable, uncountable]","lab":"informal or North American English","ex":{"en":"It's Sunday today, isn't it?","cn":"今天是星期天，对吧？"}},{"en":"a newspaper published on a Sunday","cn":"每逢星期日出版的报纸；星期日报","g":"[countable, usually plural]","lab":"British English, informal，，"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"星期日;星期天","en":"Sunday is the day after Saturday and before Monday.","ex":{"en":"I thought we might go for a drive on Sunday","cn":"我想星期天我们可以开车去兜兜风。"}}]},"examples":[{"en":"We’re going to a match on Sunday.","cn":"我们星期天要去看场比赛。"},{"en":"Sunday nights are usually pretty quiet.","cn":"星期天晚上通常都很安静。"}]},"subordinate":{"oxford":{"phon":"səˈbɔːdɪnət","pos":"adjective","senses":[{"en":"having less power or authority than somebody else in a group or an organization","cn":"隶属的；从属的；下级的","ex":{"en":"In some societies women are still subordinate to men.","cn":"在一些社会中，妇女依然从属于男人。"}},{"en":"less important than something else","cn":"次要的","ex":{"en":"All other issues are subordinate to this one.","cn":"其他所有问题都没有这一问题重要。"}},{"en":"a person who has a position with less authority and power than somebody else in an organization","cn":"下级；部属","ex":{"en":"the relationship between subordinates and superiors","cn":"上下级关系"},"pos":"noun"},{"en":"to treat somebody/something as less important than somebody/something else","cn":"把…置于次要地位；使从属于","ex":{"en":"Safety considerations were subordinated to commercial interests.","cn":"商业利益置于安全考虑之上。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"下级;下属;部属","en":"If someone is your subordinate, they have a less important position than you in the organization that you both work for.","ex":{"en":"Haig tended not to seek guidance from subordinates","cn":"黑格不愿向下属请教。"}},{"pos":"ADJ 形容词","cn":"隶属的;从属的;下级的","en":"Someone who is subordinate to you has a less important position than you and has to obey you.","ex":{"en":"Sixty of his subordinate officers followed his example","cn":"他的60个下级官员都以他为榜样。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"次要的;其次的","en":"Something that is subordinate to something else is less important than the other thing.","ex":{"en":"It was an art in which words were subordinate to images.","cn":"这是一种形象胜于语言的艺术。"}},{"pos":"VERB 动词","cn":"把…置于次要地位;看轻","en":"If you subordinate something to another thing, you regard it or treat it as less important than the other thing.","ex":{"en":"He was both willing and able to subordinate all else to this aim.","cn":"为了这个目标他愿意并能够把其他一切都放在次要的位置。"}}]},"media":{"uk":"media/uk/subordinate__gb_1.mp3","us":"media/us/subordinate__us_1.mp3"},"examples":[{"en":"In many societies women are subordinate to men.","cn":"在许多社会中，妇女都从属于男人。"},{"en":"All other issues are subordinate to this one.","cn":"所有其他问题都没有这一问题重要。"}]},"surviving":{"lemma":"survive"},"suicide":{"oxford":{"phon":"ˈsuːɪsaɪd","pos":"noun","senses":[{"en":"the act of killing yourself deliberately","cn":"自杀","g":"[uncountable, countable]","ex":{"en":"to commit suicide","cn":"自杀"}},{"en":"a course of action that is likely to destroy your career, position in society, etc.","cn":"自杀性行为；自毁；自取灭亡的行为","g":"[uncountable]","ex":{"en":"It would have been political suicide for him to challenge the allegations in court.","cn":"假如当时他在法庭上质疑那些指控，那无异于自毁政治前程。"}},{"en":"a person who commits suicide","cn":"自杀者","g":"[countable]","lab":"formal"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"自杀","en":"People who commit suicide deliberately kill themselves because they do not want to continue living.","ex":{"en":"She tried to commit suicide on several occasions.","cn":"她自杀过好几次。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自杀性行为;自毁;自取灭亡的行为","en":"You say that people commit suicide when they deliberately do something which ruins their career or position in society.","ex":{"en":"Quite a few have committed social suicide by writing their boring memoirs","cn":"有一些人因为写那些枯燥无味的回忆录而毁了自己的社会形象。"}},{"pos":"ADJ 形容词","cn":"(袭击、任务、爆炸)自杀性的","en":"The people involved in a suicide attack, mission, or bombing do not expect to survive.","ex":{"en":"According to the army, the teenager said he was on a 'suicide mission' for the movement.","cn":"军方消息称，这个少年说他正在为这次运动执行“自杀性任务”。"}}]},"media":{"uk":"media/uk/suicide__gb_1.mp3","us":"media/us/suicide__us_1.mp3"},"examples":[{"en":"It would have been political suicide for him to challenge the allegations in court.","cn":"假如当时他在法庭上质疑那些指控，那无异于自毁政治前程。"},{"en":"a suicide bomber (= who expects to die while trying to kill other people with a bomb)","cn":"自杀式爆炸者"}]},"subtle":{"media":{"uk":"media/uk/subtle__gb_1.mp3","us":"media/us/subtle__us_1.mp3"},"oxford":{"phon":"ˈsʌtl","pos":"adjective","senses":[{"en":"not very obvious or easy to notice","cn":"不易察觉的；不明显的；微妙的","lab":"often approving","ex":{"en":"subtle colours/flavours/smells, etc.","cn":"淡淡的色彩、味道、气味等"}},{"en":"behaving or organized in a clever way, and using indirect methods, in order to achieve something","cn":"机智的；机巧的；狡猾的","ex":{"en":"I decided to try a more subtle approach.","cn":"我决定智取。"}},{"en":"good at noticing and understanding things","cn":"敏锐的；头脑灵活的","ex":{"en":"The job required a subtle mind.","cn":"那项工作需要一个头脑敏锐的人去做。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不易察觉的;不明显的;微妙的","en":"Something that is subtle is not immediately obvious or noticeable.","ex":{"en":"...the slow and subtle changes that take place in all living things","cn":"发生在所有生物身上的缓慢而细微的变化"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"机智的;机巧的;狡猾的","en":"A subtle person cleverly uses indirect methods to achieve something.","ex":{"en":"I even began to exploit him in subtle ways","cn":"我甚至开始巧妙地利用他。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"清淡的;隐约的;柔和的","en":"Subtle smells, tastes, sounds, or colours are pleasantly complex and delicate.","ex":{"en":"...subtle shades of brown.","cn":"淡棕色"}}]},"examples":[{"en":"Her version of events is subtly different from what actually happened.","cn":"她对事件的描述跟实际发生的情况有些微妙的出入。"},{"en":"Not very subtly, he raised the subject of money.","cn":"他没有拐弯抹角，直接提出了钱的问题。"}]},"sure":{"media":{"uk":"media/uk/sure__gb_1.mp3","us":"media/us/sure__us_1.mp3"},"oxford":{"phon":"ʃʊə(r)","pos":"adjective","senses":[{"en":"confident that you know something or that you are right","cn":"确信；确知；肯定；有把握","g":"[not before noun]","ex":{"en":"‘Is that John over there?’ ‘I'm not sure.’","cn":"“那边那个人是约翰吗？”“我说不准。”"}},{"en":"certain that you will receive something or that something will happen","cn":"一定，必定，无疑（将会得到或发生）","g":"[not before noun]","ex":{"en":"You're always sure of a warm welcome there.","cn":"到了那里你肯定会受到热烈欢迎。"}},{"en":"certain to do something or to happen","cn":"一定，必定，无疑（会做或会发生）","ex":{"en":"The exhibition is sure to be popular.","cn":"这一展览肯定受欢迎。"}},{"en":"that can be trusted or relied on","cn":"不容置疑的；确切的；可靠的；保险的","g":"[usually before noun]","ex":{"en":"It's a sure sign of economic recovery.","cn":"这是经济复苏的确切迹象。"}},{"en":"steady and confident","cn":"沉着自信的；胸有成竹的","g":"[usually before noun]","ex":{"en":"We admired her sure touch at the keyboard.","cn":"我们欣赏她在键盘前沉着自信的演奏风格。"}},{"en":"used to say ‘yes’ to somebody","cn":"（表示同意）当然","ex":{"en":"‘Will you get me my coat?’ ‘Sure, where is it?’","cn":"“你能给我拿件外套吗？”“当然，它在哪里？”"},"pos":"adverb"},{"en":"used to emphasize something that you are saying","cn":"（加强语气）确实，的确","ex":{"en":"Boy, it sure is hot.","cn":"嗬，这天儿可真热。"},"pos":"adverb"},{"en":"used to reply to somebody who has just thanked you for something","cn":"（回答他人的感谢）不用客气，应该的","ex":{"en":"‘Thanks for the ride.’ ‘Sure—anytime.’","cn":"“谢谢你载我过来。”“不用客气，随时愿意效劳。”"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确信的;确知的;肯定的;有把握的","en":"If you are sure that something is true, you are certain that it is true. If you are not sure about something, you do not know for certain what the true situation is.","ex":{"en":"He'd never been in a class before and he was not even sure that he should have been teaching","cn":"他以前从未教过课，甚至不确定自己该不该教课。"}},{"pos":"ADJ 形容词","cn":"一定的;必定的;无疑的;确保的","en":"If someone is sure of getting something, they will definitely get it or they think they will definitely get it.","ex":{"en":"A lot of people think that it's better to pay for their education so that they can be sure of getting quality","cn":"许多人认为最好是接受付费教育，这样能确保教学质量。"}},{"pos":"PHR-MODAL 情态动词短语","cn":"(事情的发生)一定，必然","en":"If you say that something is sure to happen, you are emphasizing your belief that it will happen.","ex":{"en":"With over 80 beaches to choose from, you are sure to find a place to lay your towel","cn":"有 80 多个海滩可供选择，你一定能找到一处满意的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不容置疑的;确切的;可靠的;保险的","en":"Sure is used to emphasize that something such as a sign or ability is reliable or accurate.","ex":{"en":"Sharpe's leg and shoulder began to ache, a sure sign of rain","cn":"夏普的腿和肩膀开始疼痛，这预示着肯定要下雨了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一定的;务必的","en":"If you tell someone to be sure to do something, you mean that they must not forget to do it.","ex":{"en":"Be sure to read about how mozzarella is made, on page 65","cn":"务必看看莫泽雷勒干酪是怎么制成的，在第 65 页。"}},{"pos":"CONVENTION 惯用语","cn":"是的;当然;没问题","en":"Sure is an informal way of saying 'yes' or 'all right'.","ex":{"en":"'He rang you?' — 'Sure. Last night.'","cn":"“他给你打电话了？”——“没错。昨天晚上打的。”"}},{"pos":"ADV 副词","cn":"确实;的确","en":"You can use sure in order to emphasize what you are saying.","ex":{"en":"'Has the whole world just gone crazy?' — 'Sure looks that way, doesn't it.'","cn":"“整个世界难道都疯了吗？”——“看上去的确如此，不是吗。”"}},{"pos":"PHRASE 短语","cn":"果真，果然(尤用在讲故事时)","en":"You say sure enough, especially when telling a story, to confirm that something was really true or was actually happening.","ex":{"en":"We found the English treacle pudding too good to resist. Sure enough, it was delicious","cn":"我们觉得英国糖蜜布丁太好吃了，令人无法抗拒。的确非常美味。"}},{"pos":"PHRASE 短语","cn":"无疑;肯定","en":"If you say that something is for sure or that you know it for sure, you mean that it is definitely true.","ex":{"en":"One thing's for sure, Astbury's vocal style hasn't changed much over the years","cn":"有一点可以肯定，阿斯特伯里的演唱风格多年来没怎么改变。"}},{"pos":"PHRASE 短语","cn":"一定要;设法保证","en":"If you make sure that something is done, you take action so that it is done.","ex":{"en":"Make sure that you follow the instructions carefully","cn":"一定要认真按照操作指南来做。"}},{"pos":"PHRASE 短语","cn":"查明;核实;弄清","en":"If you make sure that something is the way that you want or expect it to be, you check that it is that way.","ex":{"en":"He looked in the bathroom to make sure that he was alone","cn":"他往浴室里看了看，确定就他一个人。"}},{"pos":"PHRASE 短语","cn":"当然之事;必然之事","en":"If you say that something is a sure thing, you mean that you are certain that it will happen or be successful.","ex":{"en":"This proposal is by no means a sure thing.","cn":"这个提议绝不会理所当然地获得通过。"}},{"pos":"CONVENTION 惯用语","cn":"当然，一定(表示同意)","en":"You say 'sure thing' to show that you agree with someone or will do as they say.","ex":{"en":"'Be careful!' — 'Sure thing, Dad. So long.'","cn":"“要多加小心!”——“一定会的，爸爸。再见。”"}},{"pos":"PHRASE 短语","cn":"(承认属实)诚然，固然，无可否认","en":"You use to be sure when you are admitting that something is true, although it seems to contradict a more general statement that you are making.","ex":{"en":"Parents make the rules. To be sure, many of the rules are no longer appropriate today.","cn":"规矩由父母立下。诚然，其中有许多放在今天已不再合适了。"}},{"pos":"PHRASE 短语","cn":"自信;确信","en":"If you are sure of yourself, you are very confident about your own abilities or opinions.","ex":{"en":"I'd never seen him like this, so sure of himself, so in command.","cn":"我从来没见他如此自信满满、指挥自若。"}}]},"examples":[{"en":"England must win this game to be sure of qualifying for the World Cup.","cn":"英格兰队必须拿下这场比赛才能确保获得世界杯的参赛资格。"},{"en":"‘Thanks for the ride.’ ‘Sure — anytime.’ “","cn":"谢谢你载我过来。” “不用客气，随时愿意效劳。”"}]},"subscription":{"media":{"uk":"media/uk/subscription__gb_1.mp3","us":"media/us/subscription__us_1.mp3"},"oxford":{"phon":"səbˈskrɪpʃn","pos":"noun","senses":[{"en":"an amount of money that you pay regularly to receive a service, be a member of a club, support a charity or receive regular copies of a newspaper or magazine; the act of paying this money","cn":"定期服务费（或会员费、捐助款）；（报刊等的）订阅费；订阅；订购","ex":{"en":"an annual subscription","cn":"一年期订阅"}},{"en":"the act of people paying money for something to be done","cn":"集体资助；集体捐助","lab":"British English","ex":{"en":"A statue in his memory was erected by public subscription.","cn":"由公众捐资建起一座纪念他的雕像。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"会员费;用户费;捐助款;订阅费","en":"A subscription is an amount of money that you pay regularly in order to belong to an organization, to help a charity or campaign, or to receive copies of a magazine or newspaper.","ex":{"en":"You can become a member by paying the yearly subscription.","cn":"支付一年的会员费就可以成为会员。"}},{"pos":"ADJ 形容词","cn":"(电视或电视频道)付费的，收费的","en":"Subscription television is television that you can watch only if you pay a subscription. A subscription channel is a channel that you can watch only if you pay a subscription.","ex":{"en":"Premiere, a subscription channel which began in 1991, shows live football covering the top two divisions","cn":"开播于 1991 年的付费电视频道 premiere 实况转播两大顶级足球联赛的赛事。"}}]},"examples":[{"en":"A statue in his memory was erected by public subscription.","cn":"由公众捐资建起一座纪念他的雕像。"},{"en":"to take out a subscription to ‘Newsweek’","cn":"订阅《新闻周刊》"}]},"supply":{"media":{"uk":"media/uk/supply__gb_1.mp3","us":"media/us/supply__us_1.mp3"},"oxford":{"phon":"səˈplaɪ","pos":"noun","senses":[{"en":"an amount of something that is provided or available to be used","cn":"供应量；供给量；储备","g":"[countable]","ex":{"en":"Advances in agriculture increased the food supply.","cn":"农业的进步增加了食品的供应量。"}},{"en":"the things such as food, medicines, fuel, etc. that are needed by a group of people, for example an army or expedition","cn":"（军队或探险队等的）补给，补给品","g":"[plural]","ex":{"en":"Our supplies were running out.","cn":"我们的补给快用完了。"}},{"en":"the act of supplying something; the fact of receiving something that is being supplied","cn":"提供；补给；（接受）供应，供给","g":"[uncountable]","ex":{"en":"the electricity/energy/gas supply","cn":"电力／能源／天然气供应"}},{"en":"to provide somebody/something with something that they need or want, especially in large quantities","cn":"（尤指大量）供应，供给，提供","ex":{"en":"The company supplied sports equipment to schools.","cn":"这家公司向学校提供了体育器材。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"供给;供应;提供","en":"If you supply someone with something that they want or need, you give them a quantity of it.","ex":{"en":"...an agreement not to produce or supply chemical weapons.","cn":"不生产或供应化学武器的协议"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指大量的)补给，补给品，日用物资","en":"You can use supplies to refer to food, equipment, and other essential things that people need, especially when these are provided in large quantities.","ex":{"en":"What happens when food and gasoline supplies run low?","cn":"如果食物和汽油供应减少，会出现什么情况呢？"}},{"pos":"N-VAR 可变名词","cn":"供应量;供给量;储备","en":"A supply of something is an amount of it which someone has or which is available for them to use.","ex":{"en":"The brain requires a constant supply of oxygen","cn":"大脑需要持续供氧。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(商品、服务的)供应量，供给量","en":"Supply is the quantity of goods and services that can be made available for people to buy.","ex":{"en":"Prices change according to supply and demand.","cn":"价格受供求关系的影响。"}},{"pos":"VERB 动词","cn":"补充;填充","en":"If you supply a missing word or piece of information, for example in a puzzle, you say or write it because you know it.","ex":{"en":"Supply the missing word(s) and you could win a T-shirt.","cn":"填出所缺少的单词，你就会赢得一件T恤。"}},{"pos":"PHRASE 短语","cn":"供应不足","en":"If something is in short supply, there is very little of it available and it is difficult to find or obtain.","ex":{"en":"Food is in short supply all over the country","cn":"全国普遍食品供应不足。"}}]},"examples":[{"en":"a transport plane carrying food and medical supplies for refugees","cn":"一架为难民运送食物和医疗用品的运输机"},{"en":"The UN has agreed to allow the supply of emergency aid.","cn":"联合国已同意允许提供紧急援助。"}]},"subsidy":{"media":{"uk":"media/uk/subsidy__gb_1.mp3","us":"media/us/subsidy__us_1.mp3"},"oxford":{"phon":"ˈsʌbsədi","pos":"noun","senses":[{"en":"money that is paid by a government or an organization to reduce the costs of services or of producing goods so that their prices can be kept low","cn":"补贴；补助金；津贴","lab":"North American English","ex":{"en":"agricultural subsidies","cn":"农业补贴"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"补贴;补助金;津贴","en":"A subsidy is money that is paid by a government or other authority in order to help an industry or business, or to pay for a public service.","ex":{"en":"European farmers are planning a massive demonstration against farm subsidy cuts","cn":"欧洲农场主正策划一场抗议削减农场补贴的大规模示威游行。"}}]},"examples":[{"en":"to reduce the level of subsidy","cn":"降低补贴金额"},{"en":"agricultural subsidies","cn":"农业补贴"}]},"supportive":{"media":{"uk":"media/uk/supportive__gb_1.mp3","us":"media/us/supportive__us_1.mp3"},"oxford":{"phon":"səˈpɔːtɪv","pos":"adjective","senses":[{"en":"encouraging somebody or giving them help or sympathy","cn":"鼓励的；支持的；给予帮助的；同情的","ex":{"en":"a supportive family","cn":"支持自己的家人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"给予帮助的;热心援助的;支持的","en":"If you are supportive, you are kind and helpful to someone at a difficult or unhappy time in their life.","ex":{"en":"They were always supportive of each other","cn":"他们一直互相帮助。"}}]},"examples":[{"en":"She was very supportive during my father's illness.","cn":"在我父亲生病期间，她给了很多帮助。"},{"en":"a supportive family","cn":"理解支持自己的家人"}]},"summarize":{"media":{"uk":"media/uk/summarize__gb_1.mp3","us":"media/us/summarize__us_1.mp3"},"oxford":{"phon":"ˈsʌməraɪz","pos":"verb","senses":[{"en":"to give a summary of something","cn":"总结；概括；概述","ex":{"en":"This essay briefly summarizes some of our approaches.","cn":"这篇文章对我们的一些方法进行简要概述。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"总结;概括;概述","en":"If you summarize something, you give a summary of it.","ex":{"en":"Table 3.1 summarizes the information given above","cn":"表格 3.1 是对以上信息的总结。"}}]},"examples":[{"en":"The results of the research are summarized at the end of the chapter.","cn":"在这一章末尾对研究结果作了总结。"},{"en":"The authors summarize their views in the introduction.","cn":"作者在序言里概述了他们的观点。"}]},"surprisingly":{"oxford":{"phon":"səˈpraɪzɪŋli","pos":"adverb","senses":[{"en":"in a way that causes surprise","cn":"令人吃惊的；使人惊奇的；出人意料的；奇怪的","ex":{"en":"She looked surprisingly well.","cn":"她看上去身体出奇地好。"}}]},"media":{"uk":"media/uk/surprisingly__gb_1.mp3","us":"media/us/surprisingly__us_1.mp3"},"examples":[{"en":"Not surprisingly on such a hot day, the beach was crowded.","cn":"在这样的大热天，海滩上人头攒动是不足为奇的。"},{"en":"Surprisingly, he agreed straight away.","cn":"真想不到，他马上同意了。"}]},"surplus":{"media":{"uk":"media/uk/surplus__gb_1.mp3","us":"media/us/surplus__us_1.mp3"},"oxford":{"phon":"ˈsɜːpləs","pos":"noun","senses":[{"en":"an amount that is extra or more than you need","cn":"过剩；剩余；过剩量；剩余额","ex":{"en":"food surpluses","cn":"过剩的食物"}},{"en":"the amount by which the amount of money received is greater than the amount of money spent","cn":"盈余；顺差","lab":"US English","ex":{"en":"a surplus of £400 million","cn":"4 亿英镑的盈余"}},{"en":"more than is needed or used","cn":"过剩的；剩余的；多余的","ex":{"en":"surplus cash","cn":"剩余的现金"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"过剩;剩余;过剩量;剩余额","en":"If there is a surplus of something, there is more than is needed.","ex":{"en":"Germany suffers from a surplus of teachers.","cn":"德国遭遇了教师过剩的问题。"}},{"pos":"ADJ 形容词","cn":"过剩的;剩余的;多余的","en":"Surplus is used to describe something that is extra or that is more than is needed.","ex":{"en":"Few people have large sums of surplus cash","cn":"几乎没人手头很富裕。"}},{"pos":"N-COUNT 可数名词","cn":"(贸易)顺差","en":"If a country has a trade surplus, it exports more than it imports.","ex":{"en":"Japan's annual trade surplus is in the region of 100 billion dollars.","cn":"日本每年的贸易顺差额在 1,000 亿美元左右。"}},{"pos":"N-COUNT 可数名词","cn":"(预算)盈余","en":"If a government has a budget surplus, it has spent less than it received in taxes.","ex":{"en":"Norway's budget surplus has fallen from 5.9% in 1986 to an expected 0.1% this year.","cn":"挪威的预算盈余已经从 1986 年的 5.9%降至今年预计的 0.1%。"}}]},"examples":[{"en":"Surplus grain is being sold for export.","cn":"过剩的谷物正销往国外。"},{"en":"The balance of payments was in surplus last year (= the value of exports was greater than the value of imports).","cn":"去年国际收支有盈余。"}]},"surveillance":{"media":{"uk":"media/uk/surveillance__gb_1.mp3","us":"media/us/surveillance__us_1.mp3"},"oxford":{"phon":"sɜːˈveɪləns","pos":"noun","senses":[{"en":"the act of carefully watching a person suspected of a crime or a place where a crime may be committed","cn":"（对犯罪嫌疑人或可能发生犯罪的地方的）监视","ex":{"en":"The police are keeping the suspects under constant surveillance.","cn":"警方正对嫌疑人实施不间断监视。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指来自警方、军队等组织的)监视，监察","en":"Surveillance is the careful watching of someone, especially by an organization such as the police or the army.","ex":{"en":"He was arrested after being kept under constant surveillance","cn":"在被连续监视了一段时间后，他被逮捕了。"}}]},"examples":[{"en":"The police are keeping the suspects under constant surveillance.","cn":"警方正对嫌疑人实施不间断监视。"},{"en":"surveillance cameras/equipment","cn":"监视摄像机/设备"}]},"surge":{"media":{"uk":"media/uk/surge__gb_1.mp3","us":"media/us/surge__us_1.mp3"},"oxford":{"phon":"sɜːdʒ","pos":"noun","senses":[{"en":"a sudden increase of a strong feeling","cn":"（强烈感情的）突发","ex":{"en":"She felt a sudden surge of anger.","cn":"她突然感觉怒火中烧。"}},{"en":"a sudden increase in the amount or number of something","cn":"（数量的）急剧上升，激增","ex":{"en":"a surge in consumer spending","cn":"消费开支的激增"}},{"en":"a sudden, strong movement forward or upwards","cn":"奔涌向前；突然的向上运动","ex":{"en":"a tidal surge","cn":"涨潮"}},{"en":"a sudden increase in the flow of electrical power through a system","cn":"（电流）浪涌","ex":{"en":"An electrical surge damaged the computer's disk drive.","cn":"电流浪涌损坏了计算机的磁盘驱动器。"}},{"en":"to move quickly and with force in a particular direction","cn":"涌；汹涌；涌动","g":"[intransitive]","ex":{"en":"The gates opened and the crowd surged forward.","cn":"大门打开了，人群向前涌去。"},"pos":"verb"},{"en":"to fill somebody with a strong feeling","cn":"使强烈地感到","g":"[intransitive]","ex":{"en":"Relief surged through her.","cn":"她顿觉宽慰。"},"pos":"verb"},{"en":"to suddenly increase in value","cn":"急剧上升；飞涨；激增","g":"[intransitive]","ex":{"en":"Share prices surged.","cn":"股价猛涨。"},"pos":"verb"},{"en":"to increase suddenly","cn":"浪涌","g":"[intransitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"激增;急剧上升;突飞猛进","en":"A surge is a sudden large increase in something that has previously been steady, or has only increased or developed slowly.","ex":{"en":"Specialists see various reasons for the recent surge in inflation","cn":"专家们认为目前通货膨胀加剧有多种原因。"}},{"pos":"VERB 动词","cn":"急剧上升;飞涨;激增","en":"If something surges, it increases suddenly and greatly, after being steady or developing only slowly.","ex":{"en":"The Freedom Party's electoral support surged from just under 10 per cent to nearly 17 per cent","cn":"自由党的选举支持率从区区不到 10%骤升至近 17%。"}},{"pos":"VERB 动词","cn":"(人群)蜂拥，涌动","en":"If a crowd of people surge forward, they suddenly move forward together.","ex":{"en":"The photographers and cameramen surged forward.","cn":"摄影师和摄像师们蜂拥上前。"}},{"pos":"N-COUNT 可数名词","cn":"(风、水等的)奔涌，汹涌","en":"A surge is a sudden powerful movement of a physical force such as wind or water.","ex":{"en":"The whole car shuddered with an almost frightening surge of power","cn":"油门猛然加大到几乎让人恐惧的程度，整个汽车剧烈震颤着。"}},{"pos":"VERB 动词","cn":"(水等)汹涌;(电)浪涌，骤强","en":"If a physical force such as water or electricity surges through something, it moves through it suddenly and powerfully.","ex":{"en":"Thousands of volts surged through his car after he careered into a lamp post, ripping out live wires","cn":"他的车猛地撞到灯柱上，扯断了带电的电线，数千伏高压电流骤然通过车身。"}},{"pos":"N-COUNT 可数名词","cn":"(情感的)突发，涌现，突然出现","en":"If you feel a surge of a particular emotion or feeling, you experience it suddenly and powerfully.","ex":{"en":"'It must be very difficult,' said Hunter, feeling a surge of embarrassment for Diane's predicament","cn":"“那肯定不好过，”亨特说，突然为黛安娜的困境感到很为难。"}},{"pos":"VERB 动词","cn":"(感情、感觉)突袭，涌动，突发","en":"If an emotion or sensation surges in you or through you, you feel it suddenly and powerfully.","ex":{"en":"Nausea surged in him and he retched violently","cn":"他突然觉得恶心，猛烈地干呕起来。"}}]},"examples":[{"en":"After an initial surge of interest, there has been little call for our services.","cn":"过了开始的一阵新鲜劲后，对我们服务的需求就变得很小。"},{"en":"We are having trouble keeping up with the recent surge in demand.","cn":"对于近来出现的需求猛增，我们难以应对。"}]},"suggestion":{"oxford":{"phon":"səˈdʒestʃən","pos":"noun","senses":[{"en":"an idea or a plan that you mention for somebody else to think about","cn":"建议；提议","g":"[countable]","ex":{"en":"Can I make a suggestion?","cn":"我提个建议好吗？"}},{"en":"a reason to think that something, especially something bad, is true","cn":"使人作（尤其是不好的事情的）推测的理由","g":"[uncountable, countable, usually singular]","ex":{"en":"A spokesman dismissed any suggestion of a boardroom rift.","cn":"发言人的话打消了人们关于董事会不和的所有推测。"}},{"en":"putting an idea into people’s minds by connecting it with other ideas","cn":"暗示；联想","g":"[uncountable]","ex":{"en":"Most advertisements work through suggestion.","cn":"多数广告都是通过暗示发挥作用。"}},{"en":"a slight amount or sign of something","cn":"微量；些微；迹象","g":"[countable, usually singular]","lab":"formal or literary","ex":{"en":"She looked at me with just a suggestion of a smile.","cn":"她看着我，脸上带着一丝笑意。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"建议;提议","en":"If you make a suggestion, you put forward an idea or plan for someone to think about.","ex":{"en":"The dietitian was helpful, making suggestions as to how I could improve my diet","cn":"这位营养学家就如何改善饮食给我提出了些建议，对我很有帮助。"}},{"pos":"N-COUNT 可数名词","cn":"暗示;示意","en":"A suggestion is something that a person says which implies that something is the case.","ex":{"en":"We reject any suggestion that the law needs amending","cn":"对于任何暗示该法律需要修改的观点我们都拒绝接受。"}},{"pos":"N-SING 单数名词","cn":"表明;征兆;根据","en":"If there is no suggestion that something is the case, there is no reason to think that it is the case.","ex":{"en":"There is no suggestion whatsoever that the two sides are any closer to agreeing","cn":"没有任何迹象表明双方将会达成一致。"}},{"pos":"N-COUNT 可数名词","cn":"些微;些许","en":"If there is a suggestion of something, there is a slight amount or sign of it.","ex":{"en":"...that fashionably faint suggestion of a tan.","cn":"略带一点流行的古铜色"}},{"pos":"N-UNCOUNT 不可数名词","cn":"联想;暗示","en":"Suggestion means giving people a particular idea by associating it with other ideas.","ex":{"en":"The power of suggestion is very strong.","cn":"暗示的力量是无比强大的。"}}]},"media":{"uk":"media/uk/suggestion__gb_1.mp3","us":"media/us/suggestion__us_1.mp3"},"examples":[{"en":"We need to get it there by four. Any suggestions?","cn":"我们需要在四点以前把东西送过去。大家有什么办法吗？"},{"en":"A spokesman dismissed any suggestion of a boardroom rift.","cn":"发言人的话打消了人们关于董事会不和的所有推测。"}]},"survival":{"media":{"uk":"media/uk/survival__gb_1.mp3","us":"media/us/survival__us_1.mp3"},"oxford":{"phon":"səˈvaɪvl","pos":"noun","senses":[{"en":"the state of continuing to live or exist, often despite difficulty or danger","cn":"生存；存活；幸存","g":"[uncountable]","ex":{"en":"the struggle/battle/fight for survival","cn":"为生存而斗争／战斗／拼搏"}},{"en":"something that has continued to exist from an earlier time","cn":"残存物；幸存事物","g":"[countable]","ex":{"en":"The ceremony is a survival from pre-Christian times.","cn":"这种仪式是从公元前遗留下来的。"}},{"en":"a popular British television series about nature. Each programme described the life of a particular wild animal. It was broadcast from the 1960s until the 1990s.","cn":"生存：一部关于大自然的英国流行电视连续剧。每个程序都描述了特定野生动物的生活。从1960年代到1990年代一直播放。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"生存","en":"If you refer to the survival of something or someone, you mean that they manage to continue or exist in spite of difficult circumstances.","ex":{"en":"...companies which have been struggling for survival in the advancing recession","cn":"在日益萧条的经济环境中挣扎求生的各个公司"}},{"pos":"N-UNCOUNT 不可数名词","cn":"幸存;存活","en":"If you refer to the survival of a person or living thing, you mean that they live through a dangerous situation in which it was possible that they might die.","ex":{"en":"If cancers are spotted early there's a high chance of survival","cn":"如果癌症在早期发现的话，存活的几率会很高。"}},{"pos":"PHRASE 短语","cn":"适者生存","en":"You can use the survival of the fittest to refer to a situation in which only the strongest people or things continue to live or be successful, while the others die or fail."}]},"examples":[{"en":"His only chance of survival was a heart transplant.","cn":"只有进行心脏移植，他才有望活下去。"},{"en":"Exporting is necessary for our economic survival.","cn":"必须有出口，才能维持我们的经济。"}]},"supplied":{"lemma":"supply"},"success":{"media":{"uk":"media/uk/success__gb_1.mp3","us":"media/us/success__us_1.mp3"},"oxford":{"phon":"səkˈses","pos":"noun","senses":[{"en":"the fact that you have achieved something that you want and have been trying to do or get","cn":"成功；胜利","g":"[uncountable]","ex":{"en":"The company has achieved considerable success in this market.","cn":"该公司在该市场取得了相当大的成功。"}},{"en":"the fact of becoming rich or famous or of getting a high social position","cn":"发财；成名；跻身上流社会","g":"[uncountable]","ex":{"en":"What's the secret of your success?","cn":"你成功的秘诀是什么？"}},{"en":"a person or thing that has achieved a good result and been successful","cn":"成功的人（或事物）","g":"[countable]","ex":{"en":"The party was a great success.","cn":"这次聚会非常成功。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"成功;胜利;成就","en":"Success is the achievement of something that you have been trying to do.","ex":{"en":"It's important for the long-term success of any diet that you vary your meals.","cn":"如果想要成功做到长期节食，很重要的一点是要膳食多样化。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(在某一领域的)成功，成名","en":"Success is the achievement of a high position in a particular field, for example in business or politics.","ex":{"en":"Nearly all of the young people interviewed believed that work was the key to success.","cn":"几乎所有被采访的年轻人都认为工作是成功的关键。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(某事所取得的)成功，良好表现","en":"The success of something is the fact that it works in a satisfactory way or has the result that is intended.","ex":{"en":"Most of the cast was amazed by the play's success","cn":"大多数演员都为该剧大获成功而感到惊奇。"}},{"pos":"N-COUNT 可数名词","cn":"成功的人(或事物)","en":"Someone or something that is a success achieves a high position, makes a lot of money, or is admired a great deal.","ex":{"en":"The jewellery was a great success","cn":"这些珠宝大获赞誉。"}}]},"examples":[{"en":"She was surprised by the book's success (= that it had sold a lot of copies).","cn":"那本书获得成功出乎她的意料。"},{"en":"He's proud of his daughter's successes.","cn":"他为女儿的种种成就感到自豪。"}]},"suburb":{"media":{"uk":"media/uk/suburb__gb_1.mp3","us":"media/us/suburb__us_1.mp3"},"oxford":{"phon":"ˈsʌbɜːb","pos":"noun","senses":[{"en":"an area where people live that is outside the centre of a city","cn":"郊区；城外","lab":"especially North American English","ex":{"en":"a suburb of London","cn":"伦敦郊区"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"城郊;郊区","en":"A suburb of a city or large town is a smaller area which is part of the city or large town but is outside its centre.","ex":{"en":"Anna was born in 1923 in Ardwick, a suburb of Manchester.","cn":"安娜于1923年出生在曼彻斯特的郊区阿德维克。"}},{"pos":"N-PLURAL 复数名词","cn":"城郊住宅区","en":"If you live in the suburbs, you live in an area of houses outside the centre of a large town or city.","ex":{"en":"His family lived in the suburbs.","cn":"他家住在城郊。"}}]},"examples":[{"en":"They live in the suburbs.","cn":"他们住在城外。"},{"en":"a suburb of London","cn":"伦敦郊区"}]},"sunk":{"collins":{"senses":[{"pos":"","cn":"","en":"Sunk is the past participle of sink ."},{"pos":"ADJ 形容词","cn":"玩完的;完蛋的;没救的","en":"If you say that someone is sunk, you mean that they have no hope of avoiding trouble or failure.","ex":{"en":"Without him we'd be well and truly sunk.","cn":"没有他我们肯定彻底玩完了。"}}]},"media":{"uk":"media/uk/sunk__gb_1.mp3","us":"media/us/sunk__us_1.mp3"}},"survey":{"media":{"uk":"media/uk/survey__gb_1.mp3","us":"media/us/survey__us_1.mp3"},"oxford":{"phon":"ˈsɜːveɪ","pos":"noun","senses":[{"en":"an investigation of the opinions, behaviour, etc. of a particular group of people, which is usually done by asking them questions","cn":"民意调查；民意测验","ex":{"en":"A recent survey showed 75 per cent of those questioned were in favour of the plan.","cn":"最近的民意调查显示，有 75% 的调查对象支持这项计划。"}},{"en":"the act of examining and recording the measurements, features, etc. of an area of land in order to make a map or plan of it","cn":"测量；勘测；测绘","ex":{"en":"an aerial survey (= made by taking photographs from a plane, drone, etc.)","cn":"航空测量"}},{"en":"an examination of the condition of a house, etc., usually done for somebody who is thinking of buying it","cn":"（通常指为欲购房者所做的）房屋鉴定","lab":"British English","ex":{"en":"a detailed structural survey","cn":"详细的结构调查"}},{"en":"a general study, view or description of something","cn":"总体研究；全面评述；概述","ex":{"en":"a comprehensive survey of modern music","cn":"现代音乐概述"}},{"en":"to look carefully at the whole of something, especially in order to get a general impression of it","cn":"查看；审视；审察","ex":{"en":"The next morning we surveyed the damage caused by the fire.","cn":"次日清早我们查看了火灾的破坏情况。"},"pos":"verb"},{"en":"to study and give a general description of something","cn":"总体研究；全面评述；概述","ex":{"en":"This chapter briefly surveys the current state of European politics.","cn":"本章对欧洲政治的现状作了概述。"},"pos":"verb"},{"en":"to investigate the opinions or behaviour of a group of people by asking them a series of questions","cn":"（对…）做民意调查，进行民意测验","ex":{"en":"We surveyed 500 smokers and found that over three quarters would like to give up.","cn":"我们对 500 名吸烟者进行了调查，发现有超过四分之三的人愿意戒烟。"},"pos":"verb"},{"en":"to measure and record the features of an area of land, for example in order to make a map or in preparation for building","cn":"测量；勘测；测绘","pos":"verb"},{"en":"to examine a building to make sure it is in good condition","cn":"（对建筑物的）鉴定，检查","lab":"British English","ex":{"en":"Have the house surveyed before you decide whether to buy it.","cn":"在你决定购买房子之前，先请人勘查一下。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"调查;民意调查;民意测验","en":"If you carry out a survey, you try to find out detailed information about a lot of different people or things, usually by asking people a series of questions.","ex":{"en":"The council conducted a survey of the uses to which farm buildings are put","cn":"市政会就农场建筑的使用情况进行了调查。"}},{"pos":"VERB 动词","cn":"调查;对…作民意调查;对…进行民意测验","en":"If you survey a number of people, companies, or organizations, you try to find out information about their opinions or behaviour, usually by asking them a series of questions.","ex":{"en":"Business Development Advisers surveyed 211 companies for the report","cn":"企业发展顾问公司为此报告调查了 211 家公司。"}},{"pos":"VERB 动词","cn":"总体研究;审视;全面观察","en":"If you survey something, you look at or consider the whole of it carefully.","ex":{"en":"He pushed himself to his feet and surveyed the room","cn":"他站起来仔细打量整间屋子。"}},{"pos":"N-SING 单数名词","cn":"概览;概述","en":"If you give something a brief survey or a quick survey, you look at or consider all of it quickly, but not in detail.","ex":{"en":"...a brief survey of some important books on astrology","cn":"有关占星术的几本重要著作的简要概述"}},{"pos":"N-COUNT 可数名词","cn":"测量;勘测;测绘","en":"If someone carries out a survey of an area of land, they examine it and measure it, usually in order to make a map of it.","ex":{"en":"...the organizer of the geological survey of India","cn":"印度地质勘察活动的组织者"}},{"pos":"VERB 动词","cn":"测量;勘测;测绘","en":"If someone surveys an area of land, they examine it and measure it, usually in order to make a map of it.","ex":{"en":"Scarborough Council commissioned geological experts earlier this year to survey the cliffs.","cn":"斯卡伯勒市政会在今年早些时候委托地质专家对这些悬崖进行勘测。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指为欲购房者作的)房屋鉴定","en":"A survey is a careful examination of the condition and structure of a house, usually carried out in order to give information to a person who wants to buy it.","ex":{"en":"...a structural survey undertaken by a qualified surveyor.","cn":"由一位有资质的房屋鉴定员所作的结构评估"}},{"pos":"VERB 动词","cn":"对(建筑物)进行评估;鉴定;检查","en":"If someone surveys a house, they examine it carefully and report on its structure, usually in order to give advice to a person who is thinking of buying it.","ex":{"en":"...the people who surveyed the house for the mortgage.","cn":"抵押贷款房屋的评估人员"}}]},"examples":[{"en":"We surveyed 500 smokers and found that over three quarters would like to give up.","cn":"我们对 500 名吸烟者进行了调查，发现有超过四分之三的人愿意戒烟。"},{"en":"A recent survey showed 75% of those questioned were in favour of the plan.","cn":"最近的民意调查显示，有 75% 的调查对象支持这项计划。"}]},"sufferings":{"lemma":"suffering","media":{"uk":"media/uk/suffering__gb_1.mp3","us":"media/us/suffering__us_1.mp3"}},"sustainability":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not harmful to the environment","cn":""},{"en":"not harmful to the environment – used especially about products","cn":""}]},"examples":[{"en":"The government should do more to promote sustainable agriculture.","cn":"","src":"ld"},{"en":"the sustainable use of rainforest resources","cn":"","src":"ld"}],"media":{"uk":"media/uk/sustainability__gb_1.mp3","us":"media/us/sustainability__us_1.mp3"},"oxford":{"phon":"səˌsteɪnəˈbɪləti","pos":"noun","senses":[{"en":"the use of natural products and energy in a way that does not harm the environment","cn":"以不损害环境的方式使用自然产品和能源","ex":{"en":"a company well-known for its commitment to environmental sustainability","cn":"该公司因致力于环境的可持续发展而闻名"}},{"en":"the ability to continue or be continued for a long time","cn":"持续或被持续很长时间的能力","ex":{"en":"The strength and sustainability of the economic recovery is still in doubt.","cn":"经济复苏的力度和可持续性仍令人怀疑。"}}]}},"surrounds":{"lemma":"surround"},"substantially":{"media":{"uk":"media/uk/substantially__gb_1.mp3","us":"media/us/substantially__us_1.mp3"},"oxford":{"phon":"səbˈstænʃəli","pos":"adverb","senses":[{"en":"very much; a lot","cn":"非常；很多","ex":{"en":"The costs have increased substantially.","cn":"成本大大提高了。"}},{"en":"mainly; in most details, even if not completely","cn":"基本上；大体上；总的来说","lab":"formal","ex":{"en":"What she says is substantially true.","cn":"她的话大体符合事实。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"非常地;巨大地","en":"If something changes substantially or is substantially different, it changes a lot or is very different.","ex":{"en":"The percentage of girls in engineering has increased substantially","cn":"学工科的女孩的比例已经大大增加了。"}},{"pos":"ADV 副词","cn":"基本上;大体上;总的来说","en":"If you say that something is substantially correct or unchanged, you mean that it is mostly correct or mostly unchanged.","ex":{"en":"He checked the details given and found them substantially correct","cn":"他核实了一下给出的细节，发现它们基本正确。"}}]},"examples":[{"en":"What she says is substantially true.","cn":"她的话大体符合事实。"},{"en":"The plane was substantially damaged in the crash.","cn":"失事飞机损坏严重。"}]},"sun-kissed":{"oxford":{"phon":"ˈsʌn kɪst","pos":"adjective","senses":[{"en":"made warm or brown by the sun","cn":"晒暖的；晒黑的","ex":{"en":"sun-kissed bodies on the beach","cn":"沙滩上晒得黝黑的身体"}}]},"media":{"uk":"media/uk/sun_kissed_1_gb_1.mp3","us":"media/us/sun_kissed_1_us_1.mp3"},"examples":[{"en":"sun-kissed bodies on the beach","cn":"沙滩上晒得黝黑的身体"},{"en":"the famous sun-kissed resort of Acapulco","cn":"阿卡普尔科一处阳光明媚的著名度假胜地"}]},"successful":{"media":{"uk":"media/uk/successful__gb_1.mp3","us":"media/us/successful__us_1.mp3"},"oxford":{"phon":"səkˈsesfl","pos":"adjective","senses":[{"en":"achieving your aims or what was intended","cn":"达到目的的；有成效的","ex":{"en":"The experiment was entirely successful.","cn":"这次实验非常有成效。"}},{"en":"having become popular and/or made a lot of money","cn":"获得成功的；有成就的","ex":{"en":"The play was very successful on Broadway.","cn":"那部剧在百老汇大获成功。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"达到目的的;有成效的;成功的","en":"Something that is successful achieves what it was intended to achieve. Someone who is successful achieves what they intended to achieve.","ex":{"en":"How successful will this new treatment be?","cn":"这一新的疗法会有多大成效？"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"获得成功的;受欢迎的;获利匪浅的","en":"Something that is successful is popular or makes a lot of money.","ex":{"en":"...the hugely successful movie that brought Robert Redford an Oscar for his directing","cn":"让罗伯特·雷德福拿到了奥斯卡最佳导演奖的大受欢迎的影片"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)成功的，有成就的","en":"Someone who is successful achieves a high position in what they do, for example in business or politics.","ex":{"en":"Women do not necessarily have to imitate men to be successful in business","cn":"女性不见得非要模仿男性才能在商界叱咤风云。"}}]},"examples":[{"en":"Small local shops stop being economic when a supermarket opens up nearby.","cn":"附近有超市开业的话，当地的小商店就没有利润可赚了。"},{"en":"They do a lot of business in lucrative overseas markets.","cn":"他们在利润丰厚的海外市场上生意很多。"}]},"subscribe":{"oxford":{"phon":"səbˈskraɪb","pos":"verb","senses":[{"en":"to pay an amount of money regularly in order to receive or use something","cn":"定期订购（或订阅等）","g":"[intransitive]","ex":{"en":"Which journals does the library subscribe to?","cn":"图书馆订有哪些报刊？"}},{"en":"to arrange to have regular access to an electronic information service or other internet service","cn":"订阅（电子信息服务或其他互联网服务）","g":"[intransitive]","ex":{"en":"He subscribed to a newsgroup (= on the internet).","cn":"他成了一个网上新闻组的用户。"}},{"en":"to pay money regularly to be a member of an organization or to support a charity","cn":"定期交纳（会员费）；定期（向慈善机构）捐款；定期捐助","g":"[intransitive]","ex":{"en":"He subscribes regularly to Amnesty International.","cn":"他定期向大赦国际捐款。"}},{"en":"to apply to buy shares in a company","cn":"认购（股份）","g":"[intransitive]","lab":"finance"},{"en":"to apply to take part in an activity, use a service, etc.","cn":"申请；预订；报名","g":"[transitive, usually passive]","ex":{"en":"The tour of Edinburgh is fully subscribed.","cn":"去爱丁堡旅游的名额已经满了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"同意;赞成","en":"If you subscribe to an opinion or belief, you are one of a number of people who have this opinion or belief.","ex":{"en":"I've personally never subscribed to the view that either sex is superior to the other.","cn":"我个人从来都不同意性别有优劣之分的观点。"}},{"pos":"VERB 动词","cn":"订阅，订购(杂志或报纸)","en":"If you subscribe to a magazine or a newspaper, you pay to receive copies of it regularly.","ex":{"en":"My main reason for subscribing to New Scientist is to keep abreast of advances in science.","cn":"我订阅《新科学家》主要是为了了解科学的最新进展。"}},{"pos":"VERB 动词","cn":"申请;注册;报名","en":"If you subscribe to an online newsgroup or service, you send a message saying that you wish to receive it or belong to it.","ex":{"en":"Usenet is a collection of discussion groups, known as newsgroups, to which anybody can subscribe.","cn":"全球新闻网络是由多个被称为新闻组的讨论组组成，任何人都可以注册加入。"}},{"pos":"VERB 动词","cn":"定期资助;定期捐款;定期捐助","en":"If you subscribe to a charity or a campaign, you send money to it regularly.","ex":{"en":"I subscribe to a few favourite charities.","cn":"我定期向几个中意的慈善机构捐款。"}},{"pos":"VERB 动词","cn":"认购(股份)","en":"If you subscribe for shares in a company, you apply to buy shares in that company.","ex":{"en":"Employees subscribed for far more shares than were available.","cn":"员工申请认购的股份远远超出实际可认购的额度。"}}]},"media":{"uk":"media/uk/subscribe__gb_1.mp3","us":"media/us/subscribe__us_1.mp3"},"examples":[{"en":"The authorities no longer subscribe to the view that disabled people are unsuitable as teachers.","cn":"当局不再支持残疾人不适宜做教师的观点。"},{"en":"We subscribe to several sports channels (= on TV).","cn":"我们付费收看好几个体育频道。"}]},"sustainable":{"media":{"uk":"media/uk/sustainable__gb_1.mp3","us":"media/us/sustainable__us_1.mp3"},"oxford":{"phon":"səˈsteɪnəbl","pos":"adjective","senses":[{"en":"involving the use of natural products and energy in a way that does not harm the environment","cn":"（对自然资源和能源的利用）不破坏生态平衡的，合理利用的","ex":{"en":"sustainable forest management","cn":"合理的森林管理"}},{"en":"that can continue or be continued for a long time","cn":"可持续的","ex":{"en":"sustainable economic growth","cn":"经济的可持续增长"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(自然资源)可持续的，不破坏环境的","en":"You use sustainable to describe the use of natural resources when this use is kept at a steady level that is not likely to damage the environment.","ex":{"en":"...the management, conservation and sustainable development of forests","cn":"森林的管理、保护和可持续发展"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(计划、方法、体制)可持续的，持续性的","en":"A sustainable plan, method, or system is designed to continue at the same rate or level of activity without any problems.","ex":{"en":"The creation of an efficient and sustainable transport system is critical to the long-term future of London.","cn":"建立一套高效稳定的交通体系对伦敦的长远发展意义重大。"}}]},"examples":[{"en":"an environmentally sustainable society","cn":"保持生态环境平衡的社会"},{"en":"sustainable economic growth","cn":"经济的可持续增长"}]},"superlative":{"oxford":{"phon":"suːˈpɜːlətɪv","pos":"adjective","senses":[{"en":"excellent","cn":"极佳的；卓越的；最优秀的","ex":{"en":"a superlative performance","cn":"精彩绝伦的演出"}},{"en":"relating to adjectives or adverbs that express the highest degree of something, for example best, worst, slowest and most difficult","cn":"（形容词或副词）最高级的","lab":"grammar"},{"en":"the form of an adjective or adverb that expresses the highest degree of something","cn":"（形容词或副词的）最高级","ex":{"en":"It's hard to find enough superlatives to describe this book.","cn":"用再多的盛赞之辞也难以描述这本书。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极佳的;最优秀的;卓越的","en":"If you describe something as superlative, you mean that it is extremely good.","ex":{"en":"Some superlative wines are made in this region","cn":"一些上好的葡萄酒就是在这个地区酿造的。"}},{"pos":"N-COUNT 可数名词","cn":"最高级别;最佳","en":"If someone uses superlatives to describe something, they use adjectives and expressions which indicate that it is extremely good.","ex":{"en":"...a spectacle which has critics world-wide reaching for superlatives.","cn":"世界各地的评论家们都极尽溢美之词夸赞不已的盛况"}},{"pos":"ADJ 形容词","cn":"(形容词或副词)最高级的","en":"In grammar, the superlative form of an adjective or adverb is the form that indicates that something has more of a quality than anything else in a group. For example, 'biggest' is the superlative form of 'big'.","ex":{"en":"...his tendency towards superlatives and exaggeration.","cn":"他爱用最高级词语并喜欢夸张的说法"}}]},"media":{"uk":"media/uk/superlative__gb_1.mp3","us":"media/us/superlative__us_1.mp3"},"examples":[{"en":"It's hard to find enough superlatives to describe this book.","cn":"用再多的盛赞之辞也难以描述这本书。"},{"en":"a superlative performance","cn":"精彩绝伦的演出"}]},"summarily":{"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"immediately, and without following the normal process","cn":"即刻﹔速决地﹐草草地〔未遵循惯常的程序〕"}]},"examples":[{"en":"He was summarily dismissed.","cn":"他被立即开除。","src":"ld"}],"media":{"uk":"media/uk/summarily__gb_1.mp3","us":"media/us/summarily__us_1.mp3"},"oxford":{"phon":"ˈsʌmərəli","pos":"adverb","senses":[{"en":"immediately, without paying attention to the normal process that should be followed","cn":"从速从简的；即决的；草草的","ex":{"en":"to be summarily dismissed/executed","cn":"被草草开除／处决"}}]}},"supermarket":{"oxford":{"phon":"ˈsuːpəmɑːkɪt","pos":"noun","senses":[{"en":"a large shop that sells food, drinks and goods used in the home. People choose what they want from the shelves and pay for it as they leave.","cn":"超级市场；超市","lab":"British English","ex":{"en":"I only shop at this supermarket.","cn":"我只在这家超市购物。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超级市场;超市","en":"A supermarket is a large shop which sells all kinds of food and some household goods.","ex":{"en":"Most of us do our food shopping in the supermarket","cn":"我们大多数人去超市购买食品。"}}]},"media":{"uk":"media/uk/supermarket__gb_1.mp3","us":"media/us/supermarket__us_1.mp3"}},"survived":{"lemma":"survive"},"sub":{"oxford":{"phon":"sʌb","pos":"noun","senses":[{"en":"a submarine (= a ship that can travel underwater)","cn":"潜艇"},{"en":"a long bread roll split open along its length and filled with various types of food","cn":"潜艇三明治，长卷三明治（用长卷面包纵向切开，内夹各种食物）","lab":"North American English"},{"en":"a substitute who replaces another player in a team","cn":"替补队员","ex":{"en":"He came on as sub.","cn":"他作为替补上场。"}},{"en":"a subscription (= money that you pay regularly when you are a member of a club, etc.)","cn":"（向俱乐部等定期交纳的）会员费","lab":"British English"},{"en":"a subeditor","cn":"助理编辑；审校人","lab":"British English"},{"en":"a substitute teacher","cn":"代课教师","lab":"North American English"},{"en":"to replace a sports player with another player during a game","cn":"（在比赛中）替换（队员）","g":"[transitive]","ex":{"en":"He was subbed after just five minutes because of a knee injury.","cn":"他仅上场了五分钟便因膝部受伤被替换下场。"},"pos":"verb"},{"en":"to do somebody else’s job for them for a short time","cn":"暂代（某人）工作；替班","g":"[intransitive]","ex":{"en":"Jake asked me to sub for him next week when he's away in California.","cn":"杰克要求我下周他去加利福尼亚时替补他。"},"pos":"verb"},{"en":"to use something instead of something else, especially instead of the thing you would normally use","cn":"代用；替代（尤指通常使用的东西）","g":"[transitive]","ex":{"en":"For a lower-calorie version of the recipe, try subbing milk for cream.","cn":"要降低这道菜的热量，可用牛奶代替奶油。"},"pos":"verb"},{"en":"to lend somebody money for a short time","cn":"短期借（款）给","g":"[transitive]","lab":"British English, informal，，","ex":{"en":"Could you sub me £50 till next week?","cn":"借我 50 英镑，下星期还你，可以吗？"},"pos":"verb"},{"en":"below; less than","cn":"在…以下；少于；低于；亚于；次于","ex":{"en":"sub-zero temperatures","cn":"零度以下气温"},"pos":"prefix"},{"en":"under","cn":"在…下面（或底下）","ex":{"en":"subway","cn":"地铁"},"pos":"prefix"},{"en":"a smaller part of something","cn":"分支；分部；分","ex":{"en":"subdivide","cn":"再划分"},"pos":"prefix"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"替补队员","en":"In team games such as football, a sub is a player who is brought into a match to replace another player.","ex":{"en":"We had a few injuries and had to use youth team kids as subs.","cn":"我们有几名队员有伤，只好用青年队的小队员做替补。"}},{"pos":"N-COUNT 可数名词","cn":"同 submarine","en":"A sub is the same as a submarine ."},{"pos":"N-PLURAL 复数名词","cn":"(向俱乐部、协会缴纳的)会员费","en":"A fixed amount of money that you pay regularly in order to be a member of a club or society is called your subs .","ex":{"en":"Subs will be raised as from next year.","cn":"从明年开始将提高会费。"}}]},"media":{"uk":"media/uk/sub__gb_1.mp3","us":"media/us/sub__us_1.mp3"},"examples":[{"en":"He was subbed after just five minutes because of a knee injury.","cn":"他仅上场了五分钟便因膝部受伤被替换下场。"},{"en":"For a lower-calorie version of the recipe, try subbing milk for cream.","cn":"要降低这道菜的热量，可用牛奶代替奶油。"}]},"suspicious":{"media":{"uk":"media/uk/suspicious__gb_1.mp3","us":"media/us/suspicious__us_1.mp3"},"oxford":{"phon":"səˈspɪʃəs","pos":"adjective","senses":[{"en":"feeling that somebody has done something wrong, illegal or dishonest, without having any proof","cn":"感觉可疑的；怀疑的","ex":{"en":"They became suspicious of his behaviour and contacted the police.","cn":"他们开始觉得他行为可疑，便报了警。"}},{"en":"making you feel that something is wrong, illegal or dishonest","cn":"令人怀疑的；可疑的","ex":{"en":"Didn't you notice anything suspicious in his behaviour?","cn":"你难道没有注意到他行为有可疑之处？"}},{"en":"not willing or able to trust somebody/something","cn":"不信任的；持怀疑态度的","ex":{"en":"I was suspicious of his motives.","cn":"我怀疑他的动机。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"猜疑的;怀疑的","en":"If you are suspicious of someone or something, you do not trust them, and are careful when dealing with them.","ex":{"en":"He was rightly suspicious of meeting me until I reassured him I was not writing about him","cn":"当然他很不放心见我，直到我再一次向他保证我不是在写他。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"觉得可疑的;起疑的","en":"If you are suspicious of someone or something, you believe that they are probably involved in a crime or some dishonest activity.","ex":{"en":"Two officers on patrol became suspicious of two men in a car","cn":"两名巡警开始对一辆车里的两个人起了疑心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引起怀疑的;可疑的","en":"If you describe someone or something as suspicious, you mean that there is some aspect of them which makes you think that they are involved in a crime or a dishonest activity.","ex":{"en":"He reported that two suspicious-looking characters had approached Callendar","cn":"他报告说两个形迹可疑的人曾跟卡伦德接触过。"}}]},"examples":[{"en":"They became suspicious of his behaviour and contacted the police.","cn":"他们开始觉得他行为可疑，便报了警。"},{"en":"Didn't you notice anything suspicious in his behaviour?","cn":"你难道没有注意到他行为有可疑之处？"}]},"succeed":{"media":{"uk":"media/uk/succeed__gb_1.mp3","us":"media/us/succeed__us_1.mp3"},"oxford":{"phon":"səkˈsiːd","pos":"verb","senses":[{"en":"to achieve something that you have been trying to do or get; to have the result or effect that was intended","cn":"达到目的；实现目标；办到；做成","g":"[intransitive]","ex":{"en":"Our plan succeeded.","cn":"我们的计划成功了。"}},{"en":"to be successful in your job, earning money, power, respect, etc.","cn":"成功；有成就；有作为","g":"[intransitive]","ex":{"en":"You will have to work hard if you are to succeed.","cn":"要想有所作为，你必须苦干。"}},{"en":"to come next after somebody/something and take their/its place or position","cn":"接替；继任；随后出现","g":"[transitive]","ex":{"en":"Who succeeded Kennedy as President?","cn":"接替肯尼迪任总统的是谁？"}},{"en":"to gain the right to a title, property, etc. when somebody dies","cn":"继承","g":"[intransitive]","ex":{"en":"She succeeded to the throne (= became queen) in 1558.","cn":"她于 1558 年继承王位。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"达到目的;成功做成;办到","en":"If you succeed in doing something, you manage to do it.","ex":{"en":"We have already succeeded in working out ground rules with the Department of Defense","cn":"我们已经成功地与国防部敲定了基本原则。"}},{"pos":"VERB 动词","cn":"取得预期效果;表现良好","en":"If something succeeds, it works in a satisfactory way or has the result that is intended.","ex":{"en":"If marriage is to succeed in the 1990's, then people have to recognise the new pressures it is facing.","cn":"在 20 世纪 90 年代人们要想婚姻美满，那就不得不认识到它所面临的新压力。"}},{"pos":"VERB 动词","cn":"功成名就;有作为","en":"Someone who succeeds gains a high position in what they do, for example in business or politics.","ex":{"en":"...the skills and qualities needed to succeed in small and medium-sized businesses.","cn":"经营好中小企业所需的技能和素质"}},{"pos":"VERB 动词","cn":"接替;继任","en":"If you succeed another person, you are the next person to have their job or position.","ex":{"en":"David Rowland is almost certain to succeed him as chairman on January 1","cn":"戴维·罗兰将在 1 月 1 日接替他任主席几乎已成定局。"}},{"pos":"VERB 动词","cn":"在…之后;随…其后","en":"If one thing is succeeded by another thing, the other thing happens or comes after it.","ex":{"en":"A quick divorce can be succeeded by a much longer — and more agonising — period of haggling over the fate of the family.","cn":"闪电式离婚后可能紧接着就是一段在家庭命运上互相纠结的更加漫长、更加痛苦的时期。"}}]},"examples":[{"en":"She doesn't have the ruthlessness required to succeed in business.","cn":"要在生意场上干出一番名堂，她缺乏必要的冷酷心肠。"},{"en":"Their early success was succeeded by a period of miserable failure.","cn":"他们起初获得成功，但随后有一段惨痛的失败时期。"}]},"submit":{"media":{"uk":"media/uk/submit__gb_1.mp3","us":"media/us/submit__us_1.mp3"},"oxford":{"phon":"səbˈmɪt","pos":"verb","senses":[{"en":"to give a document, proposal, etc. to somebody in authority so that they can study or consider it","cn":"提交，呈递（文件、建议等）","g":"[transitive]","ex":{"en":"to submit an application/a claim/a proposal","cn":"呈递申请书／书面要求／建议"}},{"en":"to accept the authority, control or greater strength of somebody/something; to agree to something because of this","cn":"顺从；屈服；投降；不得已接受","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"She refused to submit to threats.","cn":"面对威胁，她拒不低头。"}},{"en":"to say or suggest something","cn":"表示；认为；主张；建议","g":"[transitive]","lab":"law or formal","ex":{"en":"Counsel for the defence submitted that the evidence was inadmissible.","cn":"被告律师认为这一证据不可采纳。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"顺从;屈服;投降;被迫接受","en":"If you submit to something, you unwillingly allow something to be done to you, or you do what someone wants, for example because you are not powerful enough to resist.","ex":{"en":"In desperation, Mrs. Jones submitted to an operation on her right knee to relieve the pain","cn":"绝望之际，琼斯夫人只好同意在其右膝上做手术以减轻疼痛。"}},{"pos":"VERB 动词","cn":"提交，递呈(建议、报告或请求)","en":"If you submit a proposal, report, or request to someone, you formally send it to them so that they can consider it or decide about it.","ex":{"en":"They submitted their reports to the Chancellor yesterday","cn":"他们昨天向财政大臣递交了报告。"}}]},"examples":[{"en":"Completed projects must be submitted by 10 March.","cn":"完成的方案必须在 3 月 10 日前提交。"},{"en":"to submit an application/a claim/a complaint","cn":"呈递申请书/书面要求；提交控诉书"}]},"subway":{"media":{"img":["media/pic/trains_comp.jpg","media/thumb/underground.jpg"],"uk":"media/uk/subway__gb_1.mp3","us":"media/us/subway__us_1.mp3"},"oxford":{"phon":"ˈsʌbweɪ","pos":"noun","senses":[{"en":"an underground railway system in a city","cn":"地铁；地下铁路系统","lab":"North American English","ex":{"en":"the New York subway","cn":"纽约地铁"}},{"en":"a path that goes under a road, etc. which people can use to cross to the other side","cn":"（穿越马路等的）地下人行道","lab":"British English","ex":{"en":"He ran through the pedestrian subway.","cn":"他跑过地下人行道。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地铁","en":"A subway is an underground railway.","ex":{"en":"...the Bay Area Rapid Transit subway system","cn":"旧金山海湾地区地铁捷运系统"}},{"pos":"N-COUNT 可数名词","cn":"(穿越马路、铁路的)地下通道，地下人行道","en":"A subway is a passage underneath a busy road or a railway track for people to walk through.","ex":{"en":"The majority of us feel worried if we walk through a subway.","cn":"大多数人在走地下通道时都感到害怕。"}}]},"examples":[{"en":"a downtown subway stop","cn":"闹市区的地铁站"},{"en":"a subway station/train","cn":"地铁站/列车"}]},"summer":{"media":{"uk":"media/uk/summer__gb_1.mp3","us":"media/us/summer__us_1.mp3"},"oxford":{"phon":"ˈsʌmə(r)","pos":"noun","senses":[{"en":"the warmest season of the year, coming between spring and autumn","cn":"夏天；夏季","ex":{"en":"We're going away in the summer.","cn":"夏天我们要外出。"}},{"en":"a first name for girls","cn":"萨默（女子名）","pos":""}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"夏天;夏季","en":"Summer is the season between spring and autumn. In the summer the weather is usually warm or hot.","ex":{"en":"I escaped the heatwave in London earlier this summer and flew to Cork","cn":"今年初夏我逃离了伦敦的炎热，飞往科克去避暑。"}}]},"examples":[{"en":"We're going away in the summer.","cn":"夏天我们要外出。"},{"en":"It's very hot here in summer.","cn":"这里夏天很热。"}]},"supposedly":{"media":{"uk":"media/uk/supposedly__gb_1.mp3","us":"media/us/supposedly__us_1.mp3"},"oxford":{"phon":"səˈpəʊzɪdli","pos":"adverb","senses":[{"en":"according to what is generally thought or believed but not known for certain","cn":"据信；据传；据说","ex":{"en":"The novel is supposedly based on a true story.","cn":"据说这部小说取材于一个真实的故事。"}}]},"examples":[{"en":"The novel is supposedly based on a true story.","cn":"据说这部小说是以一个真实的故事为依据的。"},{"en":"How could a supposedly intelligent person be so stupid?","cn":"一个所谓的聪明人怎么会这么愚蠢？"}]},"sunshine":{"media":{"uk":"media/uk/sunshine__gb_1.mp3","us":"media/us/sunshine__us_1.mp3"},"oxford":{"phon":"ˈsʌnʃaɪn","pos":"noun","senses":[{"en":"the light and heat of the sun","cn":"阳光；日光","lab":"North American English","ex":{"en":"the warm spring sunshine","cn":"春天和煦的阳光"}},{"en":"happiness","cn":"欢乐；幸福","lab":"informal","ex":{"en":"She brought sunshine into our dull lives.","cn":"她给我们乏味的生活带来了欢乐。"}},{"en":"used for addressing somebody in a friendly, or sometimes a rude way","cn":"（友好地称呼某人，有时显得不礼貌）朋友，老兄","lab":"British English, informal，，","ex":{"en":"Hello, sunshine!","cn":"你好啊，老兄！"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"阳光;日光","en":"Sunshine is the light and heat that comes from the sun.","ex":{"en":"In the marina yachts sparkle in the sunshine","cn":"码头上游艇在阳光下闪闪发光。"}}]},"examples":[{"en":"Look, sunshine, who do you think you're talking to?","cn":"喂，哥们儿，知道你在跟谁说话吗？"},{"en":"She brought sunshine into our dull lives.","cn":"她给我们乏味的生活带来了欢乐。"}]},"suffices":{"lemma":"suffice","media":{"uk":"media/uk/suffice__gb_1.mp3","us":"media/us/suffice__us_1.mp3"}},"suffix":{"media":{"uk":"media/uk/suffix__gb_1.mp3","us":"media/us/suffix__us_1.mp3"},"oxford":{"phon":"ˈsʌfɪks","pos":"noun","senses":[{"en":"a letter or group of letters added to the end of a word to make another word, such as -ly in quickly or -ness in sadness","cn":"后缀，词尾（加在词尾，用以构成新词，如 quickly 中的 -ly 或 sadness 中的 -ness）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"后缀;词尾","en":"A suffix is a letter or group of letters, for example '-ly' or '-ness', which is added to the end of a word in order to form a different word, often of a different word class. For example, the suffix '-ly' is added to 'quick' to form 'quickly'."},{"pos":"N-COUNT 可数名词","cn":"(注于代码末尾的)尾标","en":"A suffix is one or more numbers or letters added to the end of a code number to indicate, for example, what area something belongs to.","ex":{"en":"These ships were all numbered with the suffix LBK.","cn":"这些船都有编号，末尾都是 LBK。"}}]}},"subtly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a subtle change or difference is difficult to notice unless you look closely or think about it carefully","cn":""},{"en":"something, especially an object, that is unobtrusive is not very noticeable, especially because it is small or ordinary compared to other things","cn":""}]},"examples":[{"en":"The pictures are similar, but there are subtle differences between them.","cn":"","src":"ld"},{"en":"The warning signs of the disease are so subtle that they are often ignored.","cn":"","src":"ld"}],"media":{"uk":"media/uk/subtly__gb_1.mp3","us":"media/us/subtly__us_1.mp3"},"oxford":{"phon":"ˈsʌtəli","pos":"adverb","senses":[{"en":"in a way that is not very obvious or easy to notice","cn":"巧妙地：以一种不太明显或不容易注意到的方式","ex":{"en":"Her version of events is subtly different from what actually happened.","cn":"她对事件的描述和实际情况略有不同。"}},{"en":"in a clever way, especially by using indirect methods","cn":"巧妙地：巧妙地，特别是通过使用间接方法","ex":{"en":"Not very subtly, he raised the subject of money.","cn":"他不怎么巧妙地提起了钱的事。"}}]}},"surfboard":{"oxford":{"phon":"ˈsɜːfbɔːd","pos":"noun","senses":[{"en":"a long narrow board used for surfing","cn":"冲浪板"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"冲浪板","en":"A surfboard is a long narrow board that is used for surfing."}]},"media":{"uk":"media/uk/surfboard__gb_1.mp3","us":"media/us/surfboard__us_1.mp3","img":["media/ldoce/img/surfboard.jpg"]}},"substances":{"lemma":"substance"},"surprised":{"media":{"uk":"media/uk/surprised__gb_1.mp3","us":"media/us/surprised__us_1.mp3"},"oxford":{"phon":"səˈpraɪzd","pos":"adjective","senses":[{"en":"feeling or showing surprise","cn":"惊奇的；惊讶的；觉得奇怪的；感觉意外的","ex":{"en":"a surprised look","cn":"惊讶的神色"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"惊奇的;惊讶的;觉得奇怪的;感觉意外的","en":"If you are surprised at something, you have a feeling of surprise, because it is unexpected or unusual.","ex":{"en":"This lady was genuinely surprised at what happened to her pet","cn":"这位女士对发生在自己宠物身上的事感到非常惊讶。"}}]},"examples":[{"en":"‘Will she cancel the party?’ ‘ I wouldn't be surprised. ’ “","cn":"她会取消这次聚会吗？” “即使取消我也不感到奇怪。”"},{"en":"I'm surprised at you, behaving like that in front of the kids.","cn":"我真想不到，当着孩子们的面你竟做出这种举动。"}],"base":"surprise"},"summaries":{"lemma":"summary"},"supervision":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"监督;管理","en":"Supervision is the supervising of people, activities, or places.","ex":{"en":"A toddler requires close supervision and firm control at all times","cn":"刚学步的孩子时刻需要寸步不离的照看，并要牢牢看紧。"}}]},"media":{"uk":"media/uk/supervision__gb_1.mp3","us":"media/us/supervision__us_1.mp3"},"examples":[{"en":"Very young children should not be left to play without supervision.","cn":"不能让幼儿在没人照看的情况下独自玩耍。"},{"en":"The drug should only be used under medical supervision.","cn":"这种药须遵医嘱方可使用。"}],"oxford":{"phon":"ˌsuːpəˈvɪʒn","pos":"noun","senses":[{"en":"the work or activity involved in being in charge of somebody/something and making sure that everything is done correctly, safely, etc.","cn":"监督；管理；指导；主管","g":"[uncountable]","ex":{"en":"Very young children should not be left to play without supervision.","cn":"幼儿不应在无人看管的情况下独自玩耍。"}},{"en":"a meeting between a student and their tutor or supervisor that involves teaching and discussion of the student's work","cn":"（导师辅导学生的）督导会","g":"[countable]","ex":{"en":"I have weekly supervisions.","cn":"我每周都有督导会。"}}]}},"supporter":{"oxford":{"phon":"səˈpɔːtə(r)","pos":"noun","senses":[{"en":"a person who supports a political party, an idea, etc.","cn":"支持者；拥护者","ex":{"en":"a strong/loyal/staunch/ardent supporter","cn":"积极的／忠实的／坚定的／热情的支持者"}},{"en":"a person who supports a particular sports team","cn":"（运动队的）支持者","lab":"British English","ex":{"en":"I'm an Arsenal supporter.","cn":"我是阿森纳队的球迷。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"支持者;拥护者","en":"Supporters are people who support someone or something, for example a political leader or a sports team.","ex":{"en":"The fourth night of violence in the German city of Rostock was triggered by football supporters","cn":"发生在德国城市罗斯托克的第四起夜间暴乱是由足球球迷们挑起的。"}}]},"media":{"uk":"media/uk/supporter__gb_1.mp3","us":"media/us/supporter__us_1.mp3"},"examples":[{"en":"I'm an Arsenal supporter.","cn":"我是阿森纳队的球迷。"},{"en":"a strong/loyal/staunch supporter","cn":"积极的/忠实的/坚定的支持者"}]},"surfing":{"media":{"img":["media/pic/watersports_comp.jpg","media/thumb/surfing.jpg"],"uk":"media/uk/surfing__gb_1.mp3","us":"media/us/surfing__us_1.mp3"},"oxford":{"phon":"ˈsɜːfɪŋ","pos":"noun","senses":[{"en":"the sport of riding on waves while standing on a narrow board called a surfboard","cn":"冲浪运动","ex":{"en":"to go surfing","cn":"去冲浪"}},{"en":"the activity of looking at different things on the internet in order to find something interesting","cn":"（互联网上）冲浪，漫游，浏览"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"冲浪运动","en":"Surfing is the sport of riding on the top of a wave while standing or lying on a special board."},{"pos":"N-UNCOUNT 不可数名词","cn":"(互联网上的)冲浪，漫游，浏览","en":"Surfing is the activity of looking at different sites on the Internet, especially when you are not looking for anything in particular.","ex":{"en":"The simple fact is that, for most people, surfing is too expensive.","cn":"事情很简单，那就是对大多数人来说，网上冲浪费用太高。"}}]},"examples":[{"en":"to go surfing","cn":"去冲浪"},{"en":"When we were in Hawaii, we went surfing every day.","cn":"我们在夏威夷时每天都去冲浪。"}],"base":"surf"},"superlatives":{"lemma":"superlative"},"surprises":{"lemma":"surprise","media":{"uk":"media/uk/surprise__gb_1.mp3","us":"media/us/surprise__us_1.mp3"}},"sustain":{"oxford":{"phon":"səˈsteɪn","pos":"verb","senses":[{"en":"to provide enough of what somebody/something needs in order to live or exist","cn":"维持（生命、生存）","ex":{"en":"Which planets can sustain life?","cn":"哪些行星可以维持生命的存在？"}},{"en":"to make something continue for some time without becoming less","cn":"使保持；使稳定持续","ex":{"en":"She managed to sustain everyone's interest until the end of her speech.","cn":"她使每个人兴趣盎然，一直听她把话讲完。"}},{"en":"to experience something bad","cn":"遭受；蒙受；经受","lab":"formal","ex":{"en":"to sustain damage/an injury/a defeat","cn":"遭受损失；受伤；遭到失败"}},{"en":"to provide evidence to support an opinion, a theory, etc.","cn":"证明；证实","ex":{"en":"The evidence is not detailed enough to sustain his argument.","cn":"这一证据过于笼统，不足以证明他的论点。"}},{"en":"to support a weight without breaking or falling","cn":"支撑；承受住","lab":"formal","ex":{"en":"The ice will not sustain your weight.","cn":"这冰承受不了你的体重。"}},{"en":"to decide that a claim, etc. is true or legally valid","cn":"认可；确认；准许；支持","lab":"law","ex":{"en":"The court sustained his claim that the contract was illegal.","cn":"法庭支持他的主张，认定该合同不合法。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使持续;保持","en":"If you sustain something, you continue it or maintain it for a period of time.","ex":{"en":"But he has sustained his fierce social conscience from young adulthood through old age","cn":"而他从青年时期一直到老年都始终保持着强烈的社会良知。"}},{"pos":"VERB 动词","cn":"经受;遭受;蒙受","en":"If you sustain something such as a defeat, loss, or injury, it happens to you.","ex":{"en":"Every aircraft in there has sustained some damage","cn":"那里的每架飞机都受到了一些损坏。"}},{"pos":"VERB 动词","cn":"支持;支援;救济","en":"If something sustains you, it supports you by giving you help, strength, or encouragement.","ex":{"en":"The cash dividends they get from the cash crop would sustain them during the lean season","cn":"从经济作物中获得的收益能帮助他们度过不景气的时期。"}}]},"media":{"uk":"media/uk/sustain__gb_1.mp3","us":"media/us/sustain__us_1.mp3"},"examples":[{"en":"The love and support of his family sustained him during his time in prison.","cn":"家人的关爱和支持帮助他度过了狱中的岁月。"},{"en":"She managed to sustain everyone's interest until the end of her speech.","cn":"她使每个人兴趣盎然，一直听她把话讲完。"}]},"successor":{"media":{"uk":"media/uk/successor__gb_1.mp3","us":"media/us/successor__us_1.mp3"},"oxford":{"phon":"səkˈsesə(r)","pos":"noun","senses":[{"en":"a person or thing that comes after somebody/something else and takes their/its place","cn":"接替者；继任者；接替的事物；后继的事物","ex":{"en":"Who's the likely successor to him as party leader?","cn":"谁较可能接替他担任党的领袖？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"接任者;继承者","en":"Someone's successor is the person who takes their job after they have left.","ex":{"en":"He set out several principles that he hopes will guide his successors","cn":"他制订了几条原则，希望可以引导继任者。"}}]},"examples":[{"en":"Their latest release is a worthy successor to their popular debut album.","cn":"继首张唱片大受欢迎之后，他们最新推出的专辑再获成功。"},{"en":"Who's the likely successor to him as party leader?","cn":"谁较可能接替他担任党的领袖？"}]},"supplementary":{"media":{"uk":"media/uk/supplementary__gb_1.mp3","us":"media/us/supplementary__us_1.mp3"},"oxford":{"phon":"ˌsʌplɪˈmentri","pos":"adjective","senses":[{"en":"provided in addition to something else in order to improve or complete it","cn":"增补性的；补充性的；额外的；外加的","ex":{"en":"supplementary information","cn":"补充信息"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"增补性的;补充性的;额外的","en":"Supplementary things are added to something in order to improve it.","ex":{"en":"...the question of whether or not we need to take supplementary vitamins","cn":"是否需要补充维生素的问题"}}]},"examples":[{"en":"supplementary information","cn":"补充信息"}]},"subservient":{"media":{"uk":"media/uk/subservient__gb_1.mp3","us":"media/us/subservient__us_1.mp3"},"oxford":{"phon":"səbˈsɜːviənt","pos":"adjective","senses":[{"en":"too willing to obey other people","cn":"恭顺的；驯服的；谄媚的；卑躬屈膝的","lab":"disapproving","ex":{"en":"The press was accused of being subservient to the government.","cn":"有人指责新闻界一味迎合政府。"}},{"en":"less important than something else","cn":"次要；从属于","lab":"formal","ex":{"en":"The needs of individuals were subservient to those of the group as a whole.","cn":"个人的需要服从于整个集体的需要。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"屈从的;恭顺的;顺从的","en":"If you are subservient, you do whatever someone wants you to do.","ex":{"en":"She is expected to be subservient to her uncle.","cn":"她被要求对叔叔恭敬顺从。"}},{"pos":"ADJ 形容词","cn":"次要的;从属于…的","en":"If you treat one thing as subservient to another, you treat it as less important than the other thing.","ex":{"en":"The woman's needs are seen as subservient to the group interest.","cn":"妇女的需求被认为要服从团体的利益。"}}]},"examples":[{"en":"The press was accused of being subservient to the government.","cn":"有人指责新闻界一味迎合政府的旨意。"},{"en":"The needs of individuals were subservient to those of the group as a whole.","cn":"个人的需要服从于整个集体的需要。"}]},"subject":{"media":{"uk":"media/uk/subject__gb_1.mp3","us":"media/us/subject__us_1.mp3"},"oxford":{"phon":"ˈsʌbdʒɪkt","pos":"noun","senses":[{"en":"a thing or person that is being discussed, described or dealt with","cn":"主题；话题；题材；问题","sc":"of conversation/book","ex":{"en":"Walker's work has been the subject of much debate.","cn":"沃克的作品一直是极具争议的话题。"}},{"en":"an area of knowledge studied in a school, college, etc.","cn":"学科；科目；课程","sc":"at school/college","ex":{"en":"Biology is my favourite subject.","cn":"生物是我最喜欢的学科。"}},{"en":"a person or thing that is the main feature of a picture or photograph, or that a work of art is based on","cn":"表现对象；绘画（或拍摄）题材","sc":"of picture/photograph","ex":{"en":"Focus the camera on the subject.","cn":"把相机的焦距调到被拍对象上。"}},{"en":"a person or thing being used to study something, especially in an experiment","cn":"接受试验者；实验对象","sc":"of experiment","ex":{"en":"We need male subjects between the ages of 18 and 25 for the experiment.","cn":"我们需要 18 至 25 岁之间的男性来接受试验。"}},{"en":"a noun, noun phrase or pronoun representing the person or thing that performs the action of the verb (I in I sat down.), about which something is stated (the house in the house is very old) or, in a passive sentence, that is affected by the action of the verb (the tree in the tree was blown down in the storm)","cn":"主语","sc":"grammar"},{"en":"a person who belongs to a particular country, especially one with a king or queen","cn":"（尤指君主制国家的）国民，臣民","sc":"of country","ex":{"en":"a British subject","cn":"英国国民"}},{"en":"likely to be affected by something, especially something bad","cn":"可能受…影响的；易遭受…的","ex":{"en":"At this stage these are proposals and are still subject to change.","cn":"目前这些只是建议，还可以修改。"},"pos":"adjective"},{"en":"depending on something in order to be completed or agreed","cn":"取决于；视…而定","ex":{"en":"The article is ready to publish, subject to your approval.","cn":"文章已完成，经你批准，即可发表。"},"pos":"adjective"},{"en":"under the authority of something/somebody","cn":"受…支配；服从于","ex":{"en":"As a diplomat, he is not subject to local laws.","cn":"作为外交官，他不受当地法律约束。"},"pos":"adjective"},{"en":"controlled by the government of another country","cn":"受异族统治的；臣服的","g":"[only before noun]","ex":{"en":"subject peoples","cn":"被他国统治的民族"},"pos":"adjective"},{"en":"to bring a country or group of people under your control, especially by using force","cn":"使臣服；使顺从；（尤指）压服","ex":{"en":"The Roman Empire subjected most of Europe to its rule.","cn":"罗马帝国把欧洲多数地区置于自己的统治之下。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"主题;题目;话题;题材;问题","en":"The subject of something such as a conversation, letter, or book is the thing that is being discussed or written about.","ex":{"en":"It was I who first raised the subject of plastic surgery.","cn":"是我第一个提到整形手术这个话题的。"}},{"pos":"N-COUNT 可数名词","cn":"(批评、学习、调查的)对象","en":"Someone or something that is the subject of criticism, study, or an investigation is being criticized, studied, or investigated.","ex":{"en":"Over the past few years, some of the positions Mr. Meredith has adopted have made him the subject of criticism","cn":"在过去的几年里，梅雷迪思先生所采取的某些立场使他成为了批评的对象。"}},{"pos":"N-COUNT 可数名词","cn":"(知识、研究)领域;(尤指)学科，科目，课程","en":"A subject is an area of knowledge or study, especially one that you study at school, college, or university.","ex":{"en":"Surprisingly, mathematics was voted their favourite subject.","cn":"令人惊讶的是，数学课被选为他们最喜欢的科目。"}},{"pos":"N-COUNT 可数名词","cn":"研究对象;实验对象","en":"In an experiment or piece of research, the subject is the person or animal that is being tested or studied.","ex":{"en":"'White noise' was played into the subject's ears through headphones","cn":"让受试者通过耳机听“白噪声”。"}},{"pos":"N-COUNT 可数名词","cn":"(艺术的)表现对象;绘画(或拍摄)题材","en":"An artist's subjects are the people, animals, or objects that he or she paints, models, or photographs.","ex":{"en":"Her favourite subjects are shells spotted on beach walks.","cn":"她最喜爱的题材是那些在海边散步时发现的贝壳。"}},{"pos":"N-COUNT 可数名词","cn":"(语法中的)主语","en":"In grammar, the subject of a clause is the noun group that refers to the person or thing that is doing the action expressed by the verb. For example, in 'My cat keeps catching birds', 'my cat' is the subject."},{"pos":"ADJ 形容词","cn":"可能受…影响的;易遭受…的","en":"To be subject to something means to be affected by it or to be likely to be affected by it.","ex":{"en":"Prices may be subject to alteration","cn":"价格可能会有所变动。"}},{"pos":"ADJ 形容词","cn":"受…支配的;服从于…的","en":"If someone is subject to a particular set of rules or laws, they have to obey those rules or laws.","ex":{"en":"The tribunal is unique because Mr Jones is not subject to the normal police discipline code.","cn":"因为琼斯先生不受一般的治安条例法规约束，所以专门设立了特别法庭。"}},{"pos":"VERB 动词","cn":"使经受;使遭受","en":"If you subject someone to something unpleasant, you make them experience it.","ex":{"en":"...the man who had subjected her to four years of beatings and abuse","cn":"使她遭受了 4 年毒打和辱骂的男人"}},{"pos":"N-COUNT 可数名词","cn":"(通常指君主制国家的)国民，臣民","en":"The people who live in or belong to a particular country, usually one ruled by a monarch, are the subjects of that monarch or country.","ex":{"en":"...his subjects regarded him as a great and wise monarch","cn":"他的臣民把他视为伟大而英明的君主"}},{"pos":"ADJ 形容词","cn":"臣服的;受他国统治的","en":"Subject peoples and countries are ruled or controlled by the government of another country.","ex":{"en":"The subject peoples of her empire were anxious for their own independence.","cn":"她的帝国中被迫向她臣服的民族迫切渴望自身的独立。"}},{"pos":"PHRASE 短语","cn":"(通常因为谈论的话题令人尴尬而)转换话题","en":"When someone involved in a conversation changes the subject, they start talking about something else, often because the previous subject was embarrassing.","ex":{"en":"He tried to change the subject, but she wasn't to be put off.","cn":"他努力想换个话题，但她却兴趣正浓。"}},{"pos":"PREP-PHRASE 短语介词","cn":"取决于;视…而定","en":"If an event will take place subject to a condition, it will take place only if that thing happens.","ex":{"en":"They denied a report that Egypt had agreed to a summit, subject to certain conditions.","cn":"他们否认了宣称埃及已同意在特定条件下参加峰会的报道。"}}]},"examples":[{"en":"We need male subjects between the ages of 18 and 25 for the experiment.","cn":"我们需要 18 至 25 岁之间的男性来接受试验。"},{"en":"Classical landscapes were a popular subject with many 18th century painters.","cn":"古典风景画是 18 世纪许多画家所喜欢用的题材。"}]},"suffice":{"media":{"uk":"media/uk/suffice__gb_1.mp3","us":"media/us/suffice__us_1.mp3"},"oxford":{"phon":"səˈfaɪs","pos":"verb","senses":[{"en":"to be enough for somebody/something","cn":"足够；足以","ex":{"en":"Generally a brief note or a phone call will suffice.","cn":"通常写个便条或打个电话就足够了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"足够;充足","en":"If you say that something will suffice, you mean it will be enough to achieve a purpose or to fulfil a need.","ex":{"en":"A cover letter should never exceed one page; often a far shorter letter will suffice.","cn":"附信不应超过一页，通常来说，一封相对非常简短的信就足够了。"}},{"pos":"PHRASE 短语","cn":"(用于句首)无须多说，只需说…就够了","en":"Suffice it to say or suffice to say is used at the beginning of a statement to indicate that what you are saying is obvious, or that you will only give a short explanation.","ex":{"en":"Suffice it to say that afterwards we never met again","cn":"简单地说，此后我们再也没有见过面。"}}]},"examples":[{"en":"Generally a brief note or a phone call will suffice.","cn":"通常写个便条或打个电话就足够了。"},{"en":"One example will suffice to illustrate the point.","cn":"举一个例子就足以说明这一点。"}]},"suitcase":{"oxford":{"phon":"ˈsuːtkeɪs","pos":"noun","senses":[{"en":"a case with flat sides and a handle, used for carrying clothes, etc. when you are travelling","cn":"（旅行用的）手提箱","ex":{"en":"to pack/unpack a suitcase","cn":"把东西装进手提箱；取出手提箱里的东西"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(旅行用的)手提箱","en":"A suitcase is a box or bag with a handle and a hard frame in which you carry your clothes when you are travelling.","ex":{"en":"It did not take Andrew long to pack a suitcase.","cn":"安德鲁很快就整理好了手提箱。"}}]},"media":{"uk":"media/uk/suitcase__gb_1.mp3","us":"media/us/suitcase__us_1.mp3","img":["media/ldoce/img/suitcase.jpg"]},"examples":[{"en":"to pack/unpack a suitcase","cn":"把东西装进手提箱；取出手提箱里的东西"}]},"surround":{"oxford":{"phon":"səˈraʊnd","pos":"verb","senses":[{"en":"to be all around something/somebody","cn":"围绕；环绕","ex":{"en":"Tall trees surround the lake.","cn":"环湖都是大树。"}},{"en":"to move into position all around somebody/something, especially so as to prevent them from escaping; to move somebody/something into position in this way","cn":"包围；围住","ex":{"en":"Police surrounded the building.","cn":"警方包围了那栋房子。"}},{"en":"to be closely connected with something/somebody","cn":"与…紧密相关；围绕","ex":{"en":"publicity surrounding the divorce","cn":"媒体围绕这桩离婚事件的报道"}},{"en":"to choose to have particular people or things near you all the time","cn":"喜欢结交（某类人）；喜欢身边总有（某类东西）","ex":{"en":"I like to surround myself with beautiful things.","cn":"我喜欢身边老有漂亮的东西。"}},{"en":"a border or an area around the edge of something, especially one that is decorated","cn":"（物品的）框，饰边；周围","ex":{"en":"a fireplace with a tiled surround","cn":"周围镶有瓷砖的壁炉。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"围绕;环绕","en":"If a person or thing is surrounded by something, that thing is situated all around them.","ex":{"en":"The small churchyard was surrounded by a rusted wrought-iron fence","cn":"不大的教堂墓地周边围着一圈生锈的熟铁栅栏。"}},{"pos":"VERB 动词","cn":"包围;围住","en":"If you are surrounded by soldiers or police, they spread out so that they are in positions all the way around you.","ex":{"en":"When the car stopped in the town square it was surrounded by soldiers and militiamen","cn":"当汽车停在城镇广场时立刻被士兵和民兵包围了。"}},{"pos":"VERB 动词","cn":"与…密切相关;围绕","en":"The circumstances, feelings, or ideas which surround something are those that are closely associated with it.","ex":{"en":"The decision had been agreed in principle before today's meeting, but some controversy surrounded it","cn":"该决定在今天的会议之前就已达成原则上的共识，但围绕这一决定还存在一些争议。"}},{"pos":"VERB 动词","cn":"喜欢结交(某类人);确保身边总有(某类东西)","en":"If you surround yourself with certain people or things, you make sure that you have a lot of them near you all the time.","ex":{"en":"He had made it his business to surround himself with a hand-picked group of bright young officers","cn":"他总会亲手挑选一批聪明而年轻的军官常伴他左右。"}},{"pos":"N-COUNT 可数名词","cn":"(壁炉等的)边饰，围饰","en":"The surround of something such as a fireplace is the border, wall, or shelves around it.","ex":{"en":"...a small fireplace with a cast-iron surround.","cn":"有铸铁边饰的小壁炉"}},{"pos":"N-PLURAL 复数名词","cn":"周围的事物;环境","en":"Your surrounds are your surroundings .","ex":{"en":"The entire team enjoyed hot showers in the spacious surrounds of a new, modern village hall.","cn":"全队都在新建的现代化村会所的宽敞洗浴间享受了热水淋浴。"}}]},"media":{"uk":"media/uk/surround__gb_1.mp3","us":"media/us/surround__us_1.mp3"},"examples":[{"en":"They've surrounded the building with police.","cn":"他们跟警察一起包围了那栋房子。"},{"en":"I like to surround myself with beautiful things.","cn":"我喜欢身边老有漂亮的东西。"}]},"suffer":{"oxford":{"phon":"ˈsʌfə(r)","pos":"verb","senses":[{"en":"to be badly affected by a disease, pain, sad feelings, a lack of something, etc.","cn":"（因疾病、痛苦、悲伤、匮乏等）受苦，受难，受折磨","g":"[intransitive]","ex":{"en":"I hate to see animals suffering.","cn":"我不忍心看动物受苦。"}},{"en":"to experience something unpleasant, such as injury, defeat or loss","cn":"遭受；蒙受","g":"[transitive]","ex":{"en":"to suffer a stroke/heart attack","cn":"脑卒中／心脏病发作"}},{"en":"to become worse","cn":"变差；变糟","g":"[intransitive]","ex":{"en":"His school work is suffering because of family problems.","cn":"由于家庭问题，他的学业日渐退步。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"遭受，经受(疼痛);感到(痛苦)","en":"If you suffer pain, you feel it in your body or in your mind.","ex":{"en":"Within a few days she had become seriously ill, suffering great pain and discomfort","cn":"几天的时间，她就病得很严重了，疼痛难忍，周身不舒服。"}},{"pos":"VERB 动词","cn":"(因疾病或处于其他不利境地而)受苦，受难，受折磨","en":"If you suffer from an illness or from some other bad condition, you are badly affected by it.","ex":{"en":"He was eventually diagnosed as suffering from terminal cancer","cn":"他最终被诊断出患了晚期癌症。"}},{"pos":"VERB 动词","cn":"遭遇，遭受，蒙受(不好的事)","en":"If you suffer something bad, you are in a situation in which something painful, harmful, or very unpleasant happens to you.","ex":{"en":"The peace process has suffered a serious blow now","cn":"现在和平进程遭到重创。"}},{"pos":"VERB 动词","cn":"受挫;遭受打击","en":"If you suffer, you are badly affected by an event or situation.","ex":{"en":"There are few who have not suffered","cn":"谁都会经受挫折。"}},{"pos":"VERB 动词","cn":"(因不够关注或处于不利境况而)失利，失败，不成功","en":"If something suffers, it does not succeed because it has not been given enough attention or is in a bad situation.","ex":{"en":"I'm not surprised that your studies are suffering","cn":"你的功课变得越来越差，我并不感到奇怪。"}},{"pos":"PHRASE 短语","cn":"迁就笨人;容忍愚蠢者","en":"If you do not suffer fools gladly, you are not patient with people who you think are stupid.","ex":{"en":"She doesn't suffer fools gladly and, in her view, most people are fools.","cn":"她不愿与笨人为伍，而在她看来，大多数人都是笨人。"}}]},"media":{"uk":"media/uk/suffer__gb_1.mp3","us":"media/us/suffer__us_1.mp3"},"examples":[{"en":"The company suffered huge losses in the last financial year.","cn":"公司在上一财政年度出现巨额亏损。"},{"en":"His school work is suffering because of family problems.","cn":"由于家庭问题，他的学业日渐退步。"}]},"suddenly":{"media":{"uk":"media/uk/suddenly__gb_1.mp3","us":"media/us/suddenly__us_1.mp3"},"oxford":{"phon":"ˈsʌdənli","pos":"adverb","senses":[{"en":"quickly and unexpectedly","cn":"突然；忽然；猛地；骤然","ex":{"en":"I suddenly realized what I had to do.","cn":"我突然明白该怎么做了。"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"突然地;出乎意料地","en":"If something happens suddenly, it happens quickly and unexpectedly.","ex":{"en":"Suddenly, she looked ten years older","cn":"突然间她看起来老了 10 岁。"}}]},"examples":[{"en":"I suddenly realized what I had to do.","cn":"我突然明白该怎么做了。"},{"en":"It all happened so suddenly.","cn":"一切都来得那么突然。"}]},"surly":{"media":{"uk":"media/uk/surly__gb_1.mp3","us":"media/us/surly__us_1.mp3"},"oxford":{"phon":"ˈsɜːli","pos":"adjective","senses":[{"en":"unfriendly and rude","cn":"不友善的；态度粗暴的","ex":{"en":"a surly youth","cn":"脾气暴躁的年轻人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"暴躁的;粗暴无礼的;乖戾的","en":"Someone who is surly behaves in a rude bad-tempered way.","ex":{"en":"He became surly and rude towards me.","cn":"他变得对我粗暴无礼。"}}]},"examples":[{"en":"a surly youth","cn":"脾气暴躁的年轻人"},{"en":"a surly teenager","cn":"一个脾气暴躁的少年"}]},"suggest":{"media":{"uk":"media/uk/suggest__gb_1.mp3","us":"media/us/suggest__us_1.mp3"},"oxford":{"phon":"səˈdʒest","pos":"verb","senses":[{"en":"to put forward an idea or a plan for other people to think about","cn":"建议；提议","lab":"British English also","ex":{"en":"I'd like to suggest a different explanation for the company's decline.","cn":"关于公司的业绩下滑，我想从另外的角度说明一下。"}},{"en":"to tell somebody about a suitable person, thing, method, etc. for a particular job or purpose","cn":"推荐；举荐","ex":{"en":"Who would you suggest for the job?","cn":"要你说，谁适合做这个工作？"}},{"en":"to put an idea into somebody’s mind; to make somebody think that something is true","cn":"使想到；使认为；表明","ex":{"en":"All the evidence suggests (that) he stole the money.","cn":"所有证据都表明是他偷了钱。"}},{"en":"to state something indirectly","cn":"暗示；言下之意是说","ex":{"en":"Are you suggesting (that) I’m lazy?","cn":"你言下之意是说我懒？"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"提议;建议","en":"If you suggest something, you put forward a plan or idea for someone to think about.","ex":{"en":"He suggested a link between class size and test results of seven-year-olds","cn":"他认为 7 岁大的学生的测试分数和班级的规模有关系。"}},{"pos":"VERB 动词","cn":"推荐;举荐","en":"If you suggest the name of a person or place, you recommend them to someone.","ex":{"en":"Could you suggest someone to advise me how to do this?","cn":"这该怎么办？你能不能推荐一个人帮我出个主意？"}},{"pos":"VERB 动词","cn":"意思是;言下之意是","en":"If you suggest that something is the case, you say something which you believe is the case.","ex":{"en":"I'm not suggesting that is what is happening","cn":"我没有说那就是事实。"}},{"pos":"VERB 动词","cn":"暗示;表明;显示","en":"If one thing suggests another, it implies it or makes you think that it might be the case.","ex":{"en":"Earlier reports suggested that a meeting would take place on Sunday","cn":"早先的报道暗示周日可能会召开会议。"}},{"pos":"VERB 动词","cn":"使联想到;使想起","en":"If one thing suggests another, it brings it to your mind through an association of ideas.","ex":{"en":"This onomatopoeic word suggests to me the sound a mousetrap makes when it snaps shut.","cn":"这个拟声词让我想起捕鼠夹子突然合上时的声音。"}}]},"examples":[{"en":"May I suggest a white wine with this dish, Sir?","cn":"先生，吃这道菜，我给您推荐一种白葡萄酒，好吗？"},{"en":"She suggested Paris as a good place for the conference.","cn":"她推荐说，巴黎是举行这次会议的理想地点。"}]},"superior":{"media":{"uk":"media/uk/superior__gb_1.mp3","us":"media/us/superior__us_1.mp3"},"oxford":{"phon":"suːˈpɪəriə(r)","pos":"adjective","senses":[{"en":"better in quality than somebody/something else; greater than somebody/something else","cn":"（在品质上）更好的；占优势的；更胜一筹的","ex":{"en":"vastly superior","cn":"强得多"}},{"en":"higher in rank, importance or position","cn":"（在级别、重要性或职位上）更高的","g":"[only before noun]","ex":{"en":"my superior officer","cn":"我的上级军官"}},{"en":"showing by your behaviour that you think you are better than others","cn":"有优越感的；高傲的","lab":"disapproving","ex":{"en":"a superior manner","cn":"神气活现的态度"}},{"en":"of very good quality; better than other similar things","cn":"质量卓越的；出类拔萃的；超群的","ex":{"en":"superior apartments","cn":"高级公寓套房"}},{"en":"a person of higher rank, status or position","cn":"级别（或地位、职位）更高的人；上级；上司","ex":{"en":"your social superiors","cn":"社会地位比自己高的人"},"pos":"noun"},{"en":"used in titles for the head of a religious community","cn":"（用作宗教团体领导的头衔）","ex":{"en":"Mother Superior","cn":"修女会院长"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"比…好的;比…强的;优于…的","en":"If one thing or person is superior to another, the first is better than the second.","ex":{"en":"We have a relationship infinitely superior to those of many of our friends","cn":"我们的关系要比我们其他许多朋友的关系好得多。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"优良的;优秀的;优等的","en":"If you describe something as superior, you mean that it is good, and better than other things of the same kind.","ex":{"en":"A few years ago it was virtually impossible to find superior quality coffee in local shops","cn":"几年前在当地商店里几乎买不到优质咖啡。"}},{"pos":"ADJ 形容词","cn":"(在重要性上)更高级的，上级的","en":"A superior person or thing is more important than another person or thing in the same organization or system.","ex":{"en":"...negotiations between the mutineers and their superior officers","cn":"哗变士兵和他们的上司长官间的谈判"}},{"pos":"N-COUNT 可数名词","cn":"上级;上司;级别更高的人","en":"Your superior in an organization that you work for is a person who has a higher rank than you.","ex":{"en":"Other army units are completely surrounded and cut-off from communication with their superiors","cn":"其他陆军部队被重重包围，和上级的联系也被切断了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有优越感的;高傲的;傲慢的","en":"If you describe someone as superior, you disapprove of them because they behave as if they are better, more important, or more intelligent than other people.","ex":{"en":"Finch gave a superior smile","cn":"芬奇高傲地笑了笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人数)占优的，居多的","en":"If one group of people has superior numbers to another group, the first has more people than the second, and therefore has an advantage over it.","ex":{"en":"The demonstrators fled when they saw the authorities' superior numbers","cn":"看到当局派出人员人数占优，示威者就四散逃跑了。"}},{"pos":"N-COUNT 可数名词","cn":"(某一活动的)能人，高手","en":"If you describe someone as your superior in a particular activity, you mean that they are better than you at that activity.","ex":{"en":"Anthony sometimes felt that his mistress was his superior in willpower","cn":"有时安东尼感觉他的情妇比他更有意志力。"}}]},"examples":[{"en":"This model is technically superior to its competitors.","cn":"这一款式在技术上超过了与之竞争的产品。"},{"en":"The enemy won because of their superior numbers (= there were more of them).","cn":"敌人由于在人数上占优而取胜。"}]},"surrounding":{"media":{"uk":"media/uk/surrounding__gb_1.mp3","us":"media/us/surrounding__us_1.mp3"},"oxford":{"phon":"səˈraʊndɪŋ","pos":"adjective","senses":[{"en":"that is near or around something","cn":"周围的；附近的","ex":{"en":"Oxford and the surrounding area","cn":"牛津及其周围地区"}}]},"examples":[{"en":"Oxford and the surrounding area","cn":"牛津及其周围地区"},{"en":"Troops sealed off the surrounding area .","cn":"军队封锁了周围地区。"}],"base":"surround"},"sunset":{"media":{"uk":"media/uk/sunset__gb_1.mp3","us":"media/us/sunset__us_1.mp3"},"oxford":{"phon":"ˈsʌnset","pos":"noun","senses":[{"en":"the time when the sun goes down and night begins","cn":"日落；傍晚","g":"[uncountable]","ex":{"en":"Every evening at sunset the flag was lowered.","cn":"每天傍晚日落时都要降旗。"}},{"en":"the colours in the part of the sky where the sun slowly goes down in the evening","cn":"晚霞","g":"[countable]","ex":{"en":"a spectacular sunset","cn":"绚烂的晚霞"}},{"en":"a fixed period of time after which a law or the effect of a law will end","cn":"（法律的）自动废止期，效力消减期","g":"[countable]","ex":{"en":"There is a five-year sunset on the new tax.","cn":"新税种的有效施行期限为五年。"}},{"en":"used to describe a colour that is like one of the colours in a sunset","cn":"霞红色的；浅橘红色的","ex":{"en":"sunset yellow","cn":"日落黄"},"pos":"adjective"},{"en":"used to describe something that is near its end, or that happens at the end of something","cn":"衰落的；最后期的","ex":{"en":"This is his sunset tour after fifty years as a singer.","cn":"这是他五十年歌手生涯结束前最后一次巡回演出。"},"pos":"adjective"},{"en":"designed to end or to end something after a fixed period of time","cn":"定期废止的","ex":{"en":"a two-year sunset clause in the new law","cn":"新法律中的一条实施期限为两年的“落日条款”"},"pos":"adjective"},{"en":"to end or to end something after a fixed period of time","cn":"（使）定期届满废止","ex":{"en":"The tax relief will sunset after a year.","cn":"税款减免将在一年后废止。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"日落(时分);傍晚;黄昏","en":"Sunset is the time in the evening when the sun disappears out of sight from the sky.","ex":{"en":"The dance ends at sunset.","cn":"舞会在日落时分结束。"}},{"pos":"N-COUNT 可数名词","cn":"晚霞;落日余晖","en":"A sunset is the colours and light that you see in the western part of the sky when the sun disappears in the evening.","ex":{"en":"There was a red sunset over Paris.","cn":"巴黎的天空映着红色的晚霞。"}}]},"examples":[{"en":"This is his sunset tour after fifty years as a singer.","cn":"这是他五十年歌手生涯结束前最后一次巡回演出。"},{"en":"a two-year sunset clause in the new law","cn":"新法律中的一条实施期限为两年的“日落条款”"}]},"suspend":{"oxford":{"phon":"səˈspend","pos":"verb","senses":[{"en":"to hang something from something else","cn":"悬；挂；吊","g":"[often passive]","lab":"formal","ex":{"en":"A lamp was suspended from the ceiling.","cn":"一盏吊灯悬在天花板上。"}},{"en":"to officially stop something for a time; to prevent something from being active, used, etc. for a time","cn":"暂停；中止；使暂停发挥作用（或使用等）","ex":{"en":"Production has been suspended while safety checks are carried out.","cn":"在进行安全检查期间生产暂停。"}},{"en":"to officially delay something; to arrange for something to happen later than planned","cn":"延缓；暂缓；推迟","ex":{"en":"The introduction of the new system has been suspended until next year.","cn":"新制度推迟到明年再行实施。"}},{"en":"to officially prevent somebody from doing their job, going to school, etc. for a time, as a punishment or while a complaint against them is investigated","cn":"（作为惩罚或投诉调查期间）使暂时停职（或停学等）","g":"[usually passive]","ex":{"en":"The police officer was suspended while the complaint was investigated.","cn":"投诉调查期间，这名警员被暂停职务。"}},{"en":"to float in liquid or air without moving","cn":"悬浮","lab":"specialist","ex":{"en":"Small droplets are held suspended in the atmosphere.","cn":"小水滴悬浮在大气中。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"暂缓;推迟;暂停","en":"If you suspend something, you delay it or stop it from happening for a while or until a decision is made about it.","ex":{"en":"The union suspended strike action this week","cn":"这周工会暂停了罢工。"}},{"pos":"VERB 动词","cn":"使暂时停职","en":"If someone is suspended, they are prevented from holding a particular job or position for a fixed length of time or until a decision is made about them.","ex":{"en":"Julie was suspended from her job shortly after the incident","cn":"出事后不久，朱莉就被停职了。"}},{"pos":"VERB 动词","cn":"悬挂;吊","en":"If something is suspended from a high place, it is hanging from that place.","ex":{"en":"...a mobile of birds or nursery rhyme characters which could be suspended over the cot.","cn":"能悬挂在摇篮上方、由小鸟或童谣故事人物组成的风动玩具"}}]},"media":{"uk":"media/uk/suspend__gb_1.mp3","us":"media/us/suspend__us_1.mp3"},"examples":[{"en":"In the theatre we willingly suspend disbelief (= temporarily believe that the characters, etc. are real).","cn":"在剧院看戏时，我们自愿对一切暂不置疑。"},{"en":"The police officer was suspended while the complaint was investigated.","cn":"投诉调查期间，这名警员被暂停职务。"}]},"support":{"media":{"uk":"media/uk/support__gb_1.mp3","us":"media/us/support__us_1.mp3"},"oxford":{"phon":"səˈpɔːt","pos":"verb","senses":[{"en":"to help or encourage somebody/something by saying or showing that you agree with them/it","cn":"支持；拥护；鼓励","sc":"encourage/give help","ex":{"en":"to support an idea/a view","cn":"支持某个想法／观点"}},{"en":"to give or be ready to give help to somebody if they need it","cn":"帮助；援助","sc":"encourage/give help","ex":{"en":"an organization that supports people with AIDS","cn":"一个向艾滋病患者提供援助的组织"}},{"en":"to like a particular sports team, watch their games, etc.","cn":"支持；喜爱","lab":"British English","sc":"sports team","ex":{"en":"Which team do you support?","cn":"你喜欢哪个队？"}},{"en":"to help or encourage something to be successful by giving it money","cn":"资助；赞助","sc":"provide money, etc.","ex":{"en":"The project was supported by grants from various charities.","cn":"这个项目得到了多个慈善组织的拨款资助。"}},{"en":"to provide everything necessary, especially money, so that somebody/something can live or exist","cn":"养活；赡养；扶养；维持","sc":"provide money, etc.","ex":{"en":"He struggles to support his family.","cn":"他勉力养家。"}},{"en":"to help to show that something is true","cn":"证实；提供依据","sc":"help prove something","ex":{"en":"Current data support this hypothesis.","cn":"当前的数据支持这一假设。"}},{"en":"to hold somebody/something in position; to prevent somebody/something from falling","cn":"支撑；支承；支护","sc":"hold in position","ex":{"en":"a platform supported by concrete pillars","cn":"混凝土支柱支撑的平台"}},{"en":"to perform in a pop or rock concert before the main performer","cn":"（在流行或摇滚音乐会上）当助演，担任演出嘉宾","sc":"pop/rock concert","ex":{"en":"They were supported by a local Liverpool band.","cn":"利物浦当地的一支乐队为他们作助兴演出。"}},{"en":"to allow a particular program, language or device to be used with it","cn":"支持；支援","sc":"computer","ex":{"en":"This digital audio player supports multiple formats.","cn":"这台数字音频播放器支持多种格式。"}},{"en":"approval that you give to somebody/something because you want them to be successful","cn":"支持；拥护；鼓励","g":"[uncountable]","sc":"approval","ex":{"en":"There is strong public support for the policy.","cn":"公众大力支持这一政策。"},"pos":"noun"},{"en":"money or goods that you give to somebody/something in order to help them","cn":"资助；赞助","g":"[uncountable]","sc":"money","ex":{"en":"They received no financial support from the government.","cn":"他们没有得到政府的任何资助。"},"pos":"noun"},{"en":"sympathy and help that you give to somebody who is in a difficult or unhappy situation","cn":"帮助；救助；援助","g":"[uncountable]","sc":"help","ex":{"en":"Her family and friends have given her lots of support.","cn":"家人和朋友给了她许多帮助。"},"pos":"noun"},{"en":"evidence that helps to show that something is true or correct","cn":"证据；依据","g":"[uncountable]","sc":"proof","ex":{"en":"This suggestion lacks convincing experimental support.","cn":"这一建议缺乏令人信服的实验支持。"},"pos":"noun"},{"en":"a thing that holds something and prevents it from falling","cn":"支撑物；支承；支柱；支座","g":"[countable]","lab":"figurative","sc":"holding in position","ex":{"en":"The supports under the bridge were starting to bend.","cn":"桥下的支柱开始弯曲。"},"pos":"noun"},{"en":"the act of holding something in position or preventing it from falling","cn":"支撑；支承；支护","g":"[uncountable]","lab":"figurative","sc":"holding in position","ex":{"en":"She held on to his arm for support.","cn":"她抓着他的胳膊，好站稳。"},"pos":"noun"},{"en":"something you wear to hold an injured or weak part of your body in position","cn":"（身体部位的）支持器，托","g":"[countable]","sc":"holding in position","ex":{"en":"a knee/back support","cn":"护膝；护背"},"pos":"noun"},{"en":"a band or singer who performs in a pop or rock concert before the main performer","cn":"助演嘉宾","g":"[uncountable]","sc":"pop/rock concert","ex":{"en":"The support (act) has yet to be confirmed.","cn":"助演尚未确定。"},"pos":"noun"},{"en":"technical help that a company gives to customers using their computers or other products","cn":"（公司向客户提供的）技术支持","g":"[uncountable]","sc":"technical help","ex":{"en":"There is a lack of decent home user support.","cn":"没有像样的家庭用户技术支持。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"支持;赞同;拥护","en":"If you support someone or their ideas or aims, you agree with them, and perhaps help them because you want them to succeed.","ex":{"en":"The vice president insisted that he supported the hard-working people of New York","cn":"副总统坚称他支持辛勤工作的纽约人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"帮助;支持;支援;援助","en":"If you give support to someone during a difficult or unhappy time, you are kind to them and help them.","ex":{"en":"It was hard to come to terms with her death after all the support she gave to me and the family","cn":"她曾经给予我和家人莫大的帮助，她的死讯令人难以接受。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(通常指政府的)赞助，资助","en":"Financial support is money provided to enable an organization to continue. This money is usually provided by the government.","ex":{"en":"...the government's proposal to cut agricultural support by only about 15%.","cn":"仅削减约 15%的农业拨款的政府提案"}},{"pos":"VERB 动词","cn":"资助;供养;赡养","en":"If you support someone, you provide them with money or the things that they need.","ex":{"en":"I have children to support, money to be earned, and a home to be maintained","cn":"我要抚养孩子，挣钱养家。"}},{"pos":"VERB 动词","cn":"证实;为…提供依据","en":"If a fact supports a statement or a theory, it helps to show that it is true or correct.","ex":{"en":"The Freudian theory about daughters falling in love with their father has little evidence to support it.","cn":"弗洛伊德关于女儿恋父的理论缺乏依据。"}},{"pos":"VERB 动词","cn":"支承;支撑;支护","en":"If something supports an object, it is underneath the object and holding it up.","ex":{"en":"...the thick wooden posts that supported the ceiling","cn":"支撑天花板的粗木柱子"}},{"pos":"N-COUNT 可数名词","cn":"支撑物;支柱","en":"A support is a bar or other object that supports something."},{"pos":"VERB 动词","cn":"支撑(身体);倚靠","en":"If you support yourself, you prevent yourself from falling by holding onto something or by leaning on something.","ex":{"en":"He supported himself by means of a nearby post.","cn":"他靠在旁边的柱子上。"}},{"pos":"VERB 动词","cn":"支持，喜爱(运动队)","en":"If you support a sports team, you always want them to win and perhaps go regularly to their games.","ex":{"en":"Tim, 17, supports Manchester United.","cn":"17 岁的蒂姆支持曼联队。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(音乐会、演出的)助演演员，助演乐队","en":"At a concert or show, the support or the support act is a less well-known person or band who performs before the main person or band."}]},"examples":[{"en":"The government supported the unions in their demand for a minimum wage.","cn":"政府支持这些工会组织提出的确定最低工资的要求。"},{"en":"The statistics offer further support for our theory.","cn":"这些统计数字为我们的理论提供了进一步的依据。"}]},"sunlight":{"media":{"uk":"media/uk/sunlight__gb_1.mp3","us":"media/us/sunlight__us_1.mp3"},"oxford":{"phon":"ˈsʌnlaɪt","pos":"noun","senses":[{"en":"the light from the sun","cn":"阳光；日光","ex":{"en":"a ray/pool of sunlight","cn":"一束／一片阳光"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"日光;阳光","en":"Sunlight is the light that comes from the sun during the day.","ex":{"en":"I saw her sitting at a window table, bathed in sunlight.","cn":"我看见她坐在靠窗的桌旁，沐浴在阳光中。"}}]},"examples":[{"en":"The morning sunlight flooded into the room.","cn":"早晨的阳光泻入房间。"},{"en":"shafts of bright sunlight","cn":"一道道明亮的阳光"}]},"surprising":{"media":{"uk":"media/uk/surprising__gb_1.mp3","us":"media/us/surprising__us_1.mp3"},"oxford":{"phon":"səˈpraɪzɪŋ","pos":"adjective","senses":[{"en":"causing surprise","cn":"令人吃惊的；使人惊奇的；出人意料的；奇怪的","ex":{"en":"It’s not surprising (that) they lost.","cn":"他们吃了败仗，不奇怪。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人吃惊的;令人惊奇的","en":"Something that is surprising is unexpected or unusual and makes you feel surprised.","ex":{"en":"It is not surprising that children learn to read at different rates","cn":"小孩子识字的速度不同,这不足为奇。"}}]},"examples":[{"en":"Not surprisingly on such a hot day, the beach was crowded.","cn":"在这样的大热天，海滩上人头攒动是不足为奇的。"},{"en":"It's surprising what people will do for money.","cn":"人为了钱什么干不出来，想想真令人愕然。"}],"base":"surprise"},"surface":{"media":{"uk":"media/uk/surface__gb_1.mp3","us":"media/us/surface__us_1.mp3"},"oxford":{"phon":"ˈsɜːfɪs","pos":"noun","senses":[{"en":"the outside or top layer of something","cn":"表面；表层；面","g":"[countable]","ex":{"en":"We need a flat, smooth surface to play the game on.","cn":"我们得有个平滑的表面才能玩这个游戏。"}},{"en":"the top layer of an area of water or land","cn":"水面；地面；液面","g":"[countable, usually singular]","ex":{"en":"the earth's surface","cn":"地球表面"}},{"en":"the flat upper part of a piece of furniture, that is used for working on","cn":"（家具的）顶面，操作台","g":"[countable]","ex":{"en":"She's cleaned all the kitchen surfaces.","cn":"她把厨房的所有台面全都收拾干净了。"}},{"en":"the outer appearance of a person, thing or situation; the qualities that you see or notice, that are not hidden","cn":"表面；外表；外观","g":"[singular]","ex":{"en":"Rage bubbled just below the surface of his mind.","cn":"怒火在他心中燃烧，随时可能迸发。"}},{"en":"to come up to the surface of water","cn":"升到水面；浮出水面","g":"[intransitive]","ex":{"en":"The ducks dived and surfaced again several metres away.","cn":"鸭子潜入水中，然后在几米外又钻出水面。"},"pos":"verb"},{"en":"to suddenly appear or become obvious after having been hidden for a while","cn":"（隐藏或被掩盖一段时间后）露面，重新出现，显露，被披露","g":"[intransitive]","ex":{"en":"Doubts began to surface.","cn":"质疑声开始出现。"},"pos":"verb"},{"en":"to wake up or get up after being asleep","cn":"醒来；起床","g":"[intransitive]","lab":"informal","ex":{"en":"He finally surfaced around noon.","cn":"他终于在中午时分醒来。"},"pos":"verb"},{"en":"to put a surface on a road, path, etc.","cn":"铺设（路面等）","g":"[transitive]","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"表面;表层;上面","en":"The surface of something is the flat top part of it or the outside of it.","ex":{"en":"Ozone forms a protective layer between 12 and 30 miles above the Earth's surface.","cn":"臭氧在地球表面上方 12 到 30 英里处形成一个保护层。"}},{"pos":"N-COUNT 可数名词","cn":"桌面;台面;操作台","en":"A work surface is a flat area, for example the top of a table, desk, or kitchen cupboard, on which you can work.","ex":{"en":"It can simply be left on the work surface","cn":"把它放在操作台上就行了。"}},{"pos":"N-SING 单数名词","cn":"表面;外表;表象","en":"When you refer to the surface of a situation, you are talking about what can be seen easily rather than what is hidden or not immediately obvious.","ex":{"en":"Back in Britain, things appear, on the surface, simpler","cn":"而在英国国内，事情表面上看来要简单一些。"}},{"pos":"ADJ 形容词","cn":"(军队)陆上的，水上的","en":"Surface is used to describe the parts of the armed forces which travel by ship or by land rather than underwater or in the air.","ex":{"en":"In contrast with its surface fleet, Britain's submarine force was relatively small.","cn":"同其水面舰队相比，英国的潜艇部队规模相对较小。"}},{"pos":"VERB 动词","cn":"升到水面;浮出水面","en":"If someone or something under water surfaces, they come up to the surface of the water.","ex":{"en":"He surfaced, gasping for air.","cn":"他浮出水面，大口吸气。"}},{"pos":"VERB 动词","cn":"显露;暴露;流露;公开","en":"When something such as a piece of news, a feeling, or a problem surfaces, it becomes known or becomes obvious.","ex":{"en":"The paper says the evidence, when it surfaces, is certain to cause uproar","cn":"该报称该证据一经披露，一定会引起骚动。"}},{"pos":"VERB 动词","cn":"(一段时间未见后)现身，露面;醒来","en":"When someone surfaces, they appear after not being seen for some time, for example because they have been asleep.","ex":{"en":"There's no chance that he'll surface because he's bound to have heard by now","cn":"他不会再出现了，因为他现在肯定听说了。"}}]},"examples":[{"en":"The ducks dived and surfaced again several metres away.","cn":"鸭子潜入水中，然后在几米开外钻出水面。"},{"en":"She's cleaned all the kitchen surfaces.","cn":"她把厨房的所有台面全都收拾干净了。"}]},"subscribing":{"lemma":"subscribe"},"suspecting":{"lemma":"suspect"},"surfaces":{"lemma":"surface"},"suspicions":{"lemma":"suspicion"},"sultans":{"lemma":"sultan"},"sums":{"lemma":"sum"},"surged":{"lemma":"surge"},"sundays":{"lemma":"sunday"},"suggests":{"lemma":"suggest"},"sued":{"lemma":"sue"},"summits":{"lemma":"summit"},"submitted":{"lemma":"submit"},"suppressing":{"lemma":"suppress"},"successes":{"lemma":"success"},"supplanted":{"lemma":"supplant"},"subjects":{"lemma":"subject"},"surveys":{"lemma":"survey"},"subsidies":{"lemma":"subsidy"},"supported":{"lemma":"support"},"suggested":{"lemma":"suggest"},"subscribers":{"lemma":"subscriber"},"suits":{"lemma":"suit"},"surveying":{"lemma":"survey"},"suckers":{"lemma":"sucker"},"surfers":{"oxford":{"phon":"ˈsɜːfə(r)","pos":"noun","senses":[{"en":"a person who goes surfing","cn":"进行冲浪运动的人"},{"en":"( informal ) a person who spends a lot of time using the Internet （","cn":"互联网上）冲浪者，漫游者；网迷"}]}},"succeeds":{"lemma":"succeed"},"superstitions":{"lemma":"superstition"},"surmised":{"lemma":"surmise"},"surveyed":{"lemma":"survey"},"summarized":{"lemma":"summarize"},"supplies":{"lemma":"supply"},"supports":{"lemma":"support"},"suburbs":{"lemma":"suburb"},"succeeded":{"lemma":"succeed"},"summers":{"lemma":"summer"},"subsidized":{"lemma":"subsidize","media":{"uk":"media/ldoce/hwd/bre/3/subsidize0205.mp3","us":"media/ldoce/hwd/ame/b/subsidize.mp3"}},"summarizes":{"lemma":"summarize"},"sultan":{"collins":{"senses":[{"pos":"N-TITLE; N-COUNT 头衔名词；可数名词","cn":"苏丹(某些伊斯兰国家统治者的称号)","en":"A sultan is a ruler in some Muslim countries.","ex":{"en":"...during the reign of Sultan Abdul Hamid.","cn":"在苏丹阿卜杜勒·哈米德统治期间"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ruler in some Muslim countries","cn":"苏丹〔某些伊斯兰国家统治者的称号〕"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun sultan when you talk about the king of a Muslim country. It's most commonly used to refer to the sultans of Turkey's Ottoman Empire."}]},"media":{"uk":"media/ldoce/hwd/bre/c/sultan0205.mp3","us":"media/ldoce/hwd/ame/1/sultan.mp3"},"examples":[{"en":"the Sultan of Brunei","cn":"文莱苏丹"}],"oxford":{"phon":"ˈsʌltən","pos":"noun","senses":[{"en":"the title given to Muslim rulers in some countries","cn":"苏丹（某些国家穆斯林统治者的称号）","ex":{"en":"the Sultan of Brunei","cn":"文莱苏丹"}}]}},"sullen":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"面有愠色的;闷闷不乐的;郁郁寡欢的","en":"Someone who is sullen is bad-tempered and does not speak much.","ex":{"en":"The offenders lapsed into a sullen silence","cn":"那些冒犯者都闷不作声了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is sullen behaves in a bad-tempered, unfriendly way and does not smile or talk much to people","cn":""},{"en":"someone who is sulky has an angry, unhappy look on their face and does not talk much, especially because they think they have been treated unfairly","cn":""},{"en":"if someone sulks , they are deliberately silent and bad-tempered for a period of time, because something has annoyed them, or because they think that they have been treated unfairly","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A bad-tempered or gloomy person is sullen . Sullen people are down in the dumps."}]},"media":{"uk":"media/ldoce/hwd/bre/9/sullen0205.mp3","us":"media/ldoce/hwd/ame/2/sullen.mp3"},"examples":[{"en":"She gave him a sullen glare.","cn":"她满脸不高兴地瞪了他一眼。"},{"en":"Bob looked pale and sullen.","cn":"鲍勃脸色苍白，闷闷不乐。"}],"oxford":{"phon":"ˈsʌlən","pos":"adjective","senses":[{"en":"in a bad mood and not speaking, either on a particular occasion or because it is part of your character","cn":"面有愠色的；闷闷不乐的；郁郁寡欢的","ex":{"en":"Bob looked pale and sullen.","cn":"鲍勃脸色苍白，闷闷不乐。"}},{"en":"dark and unpleasant","cn":"阴沉的","lab":"literary","ex":{"en":"a sullen grey sky","cn":"阴沉的灰色天空"}}]}},"supercomputer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超级计算机","en":"A supercomputer is a powerful computer that can process large amounts of data very quickly."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a computer that is more powerful than almost all other computers","cn":"超级计算机"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41supercomputer.mp3","us":"media/ldoce/hwd/ame/5/laadsupercomputer.mp3"},"oxford":{"phon":"ˈsuːpəkəmpjuːtə(r)","pos":"noun","senses":[{"en":"a powerful computer with a large amount of memory and a very fast central processing unit","cn":"巨型计算机；超级计算机"}]}},"sunburned":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a red and painful skin as a result of spending too much time in the sun","cn":"晒伤的﹐〔日晒过量而引起〕皮肤灼痛的"},{"en":"having skin that is attractively brown as a result of spending time in the sun 〔","cn":"皮肤〕晒得黝黑好看的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sunburned.mp3","us":"media/ldoce/hwd/ame/7/ld41sunburned.mp3"},"examples":[{"en":"She looked fit and sunburned.","cn":"她看上去挺健康，晒得一身古铜色。"},{"en":"Her shoulders were badly sunburned.","cn":"她的肩膀严重晒伤了。"}],"oxford":{"phon":"ˈsʌnbɜːnd","pos":"adjective","senses":[{"en":"suffering from sunburn","cn":"晒伤的","ex":{"en":"Her shoulders were badly sunburned.","cn":"她的肩膀严重晒伤了。"}},{"en":"having an attractive brown colour from being in the sun","cn":"晒得黝黑而好看的","lab":"British English","ex":{"en":"She looked fit and sunburned.","cn":"她看上去挺健康，晒得一身古铜色。"}}]}},"sulfurous":{"lemma":"sulphurous","media":{"uk":"media/ldoce/hwd/bre/9/ld41sulfurous.mp3","us":"media/ldoce/hwd/ame/9/ld41sulfurous.mp3"}},"surrey":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light carriage with two seats, which was pulled by a horse and was used in the past 〔","cn":"旧时的〕双座轻便马车"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41surrey.mp3","us":"media/ldoce/hwd/ame/0/surrey1.mp3"},"oxford":{"phon":"ˈsʌri","pos":"","senses":[{"en":"a county in south-east England, south-west of London. It consists of some agricultural land and many small towns in the stockbroker belt for people who work in London. The administrative centre is Kingston upon Thames.","cn":"萨里郡（英格兰东南部郡；郡首府为泰晤士河畔金斯顿）"}]}},"subdued":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"闷闷不乐的;抑郁的;默不作声的","en":"Someone who is subdued is very quiet, often because they are sad or worried about something.","ex":{"en":"He faced the press, initially, in a somewhat subdued mood","cn":"他最初面对媒体时情绪有点忧郁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)压低的;小声的","en":"Subdued sounds are not very loud.","ex":{"en":"The conversation around them was resumed, but in subdued tones.","cn":"他们周围的人又开始交谈了，但这次是窃窃私语。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(灯光、颜色)不强烈的，柔和的","en":"Subdued lights or colours are not very bright.","ex":{"en":"The lighting was subdued.","cn":"灯光柔和。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"subdued lighting, colours etc are less bright than usual 〔","cn":"照明﹑颜色等〕柔和的﹐不强烈的"},{"en":"a person that is subdued is unusually quiet and possibly unhappy","cn":"抑郁的﹔沉默寡言的﹔闷闷不乐的"},{"en":"an activity that is subdued does not have as much excitement as you would expect 〔","cn":"活动〕冷清的﹐沉闷的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective subdued refers to something, like a sound, that has a lowered intensity. Your loud conversation with a friend in the back of the classroom is likely to become subdued when the teacher passes out the exams."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound","ADV. very | almost | a bit, fairly, rather, somewhat | suitably She was dressed in grey and looked suitably subdued. | strangely, unusually "]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdesubdued.mp3","us":"media/ldoce/hwd/ame/f/subdued.mp3"},"examples":[{"en":"He seemed a bit subdued to me.","cn":"我觉得他当时有点闷闷不乐。"},{"en":"The reception was a subdued affair.","cn":"招待会开得冷冷清清的。"}],"oxford":{"phon":"səbˈdjuːd","pos":"adjective","senses":[{"en":"unusually quiet, and possibly unhappy","cn":"闷闷不乐的；抑郁的；默不作声的","ex":{"en":"He seemed a bit subdued to me.","cn":"我觉得他当时有点闷闷不乐。"}},{"en":"not very bright","cn":"柔和的","ex":{"en":"subdued lighting","cn":"柔和的灯光"}},{"en":"not very loud","cn":"压低的；小声的","ex":{"en":"a subdued conversation","cn":"小声的谈话"}},{"en":"not very busy; with not much activity","cn":"不活跃的；低迷的；萧条的","ex":{"en":"a period of subdued trading","cn":"贸易萧条时期"}}]},"base":"subdue"},"subterfuge":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"诡计;手段;伎俩;花招","en":"Subterfuge is a trick or a dishonest way of getting what you want.","ex":{"en":"Most people can see right through that type of subterfuge","cn":"大多数人能一眼看透这种伎俩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a secret trick or slightly dishonest way of doing something, or the use of this","cn":"花招﹐诡计﹐手段"}]},"vocab":{"pos":"n","senses":[{"en":"If you want to surprise your mom with a sweatshirt, but don't know her size, it might take an act of subterfuge , like going through her closet, to find it out. Subterfuge is the use of tricky actions to hide, or get something."}]},"media":{"uk":"media/ldoce/hwd/bre/a/subterfuge0205.mp3","us":"media/ldoce/hwd/ame/0/subterfuge.mp3"},"examples":[{"en":"Sereni was lured to Moscow by subterfuge.","cn":"谢雷妮被人骗到了莫斯科。"}],"oxford":{"phon":"ˈsʌbtəfjuːdʒ","pos":"noun","senses":[{"en":"a secret, usually dishonest, way of behaving","cn":"（通常指欺骗性）秘密手段；诡计","ex":{"en":"Journalists often use subterfuge to obtain material for stories.","cn":"记者经常使用诡计来获取报道材料。"}}]}},"surmount":{"collins":{"senses":[{"pos":"VERB 动词","cn":"克服;解决","en":"If you surmount a problem or difficulty, you deal successfully with it.","ex":{"en":"I realized I had to surmount the language barrier.","cn":"我意识到我不得不克服语言障碍。"}},{"pos":"VERB 动词","cn":"处于…上面;置于…顶端","en":"If something is surmounted by a particular thing, that thing is on top of it.","ex":{"en":"The island is surmounted by a huge black castle.","cn":"岛的最高处耸立着一座巨大的黑色城堡。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to succeed in dealing with a problem or difficulty","cn":"克服〔问题或困难〕"},{"en":"to be above or on top of something","cn":"耸立于…之上﹔在…顶上"}]},"vocab":{"pos":"v","senses":[{"en":"If you surmount a challenge or difficult situation, you're not just getting over it. You're outdoing yourself, exceeding expectations, and overcoming the task at hand."}]},"media":{"uk":"media/ldoce/hwd/bre/9/surmount0205.mp3","us":"media/ldoce/hwd/ame/f/surmount.mp3"},"examples":[{"en":"a high column surmounted by a statue","cn":"顶端立着一尊雕像的高大的柱子"},{"en":"She was well aware of the difficulties that had to be surmounted.","cn":"她很清楚必须克服哪些困难。"}],"oxford":{"phon":"səˈmaʊnt","pos":"verb","senses":[{"en":"to deal successfully with a difficulty","cn":"克服；解决","ex":{"en":"She was well aware of the difficulties that had to be surmounted.","cn":"她很清楚必须克服哪些困难。"}},{"en":"to be placed on top of something","cn":"处于（某物）上面；置于（某物）顶端","g":"[usually passive]","ex":{"en":"a high column surmounted by a statue","cn":"顶端立着一尊雕像的高大的柱子"}}]}},"supermodel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超级名模;超模","en":"A supermodel is a very famous fashion model."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very famous fashion model","cn":"超级名模﹐超模"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdesupermodel.mp3","us":"media/ldoce/hwd/ame/7/laadsupermodel.mp3"},"oxford":{"phon":"ˈsuːpəmɒdl","pos":"noun","senses":[{"en":"a very famous and highly paid fashion model","cn":"超级名模"}]}},"superfluity":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"多余;过剩;冗余","en":"If there is a superfluity of something, there is more of it than is needed.","ex":{"en":"The city has a superfluity of five-star hotels.","cn":"这个城市的五星级宾馆太多了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a larger amount of something than is necessary","cn":"过多的某物"}]},"vocab":{"pos":"n","senses":[{"en":"A superfluity is an excess or abundance. When you encounter superfluity , there's too much of something."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41superfluity.mp3","us":"media/ldoce/hwd/ame/9/ld41superfluity.mp3"},"oxford":{"phon":"ˌsuːpəˈfluːəti","pos":"noun","senses":[{"en":"a larger number or amount than you need or want","cn":"多余，过量，过多","ex":{"en":"There always seemed to be a superfluity of men at the dances!","cn":"舞会上似乎总是有多余的男人！"}}]}},"subtotal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"部分合计;小计","en":"A subtotal is a figure that is the result of adding some numbers together but is not the final total."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the number or amount that there is, when everything has been counted or added together","cn":""},{"en":"the total number or amount is the number that there is when everything has been counted and added together","cn":""},{"en":"use this to say or ask what a total amount is, including everything that could be included","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41subtotal.mp3","us":"media/ldoce/hwd/ame/b/subtotal.mp3"},"oxford":{"phon":"ˈsʌbtəʊtl","pos":"noun","senses":[{"en":"the total of a set of numbers which is then added to other totals to give a final number","cn":"部分和；小计"}]}},"supple":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(物体、材料)易弯曲的，柔软的，柔韧的","en":"A supple object or material bends or changes shape easily without cracking or breaking.","ex":{"en":"The leather is supple and sturdy enough to last for years","cn":"该皮革柔软而结实，足以用上数年。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)灵活的，柔韧性好的","en":"A supple person can move and bend their body very easily.","ex":{"en":"Paul was incredibly supple and strong","cn":"保罗身体极其灵活，而且非常结实。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(味道)醇滑的;(声音)悦耳的","en":"If you describe something such as a flavour or a sound as supple, you like it because it is smooth and rich.","ex":{"en":"The wine has a medium-bodied, supple flavour.","cn":"该葡萄酒味道不浓不淡，口感醇滑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is supple bends and moves easily and gracefully 〔","cn":"身体〕柔软的﹐灵活的"},{"en":"leather, skin, wood etc that is supple is soft and bends easily 〔","cn":"皮革﹑皮肤﹑木料等〕柔软易弯的﹔柔韧的"}]},"vocab":{"pos":"adj v","senses":[{"en":"Something or someone that is supple bends and moves easily, like a contortionist at a circus sideshow. If you can wrap your legs around your neck, you most likely have a supple body."}]},"collocations":{"phrases":["VERBS be, feel, look leaving your skin feeling soft and supple | become, get He was gradually getting more supple. | keep, remain, stay exer","ADV. extremely, very"]},"media":{"uk":"media/ldoce/hwd/bre/9/supple0205.mp3","us":"media/ldoce/hwd/ame/1/supple.mp3"},"examples":[{"en":"These exercises will help to keep you supple.","cn":"这些锻炼项目有助于你保持身体的柔韧性。"},{"en":"Moisturizing cream helps to keep your skin soft and supple.","cn":"保湿霜有助于保持皮肤柔软有弹性。"}],"oxford":{"phon":"ˈsʌpl","pos":"adjective","senses":[{"en":"able to bend and move parts of your body easily into different positions","cn":"（身体）柔软的，灵活的；柔韧性好的","ex":{"en":"her slim, supple body","cn":"她苗条灵活的身体"}},{"en":"soft and able to bend easily without starting to split","cn":"易弯曲的；柔韧的","ex":{"en":"Moisturizing cream helps to keep your skin soft and supple.","cn":"保湿霜有助于保持皮肤柔软有弹性。"}}]}},"suffocate":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)窒息而死;(把…)闷死","en":"If someone suffocates or is suffocated, they die because there is no air for them to breathe.","ex":{"en":"He either suffocated, or froze to death","cn":"他要么是闷死的，要么是冻死的。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)呼吸困难;(使)憋闷","en":"If you say that you are suffocating or that something is suffocating you, you mean that you feel very uncomfortable because there is not enough fresh air and it is difficult to breathe.","ex":{"en":"That's better. I was suffocating in that cell of a room","cn":"这样好些了，我刚才在那个小房间里快闷死了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(受)束缚;(受)扼制","en":"You say that a person or thing is suffocating, or that something is suffocating them, when the situation that they are in does not allow them to act freely or to develop.","ex":{"en":"After a few weeks with her parents, she felt she was suffocating","cn":"和父母呆了几个星期后，她感到自己毫无自由。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be unable to breathe because your throat is blocked or because there is not enough air","cn":""},{"en":"to die because you are unable to breathe because you cannot get any air","cn":""},{"en":"if a person or smoke, gas etc chokes someone, they make it very difficult or impossible for them to breathe","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you suffocate , you struggle for breath, either because you’re being choked to death or because you’re in a stifling room. You can also suffocate in a figurative sense anytime something is restricted."}]},"media":{"uk":"media/ldoce/hwd/bre/e/suffocate0205.mp3","us":"media/ldoce/hwd/ame/c/suffocate.mp3"},"examples":[{"en":"The couple were suffocated by fumes from a faulty gas fire.","cn":"由于劣质煤气取暖器漏气，这对夫妇窒息而死。"},{"en":"Can I open a window? It's suffocating in here!","cn":"我可以打开窗户吗？这里面都快把人闷死了！"}],"oxford":{"phon":"ˈsʌfəkeɪt","pos":"verb","senses":[{"en":"to die because there is no air to breathe; to kill somebody by not letting them breathe air","cn":"（使）窒息而死；（把…）闷死","lab":"figurative","ex":{"en":"Many dogs have suffocated in hot cars.","cn":"许多狗在热烘烘的汽车里给闷死了。"}}]}},"sustenance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"食物;营养;养料","en":"Sustenance is food or drink which a person, animal, or plant needs to remain alive and healthy.","ex":{"en":"The state provided a basic quantity of food for daily sustenance, but little else.","cn":"国家提供基本的日常食物供应，但除此之外就没什么了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"food that people or animals need in order to live","cn":"食物﹔营养"},{"en":"when something is made to continue","cn":"保持﹔维持﹔支持"}]},"vocab":{"pos":"n","senses":[{"en":"Sustenance comes from the word sustain , which means to continue. Sustenance is food or drink that allows you to continue to be alive. For many, prayer is a source of spiritual sustenance ."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sustenance.mp3","us":"media/ldoce/hwd/ame/3/sustenance.mp3"},"examples":[{"en":"( figurative ) Arguing would only give further sustenance to his allegations.","cn":"越是争论，他越会觉得自己那些说法有道理。"},{"en":"Elections are essential for the sustenance of parliamentary democracy.","cn":"选举制度是维持议会民主所必不可少的。"}],"oxford":{"phon":"ˈsʌstənəns","pos":"noun","senses":[{"en":"the food and drink that people, animals and plants need to live and stay healthy","cn":"食物；营养；养料","lab":"figurative","ex":{"en":"There's not much sustenance in a bowl of soup.","cn":"一碗汤没多少营养。"}},{"en":"the process of making something continue to exist","cn":"维持；保持","ex":{"en":"Elections are essential for the sustenance of parliamentary democracy.","cn":"选举制度是维持议会民主所必不可少的。"}}]}},"subvert":{"collins":{"senses":[{"pos":"VERB 动词","cn":"颠覆;破坏","en":"To subvert something means to destroy its power and influence.","ex":{"en":"...an alleged plot to subvert the state.","cn":"涉嫌颠覆国家的阴谋"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to destroy the power and influence of a government or the established system","cn":"颠覆﹐暗中破坏〔现政府或现有制度〕"},{"en":"to destroy someone’s beliefs or loyalty","cn":"腐蚀﹔败坏﹔使放弃〔信念或忠诚〕"}]},"vocab":{"pos":"v","senses":[{"en":"When you subvert something, your words or actions criticize or undermine the usual way of doing something or common values. The girl who wears a tuxedo to the prom might subvert traditional ideas about beauty."}]},"media":{"uk":"media/ldoce/hwd/bre/a/subvert0205.mp3","us":"media/ldoce/hwd/ame/3/subvert.mp3"},"examples":[{"en":"an attempt to subvert the democratic process","cn":"颠覆民主进程的企图"}],"oxford":{"phon":"səbˈvɜːt","pos":"verb","senses":[{"en":"to try to destroy the authority of a political, religious, etc. system by attacking it secretly or indirectly","cn":"颠覆；暗中破坏","g":"[transitive, intransitive]"},{"en":"to challenge somebody’s ideas or expectations and make them consider the opposite","cn":"策反；颠覆","g":"[transitive]","ex":{"en":"The film subverts notions of male and female identity.","cn":"这部电影颠覆了男性和女性身份的观念。"}}]}},"suffrage":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"选举权;投票权","en":"Suffrage is the right of people to vote for a government or national leader.","ex":{"en":"He was an advocate of universal suffrage as a basis for social equality.","cn":"他提倡普选权，认为这是社会公平的基础。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the right to vote in an election","cn":""},{"en":"if you have a vote , you have the right to vote","cn":""},{"en":"the right to vote in elections - use this especially to talk about people's fight to be allowed to vote","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Suffrage is the right to vote in public elections. Universal suffrage means everyone gets to vote, as opposed to only men, or property holders. Suffrage has nothing to do with \"suffering,\" unless the wrong person is elected."}]},"media":{"uk":"media/ldoce/hwd/bre/a/suffrage0205.mp3","us":"media/ldoce/hwd/ame/d/suffrage.mp3"},"examples":[{"en":"universal suffrage (= the right of all adults to vote)","cn":"普选权"},{"en":"women's suffrage","cn":"妇女的选举权"}],"oxford":{"phon":"ˈsʌfrɪdʒ","pos":"noun","senses":[{"en":"the right to vote in political elections","cn":"选举权；投票权","ex":{"en":"universal suffrage (= the right of all adults to vote)","cn":"普选权"}}]}},"subhuman":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"非人的;不齿于人类的;无人性的","en":"If you describe someone or their situation as subhuman, you mean that they behave or live in a much worse way than human beings normally do.","ex":{"en":"The Greeks treated women as subhuman","cn":"旧时希腊人不把女人当人看。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not having all the qualities a normal human being has","cn":"不齿于人类的﹔低于人类的"},{"en":"subhuman conditions are very bad or cruel 〔","cn":"条件〕非人的"}]},"vocab":{"pos":"adj","senses":[{"en":"Subhuman words and actions aren't worthy of a human being. Stealing a toy from a child is a subhuman thing to do."}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41subhuman.mp3","us":"media/ldoce/hwd/ame/b/subhuman.mp3"},"examples":[{"en":"They were living in subhuman conditions.","cn":"他们生活在非人的条件下。"},{"en":"subhuman behaviour","cn":"不齿于人类的行为"}],"oxford":{"phon":"ˌsʌbˈhjuːmən","pos":"adjective","senses":[{"en":"so cruel or bad that they do not deserve to be called human","cn":"不齿于人类的；无人性的","ex":{"en":"subhuman behaviour","cn":"不齿于人类的行为"}},{"en":"not fit for humans","cn":"非人的；不适合人类的","ex":{"en":"They were living in subhuman conditions.","cn":"他们生活在非人的条件下。"}}]}},"suite":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一套房间;套间","en":"A suite is a set of rooms in a hotel or other building.","ex":{"en":"They had a fabulous time during their week in a suite at the Paris Hilton.","cn":"他们在巴黎希尔顿酒店的套房里度过了非常愉快的一周。"}},{"pos":"N-COUNT 可数名词","cn":"一套家具","en":"A suite is a set of matching armchairs and a sofa.","ex":{"en":"...a three-piece suite.","cn":"三件套家具"}},{"pos":"N-COUNT 可数名词","cn":"一套浴室家具","en":"A bathroom suite is a matching bath, washbasin, and toilet."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a set of rooms, especially expensive ones in a hotel","cn":"套房〔尤指酒店豪华套房〕"},{"en":"a set of matching furniture for a room","cn":"一套家具"},{"en":"a group of related computer program s","cn":"套件"}]},"vocab":{"pos":"n","senses":[{"en":"A suite (sounds like \"sweet\") is a collection of matching things. It usually refers to rooms together, like when you get a suite at a fancy hotel. It can also be a set of furniture or a musical composition."}]},"collocations":{"phrases":["ADJ. three-piece a three-piece lounge suite | bathroom, bedroom, dining/dining-room, lounge","VERB + SUITE put in We're having a new bathroom suite put in.","PHRASES a suite of furniture 2 set of rooms in a hotel, office block, etc.","ADJ. private | executive, luxury | furnished | penthouse | bridal, conference, delivery (= in the maternity ward of a hospital), family, hon","PHRASES a suite of rooms/offices"]},"media":{"uk":"media/ldoce/hwd/bre/b/suite0205.mp3","us":"media/ldoce/hwd/ame/0/suite.mp3"},"examples":[{"en":"( BrE ) a three-piece suite with two armchairs and a sofa","cn":"由两张单人沙发和一张长沙发组成的三件套家具"},{"en":"a suite of software development tools","cn":"一套软件开发工具"}],"oxford":{"phon":"swiːt","pos":"noun","senses":[{"en":"a set of rooms, especially in a hotel","cn":"（尤指旅馆的）一套房间，套房","ex":{"en":"a hotel/private/honeymoon suite","cn":"旅馆／私人／蜜月套房"}},{"en":"a set of matching pieces of furniture","cn":"一套家具","lab":"British English","ex":{"en":"a bathroom/bedroom suite","cn":"一套卫生间／卧室家具"}},{"en":"a piece of music made up of three or more related parts, for example pieces from an opera","cn":"组曲（由三个或更多相关部分组成）","ex":{"en":"Stravinsky’s Firebird Suite","cn":"斯特拉文斯基的组曲《火鸟》"}},{"en":"a set of related computer programs","cn":"套；套装软件","lab":"computing","ex":{"en":"a suite of software development tools","cn":"一套软件开发工具"}}]}},"surmise":{"collins":{"senses":[{"pos":"VERB 动词","cn":"推测;猜测;臆测","en":"If you surmise that something is true, you guess it from the available evidence, although you do not know for certain.","ex":{"en":"There's so little to go on, we can only surmise what happened","cn":"几乎毫无凭据，我们只能猜测发生了什么。"}},{"pos":"N-VAR 可变名词","cn":"猜想;推测;臆测","en":"If you say that a particular conclusion is surmise, you mean that it is a guess based on the available evidence and you do not know for certain that it is true.","ex":{"en":"It is mere surmise that Bosch had Brant's poem in mind when doing this painting","cn":"认为博斯在画这幅画时脑子里想着布兰特的诗，这仅仅是猜测而已。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to guess that something is true, using the information you know already","cn":"推测﹐猜测﹐臆测"}]},"vocab":{"pos":"v n","senses":[{"en":"If you see the empty ice cream containers, the sprinkles littering the ground, a kicked can of Reddi-wip in the trash, you can surmise what has happened: Sundaes. To surmise is to form an opinion or make a guess about something."}]},"media":{"uk":"media/ldoce/hwd/bre/8/surmise0205.mp3","us":"media/ldoce/hwd/ame/7/surmise1.mp3"},"examples":[{"en":"From the looks on their faces, I surmised that they had had an argument.","cn":"看他们的脸色，我猜想他们之间发生了争执。"},{"en":"This is pure surmise on my part.","cn":"这纯粹是我的猜测。"}],"oxford":{"phon":"səˈmaɪz","pos":"verb","senses":[{"en":"to guess or suppose something using the evidence you have, without definitely knowing","cn":"推测；猜测","ex":{"en":"From the looks on their faces, I surmised that they had had an argument.","cn":"看他们的脸色，我猜想他们之间发生了争执。"}},{"en":"a guess based on some facts that you know already","cn":"推测；猜测","ex":{"en":"This is pure surmise on my part.","cn":"这纯粹是我的猜测。"},"pos":"noun"}]}},"subside":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(感情)平息，缓和，趋于平静;(噪音)减弱，降低","en":"If a feeling or noise subsides, it becomes less strong or loud.","ex":{"en":"The pain had subsided during the night","cn":"晚间疼痛已经减轻了。"}},{"pos":"VERB 动词","cn":"(争斗)平息，平静","en":"If fighting subsides, it becomes less intense or general.","ex":{"en":"Violence has subsided following two days of riots.","cn":"两天的暴乱过后，暴力事件开始平息。"}},{"pos":"VERB 动词","cn":"(地面、建筑物)下沉，沉降，下陷","en":"If the ground or a building is subsiding, it is very slowly sinking to a lower level.","ex":{"en":"Does that mean the whole house is subsiding?","cn":"那意味着整个房子正在下陷吗？"}},{"pos":"VERB 动词","cn":"(水位)回落;(尤指洪水)减退，消退","en":"If a level of water, especially flood water, subsides, it goes down.","ex":{"en":"Local officials say the flood waters have subsided.","cn":"当地官员称洪水已经退去了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something such as fear, anxiety, trouble or laughter subsides , it gradually decreases","cn":""},{"en":"if something such as people's liking or support for something or someone wanes , that feeling gradually becomes slightly less and will probably continue to decrease","cn":""},{"en":"if a possibility or chance recedes , it gradually becomes less and less likely","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To subside is to die down or become less violent, like rough ocean waves after a storm has passed (or your seasickness, if you happened to be sailing on that ocean)."}]},"collocations":{"phrases":["ADV. quickly, rapidly | gradually, slowly The storm gradually subsided. | eventually, finally","VERB + SUBSIDE begin to","PREP. into Her tears subsided into sniffs."]},"media":{"uk":"media/ldoce/hwd/bre/d/subside0205.mp3","us":"media/ldoce/hwd/ame/7/subside.mp3"},"examples":[{"en":"I took an aspirin and the pain gradually subsided.","cn":"我服了一片阿司匹林，疼痛逐渐缓解了。"},{"en":"She waited nervously for his anger to subside.","cn":"她提心吊胆地等他的怒气平息下来。"}],"oxford":{"phon":"səbˈsaɪd","pos":"verb","senses":[{"en":"to become calmer, quieter or less intense","cn":"趋于平静；平息；减弱；消退","g":"[intransitive]","ex":{"en":"She waited nervously for his anger to subside.","cn":"她提心吊胆地等他的怒气平息下来。"}},{"en":"to go back to a normal level","cn":"回落；减退","g":"[intransitive]","ex":{"en":"The flood waters gradually subsided.","cn":"洪水缓缓回落。"}},{"en":"to sink to a lower level; to sink lower into the ground","cn":"下沉；沉降；下陷","g":"[intransitive]","ex":{"en":"Weak foundations caused the house to subside.","cn":"由于地基不实，房子出现下陷。"}}]}},"subsidiary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"附属公司;子公司","en":"A subsidiary or a subsidiary company is a company which is part of a larger and more important company.","ex":{"en":"...British Asia Airways, a subsidiary of British Airways.","cn":"英国亚洲航空公司，英国航空公司的子公司"}},{"pos":"ADJ 形容词","cn":"辅助的;附带的;次要的","en":"If something is subsidiary, it is less important than something else with which it is connected.","ex":{"en":"The economics ministry has increasingly played a subsidiary role to the finance ministry.","cn":"经济部已经越来越成了财政部的附属了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organization that makes or sells something, or provides a service","cn":""},{"en":"a company, especially one that provides a service rather than producing goods","cn":""},{"en":"a company – often used when talking about a company that employs only a small number of people","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"If a company belongs to another company, then the owned company is a subsidiary . When a large company bought your small business, you became a subsidiary . It still hurts to call them the parent company, since you publish novels and they make toilet paper."}]},"collocations":{"phrases":["ADJ. foreign, overseas | Spanish, Madrid-based, etc. | owned a 58%-owned subsidiary of Millennium Graphics | banking, manufacturing, softwar","VERB + SUBSIDIARY operate as The company operates as a wholly-owned subsidiary of a large French company. | have, own | create, establish, f","SUBSIDIARY + NOUN company • Note at ORGANIZATION"]},"media":{"uk":"media/ldoce/hwd/bre/1/subsidiary_n0205.mp3","us":"media/ldoce/hwd/ame/6/subsidiary1.mp3"},"examples":[{"en":"( BrE ) I'm taking History as a subsidiary subject (= one that is not studied in as great depth as a main subject).","cn":"我把历史课作为辅修科目。"},{"en":"I'm taking History as a subsidiary subject (= one that is not studied in as great depth as a main subject).","cn":""}],"oxford":{"phon":"səbˈsɪdiəri","pos":"adjective","senses":[{"en":"connected with something but less important than it","cn":"辅助的；附带的；次要的","lab":"British English","ex":{"en":"subsidiary information","cn":"辅助资料"}},{"en":"owned or controlled by another company","cn":"附属的；隶属的"},{"en":"a business company that is owned or controlled by another larger company","cn":"附属公司；子公司","ex":{"en":"She’s working for an overseas subsidiary of the company.","cn":"她在该公司的一家海外子公司工作。"},"pos":"noun"}]}},"surf":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"激浪;拍岸浪花","en":"Surf is the mass of white bubbles that is formed by waves as they fall upon the shore.","ex":{"en":"...surf rolling onto white sand beaches.","cn":"涌上白色沙滩的激浪"}},{"pos":"VERB 动词","cn":"冲浪","en":"If you surf, you ride on big waves in the sea on a special board.","ex":{"en":"I'm going to buy a surfboard and learn to surf","cn":"我要买个冲浪板学习冲浪。"}},{"pos":"VERB 动词","cn":"(在因特网上)冲浪，漫游，浏览","en":"If you surf the Internet, you spend time finding and looking at things on the Internet.","ex":{"en":"No one knows how many people currently surf the Net.","cn":"没人知道现在有多少人在网上冲浪。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to look at information on the Internet, especially when you look quickly in order to find something that interests you","cn":""},{"en":"to copy a file from the Internet onto your own computer","cn":""},{"en":"to copy something from your computer onto the Internet","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"The surf is what you see when you stand on the beach and look at the ocean — waves rising and breaking on the shore. It’s also what you do when you ride those waves. Surf’s up, dude!"}]},"collocations":{"phrases":["ADJ. heavy | distant the roar of distant surf","VERB + SURF ride dolphins riding the surf","SURF + VERB break, roll (in) the sound of surf breaking on the beach | roar, thunder","PREP. in the ~ The children splashed about in the surf.","PHRASES the roar/thunder of (the) surf"]},"media":{"img":["media/ldoce/img/surf.jpg"],"uk":"media/ldoce/hwd/bre/f/surf_n0205.mp3","us":"media/ldoce/hwd/ame/b/serf.mp3"},"examples":[{"en":"I was surfing the Net looking for information on Indian music.","cn":"我正上网查找关于印度音乐的资料。"},{"en":"Sydney, surf capital of the world (= where the sport of surfing is very popular)","cn":"世界冲浪之都悉尼"}],"oxford":{"phon":"sɜːf","pos":"noun","senses":[{"en":"large waves in the sea or ocean, and the white foam that they produce as they fall on the beach, on rocks, etc.","cn":"激浪；拍岸浪花","g":"[uncountable]","ex":{"en":"the sound of surf breaking on the beach","cn":"激浪拍岸的声音"}},{"en":"an act of going surfing","cn":"冲浪","g":"[singular]","ex":{"en":"He decided to go for a surf near Fremantle.","cn":"他决定到弗里曼特尔附近去冲浪。"}},{"en":"to take part in the sport of riding on waves on a surfboard","cn":"进行冲浪运动；冲浪","g":"[intransitive, transitive]","pos":"verb"},{"en":"to use the internet","cn":"（互联网上）冲浪，漫游，浏览","g":"[transitive]","ex":{"en":"I was surfing the Net looking for information on Indian music.","cn":"我正上网查找关于印度音乐的资料。"},"pos":"verb"}]}},"succour":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"援助;援救;帮助","en":"Succour is help given to people who are suffering or in difficulties.","ex":{"en":"...a commitment to give succour to populations involved in the conflict.","cn":"要向战争中受难的人们提供援助的承诺"}},{"pos":"VERB 动词","cn":"援助;援救;帮助","en":"If you succour someone who is suffering or in difficulties, you help them.","ex":{"en":"Helicopters fly in appalling weather to succour shipwrecked mariners.","cn":"直升机在恶劣的天气条件下起飞前去援救遇难的船员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"help and sympathy that is given to someone","cn":"救济﹐援助﹐救助"},{"en":"to give help and sympathy to someone","cn":"救济﹐援助﹐救助"}]},"media":{"uk":"media/ldoce/hwd/bre/e/succour_n0205.mp3","us":"media/ldoce/hwd/ame/0/succor.mp3"},"examples":[{"en":"They give succour to the victims of war.","cn":"他们向战争受害者提供援助。"},{"en":"succouring the needy","cn":"救济穷苦的人"}],"oxford":{"phon":"ˈsʌkə(r)","pos":"noun","senses":[{"en":"help that you give to somebody who is suffering or having problems","cn":"救助；救援；帮助","ex":{"en":"to give/bring succour to the sick and wounded","cn":"为伤病员提供救助"}},{"en":"to help somebody who is suffering or having problems","cn":"救助；救援；帮助","pos":"verb"}]}},"sufferance":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勉强同意;宽容","en":"If you are allowed to do something on sufferance, you can do it, although you know that the person who gave you permission would prefer that you did not do it.","ex":{"en":"His party held office on sufferance","cn":"他的政党勉强获胜。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if you live or work somewhere on sufferance, you are allowed to do it by someone who would prefer you did not do it","cn":"勉强获准"}]},"vocab":{"pos":"n","senses":[{"en":"Sufferance is a type of patience, especially the patience to endure pain and suffering."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41sufferance.mp3","us":"media/ldoce/hwd/ame/e/sufferance.mp3"},"examples":[{"en":"He's only staying here on sufferance.","cn":"他是经人勉强同意待在这儿的。"},{"en":"He was never going to let her forget she was only here on sufferance.","cn":"他决不会让她忘记她是被勉强准许留在这儿的。"}]},"subsist":{"collins":{"senses":[{"pos":"VERB 动词","cn":"勉强糊口;勉强度日","en":"If people subsist, they are just able to obtain the food or money that they need in order to stay alive.","ex":{"en":"The prisoners subsisted on one mug of the worst quality porridge three times a day","cn":"犯人们每日三餐靠一碗稀粥度日。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have enough money to buy the things you need to live","cn":""},{"en":"if someone lives on a particular amount of money, this is all the money that they have to buy everything that they need","cn":""},{"en":"if it is difficult for you to make ends meet , it is difficult for you to pay for the things that you need in order to live","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you subsist , you keep yourself alive. Since most airlines have stopped serving food, many travelers are forced to subsist on little packets of pretzels, even on long flights."}]},"media":{"uk":"media/ldoce/hwd/bre/1/subsist0205.mp3","us":"media/ldoce/hwd/ame/b/subsist.mp3"},"examples":[{"en":"Old people often subsist on very small incomes.","cn":"老人往往靠十分微薄的收入艰难度日。"},{"en":"The terms of the contract subsist.","cn":"合同条款有效。"}],"oxford":{"phon":"səbˈsɪst","pos":"verb","senses":[{"en":"to manage to stay alive, especially with limited food or money","cn":"（尤指靠有限的食物或钱）维持生活，度日","g":"[intransitive]","ex":{"en":"Old people often subsist on very small incomes.","cn":"老人往往靠十分微薄的收入艰难度日。"}},{"en":"to exist; to apply and be relevant","cn":"存在；有效","g":"[intransitive]","lab":"law","ex":{"en":"The terms of the contract subsist.","cn":"合同条款有效。"}}]}},"sunlit":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"阳光照耀的;阳面的","en":"Sunlit places are brightly lit by the sun.","ex":{"en":"Her house has two big sunlit rooms with floor-to-ceiling windows.","cn":"她的房子有两间向阳的带落地窗的大屋子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made brighter by light from the sun","cn":"阳光照耀的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/sunlit0205.mp3","us":"media/ldoce/hwd/ame/0/sunlit.mp3"},"examples":[{"en":"sunlit streets","cn":"阳光照耀的街道"},{"en":"a sunlit garden","cn":"阳光灿烂的花园"}],"oxford":{"phon":"ˈsʌnlɪt","pos":"adjective","senses":[{"en":"receiving light from the sun","cn":"阳光照耀的","ex":{"en":"sunlit streets","cn":"阳光照耀的街道"}}]}},"submarine":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"潜艇(亦使用缩略形式sub)","en":"A submarine is a type of ship that can travel both above and below the surface of the sea. The abbreviation sub is also used.","ex":{"en":"...a nuclear submarine.","cn":"核潜艇"}},{"pos":"ADJ 形容词","cn":"水下的;海底的","en":"Submarine means existing below the surface of the sea.","ex":{"en":"...submarine caves.","cn":"海底洞穴"}},{"pos":"N-COUNT 可数名词","cn":"潜艇三明治，长卷三明治(亦使用缩略形式sub)","en":"A submarine sandwich is a long soft bread roll filled with a combination of things such as meat, cheese, eggs, and salad. The abbreviation sub is also used."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a military ship with guns, used in a war","cn":""},{"en":"the largest type of ship used in war, with very big guns on it","cn":""},{"en":"a military ship that planes can fly from or land on","cn":""}]},"vocab":{"pos":"n adj v","senses":[{"en":"If you're in the Navy, a submarine is a military ship that goes under the water. If you're hungry, it's a type of sandwich."}]},"collocations":{"phrases":["ADJ. conventional | diesel, diesel-powered | atomic, nuclear, nuclear-powered | midget, miniature | enemy","SUBMARINE + VERB dive | surface | sink (sth) | operate, patrol (sth) the problem of submarines operating too close to fishing vessels","SUBMARINE + NOUN captain, commander, crew | base, fleet | attack, warfare"]},"media":{"uk":"media/ldoce/hwd/bre/0/submarine_adj0205.mp3","us":"media/ldoce/hwd/ame/8/submarine1.mp3"},"examples":[{"en":"a submarine base","cn":"潜艇基地"},{"en":"submarine plant life","cn":"海底植物"}],"oxford":{"phon":"ˌsʌbməˈriːn","pos":"noun","senses":[{"en":"a ship that can travel underwater","cn":"潜艇","ex":{"en":"a nuclear submarine","cn":"核潜艇"}},{"en":"a long bread roll split open along its length and filled with various types of food","cn":"潜艇三明治，长卷三明治（用长卷面包纵向切开，内夹各种食物）","lab":"all North American English"},{"en":"existing or located under the sea","cn":"水下的；海底的","ex":{"en":"submarine plant life","cn":"海底植物"},"pos":"adjective"}]}},"supernatural":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"超自然的;神奇的;不可思议的","en":"Supernatural creatures, forces, and events are believed by some people to exist or happen, although they are impossible according to scientific laws.","ex":{"en":"The Nakani were evil spirits who looked like humans and possessed supernatural powers.","cn":"纳卡尼是邪恶的魔鬼，长得像人类但具有超能力。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"impossible to explain by natural causes, and therefore seeming to involve the powers of gods or magic","cn":"超自然的，奇异的，神奇的"},{"en":"the spirit of a dead person that some people believe they can see or hear","cn":""},{"en":"looking like a ghost, or making you think of ghosts","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"If you enjoy a good story about vampires, witches, werewolves, or ghosts, you like reading about the supernatural — forces, beings, and events that are beyond what can be explained by nature."}]},"media":{"uk":"media/ldoce/hwd/bre/f/supernatural_n0205.mp3","us":"media/ldoce/hwd/ame/b/supernatural1.mp3"},"examples":[{"en":"a belief in the supernatural","cn":"对超自然力量的相信"},{"en":"supernatural powers","cn":"超自然力量"}],"oxford":{"phon":"ˌsuːpəˈnætʃrəl","pos":"adjective","senses":[{"en":"that cannot be explained by the laws of science and that seems to involve gods or magic","cn":"超自然的；神奇的；神灵魔怪的","ex":{"en":"supernatural powers","cn":"超自然力量"}},{"en":"events, forces or powers that cannot be explained by the laws of science and that seem to involve gods or magic","cn":"超自然物；超自然力量；神奇怪异的事","g":"[singular]","ex":{"en":"a belief in the supernatural","cn":"相信超自然力量"}}]}},"suitability":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the degree to which something or someone has the right qualities for a particular purpose","cn":"合适﹐适合﹐适宜"}]},"collocations":{"phrases":["ADJ. greater","VERB + SUITABILITY assess, demonstrate, determine to assess the suitability of the accommodation for a disabled person | ensure | doubt, hav","PREP. ~ for the greater suitability of women for the work"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41suitability.mp3","us":"media/ldoce/hwd/ame/1/suitability.mp3"},"examples":[{"en":"There is no doubt about her suitability for the job.","cn":"毫无疑问，她适合做这个工作。"},{"en":"There’s no doubt about Christine’s suitability for the job.","cn":"毫无疑问﹐克里斯蒂娜适合做这份工作。"}],"oxford":{"phon":"ˌsuːtəˈbɪləti","pos":"noun","senses":[{"en":"the quality of being right or appropriate for a particular purpose or occasion","cn":"合适地；适宜地；适当地","ex":{"en":"There is no doubt about her suitability for the job.","cn":"毫无疑问她很适合这项工作。"}}]}},"submerged":{"lemma":"submerge","media":{"uk":"media/ldoce/hwd/bre/2/submerge0205.mp3","us":"media/ldoce/hwd/ame/c/submerge.mp3"}},"sunspot":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(太阳表面大约会持续存在一周的)黑子，日斑","en":"Sunspots are dark cool patches that appear on the surface of the sun and last for about a week."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small dark area on the sun’s surface 〔","cn":"太阳表面的〕黑子﹐日斑"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41sunspot.mp3","us":"media/ldoce/hwd/ame/9/sunspot.mp3"},"oxford":{"phon":"ˈsʌnspɒt","pos":"noun","senses":[{"en":"a dark area that sometimes appears on the sun’s surface","cn":"（太阳）黑子"}]}},"summons":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"召唤;召见令","en":"A summons is an order to come and see someone.","ex":{"en":"I received a summons to the Palace from Sir Robert Fellowes, the Queen's private secretary.","cn":"我被女王的私人秘书罗伯特·费洛斯爵士召往白金汉宫。"}},{"pos":"N-COUNT 可数名词","cn":"(法院的)传讯，传票，传唤","en":"A summons is an official order to appear in court.","ex":{"en":"She had received a summons to appear in court.","cn":"她已经接到法院传唤其出庭的传票。"}},{"pos":"VERB 动词","cn":"传讯;传唤;发传票给","en":"If someone is summonsed, they are officially ordered to appear in court.","ex":{"en":"The men were summonsed and last week 30 appeared before Hove magistrates","cn":"这些人被传唤，上周有30人到霍夫地方法院接受讯问。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official order to appear in a court of law 〔","cn":"法庭的〕传票"},{"en":"to order someone to appear in a court of law","cn":"发传票给〔某人〕﹐传唤﹐传讯"}]},"vocab":{"pos":"n v","senses":[{"en":"A summons is a request or order for someone to show up, especially for legal matters. You could get a summons to testify at a trial, for example."}]},"collocations":{"phrases":["ADJ. peremptory, urgent | royal","VERB + SUMMONS send (out) | await, expect I stayed in that night awaiting her summons. | get, hear, receive | answer, obey, respond to | ign","SUMMONS + VERB come She was ready when the summons duly came.","PREP. ~ from She responded immediately to the summons from the head teacher. | ~ to I received an urgent summons to her office.","PHRASES in answer to a summons He arrived panting in answer to Blake's summons. 2 order to go to a court of law","ADJ. court | private | witness","VERB + SUMMONS issue, take out | deliver, present (sb with), serve (sb with) The summons can be served on either of the partners in the busi","PREP. ~ against Her neighbours took out a summons against her for noise nuisance. | ~ for"]},"media":{"uk":"media/ldoce/hwd/bre/8/summons_n0205.mp3","us":"media/ldoce/hwd/ame/a/summons1.mp3"},"examples":[{"en":"The police have been unable to serve a summons on him.","cn":"警方一直无法把传票送达他本人。"},{"en":"She received a summons to appear in court the following week.","cn":"她收到一张传票，让她下周出庭。"}],"oxford":{"phon":"ˈsʌmənz","pos":"noun","senses":[{"en":"an order to appear in court","cn":"（法院的）传唤，传票","lab":"North American English also","ex":{"en":"to issue a summons against somebody","cn":"向某人发出传票"}},{"en":"an order to come and see somebody","cn":"召唤；召见令","ex":{"en":"to obey a royal summons","cn":"听从国王的召唤"}},{"en":"to order somebody to appear in court","cn":"传（某人）出庭；传唤","ex":{"en":"She was summonsed for speeding.","cn":"她因超速驾驶被传讯。"},"pos":"verb"}]},"base":"summon"},"subaltern":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"陆军中尉","en":"A subaltern is any commissioned officer in the army below the rank of captain."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a middle rank in the British army, or someone who has this rank 〔","cn":"英国〕陆军中尉（军衔）"}]},"vocab":{"pos":"n adj","senses":[{"en":"A subaltern is someone with a low ranking in a social, political, or other hierarchy. It can also mean someone who has been marginalized or oppressed."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41subaltern.mp3","us":"media/ldoce/hwd/ame/d/ld41subaltern.mp3"},"oxford":{"phon":"ˈsʌbltən","pos":"noun","senses":[{"en":"any officer in the British army who is lower in rank than a captain","cn":"（英国）陆军中尉"}]}},"sunbathe":{"collins":{"senses":[{"pos":"VERB 动词","cn":"晒太阳;沐日光浴","en":"When people sunbathe, they sit or lie in a place where the sun shines on them, so that their skin becomes browner.","ex":{"en":"Franklin swam and sunbathed at the pool every morning.","cn":"每天上午富兰克林都在游泳池中游泳，在池边晒太阳。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to sit or lie outside in the sun, especially in order to become brown","cn":"沐日光浴﹐晒太阳"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sunbathe0205.mp3","us":"media/ldoce/hwd/ame/2/sunbathe.mp3"},"examples":[{"en":"Her mother was sunbathing in the back garden.","cn":"她母亲在后花园晒太阳。"}],"oxford":{"phon":"ˈsʌnbeɪð","pos":"verb","senses":[{"en":"to sit or lie in the sun, especially in order to go brown (get a suntan)","cn":"沐日光浴；晒太阳","lab":"British English","ex":{"en":"We spent the day sunbathing and swimming.","cn":"我们一整天都在晒日光浴和游泳。"}}]}},"suchlike":{"collins":{"senses":[{"pos":"PRON 代词","cn":"诸如此类的东西","en":"You use suchlike to refer to other things that are like the ones you have already mentioned.","ex":{"en":"...objets d'art, gold, silver, and ivory assortments, ceramics, and suchlike","cn":"小艺术品，各式各样的金、银、象牙制品，瓷器一类的东西"}}]},"ldoce":{"phon":"hwd","pos":"pronoun","senses":[{"en":"an abbreviation for et cetera used at the end of a short list to mean 'and others of a similar kind'. When you say etc you pronounce it 'et cetera'","cn":""},{"en":"used when you expect someone to guess what the other things are","cn":""},{"en":"used when someone is making a choice and can have what they want","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41suchlike.mp3","us":"media/ldoce/hwd/ame/1/suchlike1.mp3"},"examples":[{"en":"You can buy brushes, paint, varnish and suchlike there.","cn":"你在那儿能买到刷子、油漆、清漆之类的东西。"},{"en":"food, drink, clothing and suchlike provisions","cn":"食物、饮料、服装以及其他诸如此类的日用品"}],"oxford":{"phon":"ˈsʌtʃlaɪk","pos":"determiner","senses":[{"en":"other similar","cn":"诸如此类的事物","ex":{"en":"food, drink, clothing and suchlike provisions","cn":"食物、饮料、衣物以及诸如此类的供应品"}},{"en":"things of the type mentioned","cn":"诸如此类的事物","ex":{"en":"You can buy brushes, paint, varnish and suchlike there.","cn":"你在那儿能买到刷子、油漆、清漆之类的东西。"},"pos":"pronoun"}]}},"superficial":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肤浅的;浅薄的;粗枝大叶的","en":"If you describe someone as superficial, you disapprove of them because they do not think deeply, and have little understanding of anything serious or important.","ex":{"en":"This guy is a superficial yuppie with no intellect whatsoever","cn":"这个家伙是个肤浅的雅皮士，没有什么头脑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行动、情感、关系)表面的，外表的，不深入的","en":"If you describe something such as an action, feeling, or relationship as superficial, you mean that it includes only the simplest and most obvious aspects of that thing, and not those aspects which require more effort to deal with or understand.","ex":{"en":"Their arguments do not withstand the most superficial scrutiny","cn":"他们的论据经不起一点推敲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"表面的，乍看起来的(尤指实际并非如此)","en":"Superficial is used to describe the appearance of something or the impression that it gives, especially if its real nature is very different.","ex":{"en":"Despite these superficial resemblances, this is a darker work than her earlier novels","cn":"尽管表面上有一些相似之处，但这本著作实际要比她以前的小说悲观。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(伤势或伤害)表层的，表皮的，表面的","en":"Superficial injuries are not very serious, and affect only the surface of the body. You can also describe damage to an object as superficial .","ex":{"en":"The 69-year-old clergyman escaped with superficial wounds","cn":"69 岁的牧师幸免于难，只受了点皮肉伤。"}},{"pos":"ADJ 形容词","cn":"(皮肤)表层的","en":"The superficial layers of the skin are the ones nearest the surface.","ex":{"en":"...superficial blood vessels in the forearm.","cn":"前臂的表层血管"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if a person, place, or situation is pleasant, normal, calm etc on the surface , they seem that way until you know them better","cn":""},{"en":"if someone is outwardly calm, happy etc, that is how they seem to be, but in fact they are probably nervous, unhappy etc","cn":""},{"en":"use this when something seems to be true about someone or something especially when it is not true","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything superficial has to do with the surface of something. If you're judging a book by its cover, you're being superficial . People who worry too much about their clothes and hair may also be considered superficial ."}]},"collocations":{"phrases":["VERBS be, seem | remain","ADV. extremely, very | entirely, purely He began to feel he could cope, on a purely superficial level, at least. | increasingly | largely, m"]},"media":{"uk":"media/ldoce/hwd/bre/e/superficial0205.mp3","us":"media/ldoce/hwd/ame/a/superficial.mp3"},"examples":[{"en":"When you first meet her, she gives a superficial impression of warmth and friendliness.","cn":"初次见面时，她总给人以热情亲切的表面印象。"},{"en":"The book shows only a superficial understanding of the historical context.","cn":"这部书表现出对历史背景肤浅的理解。"}],"oxford":{"phon":"ˌsuːpəˈfɪʃl","pos":"adjective","senses":[{"en":"not studying or looking at something carefully or completely; seeing only what is obvious","cn":"粗略的；肤浅的；粗枝大叶的；浅薄的","lab":"often disapproving","ex":{"en":"a superficial analysis","cn":"粗略的分析"}},{"en":"appearing to be true, real or important until you look at it more carefully","cn":"表面的；外面的；外表的","ex":{"en":"superficial differences/similarities","cn":"表面的相异／相似之处"}},{"en":"only affecting the surface and therefore not serious","cn":"表层的；表皮的","ex":{"en":"a superficial injury","cn":"皮外伤"}},{"en":"not serious or important and not having any depth of understanding or feeling","cn":"浅薄的；肤浅的","lab":"disapproving","ex":{"en":"a superficial friendship","cn":"浅薄的交情"}},{"en":"of or on the surface of something","cn":"表面的；浅表的","lab":"specialist","ex":{"en":"superficial veins","cn":"浅静脉"}}]}},"super":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"顶好的;超级的;顶呱呱的","en":"Some people use super to mean very nice or very good.","ex":{"en":"We had a super time","cn":"我们玩得很痛快。"}},{"pos":"ADV 副词","cn":"非常;格外;极","en":"Super is used before adjectives to indicate that something has a lot of a quality.","ex":{"en":"I'm going to Greece in the summer so I've got to be super slim.","cn":"夏天我要去希腊，因此我要变得格外苗条才好。"}},{"pos":"ADJ 形容词","cn":"(用于名词前)表示“超级的”","en":"Super is used before nouns to indicate that something is larger, better, or more advanced than similar things.","ex":{"en":"...building Russia into a super state.","cn":"把俄罗斯建成一个超级大国"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good","cn":"极好的﹐了不起的"},{"en":"a superintendent (4) 〔","cn":"公寓楼的〕看管人﹐管理员"},{"en":"extremely","cn":"非常﹐极其"}]},"vocab":{"pos":"n adj adv","senses":[{"en":"When something is extraordinary, it’s super , like a movie that couldn't possibly be better or the super grade you got on your test: A+."}]},"media":{"uk":"media/ldoce/hwd/bre/8/super_n0205.mp3","us":"media/ldoce/hwd/ame/7/super1.mp3"},"examples":[{"en":"She was super (= very kind) when I was having problems.","cn":"我遇到问题的时候，她待我好极了。"},{"en":"We had a super time in Italy.","cn":"我们在意大利过得十分惬意。"}],"oxford":{"phon":"ˈsuːpə(r)","pos":"adjective","senses":[{"en":"extremely good","cn":"顶好的；超级的；顶呱呱的","ex":{"en":"a super meal","cn":"一顿美餐"}},{"en":"especially; particularly","cn":"特别；格外","ex":{"en":"He's been super understanding.","cn":"他特别体谅人。"},"pos":"adverb"},{"en":"a superintendent in the police","cn":"（英国的）警官；（美国的）警长","lab":"British English, informal，，","pos":"noun"},{"en":"a superintendent of a building","cn":"（大楼的）管理人","lab":"North American English","pos":"noun"},{"en":"extremely; more or better than normal","cn":"极；超；超级","ex":{"en":"super-rich","cn":"极富有的"},"pos":"combining form"},{"en":"above; over","cn":"上；上方","ex":{"en":"superstructure","cn":"上层建筑"},"pos":"combining form"}]}},"sundown":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"日落时分","en":"Sundown is the time when the sun sets.","ex":{"en":"The fighting broke out about two hours after sundown.","cn":"日落后大约两小时战斗打响了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"sunset (1)","cn":"日落"}]},"media":{"uk":"media/ldoce/hwd/bre/3/sundown0205.mp3","us":"media/ldoce/hwd/ame/0/sundown.mp3"},"oxford":{"phon":"ˈsʌndaʊn","pos":"noun","senses":[{"en":"the time when the sun goes down and night begins","cn":"日落时分","ex":{"en":"The celebration begins at sundown.","cn":"庆祝活动在日落时分开始。"}}]}},"sunstroke":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"中暑;日射病","en":"Sunstroke is an illness caused by spending too much time in hot sunshine.","ex":{"en":"I was suffering from acute sunstroke, starvation and exhaustion.","cn":"我严重中暑，又饿又累。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"fever, weakness etc caused by being outside in the sun for too long","cn":"日射病﹐伤暑"}]},"media":{"uk":"media/ldoce/hwd/bre/d/sunstroke0205.mp3","us":"media/ldoce/hwd/ame/d/sunstroke.mp3"},"oxford":{"phon":"ˈsʌnstrəʊk","pos":"noun","senses":[{"en":"an illness with a high temperature, weakness, headache, etc. caused by too much direct sun, especially on the head","cn":"日射病；中暑"}]}},"sufferer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"受难者;受苦者;患病者","en":"A sufferer from an illness or some other bad condition is a person who is affected by the illness or condition.","ex":{"en":"Frequently sufferers of this kind of allergy are also sufferers of asthma.","cn":"患有这种过敏症的人也经常会患有哮喘病。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is ill and is being looked after by a doctor, nurse etc","cn":""},{"en":"someone who has a particular illness or who often has a particular illness","cn":""},{"en":"someone who is permanently ill and needs to be looked after, especially if they have to stay in bed","cn":""}]},"collocations":{"phrases":["ADJ. main, worst The worst sufferers of the condition tend to live in highly polluted areas. | lifelong, long-term | fellow The sessions wil","PREP. ~ from He's been a lifelong sufferer from hay fever."]},"media":{"uk":"media/ldoce/hwd/bre/0/sufferer0205.mp3","us":"media/ldoce/hwd/ame/3/sufferer.mp3"},"examples":[{"en":"She received many letters of support from fellow sufferers.","cn":"许多和她有共同遭遇的人给她来信，表示支持。"},{"en":"cancer sufferers","cn":"癌症患者"}],"oxford":{"phon":"ˈsʌfərə(r)","pos":"noun","senses":[{"en":"a person who suffers, especially somebody who has a medical condition","cn":"患病者；受苦者；受难者","ex":{"en":"allergy/asthma/migraine sufferers","cn":"过敏/哮喘/偏头痛患者"}}]}},"surgeon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外科医生，外科医师","en":"A surgeon is a doctor who is specially trained to perform surgery.","ex":{"en":"...a heart surgeon.","cn":"心脏外科医师"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who treats people who are ill, who has completed a long course of study at medical school","cn":""},{"en":"a doctor who is trained in general medicine and who treats the people who live in a local area","cn":""},{"en":"a doctor","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A surgeon is a kind of doctor who treats his patients by using his hands, often by performing surgery . If you're comfortable slicing into a person's body to remove an appendix, then you might make a decent surgeon ."}]},"collocations":{"phrases":["ADJ. distinguished, eminent, leading, top | brilliant | pioneering | chief, consultant, senior | qualified | general | brain, dental, eye, h","VERB + SURGEON be, work as | become, qualify as He is determined to qualify as a surgeon. | see","SURGEON + VERB operate, perform an operation, remove sth the surgeon who will operate on you Surgeons removed her right leg above the knee.","PHRASES surgeon's knife Many people are terrified at the thought of the surgeon's knife."]},"media":{"uk":"media/ldoce/hwd/bre/f/surgeon0205.mp3","us":"media/ldoce/hwd/ame/b/surgeon.mp3"},"examples":[{"en":"a brain/heart, etc. surgeon","cn":"脑外科、心脏外科等医生"}],"oxford":{"phon":"ˈsɜːdʒən","pos":"noun","senses":[{"en":"a doctor who is trained to perform surgery (= medical operations that involve cutting open a person’s body)","cn":"外科医生","ex":{"en":"a brain/heart surgeon","cn":"脑外科／心脏外科医生"}}]}},"suckle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"给(婴儿)喂奶;哺乳","en":"When a mother suckles her baby, she feeds it by letting it suck milk from her breast.","ex":{"en":"A young woman suckling a baby is one of life's most natural and delightful scenes.","cn":"年轻女性哺育婴儿是生命中最自然、最令人愉悦的一幕。"}},{"pos":"VERB 动词","cn":"(婴儿)吃奶，吸奶","en":"When a baby suckles, it sucks milk from its mother's breast.","ex":{"en":"As the baby suckles, a further supply of milk is generated.","cn":"婴儿吮吸时，会有更多的奶水流出来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feed a baby or young animal with milk from the breast","cn":"给〔婴儿或小动物〕喂奶﹐哺乳"},{"en":"if a baby or young animal suckles, it sucks milk from a breast 〔","cn":"婴儿或小动物〕吃奶﹐吸奶"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41suckle.mp3","us":"media/ldoce/hwd/ame/2/suckle.mp3"},"examples":[{"en":"( old-fashioned ) a mother suckling a baby","cn":"给婴儿哺乳的母亲"},{"en":"a cow suckling her calves","cn":"给小牛吃奶的母牛"}],"oxford":{"phon":"ˈsʌkl","pos":"verb","senses":[{"en":"to feed a baby or young animal with milk from the breast or udder","cn":"给…喂奶；给…哺乳","g":"[transitive]","lab":"old-fashioned","ex":{"en":"a cow suckling her calves","cn":"给小牛喂奶的母牛"}},{"en":"to drink milk from its mother’s breast or udder","cn":"吸奶；吃奶","g":"[intransitive]","ex":{"en":"The young of some mammals continue to suckle for years.","cn":"一些哺乳动物的幼崽会继续哺乳多年。"}}]}},"succession":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"一连串;一系列;连续","en":"A succession of things of the same kind is a number of them that exist or happen one after the other.","ex":{"en":"Adams took a succession of jobs which have stood him in good stead","cn":"亚当斯连着做过几份让他颇为受益的工作。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"继承;继任;继承权","en":"Succession is the fact or right of being the next person to have an important job or position.","ex":{"en":"She is now seventh in line of succession to the throne.","cn":"她目前是王位的第七顺位继承人。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"several things that happen one after the other","cn":""},{"en":"the order in which events or actions follow one another, or the order in which they are supposed to follow one another","cn":""},{"en":"a series of similar events that happen very close together, or a group of similar things that exist or are found very close together","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the word succession to describe things that follow one another, as well as the order in which they do so. The Vice President is first in line of succession to be the president and the Secretary of State is fourth."}]},"collocations":{"phrases":["ADJ. endless, long, never-ending | constant, continuous, uninterrupted | quick, rapid We lost three secretaries in quick succession. | whole","PREP. in ~ There has been a rise in crime for the second year in succession. 2 right to have an important position after sb else","ADJ. legitimate | disputed | dynastic, hereditary","VERB + SUCCESSION ensure, secure He wanted to have a son to secure the succession.","PREP. in ~ to Betty Munn is the manager in succession to Edna Greenan.","PHRASES the line/order of succession He is next in (the) line of succession to the British throne. | the right of succession, succession to "]},"media":{"uk":"media/ldoce/hwd/bre/8/succession0205.mp3","us":"media/ldoce/hwd/ame/a/succession.mp3"},"examples":[{"en":"They had three children in quick succession.","cn":"短短几年间，他们接连生了三个孩子。"},{"en":"He became chairman in succession to Bernard Allen.","cn":"他接替伯纳德 · 艾伦任主席。"}],"oxford":{"phon":"səkˈseʃn","pos":"noun","senses":[{"en":"a number of people or things that follow each other in time or order","cn":"一连串；一系列；连续的人（或事物）","g":"[countable, usually singular]","ex":{"en":"a succession of visitors","cn":"络绎不绝的来访者"}},{"en":"the regular pattern of one thing following another thing","cn":"交替；更迭","g":"[uncountable]","ex":{"en":"the succession of the seasons","cn":"四季的更迭"}},{"en":"the act of taking over an official position or title; the right to take over an official position or title, especially to become the king or queen of a country","cn":"继承；继任；（尤指王位的）继承权","g":"[uncountable]","ex":{"en":"He became chairman in succession to Bernard Allen.","cn":"他接替伯纳德·艾伦任主席。"}}]}},"sudanese":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"苏丹的;苏丹人的;苏丹文化的","en":"Sudanese means belonging or relating to Sudan, or to its people or culture.","ex":{"en":"...the Sudanese government.","cn":"苏丹政府"}},{"pos":"N-PLURAL 复数名词","cn":"苏丹人","en":"The Sudanese are the people of Sudan.","ex":{"en":"...tens of thousands of Sudanese.","cn":"成千上万的苏丹人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"from the Sudan or connected with the Sudan","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/lpd_sudanese.mp3","us":"media/ldoce/hwd/ame/b/sudanese.mp3"},"oxford":{"phon":"ˌsuːdəˈniːz","pos":"noun, adjective","senses":[{"en":"(a person) from Sudan","cn":"苏丹人；苏丹的；苏丹人的"}]}},"surplice":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(教士和唱诗班成员穿的)白色罩衣","en":"A surplice is a loose white knee-length garment which is worn over a longer garment by priests and members of the choir in some churches.","ex":{"en":"...the priest and choir in their lace surplices.","cn":"穿着蕾丝白色罩袍的教士和唱诗班"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of clothing made of white material, worn over other clothes by priests or singers in church 〔","cn":"教士或唱诗班成员穿的〕白色罩袍﹐白色法衣"}]},"vocab":{"pos":"n","senses":[{"en":"If you sing in the choir at your church, you might wear a surplice — a loose, wide-sleeved robe."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41surplice.mp3","us":"media/ldoce/hwd/ame/b/surplice.mp3"},"oxford":{"phon":"ˈsɜːpləs","pos":"noun","senses":[{"en":"a loose white piece of clothing with wide sleeves (= parts covering the arms) worn by priests and singers in the choir during church services","cn":"（教士和唱诗班穿的）白色罩衣"}]}},"supplant":{"collins":{"senses":[{"pos":"VERB 动词","cn":"替代;取代","en":"If a person or thing is supplanted, another person or thing takes their place.","ex":{"en":"He may be supplanted by a younger man","cn":"他可能会被一个年龄比他小的人取代。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be the next person to have a job or position, especially an important or powerful position, after someone else has left it or died","cn":""},{"en":"to replace someone in a job or position, especially because you have similar skills and experience to them","cn":""},{"en":"to replace someone in a job or position, and to continue the work they started","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Kate was out sick for a month with mono, and when she came back to school, Jessie had supplanted her as the funny girl at the lunch table. Supplant means to take the place of."}]},"media":{"uk":"media/ldoce/hwd/bre/6/supplant0205.mp3","us":"media/ldoce/hwd/ame/c/supplant.mp3"},"examples":[{"en":"Barker was soon supplanted as party leader.","cn":"巴克在党内的领导地位很快就被人取代了。"}],"oxford":{"phon":"səˈplɑːnt","pos":"verb","senses":[{"en":"to take the place of somebody/something (especially somebody/something older or less modern)","cn":"取代，替代（尤指年老者或落后于时代的事物）","ex":{"en":"Their work has been largely supplanted by the use of a computer program that fulfils the same function.","cn":"他们的工作很大程度上已被实现相同功能的计算机程序所取代。"}}]}},"sunken":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"沉没的;沉入水底的","en":"Sunken ships have sunk to the bottom of a sea, ocean, or lake.","ex":{"en":"The sunken sailing-boat was a glimmer of white on the bottom","cn":"沉没的帆船在海底闪烁着白光。"}},{"pos":"ADJ 形容词","cn":"(花园、公路等)低于周围地面的，低洼处的","en":"Sunken gardens, roads, or other features are below the level of their surrounding area.","ex":{"en":"Steps lead down to the sunken garden","cn":"台阶通向低处的花园。"}},{"pos":"ADJ 形容词","cn":"(眼睛、面颊等)凹陷的，深陷的","en":"Sunken eyes, cheeks, or other parts of the body curve inwards and make you look thin and unwell.","ex":{"en":"Her eyes were sunken and black-ringed.","cn":"她眼圈发黑，眼窝深陷。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having fallen to the bottom of the sea, a lake, or a river","cn":"沉没的﹐沉在海[湖﹐河]底的"},{"en":"cheeks or eyes that have fallen inwards, especially because of age or illness 〔","cn":"尤指因年老或患病所致〕凹陷的双颊/双眼等"},{"en":"built or placed at a lower level than the surrounding floor or ground","cn":"低于周围地面的；沉降式的﹐下沉式的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/sunken0205.mp3","us":"media/ldoce/hwd/ame/1/sunken.mp3"},"examples":[{"en":"sunken treasure","cn":"沉在水底的财宝"},{"en":"a sunken garden","cn":"低地花园"}],"oxford":{"phon":"ˈsʌŋkən","pos":"adjective","senses":[{"en":"that has fallen to the bottom of the sea or the ocean, or of a lake or river","cn":"沉没的；沉入水底的","g":"[only before noun]","ex":{"en":"a sunken ship","cn":"沉船"}},{"en":"hollow and deep as a result of disease, getting old, or not having enough food","cn":"凹陷的，深陷的（尤因疾病、年老或饥饿）","ex":{"en":"His eyes were dark and sunken.","cn":"他的眼睛又黑又凹陷。"}},{"en":"at a lower level than the area around","cn":"低于周围平面的；低洼处的","g":"[only before noun]","ex":{"en":"a sunken garden","cn":"沉园"}}]}},"suntan":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"晒黑的皮肤;晒成古铜色的皮肤","en":"If you have a suntan, the sun has turned your skin an attractive brown colour."},{"pos":"ADJ 形容词","cn":"(露、油或霜)防晒的","en":"Suntan lotion, oil, or cream protects your skin from the sun.","ex":{"en":"She playfully rubs suntan lotion on his neck.","cn":"她开玩笑地把防晒露擦到他脖子上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"brown skin that someone with pale skin gets after they have spent time in the sun","cn":"晒黑的皮肤﹐古铜色皮肤"}]},"collocations":{"phrases":["ADJ. golden, good","VERB + SUNTAN have | show off, sport Everyone in the bar was sporting a suntan. | get, work on He spent the mornings on the beach getting a ","SUNTAN + NOUN lotion, oil"]},"media":{"uk":"media/ldoce/hwd/bre/d/suntan0205.mp3","us":"media/ldoce/hwd/ame/d/suntan.mp3"},"examples":[{"en":"Where have you been to get that suntan?","cn":"你上哪儿去了，晒得黑黑的？"},{"en":"a suntanned face","cn":"晒得黝黑的脸庞"}],"oxford":{"phon":"ˈsʌntæn","pos":"adjective","senses":[{"en":"used to describe products that protect your skin from strong sunlight","cn":"防晒霜：用于描述可保护皮肤免受强烈阳光照射的产品","ex":{"en":"suntan oil/lotion","cn":"防晒油/乳液"}},{"en":"the brown colour that somebody with pale skin goes when they have been in the sun","cn":"晒成棕褐肤色；晒成的棕褐色","ex":{"en":"Where have you been to get that suntan?","cn":"你上哪儿去了，晒得黑黑的？"},"pos":"noun"}]}},"substitution":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone or something is replaced by someone or something else, or the person or thing being replaced 〔","cn":"人或物的〕代替﹐替换﹔替代品﹐替代的人"}]},"vocab":{"pos":"n","senses":[{"en":"The noun substitution refers to the act of replacing one thing with another. Your football coach might make a substitution by sending you onto the field to take over for a player who is tired or injured."}]},"media":{"uk":"media/ldoce/hwd/bre/7/substitution0205.mp3","us":"media/ldoce/hwd/ame/1/laadsubstitution.mp3"},"examples":[{"en":"Coach Ross made two substitutions in the second half.","cn":"罗斯教练在下半场两次换人。"},{"en":"the substitution of English for French as the world’s common language","cn":"英语取代法语﹐成为世界通用语言"}],"oxford":{"phon":"ˌsʌbstɪˈtjuːʃn","pos":"noun","senses":[{"en":"an act of using one person or thing in the place of another","cn":"代替；取代","ex":{"en":"Two substitutions were made during the game.","cn":"比赛中换了两次人。"}}]}},"sunscreen":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"防晒霜;防晒油","en":"A sunscreen is a cream that protects your skin from the sun's rays, especially in hot weather."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cream or oil that you rub into your skin to stop the sun from burning you","cn":"防晒霜﹔防晒油"}]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdesunscreen.mp3","us":"media/ldoce/hwd/ame/6/laadsunscreen.mp3"},"examples":[{"en":"a high factor (= strong) sunscreen","cn":"防晒系数高的防晒霜"}],"oxford":{"phon":"ˈsʌnskriːn","pos":"noun","senses":[{"en":"a cream or liquid that you put on your skin to protect it from the harmful effects of the sun","cn":"防晒霜；防晒油","ex":{"en":"a high factor (= strong) sunscreen","cn":"防晒系数高的防晒霜"}}]}},"susceptibility":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"易受影响(或损害)的状况;敏感性;过敏性","en":"If you have a susceptibility to something unpleasant, you are likely to be affected by it.","ex":{"en":"...his increased susceptibility to infections.","cn":"他越来越容易受感染的体质"}},{"pos":"N-PLURAL 复数名词","cn":"感情脆弱之处;情感的要害","en":"A person's susceptibilities are feelings which can be easily hurt.","ex":{"en":"I am well aware that in saying this I shall outrage a few susceptibilities.","cn":"我十分清楚这样说会戳到一些人的痛处。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how easily someone or something is affected by something","cn":"敏感﹔易受影响﹔过敏性"},{"en":"someone’s feelings, especially when they are easily offended or upset","cn":"某人易受伤害的感情﹐某人的敏感心理"}]},"vocab":{"pos":"n","senses":[{"en":"Susceptibility is a tendency to be affected by something. Some people have a greater susceptibility to colds than others."}]},"media":{"uk":"media/ldoce/hwd/bre/5/susceptibility0205.mp3","us":"media/ldoce/hwd/ame/5/laadsusceptibility.mp3"},"examples":[{"en":"It was all carried out without any consideration for the susceptibilities of the bereaved family.","cn":"这样做全然没有考虑到死者家人的感受。"},{"en":"susceptibility to disease","cn":"易患病的体质"}],"oxford":{"phon":"səˌseptəˈbɪləti","pos":"noun","senses":[{"en":"the state of being very likely to be influenced, harmed or affected by something","cn":"易受影响（或伤害等）的特性；敏感性；过敏性","g":"[uncountable, singular]","ex":{"en":"susceptibility to disease","cn":"易患病的体质"}},{"en":"a person’s feelings that are likely to be easily hurt","cn":"感情脆弱处","g":"[plural]","ex":{"en":"It was all carried out without any consideration for the susceptibilities of the bereaved family.","cn":"这样做全然没有考虑到死者家人的感受。"}}]}},"subcontractor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分包人;分包公司","en":"A subcontractor is a person or firm that has a contract to do part of a job which another firm is responsible for.","ex":{"en":"The company was considered as a possible subcontractor to build the aeroplane.","cn":"该公司被视为能够承担该飞机制造任务的潜在分包商之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does part of the work of another person or company","cn":"分包者﹔分包商"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41subcontractor.mp3","us":"media/ldoce/hwd/ame/4/subcontractor.mp3"},"oxford":{"phon":"ˈsʌbkəntræktə(r)","pos":"noun","senses":[{"en":"a person or company that does part of the work given to another person or company","cn":"分包商；分包人","ex":{"en":"The prime contractor can take on several subcontractors.","cn":"总承包人可以雇用几个分包人。"}}]}},"subterranean":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(河流、隧道)地表下的，地下的","en":"A subterranean river or tunnel is under the ground.","ex":{"en":"London has 9 miles of such subterranean passages.","cn":"伦敦像这样的地下通道有9英里长。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"under - used in formal writing or in literature","cn":""},{"en":"under the ground","cn":""},{"en":"below the ground","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Subterranean is an adjective that describes something just below what can be seen, like the subterranean jealousy you hide under a smile and kind words for the actor who got the part you wanted."}]},"media":{"uk":"media/ldoce/hwd/bre/8/subterranean0205.mp3","us":"media/ldoce/hwd/ame/3/subterranean.mp3"},"examples":[{"en":"a subterranean cave","cn":"地下洞穴"},{"en":"subterranean passage","cn":"地下通道"}],"oxford":{"phon":"ˌsʌbtəˈreɪniən","pos":"adjective","senses":[{"en":"under the ground","cn":"地下的","ex":{"en":"a subterranean cave","cn":"地下洞穴"}}]}},"sundry":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"各式各样的;形色各异的;杂七杂八的","en":"If someone refers to sundry people or things, they are referring to several people or things that are all different from each other.","ex":{"en":"Scientists, business people, and sundry others gathered on Monday for the official opening","cn":"星期一的正式开幕式上,科学家、商界人士和其他各色人等齐聚一堂。"}},{"pos":"PHRASE 短语","cn":"所有人;各色人等","en":"All and sundry means everyone.","ex":{"en":"I made tea for all and sundry at the office","cn":"我给办公室的每个人冲了一杯茶。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"all the people in a group, or people in general. Everyone is slightly more formal than everybody","cn":""},{"en":"every person in a group","cn":""},{"en":"everyone in the world, town, office etc - use this to emphasize that everyone is included","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"A woman emptying out her purse after many years might find an old stick of gum, a pair of broken sunglasses, a few movie tickets, and sundry items, meaning that that her purse was filled with a random collection of unrelated things."}]},"media":{"uk":"media/ldoce/hwd/bre/0/sundry0205.mp3","us":"media/ldoce/hwd/ame/1/sundry.mp3"},"examples":[{"en":"a watch, a diary and sundry other items","cn":"一块手表、一本日记和其他一些零碎的东西"},{"en":"The club is open to all and sundry.","cn":"这个俱乐部什么人都可以加入。"}],"oxford":{"phon":"ˈsʌndri","pos":"adjective","senses":[{"en":"various; not important enough to be named separately","cn":"杂项的","ex":{"en":"a watch, a diary and sundry other items","cn":"一块手表、一本日记和其他一些零碎的东西"}}]}},"subpoena":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(传唤某人出庭作证的)传票","en":"A subpoena is a legal document telling someone that they must attend a court of law and give evidence as a witness.","ex":{"en":"He has been served with a subpoena to answer the charges in court.","cn":"他接到传票要出庭应诉。"}},{"pos":"VERB 动词","cn":"(以传票)传唤…出庭作证;要求当庭出示(证据)","en":"If someone subpoenas a person, they give them a legal document telling them to attend a court of law and give evidence. If someone subpoenas a piece of evidence, the evidence must be produced in a court of law.","ex":{"en":"Select committees have the power to subpoena witnesses","cn":"特别委员会有权传唤证人出庭作证。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to officially tell someone to do something, especially when you tell them exactly how it should be done","cn":""},{"en":"if someone such as a leader or officer gives orders or gives instructions , they tell other people exactly what they must do","cn":""},{"en":"if someone such as a leader or officer issues orders or issues instructions , they tell people exactly what they should do, especially by sending a written statement","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A subpoena is a document that requires its recipient to appear in court as a witness. If you receive a subpoena , it doesn't mean you've done anything wrong; it just means you may have information that's needed by the court."}]},"media":{"uk":"media/ldoce/hwd/bre/f/subpoena_v0205.mp3","us":"media/ldoce/hwd/ame/d/subpoena1.mp3"},"examples":[{"en":"The court subpoenaed her to appear as a witness.","cn":"法庭传唤她出庭作证。"},{"en":"James was subpoenaed as a witness.","cn":"詹姆斯被传唤出庭作证。"}],"oxford":{"phon":"səˈpiːnə","pos":"noun","senses":[{"en":"a written order to attend court as a witness to give evidence","cn":"（传唤证人出庭的）传票","ex":{"en":"He was served with a subpoena.","cn":"他被传唤出庭作证。"}},{"en":"to order somebody to attend court and give evidence as a witness","cn":"以传票传唤（证人出庭）","lab":"especially North American English","ex":{"en":"The court subpoenaed her to appear as a witness.","cn":"法庭传唤她出庭作证。"},"pos":"verb"}]}},"sue":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(通常为索赔而)控告，对…提起诉讼","en":"If you sue someone, you start a legal case against them, usually in order to claim money from them because they have harmed you in some way.","ex":{"en":"Mr Warren sued him for libel over the remarks","cn":"沃伦先生控告他散布诽谤性言论。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a legal claim against someone, especially for money, because they have harmed you in some way 〔","cn":"尤指为要求赔偿金而〕控告﹐起诉﹐告…的状"},{"en":"if a country or army sues for peace, they ask for peace, especially because there is no other good choice 〔","cn":"尤因别无选择而〕求和"}]},"vocab":{"pos":"v","senses":[{"en":"If you sue someone, you're accusing them (in court) of doing something wrong or illegal and demanding that they pay for it. Almost every time someone sues , they're looking for money."}]},"collocations":{"phrases":["ADV. successfully | unsuccessfully","VERB + SUE be able to, be entitled to, have the right to | threaten to","PREP. for He threatened to sue the company for negligence. | over The water authority was successfully sued over his illness."]},"media":{"uk":"media/ldoce/hwd/bre/4/sue0205.mp3","us":"media/ldoce/hwd/ame/f/sioux.mp3"},"examples":[{"en":"They threatened to sue if the work was not completed.","cn":"他们威胁说，如果不完成工作，就要提起诉讼。"},{"en":"to sue sb for $10 million (= in order to get money from sb)","cn":"控告某人要求得到 1 000 万元"}],"oxford":{"phon":"suː","pos":"verb","senses":[{"en":"to make a claim against a person or an organization in court about something that they have said or done to harm you","cn":"控告；提起诉讼","g":"[transitive, intransitive]","ex":{"en":"They threatened to sue if the work was not completed.","cn":"他们威胁说，如果不完成工作，就要提起诉讼。"}},{"en":"to formally ask for something, especially in court","cn":"（尤指在法庭上）提出请求","g":"[intransitive]","lab":"formal","ex":{"en":"to sue for divorce","cn":"起诉要求离婚"}},{"en":"a first name for girls, short for Susan, Susanna or Suzanne","cn":"休（女子名，Susan、Susanna 或 Suzanne 缩写）","pos":""}]}},"sugarcane":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a tall tropical plant from whose stems sugar is obtained","cn":"甘蔗"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41sugarcane.mp3","us":"media/ldoce/hwd/ame/d/ld41sugarcane.mp3"}},"superstructure":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(船舶主甲板上方的)上层构造，上层结构","en":"The superstructure of a ship is the part of it that is above its main deck.","ex":{"en":"We might try to clear up some of the cabins in the superstructure.","cn":"我们可以设法清理出主甲板之上的一些船舱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a structure that is built on top of the main part of something such as a ship or building 〔","cn":"船﹑建筑物等的〕上部结构﹐上部[层]建筑"},{"en":"a political or social system that has developed from a simpler system 〔","cn":"政治或社会制度的〕上层建筑"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41superstructure.mp3","us":"media/ldoce/hwd/ame/6/superstructure.mp3"},"examples":[{"en":"the whole superstructure of capitalism","cn":"资本主义的整个上层建筑"}],"oxford":{"phon":"ˈsuːpəstrʌktʃə(r)","pos":"noun","senses":[{"en":"a structure that is built on top of something, for example the upper parts of a ship or the part of a building above the ground","cn":"（船舶的）上层建筑，船楼；（建筑物的）上部结构"},{"en":"the systems and beliefs in a society that have developed from more simple ones","cn":"（社会的）上层建筑","lab":"formal","ex":{"en":"the relationship between the economic base of society and the political superstructure of power","cn":"社会经济基础与权力政治上层建筑之间的关系"}}]}},"superman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超人;有非凡才能的人;体能超群的人","en":"A superman is a man who has very great physical or mental abilities.","ex":{"en":"Collor nurtured the idea that he was a superman, who single-handedly could resolve Brazil's crisis.","cn":"科洛尔一直希望自己有超凡能力，凭一己之力就能解决巴西的危机。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man of unusually great ability or strength","cn":"超人〔具有超常能力或力量的人〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41superman.mp3","us":"media/ldoce/hwd/ame/0/superman1.mp3"},"oxford":{"phon":"ˈsuːpəmæn","pos":"noun","senses":[{"en":"a man who is unusually strong or intelligent or who can do something extremely well","cn":"有非凡才能的人；超人"},{"en":"the best-known superhero of US comic books. He was created by the writer Jerry Siegel (1914-1996) and the artist Joseph Shuster (1914-1992), and first appeared in 1938 in Action Comics.","cn":"超人™：美国漫画最著名的超级英雄。他由作家Jerry Siegel（1914-1996）和艺术家Joseph Shuster（1914-1992）创建，并于1938年首次出现在动作漫画中。文化","pos":""}]}},"suspiciously":{"collins":{"senses":[{"pos":"ADV 副词","cn":"非常，相当(相似)","en":"If you say that one thing looks or sounds suspiciously like another thing, you mean that it probably is that thing, or something very similar to it, although it may be intended to seem different.","ex":{"en":"The tan-coloured dog looks suspiciously like an American pit bull terrier","cn":"这只棕黄色的狗看上去非常像美国比特犬。"}},{"pos":"ADV 副词","cn":"奇怪地;出乎意料地","en":"You can use suspiciously when you are describing something that you think is slightly strange or not as it should be.","ex":{"en":"He lives alone in a suspiciously tidy flat in Notting Hill Gate","cn":"他一个人住在诺丁山门的一套整洁干净得出奇的公寓里。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in a way that shows you think someone has done something wrong or dishonest","cn":"怀疑地﹐猜疑地"},{"en":"in a way that makes people think that something bad or illegal is happening","cn":"可疑地﹐令人怀疑地"},{"en":"in a way that shows you do not trust something or someone","cn":"不信任地"}]},"media":{"uk":"media/ldoce/hwd/bre/6/suspiciously0205.mp3","us":"media/ldoce/hwd/ame/f/laadsuspiciously.mp3"},"examples":[{"en":"Their latest single sounds suspiciously like the last one.","cn":"他们的最新单曲唱片听着和前一张很像。"},{"en":"Let me know if you see anyone acting suspiciously.","cn":"如发现有人形迹可疑，你就告诉我。"}],"oxford":{"phon":"səˈspɪʃəsli","pos":"adverb","senses":[{"en":"in a way that shows you think somebody has done something wrong, illegal or dishonest","cn":"怀疑地；有疑心地","ex":{"en":"The man looked at her suspiciously.","cn":"那个男人以狐疑的目光看着她。"}},{"en":"in a way that makes people think something wrong, illegal or dishonest is happening","cn":"令人怀疑地；形迹（或神色等）可疑地","ex":{"en":"Let me know if you see anyone acting suspiciously.","cn":"如发现有人形迹可疑，你就告诉我。"}},{"en":"in a way that shows you think there may be something wrong with something","cn":"以怀疑的态度；不信任地","ex":{"en":"She eyed the fish on her plate suspiciously.","cn":"她不放心地看着自己盘子里的鱼。"}}]}},"subculture":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"亚文化(模式)","en":"A subculture is the ideas, art, and way of life of a group of people within a society, which are different from the ideas, art, and way of life of the rest of the society.","ex":{"en":"...the latest American subculture.","cn":"最近的美国亚文化"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a particular group of people within a society and their behaviour, beliefs, and activities – often used to show disapproval","cn":"亚文化群﹔亚文化〔常含贬义〕"}]},"vocab":{"pos":"n","senses":[{"en":"A subculture is a group of people within a larger culture, such as a country, who have something in common. They might share religious or political beliefs or be science fiction fans, for example."}]},"media":{"uk":"media/ldoce/hwd/bre/8/subculture0205.mp3","us":"media/ldoce/hwd/ame/e/subculture.mp3"},"examples":[{"en":"the criminal/drug/youth, etc. subculture","cn":"犯罪、吸毒、青少年群体等的亚文化"},{"en":"the drug subculture of the inner city","cn":"旧城区的吸毒亚文化群"}],"oxford":{"phon":"ˈsʌbkʌltʃə(r)","pos":"noun","senses":[{"en":"the behaviour and beliefs of a particular group of people in society that are different from those of most people","cn":"（某群体特有的）亚文化行为观念，次文化","ex":{"en":"the criminal/drug/youth subculture","cn":"犯罪／吸毒／青少年群体的亚文化"}}]}},"suet":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(动物身上的)硬脂肪油，板油","en":"Suet is hard animal fat that is used in cooking.","ex":{"en":"...suet pudding.","cn":"脂油布丁"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"hard fat from around an animal’s kidney s , used in cooking in Britain 〔","cn":"动物腰部的〕板油﹐硬脂肪油〔在英国用于烹调〕"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41suet.mp3","us":"media/ldoce/hwd/ame/a/suet.mp3"},"examples":[{"en":"suet pudding (= one made using suet )","cn":"脂油布丁"}],"oxford":{"phon":"ˈsuːɪt","pos":"noun","senses":[{"en":"hard fat from around the kidneys of cows, sheep, etc., used in cooking","cn":"（牛、羊等肾周围的）板油","ex":{"en":"suet pudding (= one made using suet)","cn":"脂油布丁"}}]}},"sump":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(发动机下面的)集油槽，油底壳","en":"The sump is the place under an engine which holds the engine oil."},{"pos":"N-COUNT 可数名词","cn":"污水坑;集水坑","en":"A sump is a deep cave which is often filled with water.","ex":{"en":"An attempt was then made to dive the sump.","cn":"之后曾尝试潜入污水坑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the lowest part of a drainage system, where liquids or wastes remain 〔","cn":"排水系统的〕集液池﹐污水坑"},{"en":"the part of an engine that contains the supply of oil 〔","cn":"发动机的〕油盘﹐集油槽"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41sump.mp3","us":"media/ldoce/hwd/ame/2/sump.mp3"},"oxford":{"phon":"sʌmp","pos":"noun","senses":[{"en":"a hole or hollow area in which liquid waste collects","cn":"集水坑；污水池"},{"en":"the place under an engine that holds the engine oil","cn":"（发动机下面的）集油槽，油底壳","lab":"North American English also"}]}},"sulphide":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"硫化物","en":"A sulphide is a compound of sulphur with some other chemical elements.","ex":{"en":"...hydrogen sulphide.","cn":"硫化氢"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a mixture of sulphur with another substance","cn":"硫化物"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sulphide.mp3","us":"media/ldoce/hwd/ame/d/laadsulphide.mp3"},"oxford":{"phon":"ˈsʌlfaɪd","pos":"noun","senses":[{"en":"a compound of sulphur and another chemical element","cn":"硫化物"}]}},"summery":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"夏季的;适合夏季的;夏季特有的","en":"Something that is summery is suitable for summer or characteristic of summer.","ex":{"en":"It's very flowery and summery.","cn":"那里繁花似锦，很有夏季的气息。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"suitable for or reminding you of the summer","cn":"适合夏季的﹔像夏季的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41summery.mp3","us":"media/ldoce/hwd/ame/4/summery.mp3"},"examples":[{"en":"a light summery dress","cn":"夏天穿的薄连衣裙"},{"en":"summery weather","cn":"夏日的天气"}],"oxford":{"phon":"ˈsʌməri","pos":"adjective","senses":[{"en":"typical of or suitable for the summer","cn":"夏季的；夏季特有的；适合夏季的","ex":{"en":"summery weather","cn":"夏日的天气"}}]}},"surrender":{"collins":{"senses":[{"pos":"VERB 动词","cn":"投降;屈服","en":"If you surrender, you stop fighting or resisting someone and agree that you have been beaten.","ex":{"en":"General Martin Bonnet called on the rebels to surrender","cn":"马丁·邦尼特将军呼吁反叛者投降。"}},{"pos":"VERB 动词","cn":"(被迫)放弃，交出","en":"If you surrender something you would rather keep, you give it up or let someone else have it, for example after a struggle.","ex":{"en":"Nadja had to fill out forms surrendering all rights to her property","cn":"纳佳不得不填表放弃其全部财产所有权。"}},{"pos":"VERB 动词","cn":"交出，出示(票证、护照等)","en":"If you surrender something such as a ticket or your passport, you give it to someone in authority when they ask you to.","ex":{"en":"They have been ordered to surrender their passports.","cn":"他们被要求出示护照。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"屈服;屈从","en":"You use surrender to refer to someone's attitude or behaviour when they lose the will to resist their feelings or the demands of other people.","ex":{"en":"...the need for total personal surrender to and dependence on Jesus","cn":"需要完全顺从并依靠耶稣"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say officially that you want to stop fighting, especially in a war, because you realize that you cannot win – used about people and countries","cn":""},{"en":"to accept that you cannot win a game, argument, fight etc and stop trying to win it","cn":""},{"en":"to accept that you have not won something","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To surrender is to give up control of something to someone else. If you miss curfew, your parents might make you surrender the keys to the car. Okay, it's only a minivan, but it's still cooler than being on foot patrol."}]},"collocations":{"phrases":["ADV. completely After three weeks under siege they surrendered completely. | immediately | eventually, finally | formally The British formal","VERB + SURRENDER order sb to They were ordered to surrender their weapons to the police. | agree to They agreed to surrender their claim to ","PREP. to He surrendered voluntarily to his enemies. The dictator surrendered power to Parliament."]},"media":{"uk":"media/ldoce/hwd/bre/e/brelasdesurrender.mp3","us":"media/ldoce/hwd/ame/6/surrender1.mp3"},"examples":[{"en":"He agreed to surrender all claims to the property.","cn":"他同意放弃对那笔财产的一切权利要求。"},{"en":"The defendant was released to await trial but had to surrender her passport.","cn":"被告被释放候审，但须交出护照。"}],"oxford":{"phon":"səˈrendə(r)","pos":"verb","senses":[{"en":"to admit that you have been defeated and want to stop fighting; to allow yourself to be caught, taken prisoner, etc.","cn":"投降","g":"[intransitive, transitive]","ex":{"en":"The rebel soldiers were forced to surrender.","cn":"叛军被迫投降。"}},{"en":"to give up something/somebody when you are forced to","cn":"（被迫）放弃，交出","lab":"formal","ex":{"en":"He agreed to surrender all claims to the property.","cn":"他同意放弃对那笔财产的一切权利要求。"}},{"en":"an act of admitting that you have been defeated and want to stop fighting","cn":"投降","ex":{"en":"They demanded (an) unconditional surrender.","cn":"他们要求无条件投降。"},"pos":"noun"},{"en":"the fact of allowing yourself to be controlled by something","cn":"屈服；屈从","ex":{"en":"They accused the government of a surrender to business interests.","cn":"他们指责政府唯商界利益是从。"},"pos":"noun"},{"en":"an act of giving something to somebody else even though you do not want to, especially after a battle, etc.","cn":"（尤指在战争等过后）放弃，交出","ex":{"en":"They insisted on the immediate surrender of all weapons.","cn":"他们坚持要求立即交出全部武器。"},"pos":"noun"}]}},"supposition":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"假定;假设;设想","en":"A supposition is an idea or statement which someone believes or assumes to be true, although they may have no evidence for it.","ex":{"en":"There's a popular supposition that we're publicly funded but the bulk of our money comes from competitive contracts","cn":"人们普遍认为我们是受公共基金的资助，然而我们大部分资金是通过签订竞争性合同得来的。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"毫无根据的想法;无稽之谈","en":"You can describe someone's ideas or statements as supposition if you disapprove of the fact that they have no evidence to support them.","ex":{"en":"The report has been rejected by the authorities, who said much of it was based on supposition or inaccuracy.","cn":"当局驳回了该报告，称其许多内容有的纯属臆测，有的存在偏差错误。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that you think is true, even though you are not certain and cannot prove it","cn":"假定﹔推测﹔猜测"}]},"vocab":{"pos":"n","senses":[{"en":"A supposition is a guess or a hypothesis. Your supposition that your kids will automatically wash their hands before dinner is probably false. You'd best remind them to do it or risk dirty hands at dinner."}]},"collocations":{"phrases":["ADJ. mere, pure That is mere supposition! | reasonable It is a reasonable supposition that many mothers would welcome the offer of part-time","VERB + SUPPOSITION make, work on Let's work on the supposition that she meant no offence. | be based on | confirm, support | be correct in Y","SUPPOSITION + VERB be based on sth","PREP. on (a/the) ~ She was charged on the supposition that she had colluded with her husband in the murders. | ~ about They are making all s"]},"media":{"uk":"media/ldoce/hwd/bre/6/supposition0205.mp3","us":"media/ldoce/hwd/ame/2/supposition.mp3"},"examples":[{"en":"The police are working on the supposition that he was murdered.","cn":"警方正根据他被谋杀的假定展开调查。"},{"en":"The report is based entirely on supposition.","cn":"这篇报道完全建立在推测的基础上。"}],"oxford":{"phon":"ˌsʌpəˈzɪʃn","pos":"noun","senses":[{"en":"an idea that you think is true although you may not be able to prove it","cn":"推测的想法；推断的结论","g":"[countable]","ex":{"en":"The police are working on the supposition that he was murdered.","cn":"警方正根据他被谋杀的假定展开调查。"}},{"en":"the act of believing or claiming that something is true even though it cannot be proved","cn":"推测；推断","g":"[uncountable]","ex":{"en":"The report is based entirely on supposition.","cn":"这篇报道完全建立在推测的基础上。"}}]}},"suspect":{"collins":{"senses":[{"pos":"VERB 动词","cn":"猜想;觉得","en":"You use suspect when you are stating something that you believe is probably true, in order to make it sound less strong or direct.","ex":{"en":"I suspect they were right","cn":"我感觉他们是对的。"}},{"pos":"VERB 动词","cn":"怀疑;疑心","en":"If you suspect that something dishonest or unpleasant has been done, you believe that it has probably been done. If you suspect someone of doing an action of this kind, you believe that they probably did it.","ex":{"en":"He suspected that the woman staying in the flat above was using heroin","cn":"他怀疑楼上公寓里的那个女人正在吸食海洛因。"}},{"pos":"N-COUNT 可数名词","cn":"嫌疑犯;可疑分子","en":"A suspect is a person who the police or authorities think may be guilty of a crime.","ex":{"en":"Police have arrested a suspect in a series of killings and sexual assaults in the city.","cn":"警察已经逮捕了一名涉嫌在该市犯下一系列杀人及强奸案的嫌疑犯。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可靠的;不可信的;可能有假的;可疑的","en":"Suspect things or people are ones that you think may be dangerous or may be less good or genuine than they appear.","ex":{"en":"Delegates evacuated the building when a suspect package was found","cn":"发现可疑包裹后，代表们撤离了这座楼。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think that someone is probably guilty of something illegal or dishonest","cn":""},{"en":"thinking that someone might be guilty of doing something wrong or dishonest, without being sure","cn":""},{"en":"a feeling that someone is probably guilty of doing something wrong or dishonest","cn":""}]},"vocab":{"pos":"v n adj","senses":[{"en":"A suspect is a person who is believed to be guilty of a crime. If you leave the scene of a murder with blood on your hands and a weapon in your pocket, you’re likely to become a prime suspect ."}]},"collocations":{"phrases":["ADJ. chief, main, number one, prime She has been identified as the prime suspect. | likely, obvious, possible, potential | usual | murder, t","VERB + SUSPECT have, identify (sb as) The police have several suspects. | arrest, detain, hold, round up The army rounded up all the usual t","PREP. ~ for The letter makes him a possible suspect for her murder. | ~ in Two men were arrested as suspects in the bombing."]},"media":{"uk":"media/ldoce/hwd/bre/b/suspect_v0205.mp3","us":"media/ldoce/hwd/ame/f/l3suspect.mp3"},"examples":[{"en":"If you suspect a gas leak, do not strike a match or even turn on an electric light.","cn":"假如你怀疑有煤气泄漏，不要划火柴，甚至连电灯都不要开。"},{"en":"The drug is suspected of causing over 200 deaths.","cn":"人们怀疑这种药物造成 200 多人死亡。"}],"oxford":{"phon":"səˈspekt","pos":"verb","senses":[{"en":"to have an idea that something is probably true or likely to happen, especially something bad, but without having definite proof","cn":"疑有，觉得（尤指坏事可能属实或发生）","g":"[transitive, intransitive]","ex":{"en":"As I had suspected all along, he was not a real policeman.","cn":"他并不是真的警察，我一直就觉得不像。"}},{"en":"to have an idea that somebody is guilty of something, without having definite proof","cn":"怀疑（某人有罪）","g":"[transitive]","ex":{"en":"He resigned after being suspected of theft.","cn":"他被怀疑偷窃，随后就辞职了。"}},{"en":"to feel that something is not completely right, legal or honest, without having any proof; to not trust something","cn":"怀疑；感觉…有问题；不信任","g":"[transitive]","ex":{"en":"I suspected her motives in offering to help.","cn":"她主动要帮忙，我怀疑她的动机。"}},{"en":"a person who is suspected of a crime or of having done something wrong","cn":"嫌疑犯；嫌疑分子；可疑对象","ex":{"en":"a murder suspect","cn":"杀人嫌疑犯"},"pos":"noun"},{"en":"that may be false and that cannot be relied on","cn":"不可信的；靠不住的","ex":{"en":"Some of the evidence they produced was highly suspect.","cn":"他们出示的证据中有些相当成问题。"},"pos":"adjective"},{"en":"that you suspect to be dangerous or illegal","cn":"可疑的；可能有危险的；有违法嫌疑的","ex":{"en":"a suspect package (= one that may contain drugs, a bomb, etc.)","cn":"可疑包裹"},"pos":"adjective"}]}},"surrealistic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"同 surreal","en":"Surrealistic means the same as surreal .","ex":{"en":"...the surrealistic way the movie plays with time.","cn":"影片运用超现实主义手法来戏谑、把玩时间"}},{"pos":"ADJ 形容词","cn":"(方法)超现实主义的","en":"Surrealistic means related to or in the style of surrealism.","ex":{"en":"...Man Ray's surrealistic study of a woman's face with glass teardrops.","cn":"曼·雷运用超现实主义手法以几颗玻璃珠来代替眼泪拍摄出的一张流泪女性的脸"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"seeming very strange because of a combination of many unusual unrelated events, images etc","cn":"梦幻般的﹔离奇的﹔超现实的"},{"en":"relating to surrealism","cn":"超现实主义的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41surrealistic.mp3","us":"media/ldoce/hwd/ame/2/surrealistic.mp3"},"examples":[{"en":"a surrealistic painting","cn":"超现实主义绘画"}],"oxford":{"phon":"səˌriːəˈlɪstɪk","pos":"adjective","senses":[{"en":"very strange; more like a dream than reality, with ideas and images mixed together in a strange way","cn":"离奇的；怪诞的；梦幻般的；超现实的","lab":"more frequent"},{"en":"connected with surrealism","cn":"超现实主义的","ex":{"en":"a surrealistic painting","cn":"超现实主义绘画"}}]}},"supersonic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"超音速的;超声速的","en":"Supersonic aircraft travel faster than the speed of sound.","ex":{"en":"There was a huge bang; it sounded like a supersonic jet.","cn":"传来一声巨响，听起来像是超音速喷气式飞机的声音。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a train, computer etc that moves or operates very fast","cn":""},{"en":"faster than the speed of sound","cn":"超音速的"},{"en":"faster than the speed of sound","cn":"超音速的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"It’s faster than the speed of sound, it’s supersonic ! Seriously. Supersonic describes things that can travel faster than the speed of sound, like the passenger jet Concorde that used to zip from New York to London in under four hours."}]},"media":{"uk":"media/ldoce/hwd/bre/f/supersonic0205.mp3","us":"media/ldoce/hwd/ame/0/supersonic.mp3"},"examples":[{"en":"a supersonic aircraft","cn":"超音速飞机"},{"en":"supersonic flight","cn":"超声速飞行"}],"oxford":{"phon":"ˌsuːpəˈsɒnɪk","pos":"adjective","senses":[{"en":"faster than the speed of sound","cn":"超声速的；超音速的","ex":{"en":"a supersonic aircraft","cn":"超声速飞机"}}]}},"subsume":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…归入，将…纳入(更大的组织或范畴)","en":"If something is subsumed within a larger group or class, it is included within it, rather than being considered as something separate.","ex":{"en":"After that the two alliances might be subsumed into a new European security system","cn":"从那以后，这两个联盟将可能会被纳入一个新的欧洲安全体系之中。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to include someone or something as a member of a group or type, rather than considering it separately","cn":"把…归入[纳入]某一类"}]},"vocab":{"pos":"v","senses":[{"en":"Subsume means to absorb or include. A successful company might subsume a failing competitor through a merger, or love may subsume you in the early stages of a romance."}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41subsume.mp3","us":"media/ldoce/hwd/ame/9/subsume.mp3"},"examples":[{"en":"All these different ideas can be subsumed under just two broad categories.","cn":"所有这些不同的想法可归为两大类。"},{"en":"A wide range of offences are usually subsumed under the category of robbery.","cn":"很多犯罪行为通常都被归入抢劫罪的范畴。"}],"oxford":{"phon":"səbˈsjuːm","pos":"verb","senses":[{"en":"to include something in a particular group and not consider it separately","cn":"将…归入（或纳入）","ex":{"en":"All these different ideas can be subsumed under just two broad categories.","cn":"所有这些不同的想法可归为两大类。"}}]}},"superhighway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(超级)高速公路","en":"A superhighway is a large, fast motorway or freeway with several lanes.","ex":{"en":"He took off for the city on the eight-lane superhighway.","cn":"他沿着八车道的高速公路向城市驶去。"}},{"pos":"N-COUNT 可数名词","cn":"信息高速公路","en":"The information superhighway is the network of computer links that enables computer users all over the world to communicate with each other.","ex":{"en":"...a superhighway using digital and fibre-optic technology to provide new telecommunications links.","cn":"运用数字和光纤技术提供新的电信连接的信息高速公路"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large road on which you can drive fast for long distances （","cn":"超级）高速公路"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41superhighway.mp3","us":"media/ldoce/hwd/ame/1/superhighway.mp3"},"oxford":{"phon":"ˌsuːpəˈhaɪweɪ","pos":"noun","senses":[{"en":"an interstate (= in the US, a wide road, with at least two lanes in each direction, where traffic can travel fast for long distances across many states. You can only enter and leave the road at special ramps.)","cn":"高速公路：州际公路（在美国，=一条宽阔的道路，在每个方向上至少有两条车道，在许多州，交通可以快速长距离行驶。您只能在特殊的匝道上进出道路。）"}]}},"substandard":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不够标准的;不合格的;差劲的;劣质的","en":"A sub-standard service or product is unacceptable because it is below a required standard.","ex":{"en":"Residents in general are poor and undereducated, and live in sub-standard housing.","cn":"居民们普遍都很贫穷，受教育程度低，居住条件较差。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not good enough and likely to cause problems or make people unhappy","cn":""},{"en":"not good enough for a particular purpose or for what someone needs","cn":""},{"en":"if someone's performance, work, or products are not up to scratch , they are not of the standard that is necessary or expected","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something substandard is below standard — it’s shoddy or inferior. If your final paper for honors English class is scribbled on a torn sheet of notebook paper, that’s substandard work that you’ll probably have to do over."}]},"media":{"uk":"media/ldoce/hwd/bre/0/substandard0205.mp3","us":"media/ldoce/hwd/ame/e/substandard.mp3"},"examples":[{"en":"substandard goods","cn":"次货"},{"en":"substandard housing","cn":"低于标准的住宅"}],"oxford":{"phon":"ˌsʌbˈstændəd","pos":"adjective","senses":[{"en":"not as good as normal; not acceptable","cn":"不达标的；不合格的","ex":{"en":"substandard goods","cn":"次货"}}]}},"subjugate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指在战争中)征服，制服，使屈服","en":"If someone subjugates a group of people, they take complete control of them, especially by defeating them in a war.","ex":{"en":"Their costly and futile attempt to subjugate the Afghans lasted just 10 years.","cn":"他们大动干戈想要控制阿富汗地区，但只持续了10年就无果而终了。"}},{"pos":"VERB 动词","cn":"使(愿望、渴望)退居其次;使让位于","en":"If your wishes or desires are subjugated to something, they are treated as less important than that thing.","ex":{"en":"After having been subjugated to ambition, your maternal instincts are at last starting to assert themselves.","cn":"你那被雄心壮志压制已久的母性本能终于开始展现出来。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to defeat a person or group and make them obey you","cn":"使屈服﹐征服﹐降伏"}]},"vocab":{"pos":"v","senses":[{"en":"If you say you won't be kept down by the man, you are saying that you won't let the man subjugate you. To subjugate is to repress someone, or to make them subservient to you."}]},"media":{"uk":"media/ldoce/hwd/bre/6/subjugate0205.mp3","us":"media/ldoce/hwd/ame/4/subjugate.mp3"},"examples":[{"en":"Her personal ambitions had been subjugated to (= considered less important than) the needs of her family.","cn":"她个人的雄心壮志让位给了家庭的需要。"},{"en":"( formal ) the subjugation of Ireland by England","cn":"英格兰对爱尔兰的征服"}],"oxford":{"phon":"ˈsʌbdʒuɡeɪt","pos":"verb","senses":[{"en":"to defeat somebody/something; to gain control over somebody/something","cn":"征服；制伏；使屈服；使服从","ex":{"en":"Her personal ambitions had been subjugated to (= considered less important than) the needs of her family.","cn":"她个人的雄心壮志让位给了家庭的需要。"}}]}},"supplier":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"供应者;供应商;供货方","en":"A supplier is a person, company, or organization that sells or supplies something such as goods or equipment to customers.","ex":{"en":"...Hillsdown Holdings, one of the UK's biggest food suppliers","cn":"希尔斯顿控股公司，英国最大的食品供应商之一"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a company or country that supplies things to people","cn":""},{"en":"a company or organization that provides a service for customers","cn":""},{"en":"a company or person that provides a particular product","cn":"供应商"}]},"collocations":{"phrases":["ADJ. big, largest, leading, main, major, principal | small | sole | reliable | external, foreign, outside, overseas | local | independent | ","PREP. ~ to the leading arms supplier to the rebel forces"]},"media":{"uk":"media/ldoce/hwd/bre/e/supplier0205.mp3","us":"media/ldoce/hwd/ame/b/supplier.mp3"},"examples":[{"en":"a leading supplier of computers in the UK","cn":"英国一家主要电脑供应商"},{"en":"the UK’s largest supplier of office equipment","cn":"英国最大的办公设备供应商"}],"oxford":{"phon":"səˈplaɪə(r)","pos":"noun","senses":[{"en":"a person or company that supplies goods","cn":"供应者；供货商；供货方","ex":{"en":"a leading supplier of computers in the UK","cn":"英国一家主要电脑供应商"}}]}},"sulk":{"collins":{"senses":[{"pos":"VERB 动词","cn":"生闷气;面有愠色;闷闷不乐","en":"If you sulk, you are silent and bad-tempered for a while because you are annoyed about something.","ex":{"en":"He turned his back and sulked.","cn":"他转过身去，面带愠色。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"someone who is sullen behaves in a bad-tempered, unfriendly way and does not smile or talk much to people","cn":""},{"en":"someone who is sulky has an angry, unhappy look on their face and does not talk much, especially because they think they have been treated unfairly","cn":""},{"en":"if someone sulks , they are deliberately silent and bad-tempered for a period of time, because something has annoyed them, or because they think that they have been treated unfairly","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When you are displeased by something and you let your gloomy mood show, you're sulking . Do you want to bake another cake, or are you going to sulk all day about the one you dropped?"}]},"media":{"uk":"media/ldoce/hwd/bre/f/sulk_v0205.mp3","us":"media/ldoce/hwd/ame/f/sulk.mp3"},"examples":[{"en":"He went off to sulk in his room.","cn":"他回到自己的房间，生起闷气来。"},{"en":"Jo was in a sulk upstairs.","cn":"乔在楼上生闷气。"}],"oxford":{"phon":"sʌlk","pos":"verb","senses":[{"en":"to look angry and refuse to speak or smile because you want people to know that you are upset about something","cn":"面有愠色；生闷气","ex":{"en":"He went off to sulk in his room.","cn":"他回到自己的房间，生起闷气来。"}},{"en":"a period of not speaking and being unpleasant because you are angry about something","cn":"生闷气","ex":{"en":"Jo was in a sulk upstairs.","cn":"乔在楼上生闷气。"},"pos":"noun"}]}},"sunup":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"日出(时分)","en":"Sun-up is the time of day when the sun rises.","ex":{"en":"We worked from sunup to sunset.","cn":"我们从日出工作到日落。"}}]},"oxford":{"phon":"ˈsʌnʌp","pos":"noun","senses":[{"en":"the time when the sun rises and day begins","cn":"日出"}]}},"sulky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"面有愠色的;生闷气的;闷闷不乐的","en":"Someone who is sulky is sulking or is unwilling to enjoy themselves.","ex":{"en":"I was quite sulky, so I didn't take part in much.","cn":"我很烦，所以没有积极参与。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is sullen behaves in a bad-tempered, unfriendly way and does not smile or talk much to people","cn":""},{"en":"someone who is sulky has an angry, unhappy look on their face and does not talk much, especially because they think they have been treated unfairly","cn":""},{"en":"if someone sulks , they are deliberately silent and bad-tempered for a period of time, because something has annoyed them, or because they think that they have been treated unfairly","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"Someone who's sulky is gloomy, or quietly unhappy. A sulky teenager is generally not a lot of fun at a family party."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41sulky.mp3","us":"media/ldoce/hwd/ame/a/sulky1.mp3"},"examples":[{"en":"Sarah had looked sulky all morning.","cn":"萨拉一上午都不高兴地板着脸。"},{"en":"a sulky child","cn":"闷闷不乐的孩子"}],"oxford":{"phon":"ˈsʌlki","pos":"adjective","senses":[{"en":"in a bad mood or not speaking because you are angry about something","cn":"面有愠色的；生闷气的","ex":{"en":"Sarah had looked sulky all morning.","cn":"萨拉一上午都不高兴地板着脸。"}}]}},"sure-footed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人、动物)脚步稳的，不会摔倒的","en":"A person or animal that is sure-footed can move easily over steep or uneven ground without falling.","ex":{"en":"My horse is small but wiry and sure-footed.","cn":"我的马虽矮小，但精瘦结实，走路稳当。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉着的;稳健的","en":"If someone is sure-footed, they are confident in what they are doing.","ex":{"en":"The Labour Party was growing increasingly sure-footed.","cn":"工党的信心日益增强。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"able to walk without sliding or falling, in a place where it is not easy to do this","cn":"步履稳健的"},{"en":"skilful and confident and not making any mistakes","cn":"自信稳健的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41surefooted.mp3","us":"media/ldoce/hwd/ame/5/laadsure-footed.mp3"},"examples":[{"en":"The hill ponies are very sure-footed.","cn":"这些山地小型马脚步非常稳健。"},{"en":"We need a sure-footed government which understands the nature of the economic challenges we face.","cn":"我们需要自信稳健的政府，一个洞悉我们所面临的经济挑战的本质的政府。"}],"oxford":{"phon":"ˌʃʊə ˈfʊtɪd","pos":"adjective","senses":[{"en":"not likely to fall when walking or climbing on rough ground","cn":"脚步稳的；不会摔倒的"},{"en":"confident and unlikely to make mistakes, especially in difficult situations","cn":"沉着的；稳健的"}]}},"superbug":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超级病菌(新闻用语，指无法用抗生素杀死的细菌)","en":"Journalists refer to a type of bacteria as a superbug when it is very difficult to deal with because it cannot be killed by antibiotics."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of bacteria that cannot be killed by traditional drugs 〔","cn":"不能用传统药物消灭的〕超级病菌"}]},"media":{"uk":"media/ldoce/hwd/bre/7/superbug0205.mp3","us":"media/ldoce/hwd/ame/8/ld41superbug.mp3"},"oxford":{"phon":"ˈsuːpəbʌɡ","pos":"noun","senses":[{"en":"a type of bacteria that cannot easily be killed by antibiotics","cn":"超级细菌（抗生素不能轻易将其杀死）"}]}},"subsidize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"资助;补助;给…发津贴","en":"If a government or other authority subsidizes something, they pay part of the cost of it.","ex":{"en":"Around the world, governments have subsidized the housing of middle and upper-income groups","cn":"全世界各国政府都为中高收入群体提供过住房补贴。"}},{"pos":"VERB 动词","cn":"(政府)资助，出资支持","en":"If a government subsidizes an industry, they provide money so that the industry can continue.","ex":{"en":"The government continues to subsidize the production of eggs and beef.","cn":"政府继续出资扶持鸡蛋和牛肉的生产。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a government or other organization subsidizes something, it pays part of the cost","cn":""},{"en":"if a company sponsors something such as sports event, a theatre, or an art show, it provides some of the money that is needed, often as a form of advertising","cn":""},{"en":"to provide all the money needed to pay for something, especially an important or expensive plan","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To subsidize something is to support it by providing it with money or other resources. Don't expect your parents to subsidize your addiction to solid-gold puppy figurines."}]},"collocations":{"phrases":["PHRASES heavily/highly subsidized The airline is heavily subsidized by the government."]},"media":{"uk":"media/ldoce/hwd/bre/3/subsidize0205.mp3","us":"media/ldoce/hwd/ame/b/subsidize.mp3"},"examples":[{"en":"The housing projects are subsidized by the government.","cn":"这些住房项目得到政府的补贴。"},{"en":"She's not prepared to subsidize his gambling any longer.","cn":"她再不愿意拿钱供他去赌博了。"}],"oxford":{"phon":"ˈsʌbsɪdaɪz","pos":"verb","senses":[{"en":"to give money to somebody or an organization to help pay for something; to give a subsidy","cn":"资助；补助；给…发津贴","ex":{"en":"The housing projects are subsidized by the government.","cn":"这些住房项目得到政府的补贴。"}}]}},"sunrise":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"日出(时分);黎明;拂晓","en":"Sunrise is the time in the morning when the sun first appears in the sky.","ex":{"en":"The rain began before sunrise.","cn":"日出前下起了雨。"}},{"pos":"N-COUNT 可数名词","cn":"朝霞;晨曦","en":"A sunrise is the colours and light that you see in the eastern part of the sky when the sun first appears.","ex":{"en":"There was a spectacular sunrise yesterday.","cn":"昨天的朝霞很绚烂。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the time when the sun first appears in the morning","cn":"日出（时分）﹔黎明﹔拂晓"},{"en":"the coloured part of the sky where the sun is appearing in the morning","cn":"日出﹔晨曦﹐朝霞"}]},"media":{"uk":"media/ldoce/hwd/bre/2/sunrise0205.mp3","us":"media/ldoce/hwd/ame/b/sunrise.mp3"},"examples":[{"en":"the pinks and yellows of the sunrise","cn":"一道道粉红和金黄的朝霞"},{"en":"We got up at sunrise.","cn":"我们在日出时起床。"}],"oxford":{"phon":"ˈsʌnraɪz","pos":"noun","senses":[{"en":"the time when the sun first appears in the sky in the morning","cn":"日出","g":"[uncountable]","ex":{"en":"We got up at sunrise.","cn":"我们在日出时起床。"}},{"en":"the colours in the part of the sky where the sun first appears in the morning","cn":"朝霞","g":"[countable, usually singular]","ex":{"en":"the pinks and yellows of the sunrise","cn":"一道道粉红和金黄的朝霞"}}]}},"subtropical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(地区)副热带的，亚热带的","en":"Sub-tropical places have a climate that is warm and wet, and are often near tropical regions.","ex":{"en":"...the sub-tropical region of the Chapare.","cn":"查帕尔省的亚热带地区"}},{"pos":"ADJ 形容词","cn":"(植物)亚热带的","en":"Sub-tropical plants and trees grow in places that are warm and wet.","ex":{"en":"...a remarkable garden of sub-tropical plants.","cn":"景致迷人的亚热带植物园"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or typical of an area that is near a tropical area","cn":"副热带的﹐亚热带的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41subtropical.mp3","us":"media/ldoce/hwd/ame/f/subtropical.mp3"},"examples":[{"en":"subtropical vegetation","cn":"亚热带植被"}],"oxford":{"phon":"ˌsʌbˈtrɒpɪkl","pos":"adjective","senses":[{"en":"in or connected with regions that are near tropical parts of the world","cn":"亚热带的；副热带的","ex":{"en":"subtropical vegetation","cn":"亚热带植物"}}]}},"superstition":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"迷信;迷信观念","en":"Superstition is belief in things that are not real or possible, for example magic.","ex":{"en":"Fortune-telling is a very much debased art surrounded by superstition","cn":"算命是一种非常低级的把戏，充满了迷信色彩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong belief that something is true or can be trusted, especially religious belief","cn":""},{"en":"a belief that some objects or actions are lucky and some are unlucky, based on old ideas of magic","cn":""},{"en":"a belief that some objects or actions are lucky or unlucky, or that they cause events to happen, based on old ideas of magic","cn":"迷信"}]},"vocab":{"pos":"n","senses":[{"en":"A superstition is a belief or practice that isn’t entirely based on facts or reality, like carrying a rabbit’s foot because you think it brings you good fortune, or believing that Friday the 13th is a day of bad luck."}]},"collocations":{"phrases":["ADJ. popular | age-old, ancient, old | local | pagan | primitive","VERB + SUPERSTITION have We have a lot of superstitions about animals. | be riddled with The topic of birth is riddled with superstition. | ","SUPERSTITION + VERB be attached to sth Red-headed people have many superstitions attached to them.","PREP. ~ about primitive superstitions about death"]},"media":{"uk":"media/ldoce/hwd/bre/8/superstition0205.mp3","us":"media/ldoce/hwd/ame/1/superstition.mp3"},"examples":[{"en":"According to superstition, breaking a mirror brings bad luck.","cn":"按照迷信的说法，摔碎镜子会带来噩运。"},{"en":"the old superstition that walking under a ladder is unlucky","cn":"认为从梯子下面穿过不吉利的古老迷信"}],"oxford":{"phon":"ˌsuːpəˈstɪʃn","pos":"noun","senses":[{"en":"the belief that particular events happen in a way that cannot be explained by reason or science; the belief that particular events bring good or bad luck","cn":"迷信；迷信观念（或思想）","ex":{"en":"According to superstition, breaking a mirror brings bad luck.","cn":"按照迷信的说法，摔碎镜子会带来噩运。"}}]}},"subcontract":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…分包；将…转包","en":"If one firm subcontracts part of its work to another firm, it pays the other firm to do part of the work that it has been employed to do.","ex":{"en":"The company is subcontracting production of most of the parts","cn":"该公司外包了大部分零部件的生产。"}},{"pos":"N-COUNT 可数名词","cn":"分包合同;转包契约","en":"A subcontract is a contract between a firm which is being employed to do a job and another firm which agrees to do part of that job."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a company subcontracts work, they pay other people to do part of their work for them","cn":"将〔已签合约的工作〕分包[转包]给他人"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41subcontract.mp3","us":"media/ldoce/hwd/ame/a/subcontract.mp3"},"examples":[{"en":"We subcontracted a small engineering firm to do the work.","cn":"我们转包给了一家小型工程公司去干那项工作。"},{"en":"We subcontracted the work to a small engineering firm.","cn":"我们把工作转包给了一家小型工程公司。"}],"oxford":{"phon":"ˌsʌbkənˈtrækt","pos":"verb","senses":[{"en":"to pay a person or company to do some of the work that you have been given a contract to do","cn":"分包；转包","ex":{"en":"We subcontracted the work to a small engineering firm.","cn":"我们把工作转包给了一家小型工程公司。"}},{"en":"a contract to do part of the work that has been given to another person or company","cn":"分包合同；转包合同","ex":{"en":"subcontract work","cn":"分包工作"},"pos":"noun"}]}},"surpass":{"collins":{"senses":[{"pos":"VERB 动词","cn":"超过;胜过;优于","en":"If one person or thing surpasses another, the first is better than, or has more of a particular quality than, the second.","ex":{"en":"He was determined to surpass the achievements of his older brothers","cn":"他决心超越几个哥哥的成就。"}},{"pos":"VERB 动词","cn":"远远超出(预期)","en":"If something surpasses expectations, it is much better than it was expected to be.","ex":{"en":"Conrad Black gave an excellent party that surpassed expectations.","cn":"康拉德·布莱克举办了一次远超人们预期的精彩聚会。"}},{"pos":"VERB 动词","cn":"超出(理解范围)","en":"If something surpasses understanding, it is too difficult to understand.","ex":{"en":"...a clever and spectacularly successful system, the detailed complexity of which surpasses our full understanding.","cn":"一个设计巧妙且极其成功的系统，其复杂的细节非我辈所能完全理解"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be even better or greater than someone or something else","cn":"超过﹔胜过"}]},"vocab":{"pos":"v","senses":[{"en":"To surpass means to outdo someone or something, to go beyond what was expected. If you do better than you think you will, you will surpass your own expectations."}]},"collocations":{"phrases":["ADV. far | comfortably, easily","PREP. in The second half of the match comfortably surpassed the first in entertainment value."]},"media":{"uk":"media/ldoce/hwd/bre/7/surpass0205.mp3","us":"media/ldoce/hwd/ame/c/surpass.mp3"},"examples":[{"en":"Her cooking was always good, but this time she had surpassed herself (= done better than her own high standards).","cn":"她的厨艺向来不错，但这一次她更是胜过以往。"},{"en":"Its success has surpassed all expectations.","cn":"它所取得的成功远远超出了预期。"}],"oxford":{"phon":"səˈpɑːs","pos":"verb","senses":[{"en":"to do or be better than somebody/something","cn":"超过；胜过；优于","ex":{"en":"He hopes one day to surpass the world record.","cn":"他希望有一天能刷新世界纪录。"}}]}},"surreal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"离奇的;怪诞的;梦幻般的;超现实的","en":"If you describe something as surreal, you mean that the elements in it are combined in a strange way that you would not normally expect, like in a dream.","ex":{"en":"'Performance' is undoubtedly one of the most surreal movies ever made.","cn":"《迷幻演出》无疑是有史以来最离奇的电影之一。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very strange or very different from what you are used to","cn":""},{"en":"extremely strange and different from what is usually considered normal","cn":""},{"en":"extremely strange and unconnected with real life or normal experiences, like something out of a dream","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you see a bus crash into someone’s front porch while a caged dog barks in the side yard, near a man in a business suit who is grilling hamburgers, you might call that a surreal image. Things that are surreal combine unrelated elements to create a bizarre scene."}]},"media":{"uk":"media/ldoce/hwd/bre/f/surreal0205.mp3","us":"media/ldoce/hwd/ame/5/surreal.mp3"},"examples":[{"en":"The house was a surreal mixture of opulence and decay.","cn":"这座房子破落中透着奢华﹐挺离奇的。"}],"oxford":{"phon":"səˈriːəl","pos":"adjective","senses":[{"en":"very strange; more like a dream than reality, with ideas and images mixed together in a strange way","cn":"离奇的；怪诞的；梦幻般的；超现实的","ex":{"en":"surreal images","cn":"超现实图像"}}]}},"sulphurous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"弥漫着硫黄味的;含有硫黄的","en":"Sulphurous air or places contain sulphur or smell of sulphur.","ex":{"en":"...sulphurous volcanic gases.","cn":"含硫黄的火山气体"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to, full of, or used with sulphur","cn":"硫的﹐含硫的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41sulphurous.mp3","us":"media/ldoce/hwd/ame/c/ld41sulphurous.mp3"},"examples":[{"en":"sulphurous fumes","cn":"燃烧硫磺产生的烟雾"}],"oxford":{"phon":"ˈsʌlfərəs","pos":"adjective","senses":[{"en":"containing or smelling of sulphur","cn":"含硫：含有或闻到硫","ex":{"en":"sulphurous fumes","cn":"含硫的烟雾"}}]}},"succinct":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简洁的;简明的;简要的","en":"Something that is succinct expresses facts or ideas clearly and in few words.","ex":{"en":"The book gives an admirably succinct account of the technology and its history","cn":"这本书极其简明扼要地介绍了这项技术及其发展史。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a short piece of writing or speech does not have many pages or words","cn":""},{"en":"a brief note, description, remark etc uses very few words and gives very few details","cn":""},{"en":"short and clear, and with no unnecessary words","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that is succinct is short and clear. If you're going to be interviewed on television about your new book and only have a five minute slot, you'll need to come up with a succinct version of your story."}]},"media":{"uk":"media/ldoce/hwd/bre/0/succinct0205.mp3","us":"media/ldoce/hwd/ame/4/succinct.mp3"},"examples":[{"en":"Keep your answers as succinct as possible.","cn":"你们的答案要尽可能简洁明了。"},{"en":"You put that very succinctly.","cn":"你说得十分简明扼要。"}],"oxford":{"phon":"səkˈsɪŋkt","pos":"adjective","senses":[{"en":"expressed clearly and in a few words","cn":"简明的；言简意赅的","ex":{"en":"Keep your answers as succinct as possible.","cn":"你们的答案要尽可能简洁明了。"}}]}},"suspense":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对可能发生之事的)兴奋，紧张，担心，挂虑","en":"Suspense is a state of excitement or anxiety about something that is going to happen very soon, for example about some news that you are waiting to hear.","ex":{"en":"The suspense over the two remaining hostages ended last night when the police discovered the bullet ridden bodies.","cn":"随着昨晚警方发现了弹痕累累的尸体，人们对剩余两名人质的担心也终告结束。"}},{"pos":"PHRASE 短语","cn":"(故意)使着急，使焦虑","en":"If you keep or leave someone in suspense, you deliberately delay telling them something that they are very eager to know about.","ex":{"en":"Keppler kept all his men in suspense until that morning before announcing which two would be going","cn":"开普勒让所有的下属都焦急地等待着，直到那天上午才宣布哪两个人去。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make someone wait, especially by arriving late","cn":""},{"en":"to deliberately make someone wait","cn":""},{"en":"to make someone wait anxiously or excitedly before you tell them something that they are eager to know","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Suspense is a feeling of excited waiting. If you have been waiting for weeks to get an answer to your proposal of marriage, you are being kept in suspense ."}]},"collocations":{"phrases":["ADJ. heart-pounding, nail-biting, unbearable","VERB + SUSPENSE keep sb in Don't keep us in suspense?did you get the job or not? | break Don't look at the end of the book yet?you'll break ","SUSPENSE + VERB be killing sb (informal) I don't get the results till next week, and the suspense is killing me.","SUSPENSE + NOUN story","PREP. ~ about They were kept in suspense about their possibility of joining the expedition for several weeks.","PHRASES an agony of suspense I suffered agonies of suspense in silence. | a state of suspense"]},"media":{"uk":"media/ldoce/hwd/bre/8/suspense0205.mp3","us":"media/ldoce/hwd/ame/4/suspense.mp3"},"examples":[{"en":"Don't keep us in suspense. Tell us what happened!","cn":"别让我们心老悬着了，告诉我们出了什么事！"},{"en":"I couldn't bear the suspense a moment longer.","cn":"这样提心吊胆，我一刻也受不了了。"}],"oxford":{"phon":"səˈspens","pos":"noun","senses":[{"en":"a feeling of worry or excitement that you have when you feel that something is going to happen, somebody is going to tell you some news, etc.","cn":"（对即将发生的事等的）担心；焦虑；兴奋；悬念","ex":{"en":"a tale of mystery and suspense","cn":"一个神秘莫测、充满悬念的故事"}}]}},"sucker":{"collins":{"senses":[{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"容易上当受骗的人;傻瓜;笨蛋","en":"If you call someone a sucker, you mean that it is very easy to cheat them.","ex":{"en":"But that is what the suckers want so you give it them","cn":"但那就是那些笨蛋们想要的，给他们就是了。"}},{"pos":"N-COUNT 可数名词","cn":"对…入迷的人;难以抗拒…的人","en":"If you describe someone as a sucker for something, you mean that they find it very difficult to resist it.","ex":{"en":"I'm such a sucker for romance.","cn":"我对浪漫毫无招架之力。"}},{"pos":"VERB 动词","cn":"欺骗;诱骗","en":"If you sucker a person into doing something, you deceive them, usually so that they do something that is against their own interests.","ex":{"en":"If you tell those folks the truth, they won't vote for you. But if you sucker them, they'll vote for you twice over","cn":"如果你告诉这些人实情，他们是不会选你的。但是如果你耍点儿伎俩，他们会不止一次推举你。"}},{"pos":"N-COUNT 可数名词","cn":"(动物或昆虫的)吸盘","en":"The suckers on some animals and insects are the parts on the outside of their body which they use in order to stick to a surface."},{"pos":"N-COUNT 可数名词","cn":"(橡胶)吸盘","en":"A sucker is a small device used for attaching things to surfaces. It consists of a cup-shaped piece of rubber that sticks to a surface when it is pressed flat.","ex":{"en":"...sucker pads.","cn":"吸垫"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is tricked by someone else, especially so that they become involved in the other person's dishonest plans without realizing it","cn":""},{"en":"someone who believes everything they are told, even when it is clearly not true","cn":""},{"en":"someone who is easily deceived, especially so that they do much more or give much more than is fair or reasonable","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/succour_n0205.mp3","us":"media/ldoce/hwd/ame/0/succor.mp3"},"examples":[{"en":"The pilot said, ‘I don't know how I got the sucker down safely.’","cn":"机师说：“我不知道是怎么把这玩意儿安全降落下来的。”"},{"en":"I've always been a sucker for men with green eyes.","cn":"我一向对绿眼睛男人着迷。"}],"oxford":{"phon":"ˈsʌkə(r)","pos":"noun","senses":[{"en":"a person who is easily tricked or persuaded to do something","cn":"容易上当受骗的人；没有主见的人","lab":"informal","ex":{"en":"She always said the lottery was for suckers.","cn":"她总是说傻瓜才去买彩票。"}},{"en":"a person who cannot resist somebody/something or likes somebody/something very much","cn":"不由得对…入迷的人；酷爱…的人","lab":"informal","ex":{"en":"I've always been a sucker for men with green eyes.","cn":"我一向对绿眼睛男人着迷。"}},{"en":"a special organ on the body of some animals that enables them to stick to a surface","cn":"（动物的）吸盘"},{"en":"a disc like a cup in shape, usually made of rubber or plastic, that sticks to a surface when you press it against it","cn":"（橡胶或塑料等制成的）吸盘"},{"en":"a part of a tree or bush that grows from the roots rather than from the main stem or the branches and can form a new tree or bush","cn":"根出条"},{"en":"used to refer in a general way to a person or thing, especially for emphasis","cn":"（泛指人或物，尤表示强调）家伙，东西，玩意儿","lab":"North American English, slang，，","ex":{"en":"The pilot said, ‘I don't know how I got the sucker down safely.’","cn":"飞行员说：“我不知道是怎么把这玩意儿安全降落下来的。”"}},{"en":"a hard round or flat sweet made of boiled sugar on a small stick","cn":"棒棒糖","lab":"North American English, informal，，"}]}},"surtax":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对超过一定金额的收入征收的)附加税","en":"Surtax is an additional tax on incomes higher than the level at which ordinary tax is paid.","ex":{"en":"...a 10% surtax for Americans earning more than $250,000 a year.","cn":"对于年收入在 25 万美元以上的美国人征收的 10%的附加税"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an additional tax on money you earn if it is higher than a particular amount 〔","cn":"对超过一定数额的收入征收的〕附加税"}]},"media":{"uk":"media/ldoce/hwd/bre/4/surtax0205.mp3","us":"media/ldoce/hwd/ame/1/surtax.mp3"},"oxford":{"phon":"ˈsɜːtæks","pos":"noun","senses":[{"en":"a tax charged at a higher rate than the normal rate, on income above a particular level","cn":"（对超过一定金额的收入征收的）附加税"}]}},"surfeit":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"过量;过多","en":"A surfeit of something is an amount which is too large.","ex":{"en":"Rationing had put an end to a surfeit of biscuits long ago.","cn":"定量供应很久以前就结束了饼干过剩的状况。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of something that is too large or that is more than you need","cn":"过量的某物"}]},"vocab":{"pos":"v n","senses":[{"en":"Steve baked a surfeit of jam tarts. Steve ate a surfeit of jam tarts. Steve surfeited himself on jam tarts. Whether surfeit is a noun or a verb (as in \"overabundance\" or \"gorge\"), Steve is likely to end up with a bellyache."}]},"media":{"uk":"media/ldoce/hwd/bre/2/surfeit0205.mp3","us":"media/ldoce/hwd/ame/6/surfeit1.mp3"},"examples":[{"en":"a surfeit of food and drink","cn":"过量的食物和饮料"}],"oxford":{"phon":"ˈsɜːfɪt","pos":"noun","senses":[{"en":"an amount that is too large","cn":"过量","ex":{"en":"Indigestion can be brought on by a surfeit of rich food.","cn":"过多的油腻食物会导致消化不良。"}}]}},"sugar-coated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"包有糖衣的;裹糖的","en":"Sugar-coated food is covered with a sweet substance made of sugar.","ex":{"en":"Some sugar-coated cereals are 50% sugar.","cn":"有些裹糖的谷物食品含糖量达 50%。"}},{"pos":"ADJ 形容词","cn":"巧作粉饰的;经过美化的","en":"If you describe something such as a story as sugar-coated, you disapprove of it because it appears to be pleasant or attractive but in fact describes something very unpleasant.","ex":{"en":"...a sugar-coated view of a boy's introduction to sex.","cn":"对男孩首次接触性所持的冠冕堂皇的看法"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"covered with sugar","cn":"裹糖的﹐包有糖衣的"},{"en":"used to describe something that is made to seem better than it really is","cn":"经美化的﹐巧加粉饰的"}]},"media":{"uk":"media/ldoce/hwd/bre/1/sugar_coated0205.mp3","us":"media/ldoce/hwd/ame/e/laadsugar-coated.mp3"},"examples":[{"en":"a sugar-coated promise","cn":"甜言蜜语的许诺"},{"en":"sugar-coated cereals","cn":"裹糖的谷类食品"}],"oxford":{"phon":"ˌʃʊɡə ˈkəʊtɪd","pos":"adjective","senses":[{"en":"covered with sugar","cn":"裹有糖的；包糖衣的"},{"en":"made to seem attractive, in a way that tricks people","cn":"巧加粉饰的；使表面吸引人的","lab":"disapproving","ex":{"en":"a sugar-coated promise","cn":"甜言蜜语的许诺"}}]}},"supertanker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超级油轮;巨型油轮","en":"A supertanker is an extremely large ship that is used for transporting oil.","ex":{"en":"An oil slick caused by a spill from a supertanker has hit several beaches.","cn":"一艘超级油轮的石油泄漏形成的浮油膜已经影响了好几个海滩。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a ship that carries goods rather than people","cn":""},{"en":"a ship that carries goods in special containers which can be put on trucks","cn":""},{"en":"a large ship that carries goods","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41supertanker.mp3","us":"media/ldoce/hwd/ame/8/supertanker.mp3"},"oxford":{"phon":"ˈsuːpətæŋkə(r)","pos":"noun","senses":[{"en":"a very large ship for carrying oil, etc.","cn":"超级油轮"}]}},"superhuman":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"超出常人的;非凡的;超人的","en":"If you describe a quality that someone has as superhuman, you mean that it seems to be much greater than that of ordinary people.","ex":{"en":"Officers were terrified of his superhuman strength","cn":"军官们被他超凡的力量吓坏了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"much greater than ordinary human powers or abilities","cn":"超人的﹐超出常人能力的﹔非凡的"},{"en":"superhuman power/strength/effort etc It will require a superhuman effort to get the job done on time.","cn":"要按时完成这项工作需要付出非凡的努力。"}]},"media":{"uk":"media/ldoce/hwd/bre/2/brelasdesuperhuman.mp3","us":"media/ldoce/hwd/ame/e/superhuman.mp3"},"examples":[{"en":"It took an almost superhuman effort to contain his anger.","cn":"他以超常的克制力强压住怒火。"},{"en":"superhuman strength","cn":"非凡的力量"}],"oxford":{"phon":"ˌsuːpəˈhjuːmən","pos":"adjective","senses":[{"en":"having much greater power, knowledge, etc. than is normal","cn":"超出常人的；非凡的","ex":{"en":"superhuman strength","cn":"非凡的力量"}}]}},"suppository":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"栓剂;坐药","en":"A suppository is a solid block of medicine that is put into the rectum, where it gradually dissolves."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of solid medicine that is placed in someone’s rectum or vagina 〔","cn":"放入直肠或阴道内的〕栓剂"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41suppository.mp3","us":"media/ldoce/hwd/ame/e/suppository.mp3"},"oxford":{"phon":"səˈpɒzətri","pos":"noun","senses":[{"en":"a small piece of solid medicine that is placed in the rectum or vagina and left to dissolve gradually","cn":"栓剂"}]}},"supersede":{"collins":{"senses":[{"pos":"VERB 动词","cn":"取代，替代(陈旧或令人不满意的事物)","en":"If something is superseded by something newer, it is replaced because it has become old-fashioned or unacceptable.","ex":{"en":"Hand tools are relics of the past that have now been superseded by the machine.","cn":"手工工具是历史的遗物，现在已经被机器所取代。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if one thing replaces another, it is used instead of the other thing, usually permanently","cn":""},{"en":"to be used instead of another thing","cn":""},{"en":"to take the place of something – used especially about inventions, methods, organizations etc","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you click on the link after this description, a new screen will supersede, or replace, this one. A longer description will supplant, or supersede , by replacing this brief one."}]},"media":{"uk":"media/ldoce/hwd/bre/1/supersede0205.mp3","us":"media/ldoce/hwd/ame/2/supersede.mp3"},"examples":[{"en":"The theory has been superseded by more recent research.","cn":"这一理论已为新近的研究所取代。"},{"en":"Their map has since been superseded by photographic atlases.","cn":"他们的地图从此被摄影地图册取代。"}],"oxford":{"phon":"ˌsuːpəˈsiːd","pos":"verb","senses":[{"en":"to take the place of something/somebody that is considered to be old-fashioned or no longer the best available","cn":"取代，替代（已过时或已非最佳选择的人或物）","ex":{"en":"The theory has been superseded by more recent research.","cn":"这一理论已为新近的研究所取代。"}}]}},"sunglasses":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"太阳镜;墨镜","en":"Sunglasses are glasses with dark lenses which you wear to protect your eyes from bright sunlight.","ex":{"en":"She slipped on a pair of sunglasses.","cn":"她迅速戴上一副太阳镜。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dark glasses that you wear to protect your eyes when the sun is very bright","cn":"太阳镜﹐墨镜"}]},"collocations":{"phrases":["ADJ. clip-on | wrap-around | mirror, mirrored, reflecting | designer","QUANT. pair","VERB + SUNGLASSES have on, wear | put on, take off | adjust","SUNGLASSES + VERB be perched on sth, perch on sth Her sunglasses were perched on her head.","PREP. behind your ~ She observed the goings-on from behind her mirrored sunglasses."]},"media":{"img":["media/ldoce/img/pair_sunglasses.jpg"],"uk":"media/ldoce/hwd/bre/1/sunglasses0205.mp3","us":"media/ldoce/hwd/ame/7/sunglasses.mp3"},"examples":[{"en":"a pair of sunglasses","cn":"一副太阳镜"}],"oxford":{"phon":"ˈsʌnɡlɑːsɪz","pos":"noun","senses":[{"en":"a pair of glasses with dark glass in them that you wear to protect your eyes from bright light from the sun","cn":"太阳镜；墨镜","ex":{"en":"a pair of sunglasses","cn":"一副太阳镜"}}]}},"sully":{"collins":{"senses":[{"pos":"VERB 动词","cn":"败坏;有损于;使贬值","en":"If something is sullied by something else, it is damaged so that it is no longer pure or of such high value.","ex":{"en":"The City's reputation has been sullied by scandals like those at Lloyd's","cn":"类似劳埃德保险公司的那些丑闻令伦敦名声扫地。"}},{"pos":"VERB 动词","cn":"弄脏;玷污","en":"If someone sullies something, they make it dirty.","ex":{"en":"I felt loath to sully the gleaming brass knocker by handling it.","cn":"我不愿意伸手去抓那闪亮的黄铜门环，怕把它弄脏。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to spoil or reduce the value of something that was perfect","cn":"弄脏﹐玷污﹐破坏"}]},"vocab":{"pos":"v","senses":[{"en":"To sully is to attack someone's good name and to try to ruin his reputation. If you spread false rumors that there's chicken stock in the vegetarian entree at Joe's Diner, you would sully Joe's good reputation."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41sully.mp3","us":"media/ldoce/hwd/ame/4/sully.mp3"},"examples":[{"en":"a scandal that sullied his reputation","cn":"玷污了他名誉的丑闻"}],"oxford":{"phon":"ˈsʌli","pos":"verb","senses":[{"en":"to damage or reduce the value of something","cn":"败坏；有损于","ex":{"en":"By cheating they have sullied the good name of their country.","cn":"他们的欺骗行为玷污了国家的声誉。"}},{"en":"to make something dirty","cn":"弄脏；玷污","ex":{"en":"She wondered if she dared risk sullying the gleaming sink.","cn":"她想知道自己是否敢冒玷污闪闪发光的水槽的风险。"}}]}},"surrealism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(艺术、文学上的)超现实主义，超现实派","en":"Surrealism is a style in art and literature in which ideas, images, and objects are combined in a strange way, like in a dream.","ex":{"en":"His early work was influenced by the European surrealism of the 1930's.","cn":"他早期的作品受到了20世纪30年代欧洲超现实主义的影响。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a style of 20th-century art or literature in which the artist or writer connects unrelated images and objects in a strange way 〔20","cn":"世纪艺术或文学的〕超现实主义"}]},"vocab":{"pos":"n","senses":[{"en":"Surrealism is a wild painting and writing style that creates images that might come from dreams, like a landscape with gold pocket-watches bending, or an eyeball with clouds inside."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41surrealism.mp3","us":"media/ldoce/hwd/ame/8/surrealism.mp3"},"examples":[{"en":"the surrealist Salvador Dali","cn":"超现实主义画家萨尔瓦多 · 达利"},{"en":"a surrealist painter/painting","cn":"超现实主义画家/绘画"}],"oxford":{"phon":"səˈriːəlɪzəm","pos":"noun","senses":[{"en":"a 20th century style and movement in art and literature in which images and events that are not connected are put together in a strange or impossible way, like a dream, to try to express what is happening deep in the mind","cn":"超现实主义，超现实主义派（20 世纪文艺流派，以离奇怪诞的方式把无关联的形象和事情串连在一起）"}]}},"subcontinent":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"次大陆;(常指包括印度、巴基斯坦、孟加拉国在内的)南亚次大陆","en":"A subcontinent is part of a larger continent, made up of a number of countries that form a large mass of land. The subcontinent is often used to refer to the area that contains India, Pakistan, and Bangladesh."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large area of land that is part of a continent","cn":"次大陆"},{"en":"the area of land that includes India, Pakistan, and Bangladesh","cn":"南亚次大陆〔包括印度﹑巴基斯坦和孟加拉国〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/subcontinent0205.mp3","us":"media/ldoce/hwd/ame/e/laadsubcontinent.mp3"},"examples":[{"en":"the Indian subcontinent","cn":"印度次大陆"}],"oxford":{"phon":"ˌsʌbˈkɒntɪnənt","pos":"noun","senses":[{"en":"a large land mass that forms part of a continent, especially the part of Asia that includes India, Pakistan and Bangladesh","cn":"次大陆（尤指包括印度、巴基斯坦和孟加拉国在内的南亚次大陆）","ex":{"en":"the Indian subcontinent","cn":"印度次大陆"}}]}},"subsequent":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"随后的;后来的","en":"You use subsequent to describe something that happened or existed after the time or event that has just been referred to.","ex":{"en":"...the increase of population in subsequent years","cn":"随后几年人口的增长"}},{"pos":"PHRASE 短语","cn":"在…之后;继…之后","en":"If something happened subsequent to something else, it happened after that thing.","ex":{"en":"They won only one more game subsequent to their Cup semi-final win last year.","cn":"继去年在杯赛半决赛中获胜后，他们仅又赢过一场比赛。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening or existing at some time in the future after something or someone else","cn":""},{"en":"happening or coming immediately after something – used about periods of time, or parts of a piece of writing","cn":""},{"en":"likely to happen or exist at some time in the future","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"For something that comes after something else in time or order, choose the adjective subsequent . If the entire class fails an exam, the teacher will hopefully make subsequent ones a little easier."}]},"media":{"uk":"media/ldoce/hwd/bre/5/subsequent0205.mp3","us":"media/ldoce/hwd/ame/7/subsequent.mp3"},"examples":[{"en":"Developments on this issue will be dealt with in a subsequent report.","cn":"这个问题的发展将在以后的报道中予以说明。"},{"en":"Subsequent events confirmed our doubts.","cn":"后来发生的事证实了我们的疑虑。"}],"oxford":{"phon":"ˈsʌbsɪkwənt","pos":"adjective","senses":[{"en":"happening or coming after something else","cn":"随后的；后来的；之后的；接后的","ex":{"en":"subsequent generations","cn":"后代"}}]}},"subeditor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"助理编辑;审校人","en":"A sub-editor is a person whose job it is to check and correct articles in newspapers or magazines before they are printed.","ex":{"en":"I was a sub-editor on the foreign desk of the News Chronicle.","cn":"我是《新闻纪事报》国际组的一名助理编辑。"}}]},"oxford":{"phon":"ˈsʌbedɪtə(r)","pos":"noun","senses":[{"en":"a person whose job is to check and make changes to the text of a newspaper or magazine before it is printed","cn":"助理编辑；审校人"}]}},"supplemental":{"lemma":"supplementary"},"sunny":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阳光充足的;晴朗的","en":"When it is sunny, the sun is shining brightly.","ex":{"en":"The weather was surprisingly warm and sunny","cn":"天气出奇地暖和，阳光充足。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"阳光明媚的;阳光照耀的","en":"Sunny places are brightly lit by the sun.","ex":{"en":"Most roses like a sunny position in a fairly fertile soil.","cn":"多数玫瑰在土地肥沃、阳光充足的地方长得最好。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"欢乐的;快乐的;乐天的","en":"Someone who has a sunny disposition is usually cheerful and happy.","ex":{"en":"He was a nice lad — bright and with a sunny disposition","cn":"他是个不错的小伙子——聪明伶俐而且性格开朗。"}},{"pos":"PHRASE 短语","cn":"(煎蛋)只煎一面的，单面煎的","en":"If a fried egg is served sunny side up, it is cooked on one side only, with the yellow part on top.","ex":{"en":"I want my eggs sunny side up.","cn":"我想要只煎一面的鸡蛋。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if the weather is sunny, the sun is shining","cn":""},{"en":"not raining, and with no clouds or only a few clouds in the sky","cn":""},{"en":"pleasantly warm and sunny","cn":""}]},"collocations":{"phrases":["VERBS be, look | become, get | remain, stay","ADV. brilliantly, very a brilliantly sunny day | quite"]},"media":{"uk":"media/ldoce/hwd/bre/c/sunny0205.mp3","us":"media/ldoce/hwd/ame/6/sonny.mp3"},"examples":[{"en":"Italy was at its sunniest.","cn":"当时意大利正值阳光最充沛的时节。"},{"en":"The outlook for the weekend is hot and sunny.","cn":"预计本周末天气晴朗炎热。"}],"oxford":{"phon":"ˈsʌni","pos":"adjective","senses":[{"en":"with a lot of bright light from the sun","cn":"阳光充足的","ex":{"en":"a sunny day","cn":"阳光明媚的日子"}},{"en":"cheerful and happy","cn":"欢乐的；快乐的","ex":{"en":"a sunny disposition","cn":"开朗的性情"}}]}},"superintend":{"collins":{"senses":[{"pos":"VERB 动词","cn":"管理;监督;指挥;主管","en":"If you superintend something, you have responsibility for ensuring that it is carried out properly.","ex":{"en":"During the interval, Linton superintended a prize draw.","cn":"中间休息时，林顿组织了一次抽奖。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to be in charge of something, and control how it is done","cn":"主管﹔监督﹔控制"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41superintend.mp3","us":"media/ldoce/hwd/ame/7/superintend.mp3"},"oxford":{"phon":"ˌsuːpərɪnˈtend","pos":"verb","senses":[{"en":"to be in charge of something and make sure that everything is working, being done, etc. as it should be","cn":"主管；监督；监管","ex":{"en":"He superintended the building work.","cn":"他监管这项建筑工程。"}}]}},"succulent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指蔬菜及肉类)汁多味美的","en":"Succulent food, especially meat or vegetables, is juicy and good to eat.","ex":{"en":"Cook pieces of succulent chicken with ample garlic and a little sherry.","cn":"烹饪鲜美滑嫩的鸡肉时多加些大蒜，并滴入少许雪利酒。"}},{"pos":"N-COUNT 可数名词","cn":"肉质植物(叶子肥厚的植物)","en":"Succulents or succulent plants are types of plants which have thick, fleshy leaves.","ex":{"en":"His potted succulents were looking parched.","cn":"他盆栽的肉质植物看起来已经干枯了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is delicious tastes very good, and you enjoy eating or drinking it","cn":""},{"en":"food that is tasty has a strong taste that you like","cn":""},{"en":"succulent food contains a lot of juice and tastes good – used especially about fruit, vegetables, or meat","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Succulent means \"juicy\" and is often used to describe food. Think a succulent piece of meat, or berries so succulent you’re left sucking juice off your fingertips when you eat them."}]},"media":{"uk":"media/ldoce/hwd/bre/6/succulent_adj0205.mp3","us":"media/ldoce/hwd/ame/c/succulent1.mp3"},"examples":[{"en":"a succulent pear/steak","cn":"汁多味美的梨；鲜美多汁的牛排"},{"en":"a succulent steak","cn":"美味多汁的牛排"}],"oxford":{"phon":"ˈsʌkjələnt","pos":"adjective","senses":[{"en":"containing a lot of juice and tasting good","cn":"汁多味美的","lab":"approving","ex":{"en":"a succulent pear/steak","cn":"汁多味美的梨；鲜美多汁的牛排"}},{"en":"having leaves and stems that are thick and contain a lot of water","cn":"肉质的；多汁的","lab":"specialist"},{"en":"any plant with leaves and stems that are thick and contain a lot of water, for example a cactus","cn":"肉质植物","pos":"noun"}]}},"suspender":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(长筒袜上的)吊袜带","en":"Suspenders are the fastenings which hold up a woman's stockings."},{"pos":"N-PLURAL 复数名词","cn":"(裤子上的)背带，吊带","en":"Suspenders are a pair of straps that go over someone's shoulders and are fastened to their trousers at the front and back to prevent the trousers from falling down."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of a piece of women’s underwear that hangs down and can be attached to stocking s to hold them up","cn":"吊袜带"},{"en":"two bands of cloth that go over your shoulders and fasten to your trousers to hold them up 〔","cn":"男裤的〕吊带﹐背带"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41suspender.mp3","us":"media/ldoce/hwd/ame/d/ld41suspender.mp3"},"oxford":{"phon":"səˈspendə(r)","pos":"noun","senses":[{"en":"a piece of elastic attached to a belt and fastened to the top of a stocking to hold it up","cn":"吊袜带","g":"[countable, usually plural]","lab":"British English","ex":{"en":"She performed the act in stockings and suspenders.","cn":"她穿着丝袜和吊带表演了这个动作。"}},{"en":"long narrow pieces of cloth, leather, etc. for holding trousers up. They are fastened to the top of the trousers at the front and back and passed over the shoulders.","cn":"吊裤带；背带","g":"[plural]","lab":"North American English","ex":{"en":"The suspenders held up his trousers.","cn":"吊裤带把他的裤子提起来。"}}]}},"sunburnt":{"lemma":"sunburned"},"substantiate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"证实;证明","en":"To substantiate a statement or a story means to supply evidence which proves that it is true.","ex":{"en":"There is little scientific evidence to substantiate the claims.","cn":"这些主张几乎找不到科学依据来证实。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a piece of new information confirms an idea or belief that people already have, it shows that it is definitely true","cn":""},{"en":"to show that something is definitely true by providing facts","cn":""},{"en":"to provide additional information to help prove that a statement, belief, or explanation is correct","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To substantiate is to give support to a claim. We’d really like to believe in the Tooth Fairy; however, more evidence is needed to substantiate her existence (besides that quarter in your pocket)."}]},"media":{"uk":"media/ldoce/hwd/bre/f/substantiate0205.mp3","us":"media/ldoce/hwd/ame/9/substantiate.mp3"},"examples":[{"en":"The results of the tests substantiated his claims.","cn":"这些检验的结果证实了他的说法。"},{"en":"Katzen offered little evidence to substantiate his claims .","cn":"卡曾拿不出什么证据来证明他的说法。"}],"oxford":{"phon":"səbˈstænʃieɪt","pos":"verb","senses":[{"en":"to provide information or evidence to prove that something is true","cn":"证实；证明","ex":{"en":"The results of the tests substantiated his claims.","cn":"这些检验的结果证实了他的说法。"}}]}},"supplication":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"恳求;祈愿;哀求","en":"A supplication is a prayer to God or a respectful request to someone in authority for help.","ex":{"en":"He raised his arms in a gesture of supplication","cn":"他举起双手，做祈求状。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when someone asks for help from someone in power or from God 〔","cn":"尤指向当权者或上帝的〕恳求﹐哀求﹐祈求"}]},"vocab":{"pos":"n","senses":[{"en":"Think of a supplication as sort of a prayer, a request for help from a deity. The word carries a sense of awe and adoration with it, suggesting something tentative, even servile, a respectful appeal to a higher power."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41supplication.mp3","us":"media/ldoce/hwd/ame/7/laadsupplication.mp3"},"examples":[{"en":"She knelt in supplication.","cn":"她跪地祷求。"},{"en":"Paolo knelt and bowed his head in supplication.","cn":"保罗跪下来低头祈求。"}],"oxford":{"phon":"ˌsʌplɪˈkeɪʃn","pos":"noun","senses":[{"en":"the act of asking for something with a very humble request or prayer","cn":"恳求；哀求；祈求","ex":{"en":"She knelt in supplication.","cn":"她跪地祷求。"}}]}},"superstitious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷信的","en":"People who are superstitious believe in things that are not real or possible, for example magic.","ex":{"en":"Jean was extremely superstitious and believed the colour green brought bad luck.","cn":"琼非常迷信，认为绿色会带来厄运。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(恐惧、信念)非理性的，盲目的","en":"Superstitious fears or beliefs are irrational and not based on fact.","ex":{"en":"A wave of superstitious fear spread among the townspeople","cn":"盲目的恐惧感在市民中蔓延。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"influenced by superstitions","cn":"迷信的"}]},"vocab":{"pos":"adj","senses":[{"en":"Superstitious describes a belief in chance or magic. If you're superstitious , you may avoid walking under ladders, spilling salt, or passing black cats — all because you think they will bring you bad luck."}]},"media":{"uk":"media/ldoce/hwd/bre/e/superstitious0205.mp3","us":"media/ldoce/hwd/ame/d/superstitious.mp3"},"examples":[{"en":"I'm superstitious about the number 13.","cn":"我相信 13 这个数字不吉利。"},{"en":"superstitious beliefs","cn":"迷信观念"}],"oxford":{"phon":"ˌsuːpəˈstɪʃəs","pos":"adjective","senses":[{"en":"believing in superstitions","cn":"迷信的；有迷信观念的","ex":{"en":"superstitious beliefs","cn":"迷信观念"}}]}},"sultry":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"湿热的;闷热的","en":"Sultry weather is hot and damp.","ex":{"en":"The climax came one sultry August evening.","cn":"在 8 月一个闷热的夜晚，高潮到来了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"迷人的;撩人的;风情万种的","en":"Someone who is sultry is attractive in a way that suggests hidden passion.","ex":{"en":"...a dark-haired sultry woman.","cn":"性感迷人的黑发女郎"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"weather that is sultry is hot with air that feels wet 〔","cn":"天气〕闷热的"},{"en":"a woman who is sultry makes other people feel strong sexual attraction to her 〔","cn":"女子〕风骚的﹐性感迷人的"}]},"vocab":{"pos":"adj","senses":[{"en":"Stifling, humid and downright oppressive, sultry is an adjective that has everything to do with sweltering heat and a definite need for a tall glass of iced tea."}]},"media":{"uk":"media/ldoce/hwd/bre/6/sultry0205.mp3","us":"media/ldoce/hwd/ame/4/sultry.mp3"},"examples":[{"en":"a sultry summer afternoon","cn":"夏天一个闷热的下午"},{"en":"a sultry singer","cn":"嗓音撩人的歌手"}],"oxford":{"phon":"ˈsʌltri","pos":"adjective","senses":[{"en":"very hot and uncomfortable","cn":"闷热的","ex":{"en":"a sultry summer afternoon","cn":"夏天一个闷热的下午"}},{"en":"sexually attractive; seeming to have strong sexual feelings","cn":"姿色迷人的；风情万种的；性感的","ex":{"en":"a sultry smile","cn":"迷人的微笑"}}]}},"supercharged":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(汽车引擎)增压的，提高功率的","en":"If a car engine is supercharged, it has more air than normal forced into it so that the petrol burns more quickly and the car has more power."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a supercharged engine is very powerful because air or fuel is supplied to it at a higher pressure than normal 〔","cn":"引擎〕增压的﹐增加动力的"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41supercharged.mp3","us":"media/ldoce/hwd/ame/e/laadsupercharged.mp3"},"examples":[{"en":"supercharged words, like ‘terrorism’ or ‘fascism’","cn":"诸如 terrorism 或 fascism 等语义格外强烈的词"},{"en":"VW's supercharger for its 16-valve engine","cn":"大众汽车 16 阀发动机专用增压器"}],"oxford":{"phon":"ˈsuːpətʃɑːdʒd","pos":"adjective","senses":[{"en":"powerful because it is supplied with air or fuel at a pressure that is higher than normal","cn":"（用增压器）增压的，提高功率的"},{"en":"stronger, more powerful or more effective than usual","cn":"异常强烈的；格外强劲的；特别有效的","lab":"informal","ex":{"en":"supercharged words, like ‘terrorism’ or ‘fascism’","cn":"诸如 terrorism 或 fascism 等语义格外强烈的词"}}]}},"succumb":{"collins":{"senses":[{"pos":"VERB 动词","cn":"屈从于，屈服于，抵挡不住(诱惑或压力)","en":"If you succumb to temptation or pressure, you do something that you want to do, or that other people want you to do, although you feel it might be wrong.","ex":{"en":"Don't succumb to the temptation to have just one cigarette","cn":"不要经不住诱惑，只抽一支烟也不行。"}},{"pos":"VERB 动词","cn":"感染，死于(疾病)","en":"If you succumb to an illness, you become affected by it or die from it.","ex":{"en":"A few years later, Katya succumbed to cancer in London","cn":"几年后，卡佳因患癌症在伦敦病逝。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop opposing someone or something that is stronger than you, and allow them to take control","cn":"屈服﹐屈从﹔不再抵抗"},{"en":"if you succumb to an illness, you become very ill or die of it","cn":"患重病﹔死于〔某疾病〕"}]},"vocab":{"pos":"v","senses":[{"en":"Use the verb succumb to say that someone yields to something they've tried to fight off, such as despair, temptation, disease or injury."}]},"collocations":{"phrases":["ADV. almost | rapidly | eventually, finally | easily, readily people who succumb easily to exploitation","VERB + SUCCUMB be likely to","PREP. to Malnourished children are more likely to succumb to infections."]},"media":{"uk":"media/ldoce/hwd/bre/c/succumb0205.mp3","us":"media/ldoce/hwd/ame/9/succumb.mp3"},"examples":[{"en":"He finally succumbed to Lucy's charms and agreed to her request.","cn":"他最终为露西的魅力所倾倒，答应了她的请求。"},{"en":"His career was cut short when he succumbed to cancer.","cn":"他的事业随着他死于癌症而中断。"}],"oxford":{"phon":"səˈkʌm","pos":"verb","senses":[{"en":"to not be able to fight an attack, a temptation, etc.","cn":"屈服；屈从；抵挡不住（攻击、诱惑等）","g":"[intransitive]","ex":{"en":"The town succumbed after a short siege.","cn":"该城被围困不久即告失守。"}},{"en":"to die from the effect of a disease or an injury","cn":"死于（伤病）","g":"[intransitive]","ex":{"en":"His career was cut short when he succumbed to cancer.","cn":"他的事业随着他死于癌症而中断。"}}]}},"sublimate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使升华;使(欲望、情感)高尚化","en":"If you sublimate a strong desire or feeling, you express it in a way that is socially acceptable.","ex":{"en":"He could try to sublimate the problem by writing, in detail, about it","cn":"他可以努力通过详细记述该问题而使其受到人们的正视。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use the energy that comes from sexual feelings to do something, such as work or art, that is more acceptable to your society","cn":"使升华﹐使高尚化〔指把性欲冲动转移到艺术创作等更能被社会认可的行为中去〕"}]},"vocab":{"pos":"v n adj","senses":[{"en":"When you're at a lecture and you feel restless, you've got to sublimate the desire to move around. That means you force the desire to be more subtle so you can continue listening — even if you don't want to."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41sublimate.mp3","us":"media/ldoce/hwd/ame/4/sublimate1.mp3"},"oxford":{"phon":"ˈsʌblɪmeɪt","pos":"verb","senses":[{"en":"to direct your energy, especially sexual energy, to socially acceptable activities such as work, exercise, art, etc.","cn":"升华，使高尚化（把性欲冲动等转移到工作、锻炼、艺术等社会可接受的活动中）"}]}},"subdivision":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"细分部分;分支;分部","en":"A subdivision is an area, part, or section of something which is itself a part of something larger.","ex":{"en":"Months are a conventional subdivision of the year.","cn":"通常可将一年再按月细分。"}},{"pos":"N-COUNT 可数名词","cn":"分割成的小块土地(供开发住房)","en":"A subdivision is an area of land for building houses on.","ex":{"en":"Rammick lives high on a ridge in a 400-home subdivision.","cn":"拉米克住在高耸的山脊上一片有 400 户人家的地方。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is subdivided, or the parts that result from doing this","cn":"再分﹐细分﹔进一步分成的部分"},{"en":"an area of land that has been subdivided for building houses on 〔","cn":"为建房而划分的〕一块土地"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41subdivision.mp3","us":"media/ldoce/hwd/ame/3/subdivision.mp3"},"examples":[{"en":"subdivisions within the Hindu caste system","cn":"印度教种姓制度内的不同等级"},{"en":"a police subdivision (= the area covered by one particular police force)","cn":"警察部门下属的管辖分区"}],"oxford":{"phon":"","pos":"noun","senses":[{"en":"the act of dividing a part of something into smaller parts","cn":"再分割；再分；细分","g":"[uncountable]","ex":{"en":"Subdivision among major sections of the index is necessary.","cn":"指数的主要部分之间的细分是必要的。"}},{"en":"one of the smaller parts into which a part of something has been divided","cn":"进一步分成的部分；分支；分部","g":"[countable]","ex":{"en":"a police subdivision (= the area covered by one particular police force)","cn":"警察部门下属的管辖分区"}},{"en":"an area of land that has been divided up for building houses on","cn":"（分割成小块的）建房土地","g":"[countable]","lab":"North American English"}]}},"sunlamp":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a lamp that produces a special light used for making your skin brown","cn":"太阳灯﹐紫外线灯"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41sunlamp.mp3","us":"media/ldoce/hwd/ame/2/sunlamp.mp3"},"oxford":{"phon":"ˈsʌnlæmp","pos":"noun","senses":[{"en":"a lamp that produces ultraviolet light that has the same effect as the sun and can turn the skin brown","cn":"太阳灯（能发出紫外线，与日照有相同效果）"}]}},"subsidiarity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"权力自主原则，权力下放原则(允许成员针对影响自身的问题自作主张)","en":"Subsidiarity is the principle of allowing the individual members of a large organization to make decisions on issues that affect them, rather than leaving those decisions to be made by the whole group.","ex":{"en":"The chancellor knows that the principle of subsidiarity must be guaranteed and shown to work.","cn":"财政大臣很清楚，必须保证权力下放原则得到贯彻执行并使之奏效。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a word meaning a political policy (1) in which power to make decisions is given to a smaller group – used especially about the European Union giving power to its member countries","cn":"权力下放政策﹐权力自主（原则）〔尤指欧盟给予各成员国更多自主权的政策〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/subsidiarity0205.mp3","us":"media/ldoce/hwd/ame/a/ld41subsidiarity.mp3"},"oxford":{"phon":"səbˌsɪdiˈærəti","pos":"noun","senses":[{"en":"the principle that a central authority should not be very powerful, and should only control things which cannot be controlled by local organizations","cn":"辅助原则，辅从原则（中央权力机关应只控制地方上无法操控的事务）"}]}},"successive":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"连续的;接连的;相继的","en":"Successive means happening or existing one after another without a break.","ex":{"en":"Jackson was the winner for a second successive year","cn":"杰克逊已经是连续第二年获胜了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening one after the other","cn":""},{"en":"consecutive days, years etc come after one another, with no breaks in between","cn":""},{"en":"happening immediately one after another in a series, especially in an unusually long series","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Successive is a word for things (or people) that follow each other in time. If three presidents in a row were over sixty, you could say \"Three successive presidents were over sixty.\""}]},"media":{"uk":"media/ldoce/hwd/bre/4/successive0205.mp3","us":"media/ldoce/hwd/ame/b/successive.mp3"},"examples":[{"en":"This concept has been applied successively to painting, architecture and sculpture.","cn":"这一概念相继应用于绘画、建筑和雕塑中。"},{"en":"Successive governments have tried to tackle the problem.","cn":"历届政府都试图解决这个问题。"}],"oxford":{"phon":"səkˈsesɪv","pos":"adjective","senses":[{"en":"following immediately one after the other","cn":"连续的；接连的；相继的","ex":{"en":"This was their fourth successive win.","cn":"这是他们连续第四次获胜。"}}]}},"suffuse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指色彩或感情)弥漫于，布满，充满","en":"If something, especially a colour or feeling, suffuses a person or thing, it gradually spreads over or through them.","ex":{"en":"A dull red flush suffused Selby's face.","cn":"塞尔比的脸庞泛起了淡淡的红晕。"}},{"pos":"VERB 动词","cn":"使充满，使洋溢着(某种品质)","en":"If something such as a book, film, or piece of music is suffused with a quality, it is full of that quality.","ex":{"en":"This book is suffused with Shaw's characteristic wry Irish humour","cn":"这本书充满了萧伯纳独特的爱尔兰式幽默与嘲讽。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if warmth, colour, liquid etc suffuses something or someone, it covers or spreads through them 〔","cn":"温暖﹑颜色﹑液体等〕充满﹐布满﹐弥漫于"},{"en":"if someone is suffused with a feeling, they are full of that feeling","cn":"充满某种情感"}]},"vocab":{"pos":"v","senses":[{"en":"Use suffuse to describe things that spread until they fill a space, like the infectious laughter that becomes a roar on a particularly good night at the comedy club. You might say comedy suffuses the area."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41suffuse.mp3","us":"media/ldoce/hwd/ame/3/suffuse.mp3"},"examples":[{"en":"Her face was suffused with colour.","cn":"她满脸通红。"},{"en":"Colour suffused her face.","cn":"她满脸通红。"}],"oxford":{"phon":"səˈfjuːz","pos":"verb","senses":[{"en":"to spread all over or through somebody/something","cn":"布满；弥漫于；充满","ex":{"en":"Her face was suffused with colour.","cn":"她满脸通红。"}}]}},"sunroof":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(汽车车顶可开启的)活动顶板，天窗","en":"A sunroof is a panel in the roof of a car that opens to let sunshine and air enter the car."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of the roof of a car that you can open to let in air and light 〔","cn":"汽车的〕活动顶篷﹐天窗"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sunroof.mp3","us":"media/ldoce/hwd/ame/a/sunroof.mp3"},"oxford":{"phon":"ˈsʌnruːf","pos":"noun","senses":[{"en":"a part of the roof of a car that you can open to let air and light in","cn":"（汽车车顶可开启的）活动顶板，天窗"}]}},"suburbia":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(新闻用语中通常作为总称)郊区","en":"Journalists often use suburbia to refer to the suburbs of cities and large towns considered as a whole.","ex":{"en":"...images of bright summer mornings in leafy suburbia.","cn":"夏日的清晨，郊区绿茵环绕阳光明媚的景象"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"suburbs in general, and the behaviour, opinions, and ways of living that are typical of people who live there – often used to show disapproval","cn":"郊区，郊区人的行为﹑观念和生活方式，郊区习俗〔常含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/suburbia0205.mp3","us":"media/ldoce/hwd/ame/7/suburbia.mp3"},"examples":[{"en":"middle-class suburbia","cn":"郊区中产阶级的生活状态"}],"oxford":{"phon":"səˈbɜːbiə","pos":"noun","senses":[{"en":"the suburbs and the way of life, attitudes, etc. of the people who live there","cn":"郊区及其居民的生活方式（或态度等）","ex":{"en":"the leafy avenues of middle-class suburbia","cn":"中产阶级郊区绿树成荫的大道"}}]}},"suave":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精明练达的;圆滑的;温文尔雅的","en":"Someone who is suave is charming, polite, and elegant, but may be insincere.","ex":{"en":"He is a suave, cool and cultured man.","cn":"他是个世故、冷静、有教养的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is smooth , especially a man, has good manners and a relaxed, confident way of talking to people, but in a way that you do not completely trust","cn":""},{"en":"very polite, pleasant and stylish, especially in a way that is intended to be attractive to women","cn":""},{"en":"someone who is suave is polite, confident, and relaxed, sometimes in an insincere way","cn":"温文尔雅的﹔自信而世故的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be suave is to be smooth, polite, a little bit cool with a splash of lime. Men can be suave and debonair, especially the ones riding horses on the covers of Romance novels."}]},"media":{"uk":"media/ldoce/hwd/bre/0/suave0205.mp3","us":"media/ldoce/hwd/ame/0/suave.mp3"},"examples":[{"en":"a suave and sophisticated gentleman","cn":"温文尔雅﹑精明练达的绅士"}],"oxford":{"phon":"swɑːv","pos":"adjective","senses":[{"en":"confident, attractive and polite, sometimes in a way that does not seem sincere","cn":"精明练达的；圆滑的","ex":{"en":"The manager was suave and sophisticated.","cn":"经理温文尔雅，老练。"}}]}},"sundial":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"日晷","en":"A sundial is a device used for telling the time when the sun is shining. The shadow of an upright rod falls onto a flat surface that is marked with the hours, and points to the correct hour."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object used in the past for telling the time. The shadow of a pointed piece of metal shows the time and moves round as the sun moves.","cn":"日晷"}]},"media":{"img":["media/ldoce/img/sundial.jpg","media/pic/sundial.jpg"],"uk":"media/ldoce/hwd/bre/f/sundial0205.mp3","us":"media/ldoce/hwd/ame/5/sundial.mp3"},"oxford":{"phon":"ˈsʌndaɪəl","pos":"noun","senses":[{"en":"a device used outdoors, especially in the past, for telling the time when the sun is shining. A pointed piece of metal throws a shadow on a flat surface that is marked with the hours like a clock, and the shadow moves around as the sun moves across the sky.","cn":"日晷"}]}},"susceptible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易受…影响的;易为…左右的","en":"If you are susceptible to something or someone, you are very likely to be influenced by them.","ex":{"en":"Young people are the most susceptible to advertisements","cn":"年轻人最容易受广告的影响。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易受(伤)的;易患(病)的;体质过敏的","en":"If you are susceptible to a disease or injury, you are very likely to be affected by it.","ex":{"en":"Walking with weights makes the shoulders very susceptible to injury","cn":"负重行走时肩膀很容易受伤。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感情丰富的;善变的","en":"A susceptible person is very easily influenced emotionally.","ex":{"en":"Hers was a susceptible nature.","cn":"她很情绪化。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"likely to suffer from a particular illness or be affected by a particular problem","cn":"易得病的﹔易受影响的"},{"en":"a susceptible person is easily influenced or attracted by someone or something 〔","cn":"人〕易受影响的"},{"en":"if something is susceptible of an action, that action can be done to it","cn":"可以做某事的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you are susceptible to something such as infections or earaches, it means you are likely to become sick with these things."}]},"collocations":{"phrases":["VERBS be, seem | become | remain | leave sb/sth, make sb/sth The operation had left her susceptible to infection.","ADV. easily, extremely, highly, particularly, readily, unusually, very certain highly susceptible individuals | quite, rather | genetically","PREP. to Some dogs are thought to be genetically susceptible to the disease."]},"media":{"uk":"media/ldoce/hwd/bre/7/susceptible0205.mp3","us":"media/ldoce/hwd/ame/3/susceptible.mp3"},"examples":[{"en":"Some of these plants are more susceptible to frost damage than others.","cn":"这些植物中有一些较其他的易受霜冻危害。"},{"en":"Salt intake may lead to raised blood pressure in susceptible adults.","cn":"盐的摄入可能导致易病的成年人血压升高。"}],"oxford":{"phon":"səˈseptəbl","pos":"adjective","senses":[{"en":"very likely to be influenced, harmed or affected by something","cn":"易受影响（或伤害等）","g":"[not usually before noun]","ex":{"en":"He's highly susceptible to flattery.","cn":"他爱听恭维话。"}},{"en":"easily influenced by feelings and emotions","cn":"好动感情的；感情丰富的；善感的","ex":{"en":"She was both charming and susceptible.","cn":"她迷人而多情。"}},{"en":"allowing something; capable of something","cn":"容许…的；可能…的；可以…的","lab":"formal","ex":{"en":"Is this situation not susceptible of improvement by legislation?","cn":"这种状况有没有可能通过立法加以改善？"}}]}},"sunbelt":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"阳光地带(尤指美国南部地区)","en":"The warmer, sunnier parts of a country or continent, especially the southern United States, are sometimes referred to as the sunbelt .","ex":{"en":"During the last recession, migration to the sunbelt accelerated.","cn":"在上个经济萧条期，人们向美国南部阳光地带移民的速度加快了。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the southern and southwestern parts of the US, from Virginia to South California. The name comes from the hot sunny climate in this area.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/p028-000011708.mp3","us":"media/ldoce/hwd/ame/2/p028-000011708.mp3"}},"subdivide":{"collins":{"senses":[{"pos":"VERB 动词","cn":"将…再分割;细分","en":"If something is subdivided, it is divided into several smaller areas, parts, or groups.","ex":{"en":"The verbs were subdivided into transitive and intransitive categories.","cn":"动词可细分为及物动词和不及物动词。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to divide into smaller parts something that is already divided","cn":"把〔分过的东西〕再分﹐细分"}]},"media":{"uk":"media/ldoce/hwd/bre/f/subdivide0205.mp3","us":"media/ldoce/hwd/ame/4/subdivide.mp3"},"examples":[{"en":"Over time, developers subdivided the land.","cn":"开发商们渐渐地把这块土地进行了再分割。"},{"en":"The house was subdivided into apartments.","cn":"房子又被分割成几个套间。"}],"oxford":{"phon":"ˈsʌbdɪvaɪd","pos":"verb","senses":[{"en":"to divide something into smaller parts; to be divided into smaller parts","cn":"（被）再分割，再分","ex":{"en":"Each of the chapters is subdivided into several double-page spreads.","cn":"每一章又被细分为几个跨页。"}}]}},"superfluous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"多余的;过剩的;不必要的","en":"Something that is superfluous is unnecessary or is no longer needed.","ex":{"en":"My presence at the afternoon's proceedings was superfluous","cn":"我去参加下午的活动是多此一举。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"more than is needed or wanted","cn":"多余的﹐过剩的﹐不必要的"}]},"vocab":{"pos":"adj","senses":[{"en":"When something is so unnecessary that it could easily be done away with, like a fifth wheel on a car or a fifth person on a double date, call it superfluous ."}]},"collocations":{"phrases":["VERBS be, feel, seem | become | make sth, render sth | consider sth","ADV. quite, totally, wholly She gave him a look that made words quite superfluous. | almost | rather"]},"media":{"uk":"media/ldoce/hwd/bre/5/superfluous0205.mp3","us":"media/ldoce/hwd/ame/7/superfluous.mp3"},"examples":[{"en":"She gave him a look that made words superfluous.","cn":"她看了他一眼，这已表明一切，无须多言了。"},{"en":"a modern building with no superfluous decoration","cn":"一栋没有多余装饰的现代建筑"}],"oxford":{"phon":"suːˈpɜːfluəs","pos":"adjective","senses":[{"en":"unnecessary or more than you need or want","cn":"多余的；过剩的；过多的","ex":{"en":"She gave him a look that made words superfluous.","cn":"她看了他一眼，这已表明一切，无须多言了。"}}]}},"subsection":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(法律文件等的)分款，分项，分部，分段","en":"A subsection of a text or a document such as a law is one of the smaller parts into which its main parts are divided."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a part of a section , especially in a legal document 〔","cn":"尤指法律文件的〕分款，分项"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41subsection.mp3","us":"media/ldoce/hwd/ame/d/subsection.mp3"},"oxford":{"phon":"ˈsʌbsekʃn","pos":"noun","senses":[{"en":"a part of a section, especially of a legal document","cn":"分部；分段；（尤指法律文件的）分款，分项","ex":{"en":"The case is described in subsection six below.","cn":"下文第六节描述了该案例。"}}]}},"supergrass":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"向警方告密的人;向警方揭发犯罪团伙的人","en":"A supergrass is a person who gives the police information about a large group of criminals."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a criminal who gives the police information about many other criminals, in order to get a less severe punishment 〔","cn":"为获得从轻处罚而〕向警方告密的罪犯﹐告发同伙的罪犯"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41supergrass.mp3","us":"media/ldoce/hwd/ame/e/ld41supergrass.mp3"},"oxford":{"phon":"ˈsuːpəɡrɑːs","pos":"noun","senses":[{"en":"a criminal who informs the police about the activities of a large number of other criminals, usually in order to get a less severe punishment","cn":"（为求得宽大处理）向警方告密的罪犯"}]}},"suburban":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"郊区的;城外的","en":"Suburban means relating to a suburb.","ex":{"en":"...a comfortable suburban home.","cn":"城外舒适的住所"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"平淡乏味的;呆板的;传统的","en":"If you describe something as suburban, you mean that it is dull and conventional.","ex":{"en":"His clothes are conservative and suburban.","cn":"他衣着保守而传统。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"conventional people, behaviour, and opinions are the type that most people in society think are normal and socially acceptable, although some people think they are boring and old-fashioned","cn":""},{"en":"thinking and behaving like everyone else, because you do not want to be different","cn":""},{"en":"conventional and often fairly boring","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"This refers to areas just beyond a city’s border. Many suburban homes have a pool."}]},"media":{"uk":"media/ldoce/hwd/bre/9/suburban0205.mp3","us":"media/ldoce/hwd/ame/a/suburban.mp3"},"examples":[{"en":"a suburban lifestyle","cn":"平淡乏味的生活方式"},{"en":"life in suburban London","cn":"伦敦郊区的生活"}],"oxford":{"phon":"səˈbɜːbən","pos":"adjective","senses":[{"en":"in or connected with a suburb","cn":"郊区的；城外的","g":"[usually before noun]","ex":{"en":"suburban areas","cn":"郊区地带"}},{"en":"boring and ordinary","cn":"平淡乏味的；呆板的","lab":"disapproving","ex":{"en":"a suburban lifestyle","cn":"平淡乏味的生活方式"}}]}},"subconscious":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"潜意识;下意识","en":"Your subconscious is the part of your mind that can influence you or affect your behaviour even though you are not aware of it.","ex":{"en":"...the hidden power of the subconscious","cn":"潜意识的潜在力量"}},{"pos":"ADJ 形容词","cn":"下意识的;潜意识的","en":"A subconscious feeling or action exists in or is influenced by your subconscious.","ex":{"en":"He caught her arm in a subconscious attempt to detain her.","cn":"他下意识地抓住她的胳膊想挽留她。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"affecting your mind or happening in your mind","cn":""},{"en":"affecting the mind - use this especially about mental problems that influence the way someone behaves","cn":""},{"en":"subconscious feelings, desires, worries etc are hidden in your mind and you do not realize that you have them","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Subconscious describes something that is just below your awareness, like at a subconscious level hoping your friend's boyfriend breaks up with her — you didn't even realize you felt that way until it happened."}]},"media":{"uk":"media/ldoce/hwd/bre/8/subconscious_a0205.mp3","us":"media/ldoce/hwd/ame/7/subconscious1.mp3"},"examples":[{"en":"Subconsciously, she was looking for the father she had never known.","cn":"她在下意识地寻找自己从未见过的父亲。"},{"en":"subconscious desires","cn":"下意识的欲望"}],"oxford":{"phon":"ˌsʌbˈkɒnʃəs","pos":"adjective","senses":[{"en":"connected with feelings that influence your behaviour even though you are not aware of them","cn":"下意识的；潜意识的","ex":{"en":"subconscious desires","cn":"下意识的欲望"}},{"en":"the part of your mind that contains feelings that you are not aware of","cn":"下意识；潜意识","ex":{"en":"Guilt made her try to bury the memory deep in her subconscious.","cn":"愧疚让她试图将这段记忆深深地埋藏在潜意识里。"},"pos":"noun"}]}},"sublet":{"collins":{"senses":[{"pos":"VERB 动词","cn":"转租，分租(租来的物业)","en":"If you sublet a building or part of a building, you allow someone to use it and you take rent from them, although you are not the owner and pay rent for it yourself.","ex":{"en":"The company rented the building, occupied part and sublet the rest.","cn":"该公司租下了这栋大楼，占用了一部分并转租了其余的部分。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to rent to someone else a property that you rent from its owner","cn":"将〔租来的物业〕转租﹐分租"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sublet0205.mp3","us":"media/ldoce/hwd/ame/c/sublet.mp3"},"examples":[{"en":"I sublet my apartment to my sister, packed my van, and headed west.","cn":"我把公寓转租给姐姐﹐将行李装了车﹐西行而去。"}],"oxford":{"phon":"ˌsʌbˈlet","pos":"verb","senses":[{"en":"to rent to somebody else all or part of a property that you rent from the owner","cn":"转租，分租（租来的物业）","lab":"especially North American English"}]}},"sulfate":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of sulphate sulphate","cn":"的美式拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41sulfate.mp3","us":"media/ldoce/hwd/ame/1/ld41sulfate.mp3"},"oxford":{"phon":"ˈsʌlfeɪt","pos":"noun","senses":[{"en":"a compound of sulphuric acid and a chemical element","cn":"硫酸盐"}]}},"subnormal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"低能的;弱智的","en":"If someone is subnormal, they have less ability or intelligence than a normal person of their age.","ex":{"en":"...educationally subnormal children.","cn":"学习能力低下的儿童"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"less or lower than normal","cn":"比正常少的﹐低于正常的"}]},"collocations":{"phrases":["VERBS be, seem | classify sb as, treat sb as","ADV. severely | educationally, mentally special provision for educationally subnormal children"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41subnormal.mp3","us":"media/ldoce/hwd/ame/f/subnormal.mp3"},"examples":[{"en":"educationally subnormal children","cn":"学习能力低下的儿童"},{"en":"subnormal temperatures","cn":"偏低的气温"}],"oxford":{"phon":"ˌsʌbˈnɔːml","pos":"adjective","senses":[{"en":"lower than normal","cn":"低于正常的；正常值以下的；偏低的","lab":"specialist","ex":{"en":"subnormal temperatures","cn":"偏低的气温"}},{"en":"a word used to describe somebody who has lower than average intelligence that is now considered offensive","cn":"低能的；弱智的","lab":"old-fashioned, offensive，，"}]}},"surname":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"姓","en":"Your surname is the name that you share with other members of your family. In English speaking countries and many other countries it is your last name.","ex":{"en":"She'd never known his surname","cn":"她一直不知道他姓什么。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the name that your parents choose for you when you are born, which in Western countries comes at the beginning of your full name","cn":""},{"en":"someone's first name, or the name that Christian parents choose for a baby when they christen it","cn":""},{"en":"the name that comes between your first and last names","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A surname is a person’s last name, or family name. Smith is a popular surname in the U.S., while Dieng is a popular surname in Senegal."}]},"collocations":{"phrases":["ADJ. double-barrelled, hyphenated","VERB + SURNAME bear, have | address/call sb by The teacher addresses the students by their surnames. | change | adopt, assume, take On marri"]},"media":{"uk":"media/ldoce/hwd/bre/4/surname0205.mp3","us":"media/ldoce/hwd/ame/9/surname.mp3"},"oxford":{"phon":"ˈsɜːneɪm","pos":"noun","senses":[{"en":"a name shared by all the members of a family (written last in English names)","cn":"姓","ex":{"en":"Rossi is a common surname in Italy.","cn":"Rossi （罗西）这个姓在意大利很常见。"}}]}},"surcharge":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"额外费用;附加费;增收费","en":"A surcharge is an extra payment of money in addition to the usual payment for something. It is added for a specific reason, for example by a company because costs have risen or by a government as a tax.","ex":{"en":"The government introduced a 15% surcharge on imports","cn":"政府对进口产品加收 15 %的附加费。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money that you must pay to the government, especially from the money you earn, or as an additional payment when you buy something","cn":""},{"en":"a tax you pay on something you buy","cn":""},{"en":"a tax on goods coming into a country or going out of a country, especially to protect a country’s industry from cheap goods from other countries","cn":""}]},"collocations":{"phrases":["ADJ. small | tax a corporate tax surcharge","VERB + SURCHARGE add, impose, levy, put A surcharge of 40 francs was added to our bill. A surcharge is levied on late applications. | pay","PREP. ~ for There is a surcharge for excess baggage. | ~ on There is a 2% surcharge on credit card users."]},"media":{"uk":"media/ldoce/hwd/bre/2/surcharge_n0205.mp3","us":"media/ldoce/hwd/ame/2/surcharge1.mp3"},"examples":[{"en":"We were surcharged £50 for travelling on a Friday.","cn":"因为在星期五旅行，我们多付了 50 英镑。"},{"en":"a 10% surcharge on airline tickets","cn":"飞机票10%的附加费"}],"oxford":{"phon":"ˈsɜːtʃɑːdʒ","pos":"noun","senses":[{"en":"an extra amount of money that you must pay in addition to the usual price","cn":"额外费用；附加费；增收费","ex":{"en":"There is a 2% surcharge on credit card users.","cn":"信用卡用户须付2% 的附加费。"}},{"en":"to make somebody pay a surcharge","cn":"向（某人）收取额外费用","ex":{"en":"We were surcharged £50 for travelling on a Friday.","cn":"因为在星期五旅行，我们多付了 50 英镑。"},"pos":"verb"}]}},"suppressant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(遏制身体正常功能的)遏抑剂","en":"A suppressant is a drug which is used to stop one of the natural functions of the body.","ex":{"en":"...the brief period in her life when she took Dexedrine as an appetite suppressant.","cn":"她服用德克塞根来抑制食欲的短暂时期"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug or medicine that makes you less hungry, cough less etc","cn":"食欲/咳嗽/疼痛等抑制剂"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41suppressant.mp3","us":"media/ldoce/hwd/ame/d/laadsuppressant.mp3"},"examples":[{"en":"an appetite suppressant","cn":"食欲遏抑剂"}],"oxford":{"phon":"səˈpresnt","pos":"noun","senses":[{"en":"a drug that is used to prevent one of the body’s functions from working normally","cn":"（对人体功能的）抑制药，抑制剂","ex":{"en":"an appetite suppressant","cn":"食欲抑制药"}}]}},"subcutaneous":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"皮下的","en":"Subcutaneous is used to indicate that something is situated, used, or put under your skin.","ex":{"en":"...subcutaneous fat.","cn":"皮下脂肪"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"beneath your skin","cn":"皮下的"}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective subcutaneous is a medical term that describes anything that exists or is inserted just below the skin."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41subcutaneous.mp3","us":"media/ldoce/hwd/ame/9/subcutaneous.mp3"},"examples":[{"en":"a subcutaneous injection","cn":"皮下注射"},{"en":"subcutaneous fat","cn":"皮下脂肪"}],"oxford":{"phon":"ˌsʌbkjuˈteɪniəs","pos":"adjective","senses":[{"en":"under the skin","cn":"皮下的","ex":{"en":"a subcutaneous injection","cn":"皮下注射"}}]}},"suds":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(肥皂等的)泡沫","en":"Suds are the bubbles that are produced when a substance such as soap is mixed with water.","ex":{"en":"He had soap suds in his ears.","cn":"他耳朵里进了肥皂泡。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the mass of bubbles formed on the top of water with soap in it","cn":"一团肥皂泡﹐肥皂泡沫"}]},"media":{"uk":"media/ldoce/hwd/bre/1/suds0205.mp3","us":"media/ldoce/hwd/ame/4/suds.mp3"},"examples":[{"en":"She was up to her elbows in suds.","cn":"她肘部以下都是肥皂沫子。"}],"oxford":{"phon":"sʌdz","pos":"noun","senses":[{"en":"a mass of very small bubbles that forms on top of water that has soap in it","cn":"肥皂泡沫","g":"[plural]","ex":{"en":"She was up to her elbows in suds.","cn":"她肘部以下都是肥皂沫子。"}},{"en":"beer","cn":"啤酒","g":"[uncountable]","lab":"old-fashioned, North American English, informal，，，，"}]}},"succor":{"lemma":"succour"},"substratum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"下层;底层;深层特征;隐性特质","en":"A substratum of something is a layer that lies under the surface of another layer, or a feature that is less obvious than other features.","ex":{"en":"...its deep substratum of chalk","cn":"深厚的白垩地层"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a layer that lies beneath another layer, especially in the earth","cn":"下层﹐底层；〔尤指〕底土层"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41substratum.mp3","us":"media/ldoce/hwd/ame/3/substratum.mp3"},"examples":[{"en":"a substratum of rock","cn":"底层岩石"},{"en":"a social substratum","cn":"社会底层"}],"oxford":{"phon":"ˈsʌbstrɑːtəm","pos":"noun","senses":[{"en":"a layer of something, especially rock or soil, that is below another layer","cn":"（尤指岩石或土壤的）底土层，下卧层","ex":{"en":"a substratum of clay","cn":"粘土基质"}}]}},"summation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"总结;概要;概括","en":"A summation is a summary of what someone has said or done.","ex":{"en":"Her introduction is a model of fairness, a lively summation of Irish history.","cn":"她的导论是客观公正的典范，是对爱尔兰历史的生动概括。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a summary or summing-up","cn":"总结﹐概要﹔〔法官在审判结束时作的〕总结"},{"en":"the total amount or number when two or more things are added together","cn":"总和﹐总数﹐合计"}]},"vocab":{"pos":"n","senses":[{"en":"A summation is a final review or conclusion, often given in a court of law. As the incompetent lawyer approached the bench for the final time, he told the judge and jury, \"In summation , my client is guilty of all charges.\""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41summation.mp3","us":"media/ldoce/hwd/ame/0/summation.mp3"},"examples":[{"en":"The exhibition presents a summation of the artist's career.","cn":"展览全面体现了这位画家的艺术生涯。"},{"en":"What he said was a fair summation of the discussion.","cn":"他这番话对讨论作了恰当的总结。"}],"oxford":{"phon":"sʌˈmeɪʃn","pos":"noun","senses":[{"en":"a summary of what has been done or said","cn":"总结；概括","g":"[usually singular]","lab":"formal","ex":{"en":"What he said was a fair summation of the discussion.","cn":"他这番话对讨论作了恰当的总结。"}},{"en":"a collection of different parts that forms a complete account or impression of somebody/something","cn":"汇总物；综合体","lab":"formal","ex":{"en":"The exhibition presents a summation of the artist's career.","cn":"展览全面展现了这位画家的艺术生涯。"}},{"en":"a final speech that a lawyer makes near the end of a trial in court, after all the evidence has been given","cn":"（判决前的）证据总结","lab":"North American English, law，，"}]}},"sumo":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"相扑(日本摔跤运动)","en":"Sumo is the Japanese style of wrestling.","ex":{"en":"...a sumo wrestler.","cn":"相扑运动员"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Japanese form of wrestling , done by men who are very large 〔","cn":"日本〕相扑"}]},"vocab":{"pos":"n","senses":[{"en":"Sumo is a Japanese wrestling style in which opponents try to force each other out of a ring. Sumo wrestlers are known for being enormous. The wrestlers live together and follow ancient traditions like growing their hair and wearing robes."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sumo.mp3","us":"media/ldoce/hwd/ame/2/sumo.mp3"},"examples":[{"en":"a sumo wrestler","cn":"相扑运动员"}],"oxford":{"phon":"ˈsuːməʊ","pos":"noun","senses":[{"en":"a Japanese style of wrestling, in which the people taking part are extremely large","cn":"相扑","ex":{"en":"a sumo wrestler","cn":"相扑运动员"}}]}},"superb":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极佳的;卓越的;质量极高的","en":"If something is superb, its quality is very good indeed.","ex":{"en":"There is a superb 18-hole golf course 6 miles away","cn":"6 英里外有一个一流的 18 洞高尔夫球场。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(信心、控制力、技巧)非同一般的，超凡的","en":"If you say that someone has superb confidence, control, or skill, you mean that they have very great confidence, control, or skill.","ex":{"en":"With superb skill he managed to make a perfect landing.","cn":"他凭借超凡的技术实现了完美着陆。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good","cn":"极好的﹐极妙的"},{"en":"extremely good","cn":"极好的﹐极妙的"},{"en":"extremely good","cn":"极好的﹐极妙的"}]},"vocab":{"pos":"adj","senses":[{"en":"The movie far surpassed expectations. It was superb . That 5-star hotel? Also superb . Anything that goes beyond being great can be called superb ."}]},"collocations":{"phrases":["VERBS be, look, sound She looked superb.","ADV. really | absolutely, quite, simply The cuisine is absolutely superb."]},"media":{"uk":"media/ldoce/hwd/bre/0/superb0205.mp3","us":"media/ldoce/hwd/ame/9/superb.mp3"},"examples":[{"en":"His performance was absolutely superb.","cn":"他的表演精彩绝伦。"},{"en":"The car's in superb condition.","cn":"这辆车车况极好。"}],"oxford":{"phon":"suːˈpɜːb","pos":"adjective","senses":[{"en":"excellent; of very good quality","cn":"极佳的；卓越的；精彩绝伦的","ex":{"en":"a superb player","cn":"杰出的运动员"}}]}},"sumptuous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"华贵的;豪华的;奢华的","en":"Something that is sumptuous is grand and obviously very expensive.","ex":{"en":"...a sumptuous feast","cn":"盛宴"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very impressive and expensive","cn":"豪华的﹐奢华的﹐奢侈的"}]},"vocab":{"pos":"adj","senses":[{"en":"Sumptuous could be used to describe a room appointed with the finest furniture, a lush orchestra playing a beautiful symphony, or a meal meant for a king. Sumptuous describes something that costs a lot and imparts sensory pleasure."}]},"media":{"uk":"media/ldoce/hwd/bre/0/sumptuous0205.mp3","us":"media/ldoce/hwd/ame/1/sumptuous.mp3"},"examples":[{"en":"We dined in sumptuous surroundings.","cn":"我们在富丽堂皇的环境中用餐。"},{"en":"a sumptuous meal","cn":"盛宴"}],"oxford":{"phon":"ˈsʌmptʃuəs","pos":"adjective","senses":[{"en":"very expensive and looking very impressive","cn":"华贵的；豪华的；奢华的","ex":{"en":"a sumptuous meal","cn":"盛宴"}}]}},"suction":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"吸;抽吸;吸出","en":"Suction is the process by which liquids, gases, or other substances are drawn out of somewhere.","ex":{"en":"Dustbags act as a filter and suction will be reduced if they are too full","cn":"集尘袋起着过滤的作用，所集的灰尘太多时其吸附作用就会减小。"}},{"pos":"VERB 动词","cn":"(用医疗器械)抽吸，吸出","en":"If a doctor or nurse suctions a liquid, they remove it by using a machine which sucks it away.","ex":{"en":"Michael was showing the nurse how to suction his saliva","cn":"迈克尔正给护士示范如何把他的唾液吸出来。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(平面的)相吸","en":"Suction is the process by which two surfaces stick together when the air between them is removed.","ex":{"en":"...their pneumatic robot which uses air to move and sticks to surfaces by suction.","cn":"他们的气动机器人依靠空气来移动，靠吸力附着于物体表面"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process of removing air or liquid from an enclosed space so that another substance is sucked in, or so that two surfaces stick together 〔","cn":"对空气或液体的〕吸﹐抽吸﹐吸出"},{"en":"the force that causes a substance to be sucked into a closed space when the air or liquid already present is removed 〔","cn":"由真空状态等产生的〕吸力"}]},"media":{"uk":"media/ldoce/hwd/bre/c/suction0205.mp3","us":"media/ldoce/hwd/ame/e/suction.mp3"},"examples":[{"en":"Vacuum cleaners work by suction.","cn":"真空吸尘器靠抽吸除尘。"},{"en":"a suction pump/pad","cn":"抽吸泵；吸力垫"}],"oxford":{"phon":"ˈsʌkʃn","pos":"verb","senses":[{"en":"to remove air or liquid from a space or container so that something else can be taken into it or so that two surfaces can stick together","cn":"吸；抽吸；吸出"},{"en":"the process of removing air or liquid from a space or container so that something else can be taken into it or so that two surfaces can stick together","cn":"抽吸；吸出","ex":{"en":"Vacuum cleaners work by suction.","cn":"真空吸尘器靠抽吸除尘。"},"pos":"noun"}]}},"suppress":{"collins":{"senses":[{"pos":"VERB 动词","cn":"镇压;制止;压制","en":"If someone in authority suppresses an activity, they prevent it from continuing, by using force or making it illegal.","ex":{"en":"...drug traffickers, who continue to flourish despite international attempts to suppress them","cn":"在国际社会强力打击下活动依然猖獗的贩毒分子"}},{"pos":"VERB 动词","cn":"制止，阻止，抑制(身体的功能或反应)","en":"If a natural function or reaction of your body is suppressed, it is stopped, for example by drugs or illness.","ex":{"en":"The reproduction and growth of the cancerous cells can be suppressed by bombarding them with radiation.","cn":"可以通过放疗杀死癌细胞来抑制其再生和扩散。"}},{"pos":"VERB 动词","cn":"抑制，控制，克制(感情或反应);忍住","en":"If you suppress your feelings or reactions, you do not express them, even though you might want to.","ex":{"en":"Liz thought of Barry and suppressed a smile","cn":"莉兹想起了巴里，忍住没笑。"}},{"pos":"VERB 动词","cn":"封锁，隐瞒(消息)","en":"If someone suppresses a piece of information, they prevent other people from learning it.","ex":{"en":"At no time did they try to persuade me to suppress the information","cn":"他们从没有试图劝我隐瞒这个消息。"}},{"pos":"VERB 动词","cn":"压制，抑制，阻止(进程或活动)","en":"If someone or something suppresses a process or activity, they stop it continuing or developing.","ex":{"en":"'The Government is suppressing inflation by devastating the economy,' he said","cn":"他说，“政府正在通过破坏经济来抑制通货膨胀。”"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hide facts or the truth about something, especially by not giving people enough information about it or by lying","cn":""},{"en":"to do things that prevent people from finding out mistakes or unpleasant facts","cn":""},{"en":"to prevent important facts or information from being made known in a public or official situation","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To suppress something means to curb, inhibit, or even stop it. If the sound of your boss moving in his chair sounds like gas, you’re going to have to learn how to suppress your giggles."}]},"collocations":{"phrases":["ADV. bloodily, brutally, ruthlessly, vigorously, violently A pro-democracy uprising was brutally suppressed.","VERB + SUPPRESS attempt to, seek to, try to | use sth to using violence to suppress opposition","PHRASES an attempt to suppress sth 2 stop sth from being seen/known","ADV. completely | effectively The medication effectively suppressed the pain. | deliberately This information had been deliberately suppress","VERB + SUPPRESS attempt to, seek to, try to","PHRASES an attempt to suppress sth 3 stop yourself doing/expressing sth","ADV. firmly | hardly He could hardly suppress his surprise. | instantly The disloyal thought was instantly suppressed. | quickly","VERB + SUPPRESS be unable to, cannot/could not She was unable to suppress a giggle. | try to | manage to | be hard to"]},"media":{"uk":"media/ldoce/hwd/bre/3/suppress0205.mp3","us":"media/ldoce/hwd/ame/2/suppress.mp3"},"examples":[{"en":"The rebellion was brutally suppressed.","cn":"叛乱遭到了残酷的镇压。"},{"en":"The police were accused of suppressing vital evidence.","cn":"警方被指隐瞒关键证据。"}],"oxford":{"phon":"səˈpres","pos":"verb","senses":[{"en":"to put an end, often by force, to a group or an activity that is believed to threaten authority","cn":"镇压；（武力）平定；压制","lab":"usually disapproving","ex":{"en":"The rebellion was brutally suppressed.","cn":"叛乱遭到了残酷的镇压。"}},{"en":"to prevent something from being published or made known","cn":"禁止（发表）；查禁；封锁","lab":"usually disapproving","ex":{"en":"The police were accused of suppressing vital evidence.","cn":"警方被指隐瞒关键证据。"}},{"en":"to prevent yourself from having or expressing a feeling or an emotion","cn":"抑制；控制；忍住","ex":{"en":"to suppress a smile","cn":"忍住不笑"}},{"en":"to prevent something from growing, developing or continuing","cn":"压制；阻止；抑制","ex":{"en":"drugs that suppress the appetite","cn":"抑制食欲的药"}}]}},"supercilious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自高自大的;目空一切的;傲慢的","en":"If you say that someone is supercilious, you disapprove of them because they behave in a way that shows they think they are better than other people.","ex":{"en":"His manner is supercilious and arrogant","cn":"他非常傲慢自大。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"behaving as if you think that other people are less important than you – used to show disapproval","cn":"高傲的﹐傲慢的﹐目中无人的〔含贬义〕"}]},"vocab":{"pos":"adj","senses":[{"en":"Supercilious people think very highly of themselves, more highly than of others. Think of them as a \"super silly ass,\" and you'll remember the basic sense of supercilious ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41supercilious.mp3","us":"media/ldoce/hwd/ame/8/supercilious.mp3"},"examples":[{"en":"supercilious wine waiters","cn":"傲慢的侍酒师"}],"oxford":{"phon":"ˌsuːpəˈsɪliəs","pos":"adjective","senses":[{"en":"behaving towards other people as if you think you are better than they are","cn":"傲慢的；高傲的","ex":{"en":"The dress shop assistant was very supercilious.","cn":"服装店的店员很傲慢。"}}]}},"sunblock":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"防晒霜;防晒油","en":"Sunblock is a cream which you put on your skin to protect it completely from the sun."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"cream or oil that you rub into your skin, in order to completely stop the sun’s light from burning you","cn":"防晒霜，防晒油"}]},"media":{"uk":"media/ldoce/hwd/bre/6/sunblock0205.mp3","us":"media/ldoce/hwd/ame/2/sun_block.mp3"},"oxford":{"phon":"ˈsʌnblɒk","pos":"noun","senses":[{"en":"a cream that you put on your skin to protect it from the harmful effects of the sun","cn":"防晒霜；防晒油"}]}},"superpower":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超级大国","en":"A superpower is a very powerful and influential country, usually one that is rich and has nuclear weapons.","ex":{"en":"The United States could claim to be both a military and an economic superpower.","cn":"美国在军事和经济上都称得上是超级大国。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an area of land controlled by its own government, president, king etc","cn":""},{"en":"a country, considered especially in relation to its people and its political and economic structure","cn":""},{"en":"a country considered as a political organization with its own government","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The noun superpower is good for talking about a very powerful country, especially one that's strong enough to influence the way other countries act."}]},"media":{"uk":"media/ldoce/hwd/bre/b/superpower0205.mp3","us":"media/ldoce/hwd/ame/e/laadsuperpower.mp3"},"oxford":{"phon":"ˈsuːpəpaʊə(r)","pos":"noun","senses":[{"en":"one of the countries in the world that has very great military or economic power and a lot of influence, for example the US","cn":"超级大国","ex":{"en":"Japan's status as an economic superpower","cn":"日本作为经济强国的地位"}},{"en":"a special power or ability that somebody has, especially a superhero","cn":"（尤指超级英雄的）超能力，超级力量","ex":{"en":"She uses her superpowers to fight evil.","cn":"她利用自己的超能力来对抗邪恶。"}}]}},"subtract":{"collins":{"senses":[{"pos":"VERB 动词","cn":"减;减去","en":"If you subtract one number from another, you do a calculation in which you take it away from the other number. For example, if you subtract 3 from 5, you get 2.","ex":{"en":"Mandy subtracted the date of birth from the date of death","cn":"曼迪用去世的日期减去出生的日期。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put two or more numbers together to find the total","cn":""},{"en":"to reduce one number by another number. take something away sounds more informal than subtract","cn":""},{"en":"to add a number to itself a particular number of times","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/8/subtract0205.mp3","us":"media/ldoce/hwd/ame/d/subtract.mp3"},"examples":[{"en":"6 subtracted from 9 is 3. * 9","cn":"减 6 等于 3。"},{"en":"6 subtracted from 9 is 3.","cn":""}],"oxford":{"phon":"səbˈtrækt","pos":"verb","senses":[{"en":"to take a number or an amount away from another number or amount","cn":"减；减去","ex":{"en":"6 subtracted from 9 is 3.","cn":"9 减 6 等于 3。"}}]}},"submariner":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"潜艇水兵;乘潜艇者","en":"A submariner is a sailor or other person who goes in a submarine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sailor living and working in a submarine","cn":"潜艇水手"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41submariner.mp3","us":"media/ldoce/hwd/ame/1/laadsubmariner.mp3"},"oxford":{"phon":"sʌbˈmærɪnə(r)","pos":"noun","senses":[{"en":"a sailor who works on a submarine","cn":"潜艇水兵"}]}},"subjunctive":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"虚拟式;虚拟语气","en":"In English, a clause expressing a wish or suggestion can be put in the subjunctive, or in the subjunctive mood, by using the base form of a verb or 'were'. Examples are 'He asked that they be removed' and 'I wish I were somewhere else'. These structures are formal."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a verb form or a set of verb forms in grammar, used in some languages to express doubt, wishes etc. For example, in ‘if I were you’, the verb ‘to be’ is in the subjunctive. 〔","cn":"语法中的〕虚拟式〔如在if I were you中﹐be动词是虚拟式〕"}]},"vocab":{"pos":"adj n","senses":[{"en":"The subjunctive is a verb mood that expresses a possibility. Subjunctive phrases often begin with the words, \"If I were...\""}]},"media":{"uk":"media/ldoce/hwd/bre/7/subjunctive0205.mp3","us":"media/ldoce/hwd/ame/8/subjunctive.mp3"},"examples":[{"en":"In ‘I wish I were taller’, ‘were’ is a subjunctive.","cn":"在 I wish I were taller 中，were 是虚拟式。"},{"en":"The verb is in the subjunctive.","cn":"这个动词是虚拟语气。"}],"oxford":{"phon":"səbˈdʒʌŋktɪv","pos":"adjective","senses":[{"en":"in the form (or mood) that expresses wishes, possibility or uncertainty","cn":"虚拟式；虚拟语气","ex":{"en":"the subjunctive mood","cn":"虚拟语气"}},{"en":"the form (or mood) of a verb that expresses wishes, possibility or uncertainty; a verb in this form","cn":"虚拟式；虚拟语气","ex":{"en":"The verb is in the subjunctive.","cn":"这个动词是虚拟语气。"},"pos":"noun"}]}},"subcommittee":{"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"小组委员会","en":"A subcommittee is a small committee made up of members of a larger committee."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small group formed from a committee to deal with a particular subject in more detail 〔","cn":"委员会下设的〕专门小组"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41subcommittee.mp3","us":"media/ldoce/hwd/ame/4/subcommittee.mp3"},"oxford":{"phon":"ˈsʌbkəmɪti","pos":"noun","senses":[{"en":"a smaller committee formed from a main committee in order to study a particular subject in more detail","cn":"（委员会内的）小组委员会","ex":{"en":"the House of Representatives subcommittee on taxation","cn":"众议院税收小组委员会"}}]}},"subset":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小组;分组;子集","en":"A subset of a group of things is a smaller number of things that belong together within that group.","ex":{"en":"...subsets of the population such as men, women, ethnic groups, etc.","cn":"男性、女性、种族等人口的细分"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of people or things that is part of a larger group of people or things","cn":"分组﹐小组﹔子集"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun subset when you're talking about a group of things that fit in a larger category. For example, \"new horror films\" or \"new comedies\" are subsets of \"new movies.\""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41subset.mp3","us":"media/ldoce/hwd/ame/7/subset.mp3"},"examples":[{"en":"a small subset of the city’s immigrant population","cn":"该城市移民人口中的一小部分"}],"oxford":{"phon":"ˈsʌbset","pos":"noun","senses":[{"en":"a smaller group of people or things formed from the members of a larger group","cn":"分组；小组；子集","ex":{"en":"a subset of the people who took part in the survey","cn":"参与调查的一部分人"}}]}},"superintendent":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(英国的)警司;(美国的)警察局局长","en":"In Britain, a superintendent is a senior police officer of the rank above an inspector. In the United States, a superintendent is the head of a police department.","ex":{"en":"He was stopped at the airport by an assistant superintendent of police.","cn":"他在机场被一名助理警长扣留了。"}},{"pos":"N-COUNT 可数名词","cn":"(部门)主管，负责人","en":"A superintendent is a person who is responsible for a particular thing or the work done in a particular department.","ex":{"en":"He became superintendent of the bank's East African branches","cn":"他成了该银行东非分行的行长。"}},{"pos":"N-COUNT 可数名词","cn":"(大楼的)管理员","en":"A superintendent is a person whose job is to look after a large building such as a school or a block of flats and deal with small repairs to it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a high rank in the British police, or someone who has this rank 〔","cn":"英国的〕警司（职位）"},{"en":"someone who is in charge of all the schools in a particular area in the US 〔","cn":"美国的〕地区教育主管"},{"en":"someone who is officially in charge of a place, job, activity etc","cn":"主管人，负责人"}]},"vocab":{"pos":"n","senses":[{"en":"A superintendent is the overseer of an organization. The term superintendent is most often used to refer to someone who oversees a school district and — most importantly — decides when to declare a snow day."}]},"media":{"uk":"media/ldoce/hwd/bre/2/superintendent0205.mp3","us":"media/ldoce/hwd/ame/3/superintendent.mp3"},"examples":[{"en":"the superintendent of schools in Dallas","cn":"达拉斯教育局长"},{"en":"a park superintendent","cn":"公园负责人"}],"oxford":{"phon":"ˌsuːpərɪnˈtendənt","pos":"noun","senses":[{"en":"a person who has a lot of authority and manages and controls an activity, a place, a group of workers, etc.","cn":"主管人；负责人；监管人；监督人","ex":{"en":"a park superintendent","cn":"公园负责人"}},{"en":"(in the UK) a police officer just above the rank of chief inspector","cn":"（英国）警司（警阶为总督察的上一级）","ex":{"en":"Superintendent Livesey","cn":"利夫西警司"}},{"en":"(in the US) the head of a police department","cn":"（美国）警察局长，总警监"},{"en":"a person whose job is to be in charge of a building and make small repairs, etc. to it","cn":"（大楼的）管理人","lab":"North American English"}]}},"subversive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"颠覆性的;破坏性的","en":"Something that is subversive is intended to weaken or destroy a political system or government.","ex":{"en":"This courageous and subversive movie has attracted widespread critical support.","cn":"这部大胆而具颠覆性的电影引起了评论界广泛的支持。"}},{"pos":"N-COUNT 可数名词","cn":"颠覆分子;破坏分子","en":"Subversives are people who attempt to weaken or destroy a political system or government.","ex":{"en":"Agents regularly rounded up suspected subversives.","cn":"特工定期围捕可疑的颠覆分子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"subversive ideas, activities etc are secret and intended to damage or destroy a government or an established system 〔","cn":"观点﹑活动等对政府或现有制度具有〕颠覆性的"},{"en":"someone who encourages people to oppose the government by trying to make them angry enough to use violence","cn":""},{"en":"someone who spends a lot of time trying to encourage people to oppose the government or to accept new and different political beliefs","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"You might want to call someone subversive if they are sneakily trying to undermine something, from the social structure of your high school to an entire system of government."}]},"collocations":{"phrases":["ADJ. dangerous"]},"media":{"uk":"media/ldoce/hwd/bre/c/subversive_adj0205.mp3","us":"media/ldoce/hwd/ame/8/subversive1.mp3"},"examples":[{"en":"He was a known political subversive.","cn":"他是一个有名的政治颠覆分子。"},{"en":"He was engaged in subversive activities .","cn":"他参与了颠覆活动。"}],"oxford":{"phon":"səbˈvɜːsɪv","pos":"noun","senses":[{"en":"a person who tries to destroy or damage a government or political system by attacking it secretly or indirectly","cn":"颠覆性的；暗中起破坏作用的","ex":{"en":"He was a known political subversive.","cn":"他是一个众所周知的政治颠覆分子。"}},{"en":"trying or likely to destroy or damage a government or political system by attacking it secretly or indirectly","cn":"颠覆性的；暗中起破坏作用的","ex":{"en":"subversive activities","cn":"颠覆活动"},"pos":"adjective"}]}},"supremo":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"最高领导人;总管;总指挥;权威;王者","en":"A supremo is someone who is considered to have the most authority or skill in a particular organization, situation, or area of activity.","ex":{"en":"Her new role as fashion supremo is something she can really get her teeth into.","cn":"时尚总监这个新职务能让她全身心投入工作。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who controls a particular activity, organization, or industry, and has unlimited powers","cn":"最高权威﹐最高领导人"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41supremo.mp3","us":"media/ldoce/hwd/ame/7/ld41supremo.mp3"},"examples":[{"en":"the Microsoft supremo, Bill Gates","cn":"微软总裁比尔 · 盖茨"}],"oxford":{"phon":"suˈpriːməʊ","pos":"noun","senses":[{"en":"a person who has the most power or authority in a particular business or activity","cn":"（企业或活动的）最高领导人，总管，总指挥","ex":{"en":"the world football supremo, Gianni Infantino","cn":"世界足球掌门人——詹尼·因凡蒂诺"}}]}},"surefooted":{"lemma":"sure-footed"},"supernova":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超新星","en":"A supernova is an exploding star.","ex":{"en":"At least one supernova occurs per decade in our galaxy.","cn":"在我们的星系中每 10 年至少有一颗超新星出现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large ball of burning gas in space, which can be seen at night as a point of light in the sky","cn":""},{"en":"one of the large objects that goes around the Sun, for example the Earth, Saturn, Mercury, or Mars","cn":""},{"en":"the star that gives us light and heat, around which the planets move. There are also many millions of other suns in the universe","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Supernova is an astronomical term for a star that explodes like crazy. When a star turns into a supernova , it becomes extremely bright."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41supernova.mp3","us":"media/ldoce/hwd/ame/a/supernova.mp3"},"oxford":{"phon":"ˈsuːpənəʊvə","pos":"noun","senses":[{"en":"a star that suddenly becomes much brighter because it is exploding","cn":"超新星"}]}},"suntanned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"晒得黝黑的;晒成古铜色的","en":"Someone who is suntanned has an attractive brown colour from being in the sun.","ex":{"en":"He is always suntanned and incredibly fit.","cn":"他总是皮肤黝黑，无比健康。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"brown skin that someone with pale skin gets after they have spent time in the sun","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/suntan0205.mp3","us":"media/ldoce/hwd/ame/d/suntan.mp3"},"examples":[{"en":"a suntanned face","cn":"晒得黝黑的脸庞"}],"oxford":{"phon":"ˈsʌntænd","pos":"adjective","senses":[{"en":"having a brown skin colour as a result of being in the sun","cn":"皮肤晒成褐色的；晒黑的","ex":{"en":"a suntanned face","cn":"晒黑的脸"}}]}},"suv":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"多功能越野车","en":"An SUV is a powerful vehicle with four-wheel drive that can be driven over rough ground. SUV is an abbreviation for (缩略=) 'sport utility vehicle'."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of vehicle that is bigger than a car and is made for travelling over rough ground","cn":"运动型多用途车"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld42suv.mp3","us":"media/ldoce/hwd/ame/c/laadsuv.mp3"},"oxford":{"phon":"ˌes juː ˈviː","pos":"noun","senses":[{"en":"sport utility vehicle","cn":"运动型多功能汽车"}]}},"suggestible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易受影响的;耳根软的","en":"Someone who is suggestible can be easily influenced by other people.","ex":{"en":"...highly suggestible and compliant individuals.","cn":"那些毫无主见、对别人言听计从的人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"easily influenced by other people or by things you see and hear","cn":"易受影响的"},{"en":"very/highly/extremely suggestible At that age, kids are highly suggestible.","cn":"小孩在那个年龄非常容易受影响。"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41suggestible.mp3","us":"media/ldoce/hwd/ame/a/suggestible.mp3"},"examples":[{"en":"He was young and highly suggestible.","cn":"当时他年轻，很容易听信他人。"}],"oxford":{"phon":"səˈdʒestəbl","pos":"adjective","senses":[{"en":"easily influenced by other people","cn":"易受他人影响的","ex":{"en":"He was young and highly suggestible.","cn":"当时他年轻，很容易受人影响。"}}]}},"superimpose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使(一图像)叠映在(另一图像)上;使(图像)叠加","en":"If one image is superimposed on another, it is put on top of it so that you can see the second image through it.","ex":{"en":"His picture was superimposed on a muscular body","cn":"他的照片被移花接木，放在了一个肌肉发达的身体上。"}},{"pos":"VERB 动词","cn":"使同样适用于;将…强加于","en":"If features or characteristics from one situation are superimposed onto or on another, they are transferred onto or used in the second situation, though they may not fit.","ex":{"en":"Patterns of public administration and government are superimposed on traditional societies.","cn":"公共管理和执政模式移用于传统社会。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put one picture, image, or photograph on top of another so that both can be partly seen","cn":"使〔图画﹑图像或照片〕重叠﹐使叠加"},{"en":"to combine two systems, ideas, opinions etc so that one influences the other","cn":"使〔两种制度﹑思想﹑意见等〕相结合﹐使融合"}]},"vocab":{"pos":"v","senses":[{"en":"Superimpose means laying one thing on top of another. It's often use to describe images in a photo collage — like the superimposed image of a skyscraper on the surface of the moon."}]},"media":{"uk":"media/ldoce/hwd/bre/1/superimpose0205.mp3","us":"media/ldoce/hwd/ame/6/superimpose.mp3"},"examples":[{"en":"A diagram of the new road layout was superimposed on a map of the city.","cn":"新公路的规划示意图被叠映在该城市的地图上。"},{"en":"She has tried to superimpose her own attitudes onto this ancient story.","cn":"她尝试过把自己的看法加入这个古老的故事里。"}],"oxford":{"phon":"ˌsuːpərɪmˈpəʊz","pos":"verb","senses":[{"en":"to put one image on top of another so that the two can be seen combined","cn":"使（图像甲）叠映在（图像乙）上","ex":{"en":"A diagram of the new road layout was superimposed on a map of the city.","cn":"新公路的规划示意图被叠映在该城市的地图上。"}},{"en":"to add some of the qualities of one system or pattern to another one in order to produce something that combines the qualities of both","cn":"使重叠；使叠加；使附加于","ex":{"en":"She has tried to superimpose her own attitudes onto this ancient story.","cn":"她尝试过把自己的看法加入这个古老的故事里。"}}]}},"subliminal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"下意识的;潜意识的","en":"Subliminal influences or messages affect your mind without you being aware of it.","ex":{"en":"Colour has a profound, though often subliminal influence on our senses and moods.","cn":"颜色会极大地影响我们的感官和情绪，而这种影响常常是潜意识的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"affecting your mind or happening in your mind","cn":""},{"en":"affecting the mind - use this especially about mental problems that influence the way someone behaves","cn":""},{"en":"subconscious feelings, desires, worries etc are hidden in your mind and you do not realize that you have them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Each of your five senses constantly sends new information to your brain. And there’s another way your brain receives information: through subliminal messages. The unconscious mind picks up on things you don’t even realize."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41subliminal.mp3","us":"media/ldoce/hwd/ame/5/subliminal.mp3"},"examples":[{"en":"subliminal advertising","cn":"隐性广告"},{"en":"subliminal advertising (= with hidden messages and pictures in it )","cn":"潜意识广告"}],"oxford":{"phon":"ˌsʌbˈlɪmɪnl","pos":"adjective","senses":[{"en":"affecting your mind even though you are not aware of it","cn":"下意识的；潜意识的","ex":{"en":"There are strict laws against subliminal advertising.","cn":"有严格的法律禁止潜意识广告。"}}]}},"sunburn":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"晒伤;(因过度晒太阳而引起的)皮肤灼伤","en":"If someone has sunburn, their skin is bright pink and sore because they have spent too much time in hot sunshine.","ex":{"en":"The risk and severity of sunburn depend on the body's natural skin colour","cn":"晒伤的风险和严重程度取决于人体的自然肤色。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"red and painful skin that you can get from spending too much time in the sun","cn":"晒伤﹐〔日晒过量而引起的〕皮肤灼痛"}]},"media":{"uk":"media/ldoce/hwd/bre/8/sunburn0205.mp3","us":"media/ldoce/hwd/ame/7/sunburn.mp3"},"oxford":{"phon":"ˈsʌnbɜːn","pos":"noun","senses":[{"en":"the condition of having painful red skin because you have spent too much time in the sun","cn":"晒斑；晒伤","ex":{"en":"He was taken to hospital suffering from severe sunburn.","cn":"他因严重晒伤被送往医院。"}}]}},"survivor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"幸存者;生还者;幸免于难者","en":"A survivor of a disaster, accident, or illness is someone who continues to live afterwards in spite of coming close to death.","ex":{"en":"Officials said there were no survivors of the plane crash.","cn":"官方说这次飞机失事无一人生还。"}},{"pos":"N-COUNT 可数名词","cn":"遭遇过(不幸经历)的人;经受过(苦难)的人","en":"A survivor of a very unpleasant experience is a person who has had such an experience, and who is still affected by it.","ex":{"en":"This book is written with survivors of child sexual abuse in mind.","cn":"这本书关注的是童年时遭受过性骚扰的人。"}},{"pos":"N-COUNT 可数名词","cn":"(死者的)尚在世的家人;遗属","en":"A person's survivors are the members of their family who continue to live after they have died.","ex":{"en":"The compensation bill offers the miners or their survivors as much as $100,000 apiece.","cn":"这笔补偿金能向矿工或遇难矿工的家属每人赔偿100,000美元。"}},{"pos":"N-COUNT 可数名词","cn":"能在艰苦环境中生存的人;挺过困难者","en":"If you describe someone as a survivor, you approve of the fact that they are able to carry on with their life even though they experience many difficulties.","ex":{"en":"Above all Susie is a great survivor, with a bright, indomitable spirit.","cn":"总之，苏茜不畏艰难，开朗乐观、不屈不挠。"}},{"pos":"N-COUNT 可数名词","cn":"活到现在的人;留存至今的事物","en":"If you describe a person or thing as a survivor from an earlier period, you mean that they are still present or available, but other people or things from that period have died or disappeared.","ex":{"en":"Rafferty was the sole survivor from the successful Ireland team of 1988.","cn":"拉弗蒂是 1988 年红极一时的爱尔兰队硕果仅存的球员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has survived an accident, war, illness etc","cn":""},{"en":"to continue to live and not die when you are in a very dangerous situation, for example in a war or when you have very little food","cn":""},{"en":"to survive and get better after having a very serious illness or injury","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A survivor is someone who hasn't died: the word is used often about people who have been through a horrible experience, like a plane crash."}]},"collocations":{"phrases":["ADJ. great Like all great survivors, she has a ruthless streak. | the last, the only, a rare, the sole This grand park is a rare survivor fr","VERB + SURVIVOR find, pick up, rescue The navy helped pick up the survivors. | look/search for The emergency services searched all night for","PREP. ~ from a survivor from the Titanic"]},"media":{"uk":"media/ldoce/hwd/bre/6/survivor0205.mp3","us":"media/ldoce/hwd/ame/c/survivor.mp3"},"examples":[{"en":"She'll cope. She's one of life's great survivors (= sb who deals very well with difficult situations).","cn":"她能挺过去。生活中什么样的困难她都能对付。"},{"en":"The plane crashed in an area of dense jungle. There were no survivors.","cn":"飞机坠落在一个丛林茂密的地区。无人生还。"}],"oxford":{"phon":"səˈvaɪvə(r)","pos":"noun","senses":[{"en":"a person who continues to live, especially despite being nearly killed or experiencing great danger or difficulty","cn":"幸存者；生还者；挺过困难者","ex":{"en":"the sole/only survivor of the massacre","cn":"那场大屠杀的唯一幸存者"}}]}},"sulphate":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"硫酸盐","en":"A sulphate is a salt of sulphuric acid.","ex":{"en":"...copper sulphate.","cn":"硫酸铜"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a salt formed from sulphuric acid","cn":"硫酸盐"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41sulphate.mp3","us":"media/ldoce/hwd/ame/d/laadsulphate.mp3"},"examples":[{"en":"copper sulphate","cn":"硫酸铜"}],"oxford":{"phon":"ˈsʌlfeɪt","pos":"noun","senses":[{"en":"a compound of sulphuric acid and a chemical element","cn":"硫酸盐","ex":{"en":"copper sulphate","cn":"硫酸铜"}}]}},"subscriber":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(杂志或报纸的)订阅人，订购者，订户","en":"A magazine's or a newspaper's subscribers are the people who pay to receive copies of it regularly.","ex":{"en":"I have been a subscriber to Railway Magazine for many years.","cn":"我订阅《铁路杂志》已有很多年了。"}},{"pos":"N-COUNT 可数名词","cn":"消费者;用户","en":"Subscribers to a service are the people who pay to receive the service.","ex":{"en":"China has almost 15 million subscribers to satellite and cable television.","cn":"中国有将近 1,500 万卫星电视和有线电视用户。"}},{"pos":"N-COUNT 可数名词","cn":"(慈善机构、活动的)定期捐款者，定期捐助者;(组织的)定期缴费者，会员","en":"The subscribers to a charity, campaign, or organization are the people who support it by sending money regularly to it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who pays money, usually once a year, to receive copies of a newspaper or magazine, or to have a service 〔","cn":"报纸或杂志的〕订阅者﹐订户﹔〔某项服务的〕消费者﹐用户"},{"en":"someone who pays money to be part of an organization or to help its work 〔","cn":"某组织的〕会员﹔赞助者"}]},"collocations":{"phrases":["ADJ. cable/digital/satellite TV, magazine, phone, telephone | regular | annual","PREP. ~ to Subscribers to the magazine can take advantage of this special offer."]},"media":{"uk":"media/ldoce/hwd/bre/5/subscriber0205.mp3","us":"media/ldoce/hwd/ame/1/subscriber.mp3"},"examples":[{"en":"subscribers to cable television","cn":"有线电视用户"},{"en":"cable television subscribers","cn":"有线电视用户"}],"oxford":{"phon":"səbˈskraɪbə(r)","pos":"noun","senses":[{"en":"a person who pays money, usually once a year, to receive regular copies of a magazine or newspaper or have access to it online","cn":"（纸质或网络报刊的）订阅人，订购者，订户","ex":{"en":"subscribers to ‘New Scientist’","cn":"《新科学家》订户"}},{"en":"a person who pays to receive a service","cn":"消费者；用户","ex":{"en":"subscribers to cable television","cn":"有线电视用户"}},{"en":"a person who gives money regularly to help the work of an organization such as a charity","cn":"（慈善机关等的）定期捐款者，定期捐助者","ex":{"en":"subscribers to Oxfam","cn":"乐施会的定期捐款者们"}}]}},"surrealist":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"超现实主义的","en":"Surrealist means related to or in the style of surrealism.","ex":{"en":"Dali's shoe hat was undoubtedly the most surrealist idea he ever worked on with Schiaparelli.","cn":"达利的鞋状帽子无疑是他与夏帕瑞丽合作出的最具超现实主义色彩的创意。"}},{"pos":"N-COUNT 可数名词","cn":"超现实主义作家;超现实主义艺术家","en":"A surrealist is an artist or writer whose work is based on the ideas of surrealism."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a style of 20th-century art or literature in which the artist or writer connects unrelated images and objects in a strange way","cn":""},{"en":"a style of 20th-century art or literature in which the artist or writer connects unrelated images and objects in a strange way","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41surrealism.mp3","us":"media/ldoce/hwd/ame/8/surrealism.mp3"},"examples":[{"en":"the surrealist Salvador Dali","cn":"超现实主义画家萨尔瓦多 达利"},{"en":"a surrealist painter/painting","cn":"超现实主义画家/绘画"}],"oxford":{"phon":"səˈriːəlɪst","pos":"noun","senses":[{"en":"an artist who uses surrealism in their work","cn":"超现实主义者","ex":{"en":"the surrealist Salvador Dali","cn":"超现实主义画家萨尔瓦多·达利"}},{"en":"in the style of surrealism; working in this style","cn":"超现实主义的","ex":{"en":"a surrealist painting/painter","cn":"超现实主义绘画/画家"},"pos":"adjective"}]}},"suitor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"求婚者;追求者","en":"A woman's suitor is a man who wants to marry her.","ex":{"en":"My mother had a suitor who adored her.","cn":"我妈妈曾经有一个爱慕她的追求者。"}},{"pos":"N-COUNT 可数名词","cn":"有意收购另一公司的公司(或机构)","en":"A suitor is a company or organization that wants to buy another company.","ex":{"en":"The company was making little progress in trying to find a suitor","cn":"该公司试图找到一家收购公司，但进展甚微。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who wants to marry a particular woman 〔","cn":"女子的〕追求者﹐求婚者"}]},"vocab":{"pos":"n","senses":[{"en":"A suitor is a guy who asks you out on a date. You can describe your sister's prom escort as her suitor ."}]},"media":{"uk":"media/ldoce/hwd/bre/2/suitor0205.mp3","us":"media/ldoce/hwd/ame/5/suitor.mp3"},"oxford":{"phon":"ˈsuːtə(r)","pos":"noun","senses":[{"en":"a man who wants to marry a particular woman","cn":"求婚者","lab":"old-fashioned","ex":{"en":"He was an ardent suitor.","cn":"他是一个热心的追求者。"}},{"en":"a company that wants to buy another company","cn":"有意收购另一公司的公司","lab":"business","ex":{"en":"a merger proposal from an unwanted suitor","cn":"来自不受欢迎的追求者的合并提议"}}]}},"suture":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指手术后伤口的)缝线，缝合","en":"A suture is a stitch made to join together the open parts of a wound, especially one made after a patient has been operated on."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a stitch that is used to sew a wound together 〔","cn":"伤口缝合的〕一针﹐缝针"}]},"vocab":{"pos":"n v","senses":[{"en":"If your energetic dog gets his paws on your beloved teddy bear, and you don’t realize it until it’s too late, you might have to use a needle and thread to suture Teddy’s left arm back onto his body."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41suture.mp3","us":"media/ldoce/hwd/ame/3/suture1.mp3"},"oxford":{"phon":"ˈsuːtʃə(r)","pos":"noun","senses":[{"en":"a stitch or stitches made when sewing up a wound, especially after an operation","cn":"（尤指手术后伤口的）缝合，缝线"},{"en":"to sew up a wound","cn":"缝合（伤口）","pos":"verb"}]}},"superannuated":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"废弃的;陈旧不中用的;过时的","en":"If you describe something as superannuated, you mean that it is old and no longer used for its original purpose.","ex":{"en":"...the superannuated idealism of the Sixties.","cn":"早已过时的 60 年代的理想主义"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"old and no longer useful or no longer able to do things","cn":"陈旧的﹔过时无用的﹔老弱无能的"}]},"vocab":{"pos":"adj","senses":[{"en":"If a friend describes your dot matrix printer as superannuated , then you should probably plan a shopping trip for electronics. Your friend has just pointed out that your printer is obsolete."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld44superannuate.mp3","us":"media/ldoce/hwd/ame/0/superannuated.mp3"},"examples":[{"en":"superannuated rock stars","cn":"过气摇滚歌星"},{"en":"superannuated sportsmen","cn":"走下坡路的运动员"}],"oxford":{"phon":"ˌsuːpərˈænjueɪtɪd","pos":"adjective","senses":[{"en":"too old for work or to be used for their original purpose","cn":"年老不能工作的；陈旧不中用的；过时的","ex":{"en":"superannuated rock stars","cn":"过气摇滚歌星"}}]}},"superannuation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"退休金;养老金","en":"Superannuation is money which people pay regularly into a special fund so that when they retire from their job they will receive money regularly as a pension.","ex":{"en":"The union pressed for a superannuation scheme.","cn":"工会敦促制定一个退休金方案。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"money paid as a pension 1 , especially from your former employer 〔","cn":"尤指由前雇主支付的〕退休金﹐养老金"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41superannuation.mp3","us":"media/ldoce/hwd/ame/b/ld41superannuation2.mp3"},"oxford":{"phon":"ˌsuːpərˌænjuˈeɪʃn","pos":"noun","senses":[{"en":"a pension that you get, usually from your employer, when you stop working when you are old and that you pay for while you are working; the money that you pay for this","cn":"（通常由原雇主发的）退休金，养老金"}]}},"superstar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"巨星;超级明星","en":"A superstar is a very famous entertainer or sports player.","ex":{"en":"He was more than a footballing superstar, he was a celebrity.","cn":"他不仅仅是足球场上的巨星，也是一位社会名流。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very famous and successful actor, entertainer, or sports player","cn":""},{"en":"someone who is well known, for example as an entertainer or sports player, and who is often seen on television or written about in newspapers","cn":""},{"en":"an actor, musician, or sports player who is famous all over the world","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/superstar0205.mp3","us":"media/ldoce/hwd/ame/6/superstar.mp3"},"oxford":{"phon":"ˈsuːpəstɑː(r)","pos":"noun","senses":[{"en":"a very famous performer, for example an actor, a singer or a sports player","cn":"超级明星","ex":{"en":"The movie made her an international superstar.","cn":"那部电影使她成为了国际超级明星。"}}]}},"summerhouse":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small building in your garden, where you can sit in warm weather 〔","cn":"花园中的〕凉亭﹐凉棚"}]},"media":{"uk":"media/ldoce/hwd/bre/3/summerhouse0205.mp3","us":"media/ldoce/hwd/ame/e/amelasdesummerhouse.mp3"}},"suspected":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who the police believe may have done something illegal","cn":""},{"en":"someone who the police or government believe is a criminal","cn":""},{"en":"if someone is under suspicion , people believe they may have done something illegal or dishonest","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/suspected0205.mp3","us":"media/ldoce/hwd/ame/0/laadsuspected.mp3"},"examples":[{"en":"suspected terrorists","cn":"被怀疑从事恐怖主义活动的人"},{"en":"a suspected broken arm","cn":"怀疑骨折的胳膊"}],"oxford":{"phon":"səˈspektɪd","pos":"adjective","senses":[{"en":"believed to have probably happened, although there is no definite proof","cn":"可能的","ex":{"en":"a suspected broken arm","cn":"疑似骨折的手臂"}},{"en":"believed to be guilty of something, although there is no definite proof","cn":"有犯罪嫌疑的","g":"[only before noun]","ex":{"en":"suspected terrorists","cn":"恐怖分子嫌疑人"}}]},"base":"suspect"},"supremacist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"种族优越论者; (通常指)白人至上主义者","en":"A supremacist is someone who believes that one group of people, usually white people, should be more powerful and have more influence than another group.","ex":{"en":"...a plot by White supremacists to blow up a Black church in Los Angeles.","cn":"白人至上主义者试图炸毁洛杉矶一所黑人教堂的阴谋"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who believes that their own particular race or group is better than any other","cn":"种族优越论者"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41supremacist.mp3","us":"media/ldoce/hwd/ame/9/supremacist.mp3"},"examples":[{"en":"a white supremacist","cn":"白人至上主义者"}],"oxford":{"phon":"suˈpreməsɪst","pos":"noun","senses":[{"en":"a person who believes that the group of people they belong to is better than other groups and should have power over them","cn":"种族优越论者","ex":{"en":"male supremacists","cn":"男性至上主义者"}}]}},"superconductivity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"超导(电)性","en":"Superconductivity is the ability of certain metals to allow electricity to pass through them without any resistance at very low temperatures."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability of some substances to allow electricity to flow through them very easily, especially at very low temperatures","cn":"超导（电）性"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41superconductiv.mp3","us":"media/ldoce/hwd/ame/3/superconductivity.mp3"},"oxford":{"phon":"ˌsuːpəˌkɒndʌkˈtɪvəti","pos":"noun","senses":[{"en":"the property (= characteristic) of some substances at very low temperatures to let electricity flow with no resistance","cn":"超导（电）性"}]}},"sundries":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"杂物;杂项;闲杂物品","en":"When someone is making a list of things, items that are not important enough to be listed separately are sometimes referred to together as sundries .","ex":{"en":"The inn gift shop stocks quality Indian crafts and sundries.","cn":"旅馆的礼品店里备有上好的印度手工艺品和其他一些特色礼品。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"small objects that are not important enough to be named separately","cn":"杂物﹔杂项"}]},"media":{"uk":"media/ldoce/hwd/bre/1/sundries0205.mp3","us":"media/ldoce/hwd/ame/4/sundries.mp3"},"oxford":{"phon":"ˈsʌndriz","pos":"noun","senses":[{"en":"various items, especially small ones, that are not important enough to be named separately","cn":"杂物；杂项物品","ex":{"en":"You can claim up to £10 a day for sundries.","cn":"您每天最多可以申请 10 英镑的杂货费。"}}]}},"sup":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(尤指小口地)喝,呷,啜","en":"If you sup something, you drink it, especially by taking small amounts.","ex":{"en":"We supped mulled wine.","cn":"我们小口地喝着热葡萄酒。"}},{"pos":"VERB 动词","cn":"吃晚饭;进晚餐","en":"If you sup, you eat dinner in the evening.","ex":{"en":"He had been invited to sup with a colleague and his wife.","cn":"他已经受邀和一位同事及其夫人共进晚餐。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to drink something","cn":"一点点地喝﹐呷"},{"en":"to eat supper","cn":"吃晚饭"}]},"vocab":{"pos":"v n","senses":[{"en":"To sup is to eat slowly, by spoonfuls. When you eat soup, you probably sup it."}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41sup.mp3","us":"media/ldoce/hwd/ame/3/sup.mp3"},"oxford":{"phon":"sʌp","pos":"noun","senses":[{"en":"a small drink of something","cn":"（小口地）喝；呷；啜"},{"en":"to drink something, especially in small amounts","cn":"（小口地）喝；呷；啜","pos":"verb"}]}},"supremacy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"至高无上;最大权力;霸权","en":"If one group of people has supremacy over another group, they have more political or military power than the other group.","ex":{"en":"The conservative old guard had re-established its political supremacy","cn":"守旧的保守派已经重新掌控了政治大权。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"优势","en":"If someone or something has supremacy over another person or thing, they are better.","ex":{"en":"In the United States Open final, Graf retained overall supremacy.","cn":"在美国网球公开赛决赛中，格拉芙始终保持优势。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the position in which you are more powerful or advanced than anyone else","cn":"至高无上﹔最高地位"}]},"vocab":{"pos":"n","senses":[{"en":"Supremacy is the state of having the ultimate authority. A ruling king has supremacy over his kingdom."}]},"collocations":{"phrases":["ADJ. total, unchallenged | world | air, military, naval | economic, political | male","VERB + SUPREMACY enjoy, have a period when the British enjoyed supremacy in international trade | lose | battle for, fight for, struggle for","PREP. ~ in the battle for supremacy in the world economic markets | ~ over By the end of the war, the prince had established total supremacy","PHRASES a battle/fight/struggle for supremacy, a challenge/threat to sb/sth's supremacy, a symbol of supremacy"]},"media":{"uk":"media/ldoce/hwd/bre/7/supremacy0205.mp3","us":"media/ldoce/hwd/ame/e/supremacy.mp3"},"examples":[{"en":"The company has established total supremacy over its rivals.","cn":"公司奠定了超越竞争对手的绝对优势。"},{"en":"the battle for supremacy in the region","cn":"争夺地区霸权的较量"}],"oxford":{"phon":"suˈpreməsi","pos":"noun","senses":[{"en":"a position in which you have more power, authority or status than anyone else","cn":"至高无上；最大权力；最高权威；最高地位","ex":{"en":"the battle for supremacy in the region","cn":"争夺地区霸权的较量"}}]}},"suiting":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"西装料","en":"Suiting is cloth from which trousers, jackets, skirts, and men's suits are made."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"material used for making suits, especially woven wool","cn":"西服衣料﹔羊毛衣料"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld44suiting.mp3","us":"media/ldoce/hwd/ame/2/suiting.mp3"},"examples":[{"en":"men's suiting","cn":"男西装毛料"}],"oxford":{"phon":"ˈsuːtɪŋ","pos":"noun","senses":[{"en":"cloth made especially of wool, used for making suits","cn":"西服毛料","ex":{"en":"men’s suiting","cn":"男西装毛料"}}]},"base":"suit"},"suffragette":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(20 世纪初英国的)参加争取妇女选举权运动的女子","en":"In the early twentieth century in Britain, a suffragette was a woman who was involved in the campaign for women to have the right to vote.","ex":{"en":"She was a suffragette and a birth control pioneer.","cn":"她参加争取妇女选举权的运动，也是节育倡导者。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a woman who tried to gain the right to vote for women, especially as a member of a group in Britain or the US in the early 20th century","cn":"为妇女争取选举权的女子〔尤指20世纪初英国或美国争取妇女选举权团体的成员〕"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41suffragette.mp3","us":"media/ldoce/hwd/ame/1/suffragette.mp3"},"oxford":{"phon":"ˌsʌfrəˈdʒet","pos":"noun","senses":[{"en":"a member of a group of women who, in the UK and the US in the early part of the 20th century, organized a campaign for the right of women to vote in political elections","cn":"（20 世纪初叶英国和美国的）妇女争取选举权团体的成员"}]}},"subsistence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勉强维持生活;生存;存活","en":"Subsistence is the condition of just having enough food or money to stay alive.","ex":{"en":"...below the subsistence level","cn":"低于最低生活水平"}},{"pos":"ADJ 形容词","cn":"(农业或农业生产)收成仅够自身口粮的","en":"In subsistence farming or subsistence agriculture, farmers produce food to eat themselves rather than to sell.","ex":{"en":"Many black Namibians are subsistence farmers who live in the arid borderlands.","cn":"许多生活在土地贫瘠的边境地区的纳米比亚黑人农场主的收成仅够维持自身的口粮。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the condition of only just having enough money or food to stay alive 〔","cn":"以仅仅足够的食物或钱〕维持生活﹔生存﹐生计"},{"en":"farming that produces just enough food for the farmer to live on, but does not produce enough food to sell to other people 〔","cn":"收成仅够维持生存的〕生存农耕/农业等"},{"en":"money that is paid to someone so that they can buy meals, pay for a place to stay etc","cn":"仅够维持生存的补助/金额等"}]},"vocab":{"pos":"n","senses":[{"en":"Subsistence means the minimal resources that are necessary for survival. If you work for subsistence , you'll probably receive food, water, and lodging (internet access not included)."}]},"collocations":{"phrases":["ADJ. bare, basic","SUBSISTENCE + NOUN agriculture, farmer, farming | economy | level Most of the population lives at subsistence level.","PHRASES a level of subsistence They were living barely above the level of subsistence. | means of subsistence She had no means of subsistenc"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41subsistence.mp3","us":"media/ldoce/hwd/ame/c/subsistence.mp3"},"examples":[{"en":"He worked a 16-hour day for a subsistence wage (= enough money to buy only basic items).","cn":"他一天工作 16 个小时，工资才够勉强维持生计。"},{"en":"subsistence agriculture/farming (= growing enough only to live on, not to sell)","cn":"收成仅够自身口粮的自给农业"}],"oxford":{"phon":"səbˈsɪstəns","pos":"noun","senses":[{"en":"the state of having just enough money or food to stay alive","cn":"勉强维持生活","ex":{"en":"Many families are living below the level of subsistence.","cn":"许多家庭难以度日。"}}]}},"sultana":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无核小葡萄干","en":"Sultanas are dried white grapes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small pale raisin (= dried fruit ) without seeds, used in baking 〔","cn":"做糕饼用的〕无籽小葡萄干"},{"en":"the wife, mother, or daughter of a sultan","cn":"苏丹的女眷〔指其妻子﹑母亲或女儿〕"}]},"media":{"uk":"media/ldoce/hwd/bre/b/sultana0205.mp3","us":"media/ldoce/hwd/ame/f/sultana.mp3"},"oxford":{"phon":"sʌlˈtɑːnə","pos":"noun","senses":[{"en":"a small dried grape without seeds, used in cakes, etc.","cn":"无核小葡萄干（用于糕点等）","lab":"British English"},{"en":"the wife, mother, sister or daughter of a sultan","cn":"苏丹女眷（指王后、王太后、姊妹或女儿）"}]}},"subdue":{"collins":{"senses":[{"pos":"VERB 动词","cn":"制服;征服;控制","en":"If soldiers or the police subdue a group of people, they defeat them or bring them under control by using force.","ex":{"en":"Senior government officials admit they have not been able to subdue the rebels.","cn":"政府高级官员承认他们还没能制服反叛者。"}},{"pos":"VERB 动词","cn":"抑制，压制，克制(感情)","en":"To subdue feelings means to make them less strong.","ex":{"en":"He forced himself to subdue and overcome his fears.","cn":"他强迫自己克制并战胜恐惧心理。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to stop people opposing or fighting against the government, by using military force or by making their activities illegal","cn":""},{"en":"to stop it by using military force against the people involved","cn":""},{"en":"if the police or army break up something such as an organized protest, they use force to stop it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To subdue is to hold back, put down, or defeat. A Doberman can be subdued with a bone, but subduing a yapping toy poodle can be a mail carrier's greatest daily challenge."}]},"media":{"uk":"media/ldoce/hwd/bre/7/subdue0205.mp3","us":"media/ldoce/hwd/ame/f/subdue.mp3"},"examples":[{"en":"Julia had to subdue an urge to stroke his hair.","cn":"朱莉娅得克制住自己，不去抚摩他的头发。"},{"en":"Troops were called in to subdue the rebels.","cn":"军队被调来镇压反叛者。"}],"oxford":{"phon":"səbˈdjuː","pos":"verb","senses":[{"en":"to bring somebody/something under control, especially by using force","cn":"制伏；征服；控制","ex":{"en":"Troops were called in to subdue the rebels.","cn":"军队被调来镇压反叛者。"}},{"en":"to calm or control your feelings","cn":"抑制，压制，克制（感情）","ex":{"en":"Julia had to subdue an urge to stroke his hair.","cn":"朱莉娅不得不克制住自己，不去抚摩他的头发。"}}]}},"suspension":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"暂停;延缓","en":"The suspension of something is the act of delaying or stopping it for a while or until a decision is made about it.","ex":{"en":"A strike by British Airways ground staff has led to the suspension of flights between London and Manchester","cn":"英国航空公司地勤人员的罢工已经造成伦敦至曼彻斯特的航线停运。"}},{"pos":"N-VAR 可变名词","cn":"停职;暂时除名","en":"Someone's suspension is their removal from a job or position for a period of time or until a decision is made about them.","ex":{"en":"The minister warned that any civil servant not at his desk faced immediate suspension","cn":"部长警告说，任何擅离职守的公务员都会被立即停职。"}},{"pos":"N-VAR 可变名词","cn":"(车辆的)悬架，减震装置","en":"A vehicle's suspension consists of the springs and other devices attached to the wheels, which give a smooth ride over uneven ground."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is officially stopped for a period of time","cn":"暂停﹐中止"},{"en":"when someone is not allowed to go to school, do their job, or take part in an activity for a period of time as a punishment 〔","cn":"作为处分的〕暂时停学[停职﹐除名]"},{"en":"a part attached to the wheels of a vehicle that makes it more comfortable on roads that are not smooth","cn":"减震装置"}]},"vocab":{"pos":"n","senses":[{"en":"A suspension is a temporary stoppage. If you receive one in school, you temporarily can't attend classes and if the referee gives you one, you have to sit out for the rest of the game."}]},"collocations":{"phrases":["ADJ. total | brief, temporary | lengthy, long | immediate | automatic Another caution will result in his automatic suspension from the final","VERB + SUSPENSION give sb, impose, order A four-day suspension was imposed on her. | get, incur He incurred a suspension on reduced pay. | a","PREP. under ~ a detective under suspension from the Metropolitan Police | ~ from his suspension from the club","PHRASES a period of suspension The athlete could face a lengthy period of suspension if found guilty. 2 on a vehicle","ADJ. front, rear | active, computer-controlled, independent, self-levelling | car, etc.","VERB + SUSPENSION be fitted with, have The new model is fitted with computer-controlled suspension.","SUSPENSION + NOUN system"]},"media":{"uk":"media/ldoce/hwd/bre/1/suspension0205.mp3","us":"media/ldoce/hwd/ame/f/suspension.mp3"},"examples":[{"en":"The two players are appealing against their suspensions.","cn":"这两名运动员请求取消对他们的停赛处罚。"},{"en":"These events have led to the suspension of talks.","cn":"这些事件导致谈判延期。"}],"oxford":{"phon":"səˈspenʃn","pos":"noun","senses":[{"en":"the act of officially removing somebody from their job, school, team, etc. for a period of time, usually as a punishment","cn":"暂令停职（或停学、停赛等）","g":"[uncountable, countable]","ex":{"en":"suspension from school","cn":"暂被停学"}},{"en":"the act of delaying something for a period of time, until a decision has been taken","cn":"暂缓；推迟；延期","g":"[uncountable, singular]","ex":{"en":"These events have led to the suspension of talks.","cn":"这些事件导致谈判延期。"}},{"en":"the system of springs, etc. by which a vehicle is supported on its wheels and that makes it more comfortable to ride in when the road surface is not even","cn":"（车辆减震用的）悬架系统","g":"[uncountable, countable]","ex":{"en":"the front/rear suspension","cn":"前/后悬架"}},{"en":"a liquid with very small pieces of solid matter floating in it; the state of such a liquid","cn":"悬浮液；悬浮","g":"[countable, uncountable]","lab":"specialist","ex":{"en":"The suspension was passed through a filter to separate out the solid particles.","cn":"悬浮液经由过滤器将其中的固体颗粒分离出来。"}}]}},"sulfur":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of sulphur sulphur","cn":"的美式拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41sulfur.mp3","us":"media/ldoce/hwd/ame/7/ld41sulfur.mp3"},"oxford":{"phon":"ˈsʌlfə(r)","pos":"noun","senses":[{"en":"a chemical element. Sulfur is a pale yellow substance that produces a strong unpleasant smell when it burns and is used in medicine and industry.","cn":"硫；硫黄"}]}},"subjection":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"隶属;服从;言听计从;屈从","en":"Subjection to someone involves being completely controlled by them.","ex":{"en":"...their complete subjection to their captors.","cn":"他们完全屈服于俘获他们的那些人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a person or a group of people are controlled by a government or by another person","cn":"征服﹐镇压﹔强行统治"}]},"vocab":{"pos":"n","senses":[{"en":"Subjection is when a person, group, or government forces another person — or group of people — to submit or be controlled. A dictator's power lies in his subjection of the people over whom he rules."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41subjection.mp3","us":"media/ldoce/hwd/ame/c/subjection.mp3"},"examples":[{"en":"The government used brute force to keep people in subjection.","cn":"政府使用暴力让民众臣服。"},{"en":"a period of subjection to Assyrian rulers","cn":"臣服于亚述统治者的一段时期"}],"oxford":{"phon":"səbˈdʒekʃn","pos":"noun","senses":[{"en":"the process of bringing a country or group of people under your control, especially by using force; the situation of being controlled in this way","cn":"使臣服；使顺从；（尤指）压服","ex":{"en":"Scotland was placed under feudal subjection to England.","cn":"苏格兰被置于英格兰的封建统治之下。"}}]}},"surreptitious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"秘密的;鬼鬼祟祟的;偷偷摸摸的","en":"A surreptitious action is done secretly.","ex":{"en":"He made a surreptitious entrance to the club through the little door in the brick wall","cn":"他从砖墙的小门偷偷进入俱乐部。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done without anyone else knowing","cn":""},{"en":"if you do something on the quiet , you do it secretly, especially because you think that people will disapprove of what you are doing","cn":""},{"en":"if important official meetings, discussions, or decisions take place behind closed doors , they take place secretly without the public being allowed to see or hear them","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When someone behaves in a surreptitious way, they're being secretive. They're doing something that they don't want to be seen doing."}]},"media":{"uk":"media/ldoce/hwd/bre/1/surreptitious0205.mp3","us":"media/ldoce/hwd/ame/a/amelasdesurreptitious.mp3"},"examples":[{"en":"She sneaked a surreptitious glance at her watch.","cn":"她偷偷看了一眼手表。"},{"en":"Rory tried to sneak a surreptitious glance at Adam’s wristwatch.","cn":"罗里试图偷偷看一眼亚当的手表。"}],"oxford":{"phon":"ˌsʌrəpˈtɪʃəs","pos":"adjective","senses":[{"en":"done secretly or quickly, in the hope that other people will not notice","cn":"秘密的；趁人不注意赶紧进行的","ex":{"en":"She sneaked a surreptitious glance at her watch.","cn":"她偷偷看了一眼手表。"}}]}},"supranational":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(组织、官方机构)超国家的，多国的","en":"A supranational organization or authority involves or relates to more than one country.","ex":{"en":"...NATO and other Western supranational institutions.","cn":"北大西洋公约组织和其他西方超国家机构"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"involving more than one country","cn":"超国家的﹐多国的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41supranational.mp3","us":"media/ldoce/hwd/ame/2/supranational.mp3"},"examples":[{"en":"a supranational organization","cn":"一个多国组织"}],"oxford":{"phon":"ˌsuːprəˈnæʃnəl","pos":"adjective","senses":[{"en":"involving more than one country","cn":"超国家的（指涉及不止一个国家）","ex":{"en":"a supranational authority","cn":"超国家权威"}}]}},"surety":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"保证金;担保物","en":"A surety is money or something valuable which you give to someone to show that you will do what you have promised.","ex":{"en":"The insurance company will take warehouse stocks or treasury bonds as surety","cn":"该保险公司将接受仓库库存货物或长期国库券作为担保。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who will pay a debt, appear in court etc if someone else fails to do so","cn":"保证人﹐担保人"},{"en":"to be responsible for paying a debt, appearing in court etc if someone else fails to do so （","cn":"为某人）做担保人"},{"en":"money someone gives to make sure that someone will appear in court 〔","cn":"交给法院保证出庭的〕保证金"}]},"vocab":{"pos":"n","senses":[{"en":"A surety is a fact that no one questions. Surety , in a legal sense, is the security you can provide when you apply for a loan."}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41surety.mp3","us":"media/ldoce/hwd/ame/9/surety.mp3"},"examples":[{"en":"She was granted bail with a surety of $500.","cn":"她交了 500 元保证金，获得保释。"},{"en":"to act as surety for sb","cn":"为某人做担保人"}],"oxford":{"phon":"ˈʃʊərəti","pos":"noun","senses":[{"en":"money given as a promise that you will pay a debt, appear in court, etc.","cn":"保证金","ex":{"en":"She was granted bail with a surety of $500.","cn":"她交了 500 美元保证金，获得保释。"}},{"en":"a person who accepts responsibility if somebody else does not pay a debt, appear in court, etc.","cn":"保证人；担保人","ex":{"en":"to act as surety for somebody","cn":"为某人做担保人"}}]}},"supplicant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(向上帝或重要人物请求的)祈求者，恳求者，哀求者","en":"A supplicant is a person who prays to God or respectfully asks an important person to help them or to give them something that they want very much.","ex":{"en":"He flung himself down in the flat submissive posture of a mere supplicant.","cn":"他以一个卑微的哀求者绝对谦恭的姿态猛地趴在地上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who asks for something, especially from someone in a position of power or from God 〔","cn":"尤指向当权者或上帝请求的〕恳求者﹐哀求者﹐祈求者"}]},"vocab":{"pos":"n adj","senses":[{"en":"If you pray every night to be accepted to your dream college, you can call yourself a supplicant , or a person who asks humbly for something."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41supplicant.mp3","us":"media/ldoce/hwd/ame/6/supplicant.mp3"},"oxford":{"phon":"ˈsʌplɪkənt","pos":"noun","senses":[{"en":"a person who asks for something in a humble way, especially from God or a powerful person","cn":"（尤指向神灵或有权势者）恳求者，哀求者，祈求者"}]}},"subheading":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小标题;副标题","en":"Subheadings are titles that divide part of a piece of writing into shorter sections."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short phrase used as a title for a small part within a longer piece of writing","cn":"副标题﹐小标题"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41subheading.mp3","us":"media/ldoce/hwd/ame/d/subheading.mp3"},"oxford":{"phon":"ˈsʌbhedɪŋ","pos":"noun","senses":[{"en":"a title given to any of the sections into which a longer piece of writing has been divided","cn":"小标题；子标题"}]}},"suicidal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有自杀倾向的;想自杀的","en":"People who are suicidal want to kill themselves.","ex":{"en":"I was suicidal and just couldn't stop crying","cn":"我当时想自杀，一直哭个不停。"}},{"pos":"ADJ 形容词","cn":"自取灭亡的;有致命危险的","en":"If you describe an action or behaviour as suicidal, you mean that it is very dangerous.","ex":{"en":"They realized it would be suicidal to resist in the face of overwhelming military superiority.","cn":"他们意识到面对力量相差如此悬殊的军队，抵抗无异于自取灭亡。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"when someone deliberately kills himself or herself","cn":""},{"en":"to kill yourself","cn":""},{"en":"someone who is suicidal is likely to kill themselves because they are extremely unhappy","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, sound | become, get He became very depressed and even got suicidal at one point.","ADV. almost 2 likely to cause your failure","VERBS be, prove","ADV. economically, politically a move which would be politically suicidal","PREP. for These policies would prove suicidal for our economy."]},"media":{"uk":"media/ldoce/hwd/bre/b/suicidal0205.mp3","us":"media/ldoce/hwd/ame/b/suicidal.mp3"},"examples":[{"en":"The new economic policies could prove suicidal for the party.","cn":"新经济政策可能给该党带来灾难性的后果。"},{"en":"On bad days I even felt suicidal.","cn":"赶上不顺的日子，我都觉得不想活了。"}],"oxford":{"phon":"ˌsuːɪˈsaɪdl","pos":"adjective","senses":[{"en":"people who are suicidal feel that they want to kill themselves","cn":"想自杀的；有自杀倾向的","ex":{"en":"On bad days I even felt suicidal.","cn":"赶上不顺的日子，我都觉得不想活了。"}},{"en":"very dangerous and likely to lead to the person's own death; likely to cause them very serious problems or disaster","cn":"自杀性的；有致命危险的；毁灭性的；灾难性的","ex":{"en":"a suicidal leap into the swollen river","cn":"不顾死活地跳进上涨的河水"}}]}},"supervisor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指工人或学生的)管理者，监督者，指导者","en":"A supervisor is a person who supervises activities or people, especially workers or students.","ex":{"en":"...a full-time job as a supervisor at a factory","cn":"在一家工厂担任主管的全职工作"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who is in charge of you at work. Boss sounds rather informal. The usual word to use in more formal English is manager","cn":""},{"en":"the person in charge of a business such as a shop, a bank, or a hotel, or of a part of a business","cn":""},{"en":"the person who is in charge of an organization or a department within that organization","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A supervisor is the person in charge at your job, who monitors you as you work. Your supervisor prepared you for the world of sneaker sales, and makes sure you don't give them away free to your friends."}]},"collocations":{"phrases":["ADJ. chief, senior | area | office | shift | project | production | technical | research","VERB + SUPERVISOR act as","PREP. under a/the ~ the people working under that supervisor • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41supervisor.mp3","us":"media/ldoce/hwd/ame/1/laadsupervisor.mp3"},"examples":[{"en":"I have a meeting with my supervisor about my research topic.","cn":"我要就研究课题同导师见一次面。"},{"en":"She has a supervisory role on the project.","cn":"她负责这个项目的监督工作。"}],"oxford":{"phon":"ˈsuːpəvaɪzə(r)","pos":"noun","senses":[{"en":"a person who supervises somebody/something","cn":"监督人；指导者；主管人","ex":{"en":"I have a meeting with my supervisor about my research topic.","cn":"我要就研究课题同导师见一次面。"}}]}},"submission":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"屈服;投降;归顺","en":"Submission is a state in which people can no longer do what they want to do because they have been brought under the control of someone else.","ex":{"en":"The army intends to take the city or simply starve it into submission.","cn":"军队打算占领该城市或干脆截断其粮食补给迫使其投降。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"提交;呈递","en":"The submission of a proposal, report, or other document is the act of formally sending it to someone, so that they can consider it or decide about it.","ex":{"en":"Diploma and certificate courses do not normally require the submission of a dissertation.","cn":"为获得文凭和证书所修的课程通常不需要提交论文。"}},{"pos":"N-COUNT 可数名词","cn":"提交的建议(或报告等);呈递的文件","en":"A submission is a proposal, report, or other document that is formally sent or presented to someone, so that they can consider or decide about it.","ex":{"en":"A written submission has to be prepared.","cn":"必须准备一份书面报告。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being completely controlled by a person or group, and accepting that you have to obey them","cn":"屈服﹐屈从﹐顺从"},{"en":"when you give or show something to someone in authority, for them to consider or approve","cn":"提交（物）﹐呈递﹔呈交"},{"en":"an opinion or thought that you state","cn":"意见﹐建议﹐看法"}]},"vocab":{"pos":"n","senses":[{"en":"If a teacher asks for your submission , she might want you to obey her every command like a drone or, on the other hand, she may want just you to turn something in for her approval."}]},"collocations":{"phrases":["ADJ. complete, total","VERB + SUBMISSION demand, expect The emperor demanded total submission from his subjects. | gain, get | beat sb into, bomb sb into, force sb","PREP. ~ to the patient's submission to the demands of the hospital 2 of a plan/statement","ADJ. detailed | joint | oral, written","VERB + SUBMISSION make | accept | reject | consider, hear | support, uphold The judge upheld the defendant's submission and quashed his conv","PREP. in a/the ~ | ~ to The companies have made a joint submission to the minister."]},"media":{"uk":"media/ldoce/hwd/bre/8/submission0205.mp3","us":"media/ldoce/hwd/ame/4/submission.mp3"},"examples":[{"en":"They prepared a report for submission to the council.","cn":"他们准备了一份报告要提交给理事会。"},{"en":"All parties will have the opportunity to make submissions relating to this case.","cn":"各方均有机会提交与此案有关的陈述。"}],"oxford":{"phon":"səbˈmɪʃn","pos":"noun","senses":[{"en":"the act of accepting that somebody has defeated you and that you must obey them","cn":"屈服；投降；归顺","g":"[uncountable]","ex":{"en":"a gesture of submission","cn":"投降的手势"}},{"en":"the act of giving a document, proposal, etc. to somebody in authority so that they can study or consider it; the document, etc. that you give","cn":"提交；呈递；提交（或呈递）的文件、建议等","g":"[uncountable, countable]","ex":{"en":"When is the final date for the submission of proposals?","cn":"呈交提案的最后日期是什么时候？"}},{"en":"a statement that is made to a judge in court","cn":"（向法官提出的）看法，意见","g":"[countable]","lab":"law","ex":{"en":"All parties will have the opportunity to make submissions relating to this case.","cn":"各方均有机会提交与此案有关的陈述。"}}]}},"surgical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"外科手术用的","en":"Surgical equipment and clothing is used in surgery.","ex":{"en":"...an array of surgical instruments.","cn":"一批外科手术器械"}},{"pos":"ADJ 形容词","cn":"外科手术的","en":"Surgical treatment involves surgery.","ex":{"en":"A biopsy is usually a minor surgical procedure.","cn":"活组织检查通常是一个较小的外科手术。"}},{"pos":"ADJ 形容词","cn":"(军事行动)外科手术式的，有针对性的，不伤及无辜的","en":"Surgical military actions are designed to destroy a particular target without harming other people or damaging other buildings near it.","ex":{"en":"The new figures cast doubt on the government's claim to have achieved a surgical strike against military targets.","cn":"新的数字使人们对政府所声称的已经对军事目标实行了外科手术式打击产生了怀疑。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to or used for medical operations","cn":"外科的﹔外科手术用的"},{"en":"a stocking etc that someone wears to support a part of their body that is injured or weak","cn":"外科用袜子/护颈等"},{"en":"done very carefully and in exactly the right place","cn":"仔细的﹔精确的"}]},"media":{"img":["media/ldoce/img/instrument_surgical.jpg"],"uk":"media/ldoce/hwd/bre/9/surgical0205.mp3","us":"media/ldoce/hwd/ame/9/l3surgical.mp3"},"examples":[{"en":"The lumps will need to be surgically removed.","cn":"这些肿块需手术切除。"},{"en":"a surgical ward (= for patients having operations)","cn":"外科手术病房"}],"oxford":{"phon":"ˈsɜːdʒɪkl","pos":"adjective","senses":[{"en":"used in or connected with surgery","cn":"外科的；外科手术的","ex":{"en":"surgical procedures","cn":"手术程序"}},{"en":"very accurate","cn":"（尤指空中军事打击）精准的，外科手术式的","ex":{"en":"They launched surgical strikes against enemy targets.","cn":"他们对敌方目标发动精确打击。"}}]}},"subsidence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"下沉;沉降;下陷","en":"When there is subsidence in a place, the ground there sinks to a lower level.","ex":{"en":"A surveyor said that the problems were caused by subsidence and the house needed to be underpinned.","cn":"一名勘测员说是地面下陷导致了这些问题出现，房子需要加固地基。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the process by which an area of land sinks to a lower level than the land surrounding it, or a building begins to sink into the ground 〔","cn":"土地的〕塌陷﹐下陷﹔〔建筑物的〕沉降"}]},"collocations":{"phrases":["ADJ. rapid, slow, steady","VERB + SUBSIDENCE be liable to, suffer from A number of houses had suffered from coal-mining subsidence.","SUBSIDENCE + VERB occur"]},"media":{"uk":"media/ldoce/hwd/bre/d/subsidence0205.mp3","us":"media/ldoce/hwd/ame/1/subsidence.mp3"},"examples":[{"en":"Is your house insured against subsidence?","cn":"你给房子投保沉降险了吗？"}],"oxford":{"phon":"səbˈsaɪdns","pos":"noun","senses":[{"en":"the process by which an area of land sinks to a lower level than normal, or by which a building sinks into the ground","cn":"（地面或建筑物的）沉陷，沉降","ex":{"en":"The houses in this area are liable to subsidence.","cn":"这个地区的房屋容易下沉。"}}]}},"sunder":{"collins":{"senses":[{"pos":"VERB 动词","cn":"分开;使分离;割裂","en":"If people or things are sundered, they are separated or split by something.","ex":{"en":"The city is being sundered by racial tension","cn":"该城市因种族关系紧张正在形成分裂。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to break something into parts, especially violently 〔","cn":"尤指猛烈地〕将〔某物〕分开﹔使碎开﹔割开﹔切开"}]},"vocab":{"pos":"v","senses":[{"en":"Think of the word sunder as violently tearing something apart. A frequent line in a wedding ceremony is, \"What God has joined together, let no man tear asunder.\" Keep that in mind, and you'll have the meaning of the word."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sunder.mp3","us":"media/ldoce/hwd/ame/0/sunder.mp3"},"oxford":{"phon":"ˈsʌndə(r)","pos":"verb","senses":[{"en":"to split or break something/somebody apart, especially by force","cn":"（尤指强制地）分开，使分离，割裂"}]}},"suspenseful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(故事)悬疑的，充满悬念的","en":"A suspenseful story makes you feel excited or anxious about what is going to happen in the story next.","ex":{"en":"...a suspenseful and sinister tale.","cn":"悬疑恐怖故事"}}]},"oxford":{"phon":"səˈspensfl","pos":"adjective","senses":[{"en":"creating feelings of excitement or worry about what may happen","cn":"充满紧张的,悬疑的","ex":{"en":"Her new novel is a gripping and suspenseful thriller.","cn":"她的新小说是一部扣人心弦的悬疑惊悚小说。"}}]}},"sucrose":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蔗糖","en":"Sucrose is a common type of sugar.","ex":{"en":"...simple sugars like sucrose, glucose and fructose.","cn":"诸如蔗糖、葡萄糖和果糖等单糖"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the most common form of sugar","cn":"蔗糖"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41sucrose.mp3","us":"media/ldoce/hwd/ame/4/sucrose.mp3"},"oxford":{"phon":"ˈsuːkrəʊz","pos":"noun","senses":[{"en":"the form of sugar that is obtained from sugar cane and sugar beet","cn":"蔗糖"}]}},"sun-drenched":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满阳光的;阳光充足的","en":"Sun-drenched places have a lot of hot sunshine.","ex":{"en":"He sat on the terrace of his sun-drenched villa in the South of France.","cn":"他坐在自己位于法国南部的阳光别墅的露天平台上。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a sun-drenched place is one where the sun shines most of the time – used especially in advertisements, magazines etc 〔","cn":"地方〕阳光充足的﹐充满阳光的〔尤用于广告﹑杂志等中〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41sun-drenched.mp3","us":"media/ldoce/hwd/ame/e/laadsun-drenched.mp3"},"examples":[{"en":"sun-drenched Mediterranean beaches","cn":"阳光充沛的地中海海滩"},{"en":"sun-drenched tropical islands","cn":"阳光充沛的热带岛屿"}],"oxford":{"phon":"ˈsʌn drentʃt","pos":"adjective","senses":[{"en":"having a lot of hot sun","cn":"充满阳光的；阳光充足的","ex":{"en":"sun-drenched Mediterranean beaches","cn":"阳光充沛的地中海海滩"}}]}},"surrogate":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"代替的;代用的;代理的","en":"You use surrogate to describe a person or thing that is given a particular role because the person or thing that should have the role is not available.","ex":{"en":"Martin had become Howard Cosell's surrogate son","cn":"马丁代为当起了霍华德·科塞尔的儿子。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a surrogate person or thing is one that takes the place of someone or something else","cn":"替代的﹐代理的"},{"en":"a person or thing that takes the place of someone or something else","cn":"替代品"},{"en":"a surrogate mother","cn":"代孕母亲"}]},"vocab":{"pos":"n adj","senses":[{"en":"Someone who acts as a surrogate takes the place of another person. If a celebrity leaves her seat to use the restroom in the middle of a big Hollywood awards ceremony, a surrogate will take his or her place until she returns."}]},"collocations":{"phrases":["VERB + SURROGATE act as, be","SURROGATE + NOUN father, mother, parent | child","PREP. ~ for He used the Internet as a surrogate for contact with real people."]},"media":{"uk":"media/ldoce/hwd/bre/9/surrogate_adj0205.mp3","us":"media/ldoce/hwd/ame/2/surrogate.mp3"},"examples":[{"en":"She saw him as a sort of surrogate father.","cn":"在她心目中，他彷佛是能替代父亲角色的人。"},{"en":"William was acting as a surrogate father for his brother’s son.","cn":"威廉如亲生父亲一般照顾兄长的儿子。"}],"oxford":{"phon":"ˈsʌrəɡət","pos":"adjective","senses":[{"en":"used to describe a person or thing that takes the place of, or is used instead of, somebody/something else","cn":"替代的；代用的","ex":{"en":"She saw him as a sort of surrogate father.","cn":"在她心目中，他仿佛是能替代父亲角色的人。"}},{"en":"a person or thing that takes the place of, or is used instead of, somebody/something else","cn":"代替或被用来代替某人/某物的人或事物","ex":{"en":"As Tolkien noted some time ago, magic is often a surrogate for technology.","cn":"正如托尔金不久前指出的那样，魔法常常是技术的替代品。"},"pos":"noun"}]}},"sunflower":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"向日葵;葵花","en":"A sunflower is a very tall plant with large yellow flowers. Oil from sunflower seeds is used in cooking and to make margarine."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very tall plant with a large yellow flower, and seeds that can be eaten","cn":"向日葵"}]},"media":{"uk":"media/ldoce/hwd/bre/7/sunflower0205.mp3","us":"media/ldoce/hwd/ame/6/sunflower.mp3","img":["media/thumb/sunflower.jpg"]},"examples":[{"en":"sunflower oil","cn":"葵花籽油"}],"oxford":{"phon":"ˈsʌnflaʊə(r)","pos":"noun","senses":[{"en":"a very tall plant with large yellow flowers, grown in gardens or for its seeds and their oil that are used in cooking","cn":"向日葵；葵花","ex":{"en":"sunflower oil","cn":"葵花籽油"}}]}},"supplement":{"collins":{"senses":[{"pos":"VERB 动词","cn":"增补;补充","en":"If you supplement something, you add something to it in order to improve it.","ex":{"en":"...people doing extra jobs outside their regular jobs to supplement their incomes","cn":"除了正常的工作外还要额外兼职以贴补收入的人"}},{"pos":"N-COUNT 可数名词","cn":"营养片剂;补品","en":"A supplement is a pill that you take or a special kind of food that you eat in order to improve your health.","ex":{"en":"...a multiple vitamin and mineral supplement","cn":"含复合维生素和矿物质的营养剂"}},{"pos":"N-COUNT 可数名词","cn":"(杂志或报纸的)增刊，副刊","en":"A supplement is a separate part of a magazine or newspaper, often dealing with a particular topic.","ex":{"en":"...a special supplement to a monthly financial magazine.","cn":"一本金融杂志月刊的特别增刊"}},{"pos":"N-COUNT 可数名词","cn":"(书籍的)补编，补遗，附录","en":"A supplement to a book is an additional section, written some time after the main text and published either at the end of the book or separately.","ex":{"en":"...the supplement to the Encyclopedia Britannica.","cn":"《不列颠百科全书》附录"}},{"pos":"N-COUNT 可数名词","cn":"额外费用;附加费","en":"A supplement is an extra amount of money that you pay in order to obtain special facilities or services, for example when you are travelling or staying at a hotel.","ex":{"en":"If you are travelling alone, the single room supplement is £11 a night.","cn":"如果是一个人旅行，住单间每晚要多交 11 英镑。"}},{"pos":"N-COUNT 可数名词","cn":"补助;补贴","en":"A supplement is an extra amount of money that is paid to someone, in addition to their normal pension or income.","ex":{"en":"Some people may be entitled to a housing benefit supplement.","cn":"有些人可能有资格拿到住房补贴。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something added to food in order to make it last longer, taste better, or look more attractive","cn":""},{"en":"something that is added to something else in order to improve it or make it complete","cn":""},{"en":"something which is added to a basic product or service which improves it and also costs more","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A supplement is something added to something else. Nutritional supplements add vitamins and minerals to the ones already included in the food you eat."}]},"collocations":{"phrases":["ADJ. useful, valuable | colour (= a colour magazine that comes with most weekend papers in Britain), magazine, special, Sunday Our special s","VERB + SUPPLEMENT provide (sb/sth with) | add The farmer adds a supplement to the horse's feed. | take, use (sth as) I take a vitamin supple","PREP. ~ to This document is a supplement to the main report. 2 extra amount of money","ADJ. $100, &pound; 50, etc. A balcony is available for a &pound; 20 supplement. | flight, single room If you want to travel on a different d","VERB + SUPPLEMENT add, charge We charge a small supplement for this service. | carry, have Weekend flights carry a supplement. | pay","SUPPLEMENT + VERB be payable","PREP. at a ~ Single rooms are available at a supplement. | ~ for a $20 supplement for each extra night | ~ on There is a supplement on rooms"]},"media":{"uk":"media/ldoce/hwd/bre/8/supplement_n0205.mp3","us":"media/ldoce/hwd/ame/d/l3supplement.mp3"},"examples":[{"en":"Safety deposit boxes are available at a supplement.","cn":"有贵重物品保管箱可供使用，费用另计。"},{"en":"Industrial sponsorship is a supplement to government funding.","cn":"工业界的赞助是对政府拨款的补充。"}],"oxford":{"phon":"ˈsʌplɪmənt","pos":"noun","senses":[{"en":"a thing that is added to something else to improve or complete it","cn":"增补（物）；补充（物）；添加物","ex":{"en":"vitamin/dietary supplements (= vitamins and other foods eaten in addition to what you usually eat)","cn":"维生素／膳食补充剂"}},{"en":"an extra separate section, often in the form of a magazine, that is sold with a newspaper","cn":"（报纸的）增刊","ex":{"en":"the Sunday colour supplements","cn":"星期日彩色增刊"}},{"en":"a book or a section at the end of a book that gives extra information or deals with a special subject","cn":"（书籍的）补编，补遗，附录","ex":{"en":"the supplement to the Oxford English Dictionary","cn":"《牛津英语词典》补编"}},{"en":"an amount of money that you pay for an extra service or item, especially in addition to the basic cost of a holiday","cn":"（尤指度假服务的）额外费用，附加费","lab":"British English","ex":{"en":"There is a £10 supplement for a single room.","cn":"住单间另付 10 英镑。"}},{"en":"to add something to something in order to improve it or make it more complete","cn":"增补；补充","ex":{"en":"a diet supplemented with vitamin pills","cn":"搭配有维生素片的饮食"},"pos":"verb"}]}},"supervisory":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"管理的;监督的;指导的","en":"Supervisory means involved in supervising people, activities, or places.","ex":{"en":"Most supervisory boards meet only twice a year.","cn":"大多数监事会一年只开两次会议。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the person who is in charge of you at work. Boss sounds rather informal. The usual word to use in more formal English is manager","cn":""},{"en":"the person in charge of a business such as a shop, a bank, or a hotel, or of a part of a business","cn":""},{"en":"the person who is in charge of an organization or a department within that organization","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41supervisor.mp3","us":"media/ldoce/hwd/ame/1/laadsupervisor.mp3"},"examples":[{"en":"She has a supervisory role on the project.","cn":"她负责这个项目的监督工作。"}],"oxford":{"phon":"ˌsuːpəˈvaɪzəri","pos":"adjective","senses":[{"en":"making sure that everything happens correctly, safely, etc. or as it should do","cn":"监督的，管理的，指导的","ex":{"en":"She has a supervisory role on the project.","cn":"她负责监管这个项目。"}}]}},"surveyor":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(土地)测量员，勘测员","en":"A surveyor is a person whose job is to survey land.","ex":{"en":"...the surveyor's maps of the Queen Alexandra Range.","cn":"测量员绘制亚历山德拉皇后山脉勘测图"}},{"pos":"N-COUNT 可数名词","cn":"(建筑物的)鉴定人，评估人","en":"A surveyor is a person whose job is to survey buildings.","ex":{"en":"Our surveyor warned us that the house needed totally rebuilding.","cn":"我们的鉴定人警告我们这栋房子需要彻底重建。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to examine the condition of a building, or to measure and record the details of an area of land 〔","cn":"建筑物的〕鉴定人﹐房产检视员﹔〔土地〕测量员﹐勘测员"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A surveyor is someone who estimates or measures the dimensions of land. Surveyors help make maps, and are important when planning new buildings."}]},"media":{"uk":"media/ldoce/hwd/bre/9/surveyor0205.mp3","us":"media/ldoce/hwd/ame/6/surveyor.mp3"},"examples":[{"en":"the surveyor of public works","cn":"市政工程检验官"}],"oxford":{"phon":"səˈveɪə(r)","pos":"noun","senses":[{"en":"a person whose job is to examine and record the details of a piece of land","cn":"（土地）测量员，勘测员"},{"en":"a person whose job is to examine a building to make sure it is in good condition, usually done for somebody who is thinking of buying it","cn":"（建筑物）鉴定人","lab":"British English"}]}},"summon":{"collins":{"senses":[{"pos":"VERB 动词","cn":"召唤;传唤;召见","en":"If you summon someone, you order them to come to you.","ex":{"en":"Howe summoned a doctor and hurried over","cn":"豪叫了医生，然后匆忙赶了过来。"}},{"pos":"VERB 动词","cn":"鼓起(勇气);振作;使出(力气)","en":"If you summon a quality, you make a great effort to have it. For example, if you summon the courage or strength to do something, you make a great effort to be brave or strong, so that you will be able to do it.","ex":{"en":"It took her a full month to summon the courage to tell her mother.","cn":"她用了整整一个月才鼓足勇气告诉了妈妈。"}},{"pos":"","cn":"","en":"相关词组：summon up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to send someone a message ordering them to come to you","cn":""},{"en":"to officially order someone to come to you","cn":""},{"en":"to order someone to come to a place","cn":"召唤﹐叫来"}]},"vocab":{"pos":"v","senses":[{"en":"To summon is to formally call for the presence of someone. If, as soccer team captain, you find that your team members are an hour late for the big game, you might need to summon them — and fast."}]},"collocations":{"phrases":["ADV. duly | hastily, urgently | back","PREP. for She was duly summoned for an interview. | from He has been summoned from New York to give evidence at the trial. | to She was summ","ADV. barely, hardly He could hardly summon the strength to stand up. | up","VERB + SUMMON can/could | try to | manage to She managed to summon up a smile."]},"media":{"uk":"media/ldoce/hwd/bre/f/summon0205.mp3","us":"media/ldoce/hwd/ame/3/summon.mp3"},"examples":[{"en":"In May 1688 he was urgently summoned to London. * 1688","cn":"年 5 月，他被紧急召往伦敦。"},{"en":"She was trying to summon up the courage to leave him.","cn":"当时她试图鼓起勇气离开他。"}],"oxford":{"phon":"ˈsʌmən","pos":"verb","senses":[{"en":"to order somebody to appear in court","cn":"传（某人）出庭；传唤","lab":"formal","ex":{"en":"He was summoned to appear before the magistrates.","cn":"他被传唤在地方法院出庭。"}},{"en":"to order somebody to come to you","cn":"召唤","lab":"formal","ex":{"en":"In May 1688 he was urgently summoned to London.","cn":"1688 年 5 月，他被紧急召往伦敦。"}},{"en":"to call for or try to obtain something","cn":"吁求；请求；争取","lab":"formal","ex":{"en":"to summon assistance/help/reinforcements","cn":"请求援助／帮助／增援"}},{"en":"to arrange an official meeting","cn":"召集，召开（会议）","lab":"formal","ex":{"en":"to summon a meeting","cn":"召集会议"}},{"en":"to make an effort to produce a particular quality in yourself, especially when you find it difficult","cn":"鼓起；振作；使出","ex":{"en":"She was trying to summon up the courage to leave him.","cn":"当时她试图鼓起勇气离开他。"}}]}},"subsonic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"亚音速的;亚音速飞行的","en":"Subsonic speeds or aeroplanes are very fast but slower than the speed of sound.","ex":{"en":"This is 20,000 feet higher than most subsonic airliners.","cn":"这比大多数亚音速飞机的飞行高度高 20,000 英尺。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"slower than the speed of sound","cn":"亚音速的"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41subsonic.mp3","us":"media/ldoce/hwd/ame/e/subsonic.mp3"},"oxford":{"phon":"ˌsʌbˈsɒnɪk","pos":"adjective","senses":[{"en":"less than the speed of sound; flying at less than the speed of sound","cn":"亚声速的；亚声速飞行的"}]}},"sulfide":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the American spelling of sulphide sulphide","cn":"的美式拼法"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41sulfide.mp3","us":"media/ldoce/hwd/ame/9/ld41sulfide.mp3"},"oxford":{"phon":"ˈsʌlfaɪd","pos":"noun","senses":[{"en":"a compound of sulphur and another chemical element","cn":"硫化物"}]}},"subsoil":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"底土;心土;下层土","en":"The subsoil is a layer of earth that is just below the surface soil but above hard rock.","ex":{"en":"...the chalk subsoil on the site.","cn":"那个工地的白垩底土"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the layer of soil between the ground’s surface and the lower layer of hard rock","cn":"下层土﹐底土﹐心土"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41subsoil.mp3","us":"media/ldoce/hwd/ame/3/subsoil.mp3"},"oxford":{"phon":"ˈsʌbsɔɪl","pos":"noun","senses":[{"en":"the layer of soil between the surface of the ground and the hard rock below it","cn":"心土；底土"}]}},"superego":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"超我","en":"Your super-ego is the part of your mind which makes you aware of what is right and wrong, and which causes you to feel guilty when you have done something wrong."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"used in Freudian psychology to refer to the part of your mind that tells you whether what you are doing is morally right or wrong 〔","cn":"弗洛伊德心理学中的〕超我"}]},"vocab":{"pos":"n","senses":[{"en":"In psychoanalysis, the superego is the part of a person's mind that helps keep the id in check, guiding the person to follow learned rules rather than impulses."}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41superego.mp3","us":"media/ldoce/hwd/ame/b/superego.mp3"},"oxford":{"phon":"ˈsuːpəriːɡəʊ","pos":"noun","senses":[{"en":"the part of the mind that makes you aware of right and wrong and makes you feel guilty if you do wrong","cn":"超我"}]}},"suck":{"collins":{"senses":[{"pos":"VERB 动词","cn":"吮;啜;吸","en":"If you suck something, you hold it in your mouth and pull at it with the muscles in your cheeks and tongue, for example in order to get liquid out of it.","ex":{"en":"They waited in silence and sucked their sweets","cn":"他们安静地等着，嘴里咂着糖果。"}},{"pos":"VERB 动词","cn":"抽吸，抽取，抽，吸(空气、液体等)","en":"If something sucks a liquid, gas, or object in a particular direction, it draws it there with a powerful force.","ex":{"en":"The pollution-control team is at the scene and is due to start sucking up oil any time now","cn":"污染控制小组就在现场，现在随时准备开始吸油。"}},{"pos":"V-PASSIVE 被动动词","cn":"将…卷入","en":"If you are sucked into a bad situation, you are unable to prevent yourself from becoming involved in it.","ex":{"en":"He warned that if the President tried to enforce control, the country would be sucked into a power vacuum.","cn":"他警告说，如果总统想要实施强权统治的话，那么这个国家将陷入权力真空状态。"}},{"pos":"VERB 动词","cn":"糟糕透顶;很差","en":"If someone says that something sucks, they are indicating that they think it is very bad.","ex":{"en":"The system sucks.","cn":"这个系统太差劲了。"}},{"pos":"","cn":"","en":"to suck someone dry→see: ;"},{"pos":"","cn":"","en":"相关词组：suck up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"something that is bad is of a low standard, because it has been done badly, designed badly, performed badly etc","cn":""},{"en":"not good at all","cn":""},{"en":"very bad","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"To suck is to draw something by force. Vacuum cleaners suck dirt from the floor and milkshake drinkers suck this liquid, tasty liquid through a straw."}]},"collocations":{"phrases":["ADV. noisily She was noisily sucking up milk through a straw. | away, in, out, up She sucked away on her thumb. He cut the orange in half an","PREP. at He sucked at the wound on his hand. | from The machine sucks up mud and stones from the bottom of the pond. | into, on The baby suc"]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdesuck.mp3","us":"media/ldoce/hwd/ame/3/suck1.mp3","img":["media/ldoce/img/suck.jpg"]},"examples":[{"en":"She was noisily sucking up milk through a straw.","cn":"她正用吸管咕嘟咕嘟地喝牛奶。"},{"en":"The pump sucks air out through the valve.","cn":"气泵通过阀门把空气抽出去。"}],"oxford":{"phon":"sʌk","pos":"verb","senses":[{"en":"to take liquid, air, etc. into your mouth by using the muscles of your lips","cn":"吮吸；吸；咂；啜","g":"[transitive]","ex":{"en":"to suck the juice from an orange","cn":"吸橙子的汁"}},{"en":"to keep something in your mouth and pull on it with your lips and tongue","cn":"含在嘴里吸食","g":"[intransitive, transitive]","ex":{"en":"The baby sucked at its mother's breast.","cn":"婴儿在吮吸母亲的奶。"}},{"en":"to take liquid, air, etc. out of something","cn":"抽吸；抽取","g":"[transitive]","ex":{"en":"The pump sucks air out through the valve.","cn":"气泵通过阀门把空气抽出去。"}},{"en":"to pull somebody/something with great force in a particular direction","cn":"（以巨大的力量）吸，吸引，使卷入","g":"[transitive]","ex":{"en":"The canoe was sucked down into the whirlpool.","cn":"划艇被卷进了漩涡。"}},{"en":"used to say that something is very bad","cn":"（表示厌恶）臭，恶心","g":"[intransitive]","lab":"slang","ex":{"en":"Their new album sucks.","cn":"他们的新专辑难听死了。"}},{"en":"an act of sucking","cn":"吸；吮；啜；咂","ex":{"en":"The lamb staggered to its feet and took its first suck of milk.","cn":"小羊摇摇晃晃地站了起来，吸了第一口奶。"},"pos":"noun"}]}},"supplementation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"补充营养;服用补品","en":"Supplementation is the use of pills or special types of food in order to improve your health.","ex":{"en":"The product provided inadequate vitamin and mineral supplementation.","cn":"这种产品不能充分补充维生素和矿物质。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to add an amount of money, especially a tax, to the cost of something","cn":""},{"en":"to add more to something so that you have enough -- used especially about someone adding to an amount of money, or someone eating more of a particular type of food to make them healthy","cn":""},{"en":"to add something, especially to what you earn or eat, in order to increase it to an acceptable level","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/0/supplement_v0205.mp3","us":"media/ldoce/hwd/ame/c/l3supplement2.mp3"},"examples":[{"en":"Kia supplements her regular salary by tutoring in the evenings.","cn":""}],"oxford":{"phon":"ˌsʌplɪmenˈteɪʃn","pos":"noun","senses":[{"en":"the act of adding something to something else in order to improve or complete it","cn":"增补（物）；补充（物）；添加物","ex":{"en":"One study found that supplementation with the mineral selenium reduced the risk of dying from cancer by 50%.","cn":"一项研究发现，补充矿物质硒可使死于癌症的风险降低 50%。"}}]}},"suede":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"绒面革;仿麂皮","en":"Suede is leather with a soft, slightly rough surface.","ex":{"en":"Albert wore a brown suede jacket and jeans.","cn":"艾伯特穿着棕色绒面夹克和牛仔裤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"soft leather with a slightly rough surface 〔","cn":"外表略粗糙而料子柔软的〕绒面革﹐软皮革"}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdesuede.mp3","us":"media/ldoce/hwd/ame/8/laadsuede.mp3"},"examples":[{"en":"a suede jacket","cn":"绒面革夹克"},{"en":"suede shoes","cn":"绒面革皮鞋"}],"oxford":{"phon":"sweɪd","pos":"noun","senses":[{"en":"soft leather with a surface like velvet on one side, used especially for making clothes and shoes","cn":"绒面革；仿麂皮","ex":{"en":"a suede jacket","cn":"绒面革夹克"}}]}},"suggestive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人想起…的;引起联想的;暗示的","en":"Something that is suggestive of something else is quite like it or may be a sign of it.","ex":{"en":"The fingers were gnarled, lumpy, with long, curving nails suggestive of animal claws","cn":"手指粗糙，关节突出，指甲又长又弯，让人想起动物的爪子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"性暗示的;性挑逗的","en":"Suggestive remarks or looks cause people to think about sex, often in a way that makes them feel uncomfortable.","ex":{"en":"...another former employee who claims Thomas made suggestive remarks to her.","cn":"另一位声称托马斯曾对她言语挑逗的前职员"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a joke, remark, song etc that is risqué or saucy is about sex and is slightly shocking and amusing","cn":""},{"en":"remarks, questions etc that are suggestive have a slightly hidden meaning that is about sex","cn":""},{"en":"remarks that are intended to make you think about sex even though they do not directly mention sex","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"The adjective suggestive is useful when one thing indicates or hints at something else. Your constant yawning, for example, is suggestive of how tired you are."}]},"collocations":{"phrases":["VERBS be, seem","ADV. highly (medical) , strongly, very The results were highly suggestive of malignancy. | vaguely","PREP. of music that is suggestive of warm summer days 2 making people think about sex","VERBS be, look, sound | become","ADV. very | faintly, quite, rather | sexually"]},"media":{"uk":"media/ldoce/hwd/bre/9/suggestive0205.mp3","us":"media/ldoce/hwd/ame/7/suggestive.mp3"},"examples":[{"en":"music that is suggestive of warm summer days","cn":"使人想起温暖夏日的音乐"},{"en":"He leered suggestively.","cn":"他色迷迷地斜瞟一眼。"}],"oxford":{"phon":"səˈdʒestɪv","pos":"adjective","senses":[{"en":"reminding you of something or making you think about something","cn":"使人想起…的；引起联想的","ex":{"en":"music that is suggestive of warm summer days","cn":"使人想起温暖夏日的音乐"}},{"en":"making people think about sex","cn":"性暗示的；性挑逗的","ex":{"en":"suggestive jokes","cn":"黄色笑话"}}]}},"suitably":{"collins":{"senses":[{"pos":"ADV 副词","cn":"合适地;适宜地;适当地","en":"You use suitably to indicate that someone or something has the right qualities or things for a particular activity, purpose, or situation.","ex":{"en":"There are problems in recruiting suitably qualified scientific officers for NHS laboratories","cn":"很难为国民医疗保健系统的实验室招募到资历合适的高级科研人员。"}},{"pos":"ADV 副词","cn":"正如所料地;情理之中地","en":"If you say that someone or something is, for example, suitably impressed or suitably dramatic, you mean that they have as much of that quality as you would expect in that situation.","ex":{"en":"She flicked her eyes up to make certain I was suitably impressed","cn":"她抬眼瞟了瞟，以确定我不出所料地被打动了。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"wearing the right clothes, having the right information, equipment etc for a particular situation","cn":"衣着得体/准备妥当/装备完善等"},{"en":"having the amount of a feeling or quality you would hope for in a particular situation","cn":"合乎情理地﹔如常人所期望地"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld44suitably.mp3","us":"media/ldoce/hwd/ame/a/laadsuitably.mp3"},"examples":[{"en":"I am not really suitably dressed for a party.","cn":"我穿这样的衣服参加聚会并不十分得体。"},{"en":"He was suitably impressed when I told him I'd won.","cn":"我告诉他我赢了，他当然觉得我真行。"}],"oxford":{"phon":"ˈsuːtəbli","pos":"adverb","senses":[{"en":"in a way that is right or appropriate for a particular purpose or occasion","cn":"合适地；适宜地；适当地","ex":{"en":"I am not really suitably dressed for a party.","cn":"我穿这样的衣服参加聚会并不十分得体。"}},{"en":"showing the feelings, etc. that you would expect in a particular situation","cn":"如你所料地；自然","ex":{"en":"He was suitably impressed when I told him I'd won.","cn":"我告诉他我赢了，他当然觉得我真行。"}}]}},"subatomic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"亚原子的;次原子的;原子内的","en":"A subatomic particle is a particle which is part of an atom, for example an electron, a proton, or a neutron."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"smaller than an atom or existing within an atom","cn":"亚原子的﹔原子内的"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41subatomic.mp3","us":"media/ldoce/hwd/ame/9/subatomic.mp3"},"examples":[{"en":"subatomic particles","cn":"亚原子粒子"}],"oxford":{"phon":"ˌsʌbəˈtɒmɪk","pos":"adjective","senses":[{"en":"smaller than, or found in, an atom","cn":"亚原子的；比原子小的；原子内的"}]}},"sushi":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"寿司","en":"Sushi is a Japanese dish of rice with sweet vinegar, often served with raw fish."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a Japanese dish that consists of small cakes of cooked rice served with raw fish","cn":"寿司"}]},"media":{"img":["media/ldoce/img/sushi.jpg"],"uk":"media/ldoce/hwd/bre/a/ld41sushi.mp3","us":"media/ldoce/hwd/ame/2/sushi.mp3"},"examples":[{"en":"a sushi bar","cn":"寿司店"}],"oxford":{"phon":"ˈsuːʃi","pos":"noun","senses":[{"en":"a Japanese dish of small cakes of cold cooked rice, with vinegar added and served with raw fish, etc. on top","cn":"寿司（日本食物，小糕饼状冷米饭顶上配生鱼片等）","ex":{"en":"a sushi bar/restaurant","cn":"寿司店"}}]}},"submersible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"潜水的;水下使用的","en":"If something is submersible, it can go or operate under water.","ex":{"en":"...a submersible pump.","cn":"水下泵"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small vehicle that can travel under water, especially one that travels to very great depths in the ocean for scientific purposes 〔","cn":"尤指用于科研目的的〕深潜器﹐潜水器"}]},"vocab":{"pos":"adj n","senses":[{"en":"Use the adjective submersible to describe something that can be used under water, like your fancy new submersible video camera."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41submersible.mp3","us":"media/ldoce/hwd/ame/1/submersible.mp3"},"examples":[{"en":"a submersible camera","cn":"水下摄影机"}],"oxford":{"phon":"səbˈmɜːsəbl","pos":"adjective","senses":[{"en":"that can be used underwater","cn":"水下使用的","ex":{"en":"a submersible camera","cn":"水下摄影机"}},{"en":"a submarine (= a ship that can travel underwater) that goes underwater for short periods","cn":"潜水器","pos":"noun"}]}},"subtitle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"副标题;小标题","en":"The subtitle of a piece of writing is a second title which is often longer and explains more than the main title.","ex":{"en":"'Kathleen' was, as its 1892 subtitle asserted, 'An Irish Drama'.","cn":"正如 1892 年剧本的副标题所强调的，《凯瑟琳》是一部“爱尔兰戏剧”。"}},{"pos":"N-PLURAL 复数名词","cn":"(外国电影的)字幕，对白译文","en":"Subtitles are a printed translation of the words of a foreign film that are shown at the bottom of the picture.","ex":{"en":"The dialogue is in Spanish, with English subtitles.","cn":"对话是西班牙语，配有英语字幕。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the words printed over a film in a foreign language to translate what is being said by the actors 〔","cn":"电影的〕字幕"},{"en":"a second title below the main title in a book, which gives more information about what is in the book, show etc","cn":"副标题﹐小标题"}]},"collocations":{"phrases":["ADJ. English, French, etc.","VERB + SUBTITLE have | read","PREP. with ~s a Japanese film with English subtitles"]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41subtitle.mp3","us":"media/ldoce/hwd/ame/8/subtitle.mp3"},"examples":[{"en":"The book is subtitled ‘New language for new times’.","cn":"这部书的副标题是“新时代的新语言”。"},{"en":"Is the movie dubbed or are there subtitles?","cn":"这部电影是配音的还是带字幕的？"}],"oxford":{"phon":"ˈsʌbtaɪtl","pos":"noun","senses":[{"en":"words that translate what is said in a film into a different language and appear on the screen at the bottom. Subtitles are also used, especially on television, to help deaf people (= people who cannot hear well)","cn":"（电影或电视上的）字幕","g":"[usually plural]","ex":{"en":"a Polish film with English subtitles","cn":"附有英语字幕的波兰影片"}},{"en":"a second title of a book that appears after the main title and gives more information","cn":"副标题；小标题","ex":{"en":"This book’s title is ‘Oxford Learner’s Thesaurus’. Its subtitle is ‘A dictionary of synonyms’.","cn":"这部书名为《牛津英语同义词学习词典》，副标题是“一部学习型同义词词典”。"}},{"en":"to give a subtitle or subtitles to a book, film, etc.","cn":"给…加副标题；给（电影等）加字幕","ex":{"en":"a Spanish film subtitled in English","cn":"一部加了英语字幕的西班牙影片"},"pos":"verb"}]}},"subversion":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(对政府或政治体系的)颠覆，暗中破坏","en":"Subversion is the attempt to weaken or destroy a political system or a government.","ex":{"en":"He was arrested in parliament on charges of subversion for organizing the demonstration.","cn":"他因组织示威活动在议会上被以颠覆破坏罪名逮捕。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"actions, speeches etc that are intended to encourage people to oppose the government or to take part in a rebellion","cn":""},{"en":"secret activities that are intended to encourage people to oppose the government or to take part in a rebellion","cn":""},{"en":"secret activities that are intended to damage or destroy the power or influence of a government or established system 〔","cn":"对政府的〕颠覆﹔〔对现有制度的〕暗中破坏"}]},"vocab":{"pos":"n","senses":[{"en":"Subversion means overthrowing something, like a government or law, or it can mean corrupting someone’s personal morals, like making a vegetarian eat bacon by tricking her."}]},"media":{"uk":"media/ldoce/hwd/bre/3/subversion0205.mp3","us":"media/ldoce/hwd/ame/9/laadsubversion.mp3"},"examples":[{"en":"Murray was jailed for subversion.","cn":"默里因从事颠覆活动而入狱。"}],"oxford":{"phon":"səbˈvɜːʃn","pos":"noun","senses":[{"en":"the process of trying to destroy the authority of a political, religious, etc. system by attacking it secretly or indirectly","cn":"颠覆；暗中破坏","g":"[uncountable]","ex":{"en":"acts of subversion","cn":"颠覆行为"}},{"en":"an act of changing something to its opposite, especially when this challenges fixed ideas or expectations","cn":"颠覆：将事物改变为相反的行为，尤其是在挑战固定观念或期望时","g":"[uncountable, countable]","ex":{"en":"The play includes a playful subversion of gender roles.","cn":"该剧对性别角色进行了有趣的颠覆。"}}]}},"substation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"变电站;变电所","en":"A substation is a place where high-voltage electricity from power plants is converted to lower-voltage electricity for homes or factories."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where electricity is passed on from the place that produces it into the main system","cn":"变电站﹐变电所﹔配电室"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41substation.mp3","us":"media/ldoce/hwd/ame/a/substation.mp3"},"oxford":{"phon":"ˈsʌbsteɪʃn","pos":"noun","senses":[{"en":"a place where the strength of electric power from a power station is reduced before it is passed on to homes and businesses","cn":"变电站；变电所"}]}},"sundae":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"圣代冰激凌","en":"A sundae is a tall glass of ice cream with whipped cream and nuts or fruit on top.","ex":{"en":"...a chocolate sundae.","cn":"巧克力圣代"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a dish made from ice cream , fruit, sweet sauce, nuts etc","cn":"圣代冰激凌〔一种加水果﹑糖浆﹑果仁等的冰激凌〕"}]},"media":{"img":["media/ldoce/img/ice_cream.jpg"],"uk":"media/ldoce/hwd/bre/d/sundae0205.mp3","us":"media/ldoce/hwd/ame/3/sundae.mp3"},"examples":[{"en":"a chocolate sundae","cn":"巧克力圣代冰激凌"}],"oxford":{"phon":"ˈsʌndeɪ","pos":"noun","senses":[{"en":"a cold dessert (= a sweet dish) of ice cream covered with a sweet sauce, nuts, pieces of fruit, etc., usually served in a tall glass","cn":"圣代冰激凌（加甜汁、果仁、水果粒等）","ex":{"en":"a hot chocolate fudge sundae","cn":"热巧克力软糖圣代"}}]}},"submerge":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)浸没;(使)淹没;(使)潜入水中;(使)没入水中","en":"If something submerges or if you submerge it, it goes below the surface of some water or another liquid.","ex":{"en":"Hippos are unable to submerge in the few remaining water holes","cn":"在仅剩的几个水坑里，河马根本无法没入水中。"}},{"pos":"VERB 动词","cn":"沉浸;陷入;埋头于","en":"If you submerge yourself in an activity, you give all your attention to it and do not think about anything else.","ex":{"en":"He submerges himself in the world of his imagination.","cn":"他沉浸在自己想象的世界中。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go down below the surface of water, mud, sand etc, without being able to control or prevent it","cn":""},{"en":"to jump down into water with your head first","cn":""},{"en":"to jump into a river, lake etc quickly, making a lot of noise","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you go swimming, you submerge your body in water. If your head is out of the water, it is not submerged — it's just wet."}]},"media":{"uk":"media/ldoce/hwd/bre/2/submerge0205.mp3","us":"media/ldoce/hwd/ame/c/submerge.mp3"},"examples":[{"en":"Her submerged car was discovered in the river by police divers.","cn":"她被河水淹没的汽车给警方的潜水员找到了。"},{"en":"The submarine had had time to submerge before the warship could approach.","cn":"潜水艇没等军舰靠近就及时潜入水下了。"}],"oxford":{"phon":"səbˈmɜːdʒ","pos":"verb","senses":[{"en":"to go under the surface of water or liquid; to put something or make something go under the surface of water or liquid","cn":"（使）潜入水中，没入水中，浸没，淹没","g":"[intransitive, transitive]","ex":{"en":"The submarine had had time to submerge before the warship could approach.","cn":"潜水艇没等军舰靠近就及时潜入水下了。"}},{"en":"to hide ideas, feelings, opinions, etc. completely","cn":"湮没，湮灭，掩盖（思想、感情等）","g":"[transitive]","ex":{"en":"Doubts that had been submerged in her mind suddenly resurfaced.","cn":"她心里早已湮灭的疑团突然又浮现出来。"}}]}},"substitute":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"用…代替;取代;替换","en":"If you substitute one thing for another, or if one thing substitutes for another, it takes the place or performs the function of the other thing.","ex":{"en":"They were substituting violence for dialogue","cn":"他们在用暴力取代对话。"}},{"pos":"N-COUNT 可数名词","cn":"代替者;代替物;代用品","en":"A substitute is something that you have or use instead of something else.","ex":{"en":"She is seeking a substitute for the very man whose departure made her cry.","cn":"那个男人的离去令她伤心痛哭，她正想找一个人填补内心的空缺。"}},{"pos":"N-COUNT 可数名词","cn":"令人满意的替代物;与之媲美的事物","en":"If you say that one thing is no substitute for another, you mean that it does not have certain desirable features that the other thing has, and is therefore unsatisfactory. If you say that there is no substitute for something, you mean that it is the only thing which is really satisfactory.","ex":{"en":"The printed word is no substitute for personal discussion with a great thinker","cn":"阅读印在纸上的内容远不如与伟大的思想家面对面探讨那般受益。"}},{"pos":"N-COUNT 可数名词","cn":"替补(运动员)","en":"In team games such as football, a substitute is a player who is brought into a match to replace another player.","ex":{"en":"Coming on as a substitute, he scored four crucial goals for Cameroon.","cn":"作为替补队员上场的他为喀麦隆队打入了四粒关键进球。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who replaces another person in a job or in a team, especially permanently","cn":""},{"en":"the next person to have a permanent job or position after someone else has left it","cn":""},{"en":"someone who temporarily takes another person's place in a job or performance when they are unable to do it themselves, especially when this happens unexpectedly","cn":""}]},"vocab":{"pos":"n v adj","senses":[{"en":"Something or someone that takes the place of another is said to be a substitute . You may be sent into a game as a substitute for an injured player, or you might substitute chocolate chips for blueberries in a pancake recipe."}]},"collocations":{"phrases":["ADJ. good | acceptable, adequate, satisfactory | close | poor The television is a poor substitute for human companionship.","VERB + SUBSTITUTE act as, serve as His teacher acted as a father substitute. | use sth as | produce, provide The company produces substitute","PREP. ~ for There's no substitute for hard work."]},"media":{"uk":"media/ldoce/hwd/bre/7/substitute_v0205.mp3","us":"media/ldoce/hwd/ame/e/substitute1.mp3"},"examples":[{"en":"The course teaches you the theory but there's no substitute for practical experience.","cn":"这门课教的是理论，但没有任何东西能代替实践经验。"},{"en":"The local bus service was a poor substitute for their car.","cn":"他们坐当地的公交车，这比坐自己的汽车可差远了。"}],"oxford":{"phon":"ˈsʌbstɪtjuːt","pos":"noun","senses":[{"en":"a person or thing that you use or have instead of the one you normally use or have","cn":"代替者；代替物；代用品","ex":{"en":"a meat substitute","cn":"肉食替代品"}},{"en":"a player who replaces another player in a sports game","cn":"替补（运动员）","lab":"informal","ex":{"en":"He was brought on as (a) substitute after half-time.","cn":"他作为替补队员在下半场上场。"}},{"en":"to take the place of somebody/something else; to use somebody/something instead of somebody/something else","cn":"（以…）代替；取代","ex":{"en":"Nothing can substitute for the advice your doctor is able to give you.","cn":"大夫所能给你的忠告是无可替代的。"},"pos":"verb"}]}},"sunless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"无阳光的;阴天的","en":"On sunless days, the sun does not shine.","ex":{"en":"The day dawned sunless and with a low cloud base.","cn":"黎明时分天气阴沉，云幕低垂。"}},{"pos":"ADJ 形容词","cn":"阳光照不到的;阴面的","en":"Sunless places are not lit by the sun.","ex":{"en":"Carmen stayed behind in the dark, sunless room.","cn":"卡门留在那个黑漆漆不见阳光的屋子里。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having no light from the sun","cn":"无阳[日]光的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41sunless.mp3","us":"media/ldoce/hwd/ame/5/sunless.mp3"},"examples":[{"en":"a sunless day","cn":"无阳光的一天"},{"en":"the sunless depths of the ocean","cn":"阳光照不到的海洋深处"}],"oxford":{"phon":"ˈsʌnləs","pos":"adjective","senses":[{"en":"without any sun; receiving no light from the sun","cn":"无阳光的；阳光照不到的","ex":{"en":"a sunless day","cn":"无阳光的一天"}}]}},"submissive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"顺从的;恭顺的;听话的","en":"If you are submissive, you obey someone without arguing.","ex":{"en":"Most doctors want their patients to be submissive.","cn":"大部分医生希望病人能听从医嘱。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"always willing to do what someone tells you to do even if it is unpleasant or they ask you in an unpleasant way","cn":""},{"en":"someone who always agrees with and obeys their employer or leader etc","cn":""},{"en":"obeying someone too eagerly and showing them too much respect","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"When animals live in packs, one animal is usually the dominant leader, while the others fall into more submissive roles. To be submissive is to obey or yield to someone else."}]},"media":{"uk":"media/ldoce/hwd/bre/2/submissive0205.mp3","us":"media/ldoce/hwd/ame/a/submissive.mp3"},"examples":[{"en":"‘You're right and I was wrong,’ he said submissively. “","cn":"你说得对，是我错了。”他恭顺地说。"},{"en":"She followed him like a submissive child.","cn":"她对他百依百顺，像个听话的孩子。"}],"oxford":{"phon":"səbˈmɪsɪv","pos":"adjective","senses":[{"en":"too willing to accept somebody else’s authority and willing to obey them without questioning anything they want you to do","cn":"唯命是从的；顺从的；驯服的；听话的","ex":{"en":"He expected his daughters to be meek and submissive.","cn":"他期望女儿都温顺听话。"}}]}},"supine":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"仰卧的;平躺着的","en":"If you are supine, you are lying flat on your back.","ex":{"en":"...bedridden persons confined to the supine position.","cn":"那些只能平躺在床上的久病不起的人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"懒散的;得过且过的;软弱的","en":"If you describe someone as supine, you mean that they let events happen because they are too lazy or afraid to influence them.","ex":{"en":"...a willing and supine executive.","cn":"一个为人和气、得过且过的主管"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"lying on your back","cn":"仰卧的"},{"en":"allowing other people to make decisions instead of you, in a way that seems very weak","cn":"无所作为的﹔消极的﹔软弱的"}]},"vocab":{"pos":"adj","senses":[{"en":"One can be described as supine when lying face up (\"his favorite yoga poses were always the supine ones\"); or, if one is very passive or lethargic (\" supine in the face of their threats and insults\")."}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41supine.mp3","us":"media/ldoce/hwd/ame/1/supine.mp3"},"examples":[{"en":"a supine position","cn":"仰卧姿势"},{"en":"in a supine position","cn":"以仰卧的姿势"}],"oxford":{"phon":"ˈsuːpaɪn","pos":"adjective","senses":[{"en":"lying flat on your back","cn":"仰卧的；平躺着的","ex":{"en":"a supine position","cn":"仰卧姿势"}},{"en":"not willing to act or disagree with somebody because you are lazy or morally weak","cn":"得过且过的；苟安的；软弱的","lab":"disapproving","ex":{"en":"the supine attitude of some of our politicians","cn":"我们一些政客的消极态度"}}]}},"sulphur":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"硫;硫黄","en":"Sulphur is a yellow chemical which has a strong smell.","ex":{"en":"The air reeks of sulphur.","cn":"空气中散发着硫黄味儿。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a common light yellow chemical substance that burns with a very strong unpleasant smell, and is used in drugs, explosives, and industry. It is a chemical element : symbol S","cn":"硫〔一种化学元素﹐符号为S〕"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41sulphur.mp3","us":"media/ldoce/hwd/ame/8/laadsulphur.mp3"},"examples":[{"en":"sulphurous fumes","cn":"燃烧硫磺产生的烟雾"}],"oxford":{"phon":"ˈsʌlfə(r)","pos":"noun","senses":[{"en":"a chemical element. Sulphur is a pale yellow substance that produces a strong unpleasant smell when it burns and is used in medicine and industry.","cn":"硫；硫黄"}]}}});
